	var t int
	fmt.Fscan(in, &t)

	for ; t > 0; t-- {
		var n int
		fmt.Fscan(in, &n)

		a := make([]]int64, n)
		for i := range a {
			fmt.Fscan(in, &a[i])
		}

		var maximum int64
		for incremented := 0; incremented < n; incremented++ {
			product := int64(1)
			for i, digit := range a {
				if i == incremented {
					digit++
				}
				product *= digit
			}
			if product > maximum {
				maximum = product
			}
		}

		fmt.Fprintln(out, maximum)
	}
}
