import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var t int
	fmt.Fscan(in, &t)

	for ; t > 0; t-- {
		var n int
		fmt.Fscan(in, &n)

		prefix := make([]int64, n+1)
		for i := 1; i <= n; i++ {
			var x int64
			fmt.Fscan(in, &x)
			prefix[i] = prefix[i-1] + x
		}

		var answer int64

		for k := 1; k <= n; k++ {
			if n%k != 0 {
				continue
			}

			var minSum, maxSum int64
			first := true

			for end := k; end <= n; end += k {
				sum := prefix[end] - prefix[end-k]
				if first {
					minSum, maxSum = sum, sum
					first = false
				} else {
					if sum < minSum {
						minSum = sum
					}
					if sum > maxSum {
						maxSum = sum
					}
				}
			}

			if maxSum-minSum > answer {
				answer = maxSum - minSum
			}
		}

		fmt.Fprintln(out, answer)
	}
}
