package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := int(in.NextInt64())
	for ; t > 0; t-- {
		n := int(in.NextInt64())
		prefix := make([]int64, n+1)

		for i := 1; i <= n; i++ {
			prefix[i] = prefix[i-1] + in.NextInt64()
		}

		var answer int64

		for k := 1; k <= n; k++ {
			if n%k != 0 {
				continue
			}

			firstSum := prefix[k]
			minSum, maxSum := firstSum, firstSum

			for end := 2 * k; end <= n; end += k {
				sum := prefix[end] - prefix[end-k]
				if sum < minSum {
					minSum = sum
				}
				if sum > maxSum {
					maxSum = sum
				}
			}

			if maxSum-minSum > answer {
				answer = maxSum - minSum
			}
		}

		fmt.Fprintln(out, answer)
