func main() {
	in := bufio.NewReader(os.Stdin)
	var nums []int64

	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	if len(nums) == 0 {
		return
	}

	var maxStrength int64
	initialized := false

	for mask := 1; mask < (1 << len(nums)); mask++ {
		product := int64(1)
		for i, num := range nums {
			if mask&(1<<i) != 0 {
				product *= num
			}
		}
		if !initialized || product > maxStrength {
			maxStrength = product
			initialized = true
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxStrength)
}
