package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	if len(nums) == 0 {
		return
	}

	maxProduct := nums[0]
	minEnding := nums[0]
	maxEnding := nums[0]

	for _, x := range nums[1:] {
		prevMin, prevMax := minEnding, maxEnding
		a, b := prevMin*x, prevMax*x

		minEnding = min64(x, min64(a, b))
		maxEnding = max64(x, max64(a, b))
		maxProduct = max64(maxProduct, maxEnding)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxProduct)
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}
