import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	dictionary := make(map[string]struct{})
	var word string
	for {
		if _, err := fmt.Fscan(in, &word); err != nil {
			break
		}
		dictionary[word] = struct{}{}
	}

	n := len(s)
	dp := make([]int, n+1)

	for i := n - 1; i >= 0; i-- {
		dp[i] = 1 + dp[i+1]
		for j := i + 1; j <= n; j++ {
			if _, exists := dictionary[s[i:j]]; exists && dp[j] < dp[i] {
				dp[i] = dp[j]
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[0])
}
