package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func countUpTo(num string, minSum, maxSum int) int64 {
	if maxSum < 0 || minSum > maxSum {
		return 0
	}

	possibleMax := 9 * len(num)
	if minSum > possibleMax {
		return 0
	}
	if maxSum > possibleMax {
		maxSum = possibleMax
	}

	dp := make([][2]int64, maxSum+1)
	dp[0][1] = 1

	for _, ch := range num {
		digit := int(ch - '0')
		next := make([][2]int64, maxSum+1)

		for sum := 0; sum <= maxSum; sum++ {
			for tight := 0; tight <= 1; tight++ {
				ways := dp[sum][tight]
				if ways == 0 {
					continue
				}

				limit := 9
				if tight == 1 {
					limit = digit
				}

				for d := 0; d <= limit && sum+d <= maxSum; d++ {
					nextTight := 0
					if tight == 1 && d == digit {
						nextTight = 1
					}
					next[sum+d][nextTight] = (next[sum+d][nextTight] + ways) % mod
				}
			}
		}
		dp = next
	}

	var result int64
	for sum := minSum; sum <= maxSum; sum++ {
		result = (result + dp[sum][0] + dp[sum][1]) % mod
	}
	return result
}

func digitSum(num string) int {
	sum := 0
	for _, ch := range num {
		sum += int(ch - '0')
	}
	return sum
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var num1, num2 string
	var minSum, maxSum int
	if _, err := fmt.Fscan(in, &num1, &num2, &minSum, &maxSum); err != nil {
		return
	}

	answer := (countUpTo(num2, minSum, maxSum) - countUpTo(num1, minSum, maxSum)) % mod

	sum1 := digitSum(num1)
	if sum1 >= minSum && sum1 <= maxSum {
		answer++
	}

	answer %= mod
	if answer < 0 {
		answer += mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
