	nonEmpty := make([]string, 0, len(lines))
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line != "" {
			nonEmpty = append(nonEmpty, line)
		}
	}
	if len(nonEmpty) < 2 {
		return
	}

	nums := parseIntegers(nonEmpty[0])
	kValues := parseIntegers(strings.Join(nonEmpty[1:], " "))
	if len(nums) == 0 || len(kValues) == 0 {
		return
	}
	k := uint(kValues[0])

	n := len(nums)
	suffixOR := make([]int64, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixOR[i] = suffixOR[i+1] | nums[i]
