	sort.Slice(nums, func(i, j int) bool {
		return nums[i] < nums[j]
	})

	var answer, minSum int64
	for _, value := range nums {
		x := value % mod
		xSquared := x * x % mod

		answer = (answer + xSquared*((x+minSum)%mod)) % mod
		minSum = (2*minSum + x) % mod
