	"fmt"
	"os"
	"strconv"
)

func canPartition(square, target int) bool {
	s := strconv.Itoa(square)
	memo := make(map[[2]int]bool)
	visited := make(map[[2]int]bool)

	var dfs func(int, int) bool
	dfs = func(pos, remaining int) bool {
		if pos == len(s) {
			return remaining == 0
		}
		if remaining < 0 {
			return false
		}

		state := [2]int{pos, remaining}
		if visited[state] {
			return memo[state]
		}
		visited[state] = true

		value := 0
		for end := pos; end < len(s); end++ {
			value = value*10 + int(s[end]-'0')
			if value > remaining {
				break
			}
			if dfs(end+1, remaining-value) {
				memo[state] = true
				return true
			}
		}

		memo[state] = false
		return false
	}

	return dfs(0, target)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	answer := 0
	for i := 1; i <= n; i++ {
		square := i * i
		if canPartition(square, i) {
			answer += square
		}
	}

	fmt.Fprintln(out, answer)
}
