package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func parseInts(s string) []int {
	var nums []int
	for i := 0; i < len(s); {
		if s[i] < '0' || s[i] > '9' {
			i++
			continue
		}
		value := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
		}
		nums = append(nums, value)
	}
	return nums
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	var rows [][]int
	for _, line := range strings.Split(string(data), "\n") {
		nums := parseInts(line)
		if len(nums) > 0 {
			rows = append(rows, nums)
		}
	}

	if len(rows) < 2 {
		return
	}

	var cost, times []int
	if len(rows) >= 3 && len(rows[0]) == 1 &&
		len(rows[1]) == rows[0][0] && len(rows[2]) == rows[0][0] {
		cost, times = rows[1], rows[2]
	} else {
		cost, times = rows[0], rows[1]
	}

	n := len(cost)
	if len(times) < n {
		n = len(times)
	}

	const inf int64 = 1 << 60
	dp := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		dp[i] = inf
	}

	for i := 0; i < n; i++ {
		coverage := times[i] + 1
		for painted := n; painted >= 0; painted-- {
			if dp[painted] == inf {
				continue
			}
			next := painted + coverage
			if next > n {
				next = n
			}
			candidate := dp[painted] + int64(cost[i])
			if candidate < dp[next] {
				dp[next] = candidate
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[n])
}
