package main

import (
	"bufio"
	"fmt"
	"os"
)

type DSU struct {
	parent []int
	size   []int
}

func newDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) union(a, b int) {
	ra, rb := d.find(a), d.find(b)
	if ra == rb {
		return
	}
	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}
	d.parent[rb] = ra
	d.size[ra] += d.size[rb]
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var nums []int
	maxValue := 0

	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
		if x > maxValue {
			maxValue = x
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := len(nums)
	if n <= 1 {
		fmt.Fprintln(out, "true")
		return
	}

	for _, x := range nums {
		if x == 1 {
			fmt.Fprintln(out, "false")
			return
		}
	}

	smallestPrime := make([]int, maxValue+1)
	for i := 2; i <= maxValue; i++ {
		if smallestPrime[i] == 0 {
			smallestPrime[i] = i
			if i <= maxValue/i {
				for j := i * i; j <= maxValue; j += i {
					if smallestPrime[j] == 0 {
						smallestPrime[j] = i
					}
				}
			}
		}
	}

	dsu := newDSU(n)
	owner := make(map[int]int)

	for i, value := range nums {
		for value > 1 {
			p := smallestPrime[value]
			if p == 0 {
				p = value
			}

			if j, exists := owner[p]; exists {
				dsu.union(i, j)
			} else {
				owner[p] = i
			}

			for value%p == 0 {
				value /= p
			}
		}
	}

	root := dsu.find(0)
	for i := 1; i < n; i++ {
		if dsu.find(i) != root {
			fmt.Fprintln(out, "false")
			return
		}
	}

	fmt.Fprintln(out, "true")
}
