package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

func parseInts(s string) []int64 {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return !unicode.IsDigit(r) && r != '-'
	})

	values := make([]int64, 0, len(fields))
	for _, field := range fields {
		v, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			values = append(values, v)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 2 {
		return
	}

	var nums []int64
	var x int64

	// Supports both:
	// nums on the first line, x on the second line
	// and n on the first line, nums on the second, x on the third.
	if len(lines) >= 3 && len(lines[0]) == 1 && int(lines[0][0]) == len(lines[1]) {
		nums = lines[1]
		x = lines[2][0]
	} else {
		nums = lines[0]
		x = lines[1][0]
	}

	n := len(nums)
	bestCosts := append([]int64(nil), nums...)

	var currentSum int64
	for _, cost := range bestCosts {
		currentSum += cost
	}

	answer := currentSum

	for operations := 1; operations < n; operations++ {
		for i := 0; i < n; i++ {
			cost := nums[(i-operations+n)%n]
			if cost < bestCosts[i] {
				currentSum += cost - bestCosts[i]
				bestCosts[i] = cost
			}
		}

		total := currentSum + int64(operations)*x
		if total < answer {
			answer = total
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
