	var x, y, z int
	fmt.Fscan(in, &x, &y, &z)

	dy, dz := y+1, z+1
	index := func(i, j, k, state int) int {
		return ((((i * dy) + j) * dz) + k) * 5 + state
	}

	reachable := make([]bool, (x+1)*(y+1)*(z+1)*5)
	reachable[index(0, 0, 0, 0)] = true

	maxBlocks := 0

	for i := 0; i <= x; i++ {
		for j := 0; j <= y; j++ {
			for k := 0; k <= z; k++ {
				for state := 0; state < 5; state++ {
					if !reachable[index(i, j, k, state)] {
						continue
					}

					if i+j+k > maxBlocks {
						maxBlocks = i + j + k
					}

					// Append "AA". This is valid only if the current
					// string is empty or ends in B.
					if i < x && (state == 0 || state == 3 || state == 4) {
						reachable[index(i+1, j, k, 2)] = true
					}

					// Append "BB". This is valid only if the current
					// string is empty or ends in A.
					if j < y && (state == 0 || state == 1 || state == 2) {
						reachable[index(i, j+1, k, 4)] = true
					}

					// Append "AB". It is invalid only when the current
					// string already ends in "AA".
					if k < z && state != 2 {
						reachable[index(i, j, k+1, 3)] = true
					}
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, 2*maxBlocks)
