			i++
			continue
		}

		start := i
		if s[i] == '-' {
			i++
			if i >= len(s) || !unicode.IsDigit(rune(s[i])) {
				continue
			}
		}
		for i < len(s) && unicode.IsDigit(rune(s[i])) {
			i++
		}

		value, err := strconv.ParseInt(s[start:i], 10, 64)
		if err == nil {
