			current = 0
			continue
		}

		if current == 0 {
			if num%2 == 0 {
				current = 1
			}
		} else if nums[i-1]%2 != num%2 {
			current++
		} else if num%2 == 0 {
			current = 1
		} else {
			current = 0
		}

		if current > longest {
			longest = current
		}
	}

	writer := bufio.NewWriter(os.Stdout)
