func readArray(scanner *bufio.Scanner) []int64 {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		fields := strings.Fields(line)
		nums := make([]int64, 0, len(fields))
		for _, field := range fields {
			value, err := strconv.ParseInt(field, 10, 64)
			if err == nil {
				nums = append(nums, value)
			}
		}
		return nums
	}
	return nil
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	nums1 := readArray(scanner)
	nums2 := readArray(scanner)

	n := len(nums1)
	if len(nums2) < n {
		n = len(nums2)
	}
	if n == 0 {
		fmt.Println(0)
		return
	}

	endWithFirst, endWithSecond := 1, 1
	answer := 1

	for i := 1; i < n; i++ {
		nextFirst, nextSecond := 1, 1

		if nums1[i] >= nums1[i-1] {
			nextFirst = max(nextFirst, endWithFirst+1)
		}
		if nums1[i] >= nums2[i-1] {
			nextFirst = max(nextFirst, endWithSecond+1)
		}
		if nums2[i] >= nums1[i-1] {
			nextSecond = max(nextSecond, endWithFirst+1)
		}
		if nums2[i] >= nums2[i-1] {
			nextSecond = max(nextSecond, endWithSecond+1)
		}

		endWithFirst, endWithSecond = nextFirst, nextSecond
		answer = max(answer, max(endWithFirst, endWithSecond))
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
