		if (data[i] >= '0' && data[i] <= '9') || data[i] == '-' {
			sign := int64(1)
			if data[i] == '-' {
				sign = -1
				i++
			}

			var value int64
			found := false
			for i < len(data) && data[i] >= '0' && data[i] <= '9' {
				value = value*10 + int64(data[i]-'0')
				i++
				found = true
			}
			if found {
				values = append(values, sign*value)
			}
		} else {
			i++
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(values) < 2 {
		fmt.Fprintln(out, false)
		return
	}

	k := int(values[len(values)-1])
	nums := values[:len(values)-1]
	n := len(nums)

	if k <= 0 || k > n {
		fmt.Fprintln(out, false)
		return
	}

	ends := make([]int64, n+1)
	var active int64

	for i := 0; i < n; i++ {
		active -= ends[i]

		if nums[i] < active {
			fmt.Fprintln(out, false)
			return
		}

		needed := nums[i] - active
		if needed == 0 {
			continue
		}

		if i+k > n {
			fmt.Fprintln(out, false)
			return
		}

		active += needed
		ends[i+k] += needed
	}

	fmt.Fprintln(out, true)
