		return !unicode.IsDigit(r) && r != '-'
	})

	values := make([]int64, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			values = append(values, value)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if len(lines) < 2 || len(lines[0]) == 0 || len(lines[1]) == 0 {
		fmt.Fprintln(writer, "false")
		return
	}

	nums := lines[0]
	k := int(lines[1][0])
	n := len(nums)

	if k <= 0 || k > n {
		fmt.Fprintln(writer, "false")
		return
	}

	expire := make([]int64, n+1)
	var active int64

	for i := 0; i < n; i++ {
		active -= expire[i]
		needed := nums[i] - active

		if needed < 0 {
			fmt.Fprintln(writer, "false")
			return
		}

		if needed > 0 {
			if i+k > n {
				fmt.Fprintln(writer, "false")
				return
			}
			active += needed
			expire[i+k] += needed
		}
