package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}
	fmt.Fscan(in, &k)

	n := len(s)
	cost := make([][]int, n)
	for i := range cost {
		cost[i] = make([]int, n+1)
	}

	// cost[left][right] is the minimum changes needed to make
	// s[left:right] a semi-palindrome.
	for length := 2; length <= n; length++ {
		for left := 0; left+length <= n; left++ {
			right := left + length
			best := n

			for d := 1; d < length; d++ {
				if length%d != 0 {
					continue
				}

				groupLength := length / d
				changes := 0

				for remainder := 0; remainder < d; remainder++ {
					for a, b := 0, groupLength-1; a < b; a, b = a+1, b-1 {
						i := left + remainder + a*d
						j := left + remainder + b*d
						if s[i] != s[j] {
							changes++
						}
					}
				}

				if changes < best {
					best = changes
				}
			}

			cost[left][right] = best
		}
	}

	const inf = int(1e9)
	dp := make([][]int, k+1)
	for parts := range dp {
		dp[parts] = make([]int, n+1)
		for i := range dp[parts] {
			dp[parts][i] = inf
		}
	}
	dp[0][0] = 0

	for parts := 1; parts <= k; parts++ {
		for end := 2 * parts; end <= n; end++ {
			for start := 2 * (parts - 1); start <= end-2; start++ {
				if dp[parts-1][start] == inf {
					continue
				}
				value := dp[parts-1][start] + cost[start][end]
				if value < dp[parts][end] {
					dp[parts][end] = value
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[k][n])
}
