const mod = 1_000_000_007

func powerLimited(base, exp, limit int) int {
	result := 1
	for i := 0; i < exp; i++ {
		if result > limit/base {
			return limit + 1
		}
		result *= base
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, x int
	if _, err := fmt.Fscan(in, &n, &x); err != nil {
		return
	}

	dp := make([]int, n+1)
	dp[0] = 1

	for base := 1; ; base++ {
		value := powerLimited(base, x, n)
		if value > n {
			break
		}

		for sum := n; sum >= value; sum-- {
			dp[sum] += dp[sum-value]
			if dp[sum] >= mod {
				dp[sum] -= mod
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[n])
}
