	for i := 1; i <= n; i++ {
		dp[i] = inf
	}

	for i := 0; i < n; i++ {
		if dp[i] == inf || s[i] == '0' {
			continue
		}

		value := 0
		for j := i; j < n; j++ {
			value = value*2 + int(s[j]-'0')
			if isPowerOfFive(value) && dp[j+1] > dp[i]+1 {
				dp[j+1] = dp[i] + 1
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if dp[n] == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, dp[n])
	}
}

func isPowerOfFive(x int) bool {
	if x < 1 {
		return false
	}
	for x%5 == 0 {
		x /= 5
	}
	return x == 1
}
