package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func merge(a, b string) string {
	if strings.Contains(a, b) {
		return a
	}

	maxOverlap := 0
	limit := len(a)
	if len(b) < limit {
		limit = len(b)
	}

	for overlap := 1; overlap <= limit; overlap++ {
		if a[len(a)-overlap:] == b[:overlap] {
			maxOverlap = overlap
		}
	}

	return a + b[maxOverlap:]
}

func better(a, b string) bool {
	return b == "" || len(a) < len(b) || (len(a) == len(b) && a < b)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var input [3]string
	if _, err := fmt.Fscan(in, &input[0], &input[1], &input[2]); err != nil {
		return
	}

	unique := make([]string, 0, 3)
	for _, s := range input {
		found := false
		for _, existing := range unique {
			if s == existing {
				found = true
				break
			}
		}
		if !found {
			unique = append(unique, s)
		}
	}

	strs := make([]string, 0, len(unique))
	for i, s := range unique {
		contained := false
		for j, other := range unique {
			if i != j && strings.Contains(other, s) {
				contained = true
				break
			}
		}
		if !contained {
			strs = append(strs, s)
		}
	}

	best := ""
	used := make([]bool, len(strs))

	var generate func([]int)
	generate = func(order []int) {
		if len(order) == len(strs) {
			candidate := strs[order[0]]
			for i := 1; i < len(order); i++ {
				candidate = merge(candidate, strs[order[i]])
			}
			if better(candidate, best) {
				best = candidate
			}
			return
		}

		for i := range strs {
			if !used[i] {
				used[i] = true
				generate(append(order, i))
				used[i] = false
			}
		}
	}

	generate(nil)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
}
