	left, answer := 0, 0
	for right := 0; right < len(word); right++ {
		minStart := right - maxForbiddenLen + 1
		if minStart < left {
			minStart = left
		}

		for start := right; start >= minStart; start-- {
			if _, found := forbidden[word[start:right+1]]; found {
				if start+1 > left {
					left = start + 1
				}
				break
			}
		}

		if length := right - left + 1; length > answer {
			answer = length
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
