	if _, err := fmt.Fscan(in, &word); err != nil {
		return
	}

	forbiddenByLength := make(map[int]map[string]struct{})
	maxForbiddenLength := 0

	var s string
	for {
		if _, err := fmt.Fscan(in, &s); err != nil {
			break
		}
		length := len(s)
		if forbiddenByLength[length] == nil {
			forbiddenByLength[length] = make(map[string]struct{})
		}
		forbiddenByLength[length][s] = struct{}{}
		if length > maxForbiddenLength {
			maxForbiddenLength = length
		}
	}

	left, answer := 0, 0

	for right := 0; right < len(word); right++ {
		limit := maxForbiddenLength
		if right+1 < limit {
			limit = right + 1
		}

		for length := 1; length <= limit; length++ {
			set := forbiddenByLength[length]
			if set == nil {
				continue
			}

			start := right - length + 1
			if _, found := set[word[start:right+1]]; found && start+1 > left {
				left = start + 1
			}
		}

		if current := right - left + 1; current > answer {
			answer = current
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
