import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

func parseInts(line string) []int64 {
	fields := strings.FieldsFunc(line, func(r rune) bool {
		return !(unicode.IsDigit(r) || r == '-')
	})

	values := make([]int64, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			values = append(values, value)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	lines := make([][]int64, 0, 3)
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 || len(lines[0]) == 0 {
		return
	}

	nums := lines[0]
	modulo := lines[1][0]
	k := lines[2][0]

	frequency := make(map[int64]int64)
	frequency[0] = 1

	var prefix, answer int64
	for _, num := range nums {
		if num%modulo == k {
			prefix = (prefix + 1) % modulo
		}

		required := (prefix - k + modulo) % modulo
		answer += frequency[required]
		frequency[prefix]++
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
