package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s, &k); err != nil {
		return
	}

	n := len(s)
	const inf = int(1e9)

	// cost[l][r] is the minimum changes needed to make s[l:r]
	// a semi-palindrome.
	cost := make([][]int, n)
	for i := range cost {
		cost[i] = make([]int, n+1)
	}

	for length := 2; length <= n; length++ {
		divisors := make([]int, 0)
		for d := 1; d < length; d++ {
			if length%d == 0 {
				divisors = append(divisors, d)
			}
		}

		for l := 0; l+length <= n; l++ {
			r := l + length
			best := inf

			for _, d := range divisors {
				groupLen := length / d
				changes := 0

				for rem := 0; rem < d; rem++ {
					for a, b := 0, groupLen-1; a < b; a, b = a+1, b-1 {
						if s[l+rem+a*d] != s[l+rem+b*d] {
							changes++
						}
					}
				}

				if changes < best {
					best = changes
				}
			}

			cost[l][r] = best
		}
	}

	// dp[parts][i] is the minimum cost to partition s[:i]
	// into exactly 'parts' semi-palindrome substrings.
	dp := make([][]int, k+1)
	for parts := range dp {
		dp[parts] = make([]int, n+1)
		for i := range dp[parts] {
			dp[parts][i] = inf
		}
	}
	dp[0][0] = 0

	for parts := 1; parts <= k; parts++ {
		for end := 2 * parts; end <= n; end++ {
			for start := 2 * (parts - 1); start <= end-2; start++ {
				if dp[parts-1][start] == inf {
					continue
				}
				value := dp[parts-1][start] + cost[start][end]
				if value < dp[parts][end] {
					dp[parts][end] = value
				}
			}
		}
	}

	fmt.Fprintln(out, dp[k][n])
}
