	nums := make([]int, 0)

	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	if n <= 1 {
		fmt.Println(0)
		return
	}

	positions := make(map[int]info)
	for i, value := range nums {
		if p, ok := positions[value]; ok {
			gap := i - p.last
			if gap > p.maxGap {
				p.maxGap = gap
			}
			p.last = i
			positions[value] = p
		} else {
			positions[value] = info{
				first: i,
				last:  i,
			}
		}
	}

	answer := n
	for _, p := range positions {
		circularGap := n - p.last + p.first
		if circularGap > p.maxGap {
			p.maxGap = circularGap
		}

		seconds := p.maxGap / 2
		if seconds < answer {
			answer = seconds
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
