		cyclicGap := n - last[value] + firstIndex
		if cyclicGap > maxGap[value] {
			maxGap[value] = cyclicGap
		}

		seconds := maxGap[value] / 2
		if seconds < answer {
			answer = seconds
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
