import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const mod int64 = 1_000_000_007

func countSteppingLE(bound string) int64 {
	var dp [2][11]int64
	dp[1][10] = 1 // 10 represents that the number has not started yet.

	for _, ch := range bound {
		limit := int(ch - '0')
		var next [2][11]int64

		for tight := 0; tight <= 1; tight++ {
			maxDigit := 9
			if tight == 1 {
				maxDigit = limit
			}

			for prev := 0; prev <= 10; prev++ {
				ways := dp[tight][prev]
				if ways == 0 {
					continue
				}

				for digit := 0; digit <= maxDigit; digit++ {
					nextTight := 0
					if tight == 1 && digit == limit {
						nextTight = 1
					}

					if prev == 10 {
						if digit == 0 {
							next[nextTight][10] = (next[nextTight][10] + ways) % mod
						} else {
							next[nextTight][digit] = (next[nextTight][digit] + ways) % mod
						}
					} else if digit-prev == 1 || prev-digit == 1 {
						next[nextTight][digit] = (next[nextTight][digit] + ways) % mod
					}
				}
			}
		}
		dp = next
	}

	var result int64
	for tight := 0; tight <= 1; tight++ {
		for lastDigit := 0; lastDigit <= 9; lastDigit++ {
			result = (result + dp[tight][lastDigit]) % mod
		}
	}
	return result
}

func decrement(number string) string {
	digits := []byte(number)
	i := len(digits) - 1

	for i >= 0 && digits[i] == '0' {
		digits[i] = '9'
		i--
	}
	if i >= 0 {
		digits[i]--
	}

	result := strings.TrimLeft(string(digits), "0")
	if result == "" {
		return "0"
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var low, high string
	fmt.Fscan(in, &low, &high)

	answer := (countSteppingLE(high) - countSteppingLE(decrement(low)) + mod) % mod
	fmt.Fprintln(out, answer)
}
