						}
					} else if d-prev == 1 || prev-d == 1 {
						next[nextTight][d] = (next[nextTight][d] + ways) % mod
					}
				}
			}
		}
		dp = next
	}

	var result int64
	for tight := 0; tight <= 1; tight++ {
		for prev := 0; prev < 10; prev++ {
