package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type pair struct {
	a, b int64
}

func parseInts(s string) []int64 {
	var values []int64
	for i := 0; i < len(s); {
		sign := int64(1)
		if s[i] == '-' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			sign = -1
			i++
		}
		if i >= len(s) || s[i] < '0' || s[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 {
		return
	}

	var nums1, nums2 []int64
	var x int64

	// Also accept an optional first line containing the array length.
	if len(lines) >= 4 && len(lines[0]) == 1 &&
		int(lines[0][0]) == len(lines[1]) &&
		len(lines[1]) == len(lines[2]) {
		nums1 = lines[1]
		nums2 = lines[2]
		x = lines[3][0]
	} else {
		nums1 = lines[0]
		nums2 = lines[1]
		x = lines[2][0]
	}

	n := len(nums1)
	pairs := make([]pair, n)
	var sum1, sum2 int64

	for i := 0; i < n; i++ {
		pairs[i] = pair{a: nums1[i], b: nums2[i]}
		sum1 += nums1[i]
		sum2 += nums2[i]
	}

	sort.Slice(pairs, func(i, j int) bool {
		return pairs[i].b < pairs[j].b
	})

	dp := make([]int64, n+1)
	for i, p := range pairs {
		for operations := i + 1; operations >= 1; operations-- {
			reduction := dp[operations-1] + p.a + int64(operations)*p.b
			if reduction > dp[operations] {
				dp[operations] = reduction
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for t := 0; t <= n; t++ {
		total := sum1 + int64(t)*sum2 - dp[t]
		if total <= x {
			fmt.Fprintln(writer, t)
			return
		}
	}

	fmt.Fprintln(writer, -1)
}
