func countBeautiful(n, k int) int64 {
	if n <= 0 {
		return 0
	}

	s := fmt.Sprintf("%d", n)
	digits := make([]int, len(s))
	for i := range s {
		digits[i] = int(s[i] - '0')
	}

	type state struct {
		pos, remainder, balance int
		started                bool
	}

	memo := make(map[state]int64)

	var dfs func(pos, remainder, balance int, started, tight bool) int64
	dfs = func(pos, remainder, balance int, started, tight bool) int64 {
		if pos == len(digits) {
			if started && remainder == 0 && balance == 0 {
				return 1
			}
			return 0
		}

		st := state{pos, remainder, balance, started}
		if !tight {
			if value, ok := memo[st]; ok {
				return value
			}
		}

		limit := 9
		if tight {
			limit = digits[pos]
		}

		var result int64
		for digit := 0; digit <= limit; digit++ {
			nextTight := tight && digit == limit

			if !started && digit == 0 {
				result += dfs(pos+1, 0, balance, false, nextTight)
				continue
			}

			nextBalance := balance
			if digit%2 == 0 {
				nextBalance++
			} else {
				nextBalance--
			}

			nextRemainder := (remainder*10 + digit) % k
			result += dfs(pos+1, nextRemainder, nextBalance, true, nextTight)
		}

		if !tight {
			memo[st] = result
		}
		return result
	}

	return dfs(0, 0, 0, false, true)
}

