package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

type Matrix struct {
	a00, a01 int64
	a10, a11 int64
}

func multiply(a, b Matrix) Matrix {
	return Matrix{
		a00: (a.a00*b.a00 + a.a01*b.a10) % mod,
		a01: (a.a00*b.a01 + a.a01*b.a11) % mod,
		a10: (a.a10*b.a00 + a.a11*b.a10) % mod,
		a11: (a.a10*b.a01 + a.a11*b.a11) % mod,
	}
}

func matrixPow(base Matrix, exp int64) Matrix {
	result := Matrix{a00: 1, a11: 1}
	for exp > 0 {
		if exp&1 == 1 {
			result = multiply(result, base)
		}
		base = multiply(base, base)
		exp >>= 1
	}
	return result
}

func countMatchingRotations(s, t string) int64 {
	n := len(s)

	prefix := make([]int, n)
	for i, j := 1, 0; i < n; i++ {
		for j > 0 && t[i] != t[j] {
			j = prefix[j-1]
		}
		if t[i] == t[j] {
			j++
		}
		prefix[i] = j
	}

	var matches int64
	j := 0
	for i := 0; i < 2*n-1; i++ {
		ch := s[i%n]
		for j > 0 && ch != t[j] {
			j = prefix[j-1]
		}
		if ch == t[j] {
			j++
		}
		if j == n {
			matches++
			j = prefix[j-1]
		}
	}
	return matches
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s, t string
	var k int64
	if _, err := fmt.Fscan(in, &s, &t, &k); err != nil {
		return
	}

	n := int64(len(s))
	totalMatches := countMatchingRotations(s, t)

	var zeroMatches int64
	if s == t {
		zeroMatches = 1
	}
	nonZeroMatches := totalMatches - zeroMatches

	transition := Matrix{
		a00: 0,
		a01: (n - 1) % mod,
		a10: 1,
		a11: (n - 2) % mod,
	}
	powered := matrixPow(transition, k)

	waysToZero := powered.a00
	waysToEachNonZero := powered.a10

	answer := (zeroMatches*waysToZero + nonZeroMatches*waysToEachNonZero) % mod
	fmt.Fprintln(out, answer)
}
