package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int, n+1)}
}

func (f *Fenwick) Add(index, delta int) {
	for i := index + 1; i < len(f.tree); i += i & -i {
		f.tree[i] += delta
	}
}

// Sum returns the sum of elements with zero-based indices in [0, end).
func (f *Fenwick) Sum(end int) int {
	result := 0
	for i := end; i > 0; i -= i & -i {
		result += f.tree[i]
	}
	return result
}

// Kth returns the zero-based index containing the k-th element, where k is 1-based.
func (f *Fenwick) Kth(k int) int {
	index := 0
	step := 1
	for step<<1 < len(f.tree) {
		step <<= 1
	}
	for step > 0 {
		next := index + step
		if next < len(f.tree) && f.tree[next] < k {
			index = next
			k -= f.tree[next]
		}
		step >>= 1
	}
	return index
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 2 {
		return
	}

	numFields := strings.Fields(lines[0])
	nums := make([]int64, len(numFields))
	for i, field := range numFields {
		value, _ := strconv.ParseInt(field, 10, 64)
		nums[i] = value
	}

	xFields := strings.Fields(lines[1])
	x, _ := strconv.Atoi(xFields[0])

	values := append([]int64(nil), nums...)
	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	unique := values[:0]
	for _, value := range values {
		if len(unique) == 0 || unique[len(unique)-1] != value {
			unique = append(unique, value)
		}
	}
	values = unique

	fenwick := NewFenwick(len(values))
	answer := int64(^uint64(0) >> 1)

	for i := x; i < len(nums); i++ {
		addValue := nums[i-x]
		addIndex := sort.Search(len(values), func(j int) bool {
			return values[j] >= addValue
		})
		fenwick.Add(addIndex, 1)

		current := nums[i]
		position := sort.Search(len(values), func(j int) bool {
			return values[j] >= current
		})

		beforeCount := fenwick.Sum(position)
		totalCount := fenwick.Sum(len(values))

		if beforeCount < totalCount {
			successorIndex := fenwick.Kth(beforeCount + 1)
			diff := abs64(current - values[successorIndex])
			if diff < answer {
				answer = diff
			}
		}

		upToCount := fenwick.Sum(position + 1)
		if upToCount > 0 {
			predecessorIndex := fenwick.Kth(upToCount)
			diff := abs64(current - values[predecessorIndex])
			if diff < answer {
				answer = diff
			}
		}

		if answer == 0 {
			break
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
