		fmt.Fprintln(out, -1)
		return
	}

	target := values[len(values)-1]
	nums := values[:len(values)-1]

	var total int64
	count := make([]int64, 64)

	for _, num := range nums {
		total += num
		for bit := 0; bit < len(count); bit++ {
			if num == int64(1)<<bit {
				count[bit]++
				break
			}
		}
	}

	if total < target {
		fmt.Fprintln(out, -1)
		return
	}

	operations := 0

	for bit := 0; bit <= 30; bit++ {
		if target&(int64(1)<<bit) != 0 {
			if count[bit] == 0 {
				higher := bit + 1
				for higher < len(count) && count[higher] == 0 {
					higher++
				}

				if higher == len(count) {
					fmt.Fprintln(out, -1)
					return
