		}
		return intervals[i].start < intervals[j].start
	})

	total := 0
	start, end := intervals[0].start, intervals[0].end

	for i := 1; i < n; i++ {
		if intervals[i].start <= end+1 {
			if intervals[i].end > end {
				end = intervals[i].end
			}
		} else {
			total += end - start + 1
			start, end = intervals[i].start, intervals[i].end
		}
	}
	total += end - start + 1

	fmt.Fprintln(out, total)
