	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	var receiver []int
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 {
			continue
		}
		receiver = make([]int, len(fields))
		for i, field := range fields {
			receiver[i], _ = strconv.Atoi(field)
		}
		break
	}

	var k int64
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 {
			continue
		}
		k, _ = strconv.ParseInt(fields[0], 10, 64)
		break
	}

	n := len(receiver)
	jump := make([]int, n)
	sum := make([]int64, n)
	position := make([]int, n)
	total := make([]int64, n)

	for i := 0; i < n; i++ {
		jump[i] = receiver[i]
		sum[i] = int64(receiver[i])
		position[i] = i
		total[i] = int64(i)
	}

	remaining := k
	for remaining > 0 {
		if remaining&1 == 1 {
			for i := 0; i < n; i++ {
				p := position[i]
				total[i] += sum[p]
				position[i] = jump[p]
			}
		}

		remaining >>= 1
		if remaining == 0 {
			break
		}

		nextJump := make([]int, n)
		nextSum := make([]int64, n)
		for i := 0; i < n; i++ {
			mid := jump[i]
			nextJump[i] = jump[mid]
			nextSum[i] = sum[i] + sum[mid]
		}
		jump, sum = nextJump, nextSum
	}

	answer := total[0]
	for i := 1; i < n; i++ {
		if total[i] > answer {
			answer = total[i]
		}
	}

