		values := parseInts(line)
		if len(values) == 0 {
			continue
		}
		if nums == nil {
			nums = values
		} else {
			k = values[0]
			break
		}
	}

	collected := make([]bool, k+1)
	remaining := k
	operations := 0

	for i := len(nums) - 1; i >= 0; i-- {
		operations++
		value := nums[i]
		if value >= 1 && value <= k && !collected[value] {
