				deletions := n - i - 2
				if deletions < answer {
					answer = deletions
				}
			}
		}
	}

	// Keeping any single zero also produces the special number 0.
	for i := 0; i < n; i++ {
		if num[i] == '0' {
			if n-1 < answer {
				answer = n - 1
			}
			break
		}
	}

	// Deleting every digit produces 0.
	if n < answer {
		answer = n
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
