	"fmt"
	"io"
	"math/bits"
	"os"
)

func parseNumbers(data []byte) []int64 {
	var numbers []int64
	for i := 0; i < len(data); {
		if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		numbers = append(numbers, value)
	}
	return numbers
}

func minimumOperations(nums []int64, target int64) int {
	var total int64
	count := make([]int, 33)

	for _, num := range nums {
		total += num
		bit := bits.TrailingZeros64(uint64(num))
		count[bit]++
	}

	if total < target {
		return -1
	}

	operations := 0

	for i := 0; i <= 30; i++ {
		if target&(int64(1)<<i) != 0 {
			if count[i] > 0 {
				count[i]--
			} else {
				j := i + 1
				for j < len(count) && count[j] == 0 {
					j++
				}
				if j == len(count) {
					return -1
				}

				for j > i {
					count[j]--
					count[j-1] += 2
					operations++
					j--
				}
				count[i]--
			}
		}

		count[i+1] += count[i] / 2
	}

	return operations
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	values := parseNumbers(data)
	if len(values) < 2 {
		return
	}

	nums := values[:len(values)-1]
	target := values[len(values)-1]

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	fmt.Fprintln(writer, minimumOperations(nums, target))
}
