func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s1, s2 string
	var x int
	if _, err := fmt.Fscan(in, &s1, &s2, &x); err != nil {
		return
	}

	mismatches := make([]int, 0)
	for i := 0; i < len(s1); i++ {
		if s1[i] != s2[i] {
			mismatches = append(mismatches, i)
		}
	}

	m := len(mismatches)
	if m%2 == 1 {
		fmt.Fprintln(out, -1)
		return
	}
	if m == 0 {
		fmt.Fprintln(out, 0)
		return
	}

	// Costs are doubled to allow assigning half of an arbitrary-pair
	// operation's cost to each mismatched position.
	dp := make([]int, m+1)
	dp[1] = x

	for i := 2; i <= m; i++ {
		arbitrary := dp[i-1] + x
		adjacent := dp[i-2] + 2*(mismatches[i-1]-mismatches[i-2])
		if arbitrary < adjacent {
			dp[i] = arbitrary
		} else {
			dp[i] = adjacent
		}
	}

	fmt.Fprintln(out, dp[m]/2)
}
