func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int64
	var x int64
	for {
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	if n == 0 {
		return
	}

	spf := make([]int, n+1)
	for i := 2; i <= n; i++ {
		if spf[i] == 0 {
			spf[i] = i
			if i <= n/i {
				for j := i * i; j <= n; j += i {
					if spf[j] == 0 {
						spf[j] = i
					}
				}
			}
		}
	}

	sums := make(map[int]int64)
	var answer int64

	for i := 1; i <= n; i++ {
		value := i
		kernel := 1

		for value > 1 {
			p := spf[value]
			count := 0
			for value%p == 0 {
				value /= p
				count++
			}
			if count%2 == 1 {
				kernel *= p
			}
		}

		sums[kernel] += nums[i-1]
		if sums[kernel] > answer {
			answer = sums[kernel]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
