)

func squareFreePart(x int) int {
	result := 1
	for p := 2; p*p <= x; p++ {
		odd := false
		for x%p == 0 {
			x /= p
			odd = !odd
		}
		if odd {
			result *= p
		}
	}
	if x > 1 {
		result *= x
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	sums := make(map[int]int64)
	var answer int64

	for i, value := range nums {
		key := squareFreePart(i + 1)
		sums[key] += value
		if sums[key] > answer {
			answer = sums[key]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
