)

const mod int64 = 1_000_000_007

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	values := make([]int, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') {
			i++
		}
		if i >= len(data) {
			break
		}

		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		values = append(values, value)
	}

	if len(values) < 3 {
		return
	}

	l := values[len(values)-2]
	r := values[len(values)-1]
	nums := values[:len(values)-2]

	frequencies := make(map[int]int)
	for _, value := range nums {
		frequencies[value]++
	}

	dp := make([]int64, r+1)
	dp[0] = 1

	if zeroCount := frequencies[0]; zeroCount > 0 {
		dp[0] = int64(zeroCount + 1)
		delete(frequencies, 0)
	}

	for value, count := range frequencies {
		if value > r {
			continue
		}

		next := make([]int64, r+1)
		for remainder := 0; remainder < value && remainder <= r; remainder++ {
			var window int64
			for sum := remainder; sum <= r; sum += value {
				window += dp[sum]
				if window >= mod {
					window -= mod
				}

				removed := sum - (count+1)*value
				if removed >= 0 {
					window -= dp[removed]
					if window < 0 {
						window += mod
					}
				}
				next[sum] = window
			}
		}
		dp = next
	}

	var answer int64
	for sum := l; sum <= r; sum++ {
		answer += dp[sum]
		if answer >= mod {
			answer -= mod
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
