	n := len(maxHeights)
	if n == 0 {
		return
	}

	left := make([]int64, n)
	right := make([]int64, n)
	stack := make([]int, 0, n)

	for i := 0; i < n; i++ {
		for len(stack) > 0 && maxHeights[stack[len(stack)-1]] > maxHeights[i] {
			stack = stack[:len(stack)-1]
		}

		if len(stack) == 0 {
			left[i] = int64(i+1) * maxHeights[i]
		} else {
			j := stack[len(stack)-1]
			left[i] = left[j] + int64(i-j)*maxHeights[i]
		}
		stack = append(stack, i)
	}

	stack = stack[:0]
	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && maxHeights[stack[len(stack)-1]] > maxHeights[i] {
			stack = stack[:len(stack)-1]
		}

		if len(stack) == 0 {
			right[i] = int64(n-i) * maxHeights[i]
		} else {
			j := stack[len(stack)-1]
			right[i] = right[j] + int64(j-i)*maxHeights[i]
		}
		stack = append(stack, i)
	}

