func parseLine(line string) []int64 {
	fields := strings.Fields(line)
	values := make([]int64, 0, len(fields))
	for _, field := range fields {
		v, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			values = append(values, v)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	var processorTime, tasks []int64

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if processorTime == nil {
			processorTime = parseLine(line)
		} else {
			tasks = append(tasks, parseLine(line)...)
		}
	}

	sort.Slice(processorTime, func(i, j int) bool {
		return processorTime[i] < processorTime[j]
	})
	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i] > tasks[j]
	})

	var answer int64
	for i, availableAt := range processorTime {
		finishTime := availableAt + tasks[4*i]
		if finishTime > answer {
			answer = finishTime
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
