	if err != nil {
		return
	}

	values := make([]int64, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, value*sign)
	}

	if len(values) < 2 {
		return
	}

	k := int(values[len(values)-1])
	nums := values[:len(values)-1]

	var bitCount [31]int
	for _, num := range nums {
		for bit := 0; bit < 31; bit++ {
			if num&(int64(1)<<bit) != 0 {
				bitCount[bit]++
			}
		}
	}

	var answer int64
	for i := 0; i < k; i++ {
		var value int64
		for bit := 0; bit < 31; bit++ {
			if bitCount[bit] > 0 {
				value |= int64(1) << bit
				bitCount[bit]--
			}
		}
		value %= mod
		answer = (answer + value*value) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
