package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func parseInts(s string) []int {
	result := make([]int, 0)
	value := 0
	inNumber := false

	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			inNumber = true
		} else if inNumber {
			result = append(result, value)
			value = 0
			inNumber = false
		}
	}
	if inNumber {
		result = append(result, value)
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	lines := make([][]int, 0)
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}
	if len(lines) < 2 {
		return
	}

	var nums []int
	var remaining []int

	// Also support an optional first line containing the array length.
	if len(lines) >= 4 && len(lines[0]) == 1 && lines[0][0] == len(lines[1]) {
		nums = lines[1]
		for i := 2; i < len(lines); i++ {
			remaining = append(remaining, lines[i]...)
		}
	} else {
		nums = lines[0]
		for i := 1; i < len(lines); i++ {
			remaining = append(remaining, lines[i]...)
		}
	}

	if len(remaining) < 2 {
		return
	}
	l, r := remaining[0], remaining[1]

	counts := make(map[int]int)
	for _, value := range nums {
		counts[value]++
	}

	dp := make([]int64, r+1)
	dp[0] = int64(counts[0]+1) % mod

	for value, count := range counts {
		if value == 0 || value > r {
			continue
		}

		next := make([]int64, r+1)

		for remainder := 0; remainder < value && remainder <= r; remainder++ {
			var window int64

			for sum := remainder; sum <= r; sum += value {
				window += dp[sum]
				if window >= mod {
					window -= mod
				}

				remove := sum - (count+1)*value
				if remove >= 0 {
					window -= dp[remove]
					if window < 0 {
						window += mod
					}
				}

				next[sum] = window
			}
		}

		dp = next
	}

	var answer int64
	for sum := l; sum <= r; sum++ {
		answer += dp[sum]
		if answer >= mod {
			answer -= mod
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
