			i++
		}
		values = append(values, value)
	}

	if len(values) < 2 {
		return
	}

	k := int(values[len(values)-1])
	nums := values[:len(values)-1]

	var bitCount [31]int
	for _, num := range nums {
		for bit := 0; bit < 31; bit++ {
			if num&(int64(1)<<bit) != 0 {
				bitCount[bit]++
			}
		}
	}

	var answer int64
	for i := 0; i < k; i++ {
		var value int64
		for bit := 0; bit < 31; bit++ {
			if bitCount[bit] > 0 {
				value |= int64(1) << bit
				bitCount[bit]--
			}
		}

		value %= mod
		answer = (answer + value*value) % mod
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
