	var total int64
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err != nil {
			return
		}
		nums = append(nums, value)
		total += value
	}

	targetField := strings.Fields(lines[1])
	if len(targetField) == 0 {
		return
	}
	target, err := strconv.ParseInt(targetField[0], 10, 64)
	if err != nil {
		return
	}

	n := len(nums)
	fullCycles := target / total
	remainder := target % total

	if remainder == 0 {
		fmt.Println(fullCycles * int64(n))
		return
	}

	left := 0
	var sum int64
	minLength := n + 1

	for right := 0; right < 2*n; right++ {
		sum += nums[right%n]

		for left <= right && (sum > remainder || right-left+1 > n) {
			sum -= nums[left%n]
			left++
		}

		if sum == remainder && right-left+1 < minLength {
			minLength = right - left + 1
		}
	}

	if minLength == n+1 {
		fmt.Println(-1)
		return
	}

