	line = strings.NewReplacer("[", " ", "]", " ", ",", " ").Replace(line)
	fields := strings.Fields(line)

	var minSum, zeroCount int64
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err != nil {
			continue
		}
		if value == 0 {
			zeroCount++
			minSum++
		} else {
			minSum += value
		}
	}
	return minSum, zeroCount
}

func main() {
