	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
			if len(lines) == 2 {
				break
			}
		}
	}

	if len(lines) < 2 {
		return
	}

	sum1, zeros1 := parseArray(lines[0])
	sum2, zeros2 := parseArray(lines[1])

	var answer int64
	switch {
	case sum1 == sum2:
		answer = sum1
	case sum1 < sum2:
		if zeros1 == 0 {
			answer = -1
		} else {
			answer = sum2
		}
	default:
		if zeros2 == 0 {
			answer = -1
		} else {
			answer = sum1
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
