func readArray(scanner *bufio.Scanner) ([]int64, bool) {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		fields := strings.Fields(line)
		nums := make([]int64, 0, len(fields))
		for _, field := range fields {
			n, err := strconv.ParseInt(field, 10, 64)
			if err != nil {
				return nil, false
			}
			nums = append(nums, n)
		}
		return nums, true
	}
	return nil, false
}

func minimumSum(nums []int64) (sum int64, zeros int64) {
	for _, n := range nums {
		if n == 0 {
			zeros++
			sum++
		} else {
			sum += n
		}
	}
	return sum, zeros
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	nums1, ok1 := readArray(scanner)
	nums2, ok2 := readArray(scanner)
	if !ok1 || !ok2 {
		return
	}

	sum1, zeros1 := minimumSum(nums1)
	sum2, zeros2 := minimumSum(nums2)

	var answer int64
	if sum1 < sum2 {
		if zeros1 == 0 {
			answer = -1
		} else {
			answer = sum2
		}
	} else if sum2 < sum1 {
		if zeros2 == 0 {
			answer = -1
		} else {
			answer = sum1
		}
	} else {
		answer = sum1
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
