type Fenwick struct {
	tree []int64
}

func (f *Fenwick) Update(i int, value int64) {
	for i < len(f.tree) {
		if value > f.tree[i] {
			f.tree[i] = value
		}
		i += i & -i
	}
}

func (f *Fenwick) Query(i int) int64 {
	var best int64
	for i > 0 {
		if f.tree[i] > best {
			best = f.tree[i]
		}
		i -= i & -i
	}
	return best
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var nums []int64
