		return
	}

	keys := make([]int64, len(nums))
	sortedKeys := make([]int64, len(nums))
	for i, x := range nums {
		keys[i] = x - int64(i)
		sortedKeys[i] = keys[i]
	}

	sort.Slice(sortedKeys, func(i, j int) bool {
		return sortedKeys[i] < sortedKeys[j]
	})

	unique := sortedKeys[:0]
	for _, x := range sortedKeys {
		if len(unique) == 0 || unique[len(unique)-1] != x {
			unique = append(unique, x)
		}
	}

	fenwick := Fenwick{tree: make([]int64, len(unique)+1)}
	answer := int64(-1 << 63)

	for i, x := range nums {
		position := sort.Search(len(unique), func(j int) bool {
