type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt64() (int64, bool) {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] == ' ' || fs.data[fs.pos] == '\n' || fs.data[fs.pos] == '\r' || fs.data[fs.pos] == '\t') {
		fs.pos++
	}
	if fs.pos >= len(fs.data) {
		return 0, false
	}

	sign := int64(1)
	if fs.data[fs.pos] == '-' {
		sign = -1
		fs.pos++
	}

	var value int64
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		value = value*10 + int64(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return value * sign, true
}

type FenwickMax struct {
	tree []int64
}

func NewFenwickMax(n int) *FenwickMax {
	return &FenwickMax{tree: make([]int64, n+1)}
}

func (f *FenwickMax) Update(index int, value int64) {
	for index < len(f.tree) {
		if value > f.tree[index] {
			f.tree[index] = value
		}
		index += index & -index
	}
}

func (f *FenwickMax) Query(index int) int64 {
	var result int64
	for index > 0 {
		if f.tree[index] > result {
			result = f.tree[index]
		}
		index -= index & -index
	}
	return result
}

func main() {
	in := NewFastScanner()

	var nums []int64
	for {
		value, ok := in.NextInt64()
		if !ok {
			break
		}
		nums = append(nums, value)
	}

	if len(nums) == 0 {
		return
	}

	keys := make([]int64, len(nums))
	for i, value := range nums {
		keys[i] = value - int64(i)
	}

	sortedKeys := append([]int64(nil), keys...)
	sort.Slice(sortedKeys, func(i, j int) bool {
		return sortedKeys[i] < sortedKeys[j]
	})

	unique := sortedKeys[:0]
	for _, key := range sortedKeys {
		if len(unique) == 0 || unique[len(unique)-1] != key {
			unique = append(unique, key)
		}
	}

	fenwick := NewFenwickMax(len(unique))
	answer := nums[0]

	for i, value := range nums {
		position := sort.Search(len(unique), func(j int) bool {
			return unique[j] >= keys[i]
		}) + 1

		bestPrevious := fenwick.Query(position)
		current := value + bestPrevious

		if current > answer {
			answer = current
		}
		fenwick.Update(position, current)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
