	"fmt"
	"os"
)

const mod uint64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var a, b uint64
	var n int
	if _, err := fmt.Fscan(in, &a, &b, &n); err != nil {
		return
	}

	// Bits at positions n and above cannot be changed by x.
	xorA := (a >> n) << n
	xorB := (b >> n) << n

	for i := n - 1; i >= 0; i-- {
		bit := uint64(1) << i
		aBit := a & bit
		bBit := b & bit

		if aBit == bBit {
			// Choose x's bit so both resulting bits become 1.
			xorA |= bit
			xorB |= bit
		} else if xorA <= xorB {
			// Assign the available 1-bit to the currently smaller value.
			xorA |= bit
		} else {
			xorB |= bit
		}
	}

	answer := (xorA % mod) * (xorB % mod) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
