	"sort"
)

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	values := make([]int64, 0)
	var value int64
	var sign int64 = 1
	inNumber := false

	for _, ch := range data {
		if ch == '-' {
			sign = -1
		} else if ch >= '0' && ch <= '9' {
			value = value*10 + int64(ch-'0')
			inNumber = true
		} else if inNumber {
			values = append(values, sign*value)
			value = 0
			sign = 1
			inNumber = false
		}
	}
	if inNumber {
		values = append(values, sign*value)
	}

	if len(values) < 2 {
		return
	}

	k := values[len(values)-1]
	nums := values[:len(values)-1]
	sort.Slice(nums, func(i, j int) bool {
		return nums[i] < nums[j]
	})

	n := len(nums)
	prefix := make([]int64, n+1)
	for i, x := range nums {
		prefix[i+1] = prefix[i] + x
	}

	cost := func(left, right int) int64 {
		mid := (left + right) / 2
		median := nums[mid]

		leftCost := median*int64(mid-left) - (prefix[mid] - prefix[left])
		rightCost := (prefix[right+1] - prefix[mid+1]) -
			median*int64(right-mid)

		return leftCost + rightCost
	}

	best, left := 1, 0
	for right := 0; right < n; right++ {
		for left <= right && cost(left, right) > k {
			left++
		}
		if right-left+1 > best {
			best = right - left + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
}
