		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	if n == 0 {
		return
	}

	prefix := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		prefix[i] = prefix[i-1] + nums[i-1]
	}

	dp := make([]int, n+1)
	lastSum := make([]int64, n+1)
	queue := make([]int, 1, n+1)
	queue[0] = 0
	head := 0

	for i := 1; i <= n; i++ {
		for len(queue)-head >= 2 {
			next := queue[head+1]
			if prefix[next]+lastSum[next] > prefix[i] {
				break
			}
			head++
		}

		j := queue[head]
		dp[i] = dp[j] + 1
		lastSum[i] = prefix[i] - prefix[j]
		threshold := prefix[i] + lastSum[i]

		for len(queue) > head {
			back := queue[len(queue)-1]
			if prefix[back]+lastSum[back] < threshold {
				break
			}
			queue = queue[:len(queue)-1]
		}
		queue = append(queue, i)
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, dp[n])
	out.Flush()
}
