package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type pair struct {
	value int
	index int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var values []int
	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		values = append(values, x)
	}

	if len(values) < 2 {
		return
	}

	limit := values[len(values)-1]
	nums := values[:len(values)-1]
	n := len(nums)

	pairs := make([]pair, n)
	for i, value := range nums {
		pairs[i] = pair{value: value, index: i}
	}

	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].value == pairs[j].value {
			return pairs[i].index < pairs[j].index
		}
		return pairs[i].value < pairs[j].value
	})

	result := make([]int, n)

	for start := 0; start < n; {
		end := start + 1
		for end < n && pairs[end].value-pairs[end-1].value <= limit {
			end++
		}

		indices := make([]int, end-start)
		for i := start; i < end; i++ {
			indices[i-start] = pairs[i].index
		}
		sort.Ints(indices)

		for i := 0; i < len(indices); i++ {
			result[indices[i]] = pairs[start+i].value
		}

