package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

type pair struct {
	value int64
	index int
}

func parseIntegers(line string) []int64 {
	fields := strings.FieldsFunc(line, func(r rune) bool {
		return !unicode.IsDigit(r) && r != '-'
	})

	result := make([]int64, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			result = append(result, value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseIntegers(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 2 || len(lines[0]) == 0 || len(lines[1]) == 0 {
		return
	}

	nums := lines[0]
	limit := lines[1][0]
	n := len(nums)

	pairs := make([]pair, n)
	for i, value := range nums {
		pairs[i] = pair{value: value, index: i}
	}

	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].value == pairs[j].value {
			return pairs[i].index < pairs[j].index
		}
		return pairs[i].value < pairs[j].value
	})

	answer := make([]int64, n)

	for start := 0; start < n; {
		end := start + 1
		for end < n && pairs[end].value-pairs[end-1].value <= limit {
			end++
		}

		indices := make([]int, end-start)
		for i := start; i < end; i++ {
			indices[i-start] = pairs[i].index
		}
		sort.Ints(indices)

		for i, index := range indices {
			answer[index] = pairs[start+i].value
		}

		start = end
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, value)
	}
	fmt.Fprintln(writer)
}
