func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	n := len(s)
	m := n / 2

	prefixA := make([][26]int32, m+1)
	prefixB := make([][26]int32, m+1)
	mismatch := make([]int, m+1)

	for i := 0; i < m; i++ {
		prefixA[i+1] = prefixA[i]
		prefixB[i+1] = prefixB[i]

		a := s[i] - 'a'
		b := s[n-1-i] - 'a'
		prefixA[i+1][a]++
		prefixB[i+1][b]++

		mismatch[i+1] = mismatch[i]
		if a != b {
			mismatch[i+1]++
		}
	}

	rangeMismatch := func(l, r int) int {
		if l > r {
			return 0
		}
		return mismatch[r+1] - mismatch[l]
	}

	var q int
	fmt.Fscan(in, &q)

	for queryIndex := 0; queryIndex < q; queryIndex++ {
		var a, b, c, d int
		fmt.Fscan(in, &a, &b, &c, &d)

		// Map the interval in the second half onto the reversed second half.
		l2 := n - 1 - d
		r2 := n - 1 - c

		interL := a
		if l2 > interL {
			interL = l2
		}
		interR := b
		if r2 < interR {
			interR = r2
		}

		coveredMismatches := rangeMismatch(a, b) + rangeMismatch(l2, r2)
		if interL <= interR {
			coveredMismatches -= rangeMismatch(interL, interR)
		}

		ok := coveredMismatches == mismatch[m]

		if ok {
			for ch := 0; ch < 26; ch++ {
				countAI := prefixA[b+1][ch] - prefixA[a][ch]
				countBJ := prefixB[r2+1][ch] - prefixB[l2][ch]

				countBI := prefixB[b+1][ch] - prefixB[a][ch]
				countAJ := prefixA[r2+1][ch] - prefixA[l2][ch]

				var countBK, countAK int32
				if interL <= interR {
					countBK = prefixB[interR+1][ch] - prefixB[interL][ch]
					countAK = prefixA[interR+1][ch] - prefixA[interL][ch]
				}

				requiredFromA := countBI - countBK
				requiredFromB := countAJ - countAK

				remainingA := countAI - requiredFromA
				remainingB := countBJ - requiredFromB

				if remainingA < 0 || remainingB < 0 || remainingA != remainingB {
					ok = false
					break
				}
			}
		}

		if queryIndex > 0 {
			fmt.Fprint(out, " ")
		}
		if ok {
			fmt.Fprint(out, "true")
