const mod int64 = 1_000_000_007

func modPow(base, exp int64) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	sick := make([]int, 0)
	for {
		var position int
		if _, err := fmt.Fscan(in, &position); err != nil {
			break
		}
		sick = append(sick, position)
	}

	healthy := n - len(sick)

	fact := make([]int64, healthy+1)
	invFact := make([]int64, healthy+1)
	fact[0] = 1
	for i := 1; i <= healthy; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	invFact[healthy] = modPow(fact[healthy], mod-2)
	for i := healthy; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	answer := fact[healthy]

	leftGap := sick[0]
	answer = answer * invFact[leftGap] % mod

	internalPower := 0
	for i := 1; i < len(sick); i++ {
		gap := sick[i] - sick[i-1] - 1
		answer = answer * invFact[gap] % mod
		if gap > 0 {
			internalPower += gap - 1
		}
	}

	rightGap := n - 1 - sick[len(sick)-1]
	answer = answer * invFact[rightGap] % mod
	answer = answer * modPow(2, int64(internalPower)) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
