package main

import (
	"bufio"
	"fmt"
	"os"
)

func countComplete(segment string, k int) int64 {
	n := len(segment)
	var result int64

	for distinctTarget := 1; distinctTarget <= 26; distinctTarget++ {
		windowSize := distinctTarget * k
		if windowSize > n {
			break
		}

		var counts [26]int
		distinct := 0
		exactK := 0

		add := func(ch byte) {
			idx := int(ch - 'a')
			old := counts[idx]
			if old == 0 {
				distinct++
			}
			if old == k {
				exactK--
			}
			counts[idx]++
			if counts[idx] == k {
				exactK++
			}
		}

		remove := func(ch byte) {
			idx := int(ch - 'a')
			old := counts[idx]
			if old == k {
				exactK--
			}
			counts[idx]--
			if counts[idx] == k {
				exactK++
			}
			if counts[idx] == 0 {
				distinct--
			}
		}

		for right := 0; right < n; right++ {
			add(segment[right])

			if right >= windowSize {
				remove(segment[right-windowSize])
			}

			if right+1 >= windowSize &&
				distinct == distinctTarget &&
				exactK == distinctTarget {
				result++
			}
		}
	}

	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var word string
	var k int
	if _, err := fmt.Fscan(in, &word, &k); err != nil {
		return
	}

	var answer int64
	start := 0

	for i := 1; i <= len(word); i++ {
		if i == len(word) || abs(int(word[i])-int(word[i-1])) > 2 {
			answer += countComplete(word[start:i], k)
			start = i
		}
	}

	fmt.Fprintln(out, answer)
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
