func countSegment(word string, start, end, k int) int64 {
	length := end - start
	var result int64

	for distinct := 1; distinct <= 26 && distinct*k <= length; distinct++ {
		windowSize := distinct * k
		var counts [26]int
		exactK := 0

		add := func(index int) {
			c := int(word[index] - 'a')
			if counts[c] == k {
				exactK--
			}
			counts[c]++
			if counts[c] == k {
				exactK++
			}
		}

		remove := func(index int) {
			c := int(word[index] - 'a')
			if counts[c] == k {
				exactK--
			}
			counts[c]--
			if counts[c] == k {
				exactK++
			}
		}

		for i := start; i < start+windowSize; i++ {
			add(i)
		}
		if exactK == distinct {
			result++
		}

		for right := start + windowSize; right < end; right++ {
			remove(right - windowSize)
			add(right)
			if exactK == distinct {
				result++
			}
		}
	}

	return result
