package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

type State struct {
	threshold int64
	dp        int
	prefix    int64
}

type MinHeap []State

func (h MinHeap) Len() int { return len(h) }
func (h MinHeap) Less(i, j int) bool {
	return h[i].threshold < h[j].threshold
}
func (h MinHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x any) {
	*h = append(*h, x.(State))
}

func (h *MinHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func readNumbers() []int64 {
	data, _ := io.ReadAll(os.Stdin)
	nums := make([]int64, 0)

	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		found := false
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
			found = true
		}
		if found {
			nums = append(nums, sign*value)
		}
	}
	return nums
}

func main() {
	nums := readNumbers()
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(nums) == 0 {
		fmt.Fprintln(out, 0)
		return
	}

	h := &MinHeap{}
	heap.Init(h)
	heap.Push(h, State{threshold: 0, dp: 0, prefix: 0})

	var prefix int64
	bestDP := -1
	var bestPrefix int64
	answer := 0

	for _, num := range nums {
		prefix += num

		for h.Len() > 0 && (*h)[0].threshold <= prefix {
			state := heap.Pop(h).(State)
			if state.dp > bestDP || (state.dp == bestDP && state.prefix > bestPrefix) {
				bestDP = state.dp
				bestPrefix = state.prefix
			}
		}

		answer = bestDP + 1
		lastSum := prefix - bestPrefix

		heap.Push(h, State{
			threshold: prefix + lastSum,
			dp:        answer,
			prefix:    prefix,
		})
	}

	fmt.Fprintln(out, answer)
}
