package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

func parseIntegers(data []byte) []int {
	nums := make([]int, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') {
			i++
		}
		if i >= len(data) {
			break
		}
		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		nums = append(nums, value)
	}
	return nums
}

func power10(exp int) int {
	result := 1
	for i := 0; i < exp; i++ {
		result *= 10
	}
	return result
}

func makePalindrome(prefix, length int) int {
	result := prefix
	if length%2 == 1 {
		prefix /= 10
	}
	for prefix > 0 {
		result = result*10 + prefix%10
		prefix /= 10
	}
	return result
}

func generatePalindromes() []int {
	palindromes := make([]int, 0, 110000)
	for length := 1; length <= 9; length++ {
		halfLength := (length + 1) / 2
		start := power10(halfLength - 1)
		end := power10(halfLength)
		for prefix := start; prefix < end; prefix++ {
			p := makePalindrome(prefix, length)
			if p < 1_000_000_000 {
				palindromes = append(palindromes, p)
			}
		}
	}
	return palindromes
}

func totalCost(nums []int, target int) int64 {
	var cost int64
	for _, value := range nums {
		diff := int64(value) - int64(target)
		if diff < 0 {
			diff = -diff
		}
		cost += diff
	}
	return cost
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := parseIntegers(data)
	if len(nums) == 0 {
		return
	}

	sort.Ints(nums)
	median := nums[(len(nums)-1)/2]
	palindromes := generatePalindromes()

	index := sort.SearchInts(palindromes, median)
	best := int64(^uint64(0) >> 1)

	if index < len(palindromes) {
		best = totalCost(nums, palindromes[index])
	}
	if index > 0 {
		cost := totalCost(nums, palindromes[index-1])
		if cost < best {
			best = cost
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
}
