}

func power10(exp int) int {
	result := 1
	for ; exp > 0; exp-- {
		result *= 10
	}
	return result
}

func makePalindrome(prefix int, oddLength bool) int {
	result := prefix
	if oddLength {
		prefix /= 10
	}
	for prefix > 0 {
		result = result*10 + prefix%10
		prefix /= 10
	}
	return result
}

func generatePalindromes() []int {
	palindromes := make([]int, 0, 110000)

	for length := 1; length <= 9; length++ {
		halfLength := (length + 1) / 2
		start := power10(halfLength - 1)
		end := power10(halfLength)

		for prefix := start; prefix < end; prefix++ {
			palindrome := makePalindrome(prefix, length%2 == 1)
			if palindrome < 1_000_000_000 {
				palindromes = append(palindromes, palindrome)
			}
		}
	}

	return palindromes
}

