	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var x, y int
	fmt.Fscan(in, &x, &y)

	if x == y {
		fmt.Fprintln(out, 0)
		return
	}

	// A direct sequence of increments/decrements takes |x-y| operations,
	// so no optimal path needs to exceed this reachable-state bound.
	limit := x
	if x > y {
		limit += x - y
	} else {
		limit = y
	}

	dist := make([]int, limit+1)
	for i := range dist {
		dist[i] = -1
	}

	queue := make([]int, 0, limit+1)
	queue = append(queue, x)
	dist[x] = 0

	for head := 0; head < len(queue); head++ {
		cur := queue[head]
		nextDist := dist[cur] + 1

		nextValues := [4]int{-1, -1, -1, -1}
		count := 0

		if cur > 0 {
			nextValues[count] = cur - 1
			count++
		}
		if cur < limit {
			nextValues[count] = cur + 1
			count++
		}
		if cur%5 == 0 {
			nextValues[count] = cur / 5
			count++
		}
		if cur%11 == 0 {
			nextValues[count] = cur / 11
			count++
		}

		for i := 0; i < count; i++ {
			next := nextValues[i]
			if dist[next] != -1 {
				continue
			}

			dist[next] = nextDist
			if next == y {
				fmt.Fprintln(out, nextDist)
				return
			}
			queue = append(queue, next)
		}
	}
}
