func totalPrice(n, limit uint64, x int) uint64 {
	total := uint64(0)
	count := n + 1 // Include 0; it contributes no set bits.

	for bit := x - 1; bit <= 60; bit += x {
		half := uint64(1) << bit
		cycle := half << 1

		ones := (count / cycle) * half
		remainder := count % cycle
		if remainder > half {
			ones += remainder - half
		}

		if ones > limit-total {
			return limit + 1
		}
		total += ones
	}

	return total
}

