func totalPrice(n, k uint64, x uint) uint64 {
	totalNumbers := n + 1
	var sum uint64

	for position := x; position <= 63; position += x {
		bit := position - 1
		halfCycle := uint64(1) << bit

		if halfCycle >= totalNumbers {
			break
		}

		cycle := halfCycle << 1
		fullCycles := totalNumbers / cycle
		remainder := totalNumbers % cycle

		ones := fullCycles * halfCycle
		if remainder > halfCycle {
			ones += remainder - halfCycle
		}

		sum += ones
		if sum > k {
			return k + 1
		}
	}

	return sum
}

