	high := uint64(1)

	for totalPrice(high, k, x) <= k {
		high *= 2
	}

	for low+1 < high {
		mid := low + (high-low)/2
		if totalPrice(mid, k, x) <= k {
			low = mid
		} else {
			high = mid
		}
	}

