import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func countExactLength(length int, upper, suffix string, limit int) int64 {
	suffixStart := length - len(suffix)
	var dp [2]int64
	dp[1] = 1

	for pos := 0; pos < length; pos++ {
		var next [2]int64
		upperDigit := int(upper[pos] - '0')

		for tight := 0; tight <= 1; tight++ {
			if dp[tight] == 0 {
				continue
			}

			low, high := 0, limit
			if pos == 0 {
				low = 1
			}

			if pos >= suffixStart {
				digit := int(suffix[pos-suffixStart] - '0')
				if digit < low || digit > high {
					continue
				}
				if tight == 1 && digit > upperDigit {
					continue
				}

				newTight := 0
				if tight == 1 && digit == upperDigit {
					newTight = 1
				}
				next[newTight] += dp[tight]
				continue
			}

			for digit := low; digit <= high; digit++ {
				if tight == 1 && digit > upperDigit {
					break
				}
				newTight := 0
				if tight == 1 && digit == upperDigit {
					newTight = 1
				}
				next[newTight] += dp[tight]
			}
		}
		dp = next
	}

	return dp[0] + dp[1]
}

func countPowerful(bound int64, limit int, suffix string) int64 {
	if bound <= 0 {
		return 0
	}

	boundString := strconv.FormatInt(bound, 10)
	minLength := len(suffix)
	maxLength := len(boundString)

	var total int64
	for length := minLength; length <= maxLength; length++ {
		upper := boundString
		if length < maxLength {
			upper = strings.Repeat("9", length)
		}
		total += countExactLength(length, upper, suffix, limit)
	}
	return total
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var start, finish int64
	var limit int
	var suffix string

	fmt.Fscan(in, &start)
	fmt.Fscan(in, &finish)
	fmt.Fscan(in, &limit)
	fmt.Fscan(in, &suffix)

	answer := countPowerful(finish, limit, suffix) -
		countPowerful(start-1, limit, suffix)

	fmt.Fprintln(out, answer)
}
