import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func countDigitLimited(n int64, limit int) int64 {
	if n < 0 {
		return 0
	}

	digits := strconv.FormatInt(n, 10)
	base := int64(limit + 1)

	powers := make([]int64, len(digits)+1)
	powers[0] = 1
	for i := 1; i <= len(digits); i++ {
		powers[i] = powers[i-1] * base
	}

	var count int64
	for i, ch := range digits {
		digit := int(ch - '0')
		lessChoices := digit
		if lessChoices > limit+1 {
			lessChoices = limit + 1
		}

		remaining := len(digits) - i - 1
		count += int64(lessChoices) * powers[remaining]

		if digit > limit {
			return count
		}
	}

	return count + 1
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var start, finish int64
	var limit int
	var s string

	fmt.Fscan(in, &start, &finish, &limit, &s)

	suffix, _ := strconv.ParseInt(s, 10, 64)
	powerOfTen := int64(1)
	for range s {
		powerOfTen *= 10
	}

	countUpTo := func(n int64) int64 {
		if n < suffix {
			return 0
		}
		maxPrefix := (n - suffix) / powerOfTen
		return countDigitLimited(maxPrefix, limit)
	}

	answer := countUpTo(finish) - countUpTo(start-1)
	fmt.Fprintln(out, answer)
}
