package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s, &k); err != nil {
		return
	}

	if k == 26 {
		fmt.Println(1)
		return
	}

	n := len(s)
	memo := make(map[uint64]uint16, n*32)

	var dfs func(index int, mask uint32, canChange bool) int
	dfs = func(index int, mask uint32, canChange bool) int {
		if index == n {
			return 1
		}

		var changeBit uint64
		if canChange {
			changeBit = 1
		}
		key := (uint64(index) << 27) | (uint64(mask) << 1) | changeBit
		if value, ok := memo[key]; ok {
			return int(value)
		}

		original := int(s[index] - 'a')
		originalBit := uint32(1) << original
		nextMask := mask | originalBit

		best := 0
		if bits.OnesCount32(nextMask) > k {
			best = 1 + dfs(index+1, originalBit, canChange)
		} else {
			best = dfs(index+1, nextMask, canChange)
		}

		if canChange {
			originalAlreadyPresent := mask&originalBit != 0
			triedExisting := false

			for c := 0; c < 26; c++ {
				if c == original {
					continue
				}

				bit := uint32(1) << c

				// All replacements by a character already in the current
				// mask produce the same next state.
				if mask&bit != 0 {
					if originalAlreadyPresent || triedExisting {
						continue
					}
					triedExisting = true
				}

				changedMask := mask | bit
				var candidate int
				if bits.OnesCount32(changedMask) > k {
					candidate = 1 + dfs(index+1, bit, false)
				} else {
					candidate = dfs(index+1, changedMask, false)
				}

				if candidate > best {
					best = candidate
				}
			}
		}

		memo[key] = uint16(best)
		return best
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 0, true))
}
