			if len(values) > 0 {
				k = values[0]
				break
			}
		}
	}

	n := len(nums)
	requiredGroups := n - k
	const allBits = (1 << 30) - 1

	feasible := func(zeroMask int) bool {
		groups := 0
		currentAnd := allBits

		for _, value := range nums {
			currentAnd &= value
			if currentAnd&zeroMask == 0 {
				groups++
				currentAnd = allBits
			}
		}
		return groups >= requiredGroups
	}

	answer := 0
	zeroMask := 0

	for bit := 29; bit >= 0; bit-- {
		candidate := zeroMask | (1 << bit)
