package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int64 {
	result := make([]int64, 0)
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := int64(1)
		if s[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		found := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
			found = true
		}
		if found {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		line := scanner.Text()
		if len(parseInts(line)) > 0 {
			lines = append(lines, line)
			if len(lines) == 2 {
				break
			}
		}
	}

	if len(lines) < 2 {
		fmt.Println(-1)
		return
	}

	nums := parseInts(lines[0])
	changeValues := parseInts(lines[1])

	n := len(nums)
	m := len(changeValues)
	changeIndices := make([]int, m)
	for i, value := range changeValues {
		changeIndices[i] = int(value) - 1
	}

	canMarkAll := func(seconds int) bool {
		last := make([]int, n)
		for i := range last {
			last[i] = -1
		}

		for second := 0; second < seconds; second++ {
			index := changeIndices[second]
			if index >= 0 && index < n {
				last[index] = second
			}
		}

		for _, position := range last {
			if position == -1 {
				return false
			}
		}

		var available int64
		for second := 0; second < seconds; second++ {
			index := changeIndices[second]
			if last[index] == second {
				if available < nums[index] {
					return false
				}
				available -= nums[index]
			} else {
				available++
			}
		}
		return true
	}

	if !canMarkAll(m) {
		fmt.Println(-1)
		return
	}

	left, right := 1, m
	for left < right {
		mid := left + (right-left)/2
		if canMarkAll(mid) {
			right = mid
		} else {
			left = mid + 1
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, left)
}
