func parseInts(line string) []int64 {
	result := make([]int64, 0)
	var value int64
	sign := int64(1)
	inNumber := false

	for i := 0; i <= len(line); i++ {
		var c byte
		if i < len(line) {
			c = line[i]
		}

		if c == '-' && !inNumber {
			sign = -1
			inNumber = true
			value = 0
		} else if c >= '0' && c <= '9' {
			if !inNumber {
				inNumber = true
				sign = 1
				value = 0
			}
			value = value*10 + int64(c-'0')
		} else if inNumber {
			result = append(result, sign*value)
			value = 0
			sign = 1
			inNumber = false
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		line := scanner.Text()
		if len(parseInts(line)) > 0 {
			lines = append(lines, line)
			if len(lines) == 2 {
				break
			}
		}
	}

	if len(lines) < 2 {
		fmt.Println(-1)
		return
	}

	nums := parseInts(lines[0])
	changeValues := parseInts(lines[1])

	n := len(nums)
	m := len(changeValues)
	changeIndices := make([]int, m)
	for i, v := range changeValues {
		changeIndices[i] = int(v) - 1
	}

	canMarkAll := func(seconds int) bool {
		last := make([]int, n)
		for i := range last {
			last[i] = -1
		}

		for s := 0; s < seconds; s++ {
			idx := changeIndices[s]
			if idx < 0 || idx >= n {
				return false
			}
			last[idx] = s
		}

		for _, position := range last {
			if position == -1 {
				return false
			}
		}

		var available int64
		for s := 0; s < seconds; s++ {
			idx := changeIndices[s]
			if last[idx] == s {
				if available < nums[idx] {
					return false
				}
				available -= nums[idx]
			} else {
				available++
			}
		}
		return true
	}

	left, right := 1, m
	answer := -1

	for left <= right {
		mid := left + (right-left)/2
		if canMarkAll(mid) {
			answer = mid
			right = mid - 1
		} else {
			left = mid + 1
		}
