func parseInts(data []byte) []int64 {
	values := make([]int64, 0)
	for i := 0; i < len(data); {
		if data[i] != '-' && (data[i] < '0' || data[i] > '9') {
			i++
			continue
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
			if i >= len(data) || data[i] < '0' || data[i] > '9' {
				continue
			}
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}
	return values
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	values := parseInts(data)
	if len(values) < 2 {
		return
	}

	k := int(values[len(values)-1])
	nums := values[:len(values)-1]

	const negInf int64 = -1 << 62

	// best[j] is the maximum value using exactly j completed subarrays.
	// ending[j] is the maximum value using exactly j subarrays where the
	// j-th subarray ends at the current position.
	best := make([]int64, k+1)
	ending := make([]int64, k+1)
	for j := 1; j <= k; j++ {
		best[j] = negInf
		ending[j] = negInf
	}

	for i, x := range nums {
		limit := k
		if i+1 < limit {
			limit = i + 1
		}

		for j := limit; j >= 1; j-- {
			coefficient := int64(k - j + 1)
			if j%2 == 0 {
				coefficient = -coefficient
			}
			contribution := coefficient * x

			continueCurrent := negInf
			if ending[j] != negInf {
				continueCurrent = ending[j] + contribution
			}

			startNew := negInf
			if best[j-1] != negInf {
				startNew = best[j-1] + contribution
			}

			if startNew > continueCurrent {
				ending[j] = startNew
			} else {
				ending[j] = continueCurrent
			}

			if ending[j] > best[j] {
				best[j] = ending[j]
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best[k])
}
