package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

const mod int64 = 1_000_000_007

func parseIntegers(data []byte) []int64 {
	var values []int64
	for i := 0; i < len(data); {
		sign := int64(1)
		if data[i] == '-' && i+1 < len(data) && data[i+1] >= '0' && data[i+1] <= '9' {
			sign = -1
			i++
		} else if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}
	return values
}

func countSubsequences(nums []int64, k int, minDifference int64) int64 {
	n := len(nums)
	prev := make([]int64, n)
	for i := range prev {
		prev[i] = 1
	}

	for length := 2; length <= k; length++ {
		curr := make([]int64, n)
		right := -1
		var prefixSum int64

		for i := 0; i < n; i++ {
			for right+1 < i && nums[i]-nums[right+1] >= minDifference {
				right++
				prefixSum += prev[right]
				if prefixSum >= mod {
					prefixSum -= mod
				}
			}
			curr[i] = prefixSum
		}
		prev = curr
	}

	var total int64
	for _, ways := range prev {
		total += ways
		if total >= mod {
			total -= mod
		}
	}
	return total
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}
	values := parseIntegers(data)
	if len(values) < 3 {
		return
	}

	k := int(values[len(values)-1])
	nums := append([]int64(nil), values[:len(values)-1]...)
	sort.Slice(nums, func(i, j int) bool {
		return nums[i] < nums[j]
	})

	differences := make([]int64, 0, len(nums)*(len(nums)-1)/2)
	for i := 0; i < len(nums); i++ {
		for j := i + 1; j < len(nums); j++ {
			if nums[j] > nums[i] {
				differences = append(differences, nums[j]-nums[i])
			}
		}
	}

	if len(differences) == 0 {
		fmt.Println(0)
		return
	}

	sort.Slice(differences, func(i, j int) bool {
		return differences[i] < differences[j]
	})

	unique := differences[:0]
	for _, d := range differences {
		if len(unique) == 0 || unique[len(unique)-1] != d {
			unique = append(unique, d)
		}
	}

	counts := make([]int64, len(unique))
	for i, d := range unique {
		counts[i] = countSubsequences(nums, k, d)
	}

	var answer int64
	for i, d := range unique {
		nextCount := int64(0)
		if i+1 < len(unique) {
			nextCount = counts[i+1]
		}

		exactCount := (counts[i] - nextCount + mod) % mod
		answer = (answer + (d%mod)*exactCount) % mod
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
