const mod int64 = 1_000_000_007

func parseIntegers(data []byte) []int64 {
	var values []int64
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		if i >= len(data) || data[i] < '0' || data[i] > '9' {
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}
	return values
}

// countSubsequences returns the number of length-k subsequences whose
// pairwise differences are all at least minDifference.
func countSubsequences(nums []int64, k int, minDifference int64) int64 {
	n := len(nums)
	var prefix [51][51]int64
	prefix[0][0] = 1

	for i := 0; i < n; i++ {
		// q is the number of earlier elements that can precede nums[i].
		q := sort.Search(i, func(j int) bool {
			return nums[j] > nums[i]-minDifference
		})

		prefix[i+1][0] = 1
		for length := 1; length <= k; length++ {
			waysUsingCurrent := prefix[q][length-1]
			prefix[i+1][length] = (prefix[i][length] + waysUsingCurrent) % mod
		}
	}

	return prefix[n][k]
}

func main() {
	data, err := io.ReadAll(bufio.NewReader(os.Stdin))
	if err != nil {
		return
	}

	values := parseIntegers(data)
	if len(values) < 3 {
		return
	}

	k := int(values[len(values)-1])
	nums := append([]int64(nil), values[:len(values)-1]...)
	sort.Slice(nums, func(i, j int) bool {
		return nums[i] < nums[j]
	})

	distances := make([]int64, 0, len(nums)*(len(nums)-1)/2)
	for i := 0; i < len(nums); i++ {
		for j := i + 1; j < len(nums); j++ {
			difference := nums[j] - nums[i]
			if difference > 0 {
				distances = append(distances, difference)
			}
		}
	}

	sort.Slice(distances, func(i, j int) bool {
		return distances[i] < distances[j]
	})

	var answer int64
	var previous int64
	for i, distance := range distances {
		if i > 0 && distance == distances[i-1] {
			continue
		}

		count := countSubsequences(nums, k, distance)
		increment := (distance - previous) % mod
		answer = (answer + increment*count) % mod
		previous = distance
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
