)

type extrema struct {
	min1, min2 int64
	max1, max2 int64
	minCount   int
	maxCount   int
}

func newExtrema() extrema {
	return extrema{
		min1: math.MaxInt64,
		min2: math.MaxInt64,
		max1: math.MinInt64,
		max2: math.MinInt64,
	}
}

func (e *extrema) add(v int64) {
	if v < e.min1 {
		e.min2 = e.min1
		e.min1 = v
		e.minCount = 1
	} else if v == e.min1 {
		e.minCount++
	} else if v < e.min2 {
		e.min2 = v
	}

	if v > e.max1 {
		e.max2 = e.max1
		e.max1 = v
		e.maxCount = 1
	} else if v == e.max1 {
		e.maxCount++
	} else if v > e.max2 {
		e.max2 = v
	}
}

func (e extrema) rangeWithout(v int64) int64 {
	minValue := e.min1
	if v == e.min1 && e.minCount == 1 {
		minValue = e.min2
	}

	maxValue := e.max1
	if v == e.max1 && e.maxCount == 1 {
		maxValue = e.max2
	}

	return maxValue - minValue
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	sums := make([]int64, n)
	diffs := make([]int64, n)
	sumExt := newExtrema()
	diffExt := newExtrema()

	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)

		sums[i] = x + y
		diffs[i] = x - y

		sumExt.add(sums[i])
		diffExt.add(diffs[i])
	}

	answer := int64(math.MaxInt64)

	for i := 0; i < n; i++ {
		sumRange := sumExt.rangeWithout(sums[i])
		diffRange := diffExt.rangeWithout(diffs[i])

		maxDistance := sumRange
		if diffRange > maxDistance {
			maxDistance = diffRange
		}

		if maxDistance < answer {
			answer = maxDistance
		}
	}

	fmt.Fprintln(out, answer)
}
