			i++
		}
		if i >= len(data) {
			break
		}

		sign := 1
		if data[i] == '-' {
			sign = -1
			i++
		}

		value := 0
		hasDigit := false
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			values = append(values, sign*value)
		}
	}

	if len(values) < 2 {
		return
	}

	nums := values[:len(values)-1]
	k := values[len(values)-1]

	dp := make([]int64, k+1)
	dp[0] = 1

	for _, x := range nums {
		next := make([]int64, k+1)
		for sum := 0; sum <= k; sum++ {
			next[sum] = (2 * dp[sum]) % mod
			if x <= sum {
				next[sum] = (next[sum] + dp[sum-x]) % mod
			}
		}
		dp = next
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[k])
