func parseInts(s string) []int {
	result := make([]int, 0)
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := 1
		if s[i] == '-' {
			sign = -1
			i++
		}

		value := 0
		found := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
			found = true
		}
		if found {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	lines := make([][]int, 0, 4)
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}
	if len(lines) < 3 {
		return
	}

	var nums []int
	var k, maxChanges int

	// Supports both the specified format and an optional leading n.
	if len(lines) >= 4 && len(lines[0]) == 1 &&
		lines[0][0] >= 2 && len(lines[1]) == lines[0][0] {
		nums = lines[1]
		k = lines[2][0]
		maxChanges = lines[3][0]
	} else {
		nums = lines[0]
		k = lines[1][0]
		maxChanges = lines[2][0]
	}

	positions := make([]int, 0)
	maxRun, run := 0, 0
	for i, value := range nums {
		if value == 1 {
			positions = append(positions, i)
			run++
			if run > maxRun {
				maxRun = run
			}
		} else {
			run = 0
		}
	}

	closeOnes := maxRun
	if closeOnes > 3 {
		closeOnes = 3
	}
	if closeOnes > k {
		closeOnes = k
	}

	if closeOnes+maxChanges >= k {
		cost := 2 * (k - closeOnes)
		if closeOnes > 0 {
			cost += closeOnes - 1
		}
		fmt.Println(cost)
		return
	}

	neededExisting := k - maxChanges

	prefix := make([]int64, len(positions)+1)
	for i, position := range positions {
		prefix[i+1] = prefix[i] + int64(position)
	}

	best := int64(^uint64(0) >> 1)
	for left := 0; left+neededExisting <= len(positions); left++ {
		right := left + neededExisting
		mid := left + neededExisting/2
		median := int64(positions[mid])

		leftCost := median*int64(mid-left) - (prefix[mid] - prefix[left])
		rightCost := (prefix[right] - prefix[mid+1]) -
			median*int64(right-mid-1)

		cost := leftCost + rightCost
		if cost < best {
			best = cost
		}
	}

	best += int64(2 * maxChanges)
	fmt.Println(best)
}
