	"os"
)

type extrema struct {
	max1, max2       int64
	maxIdx1, maxIdx2 int
	min1, min2       int64
	minIdx1, minIdx2 int
}

func newExtrema() extrema {
	const inf int64 = 1 << 62
	return extrema{
		max1: -inf, max2: -inf,
		maxIdx1: -1, maxIdx2: -1,
		min1: inf, min2: inf,
		minIdx1: -1, minIdx2: -1,
	}
}

func (e *extrema) add(value int64, index int) {
	if value > e.max1 {
		e.max2, e.maxIdx2 = e.max1, e.maxIdx1
		e.max1, e.maxIdx1 = value, index
	} else if value > e.max2 {
		e.max2, e.maxIdx2 = value, index
	}

	if value < e.min1 {
		e.min2, e.minIdx2 = e.min1, e.minIdx1
		e.min1, e.minIdx1 = value, index
	} else if value < e.min2 {
		e.min2, e.minIdx2 = value, index
	}
}

func (e extrema) rangeWithout(index int) int64 {
	maxValue := e.max1
	if e.maxIdx1 == index {
		maxValue = e.max2
	}

	minValue := e.min1
	if e.minIdx1 == index {
		minValue = e.min2
	}

	return maxValue - minValue
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	sumExtrema := newExtrema()
	diffExtrema := newExtrema()

	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)
		sumExtrema.add(x+y, i)
		diffExtrema.add(x-y, i)
	}

	const inf int64 = 1 << 62
	answer := inf

	for i := 0; i < n; i++ {
		sumRange := sumExtrema.rangeWithout(i)
		diffRange := diffExtrema.rangeWithout(i)

		maxDistance := sumRange
		if diffRange > maxDistance {
			maxDistance = diffRange
		}
		if maxDistance < answer {
			answer = maxDistance
		}
	}

	fmt.Fprintln(out, answer)
}
