package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int {
	res := make([]int, 0)
	for i := 0; i < len(s); {
		if s[i] < '0' || s[i] > '9' {
			i++
			continue
		}
		v := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			v = v*10 + int(s[i]-'0')
			i++
		}
		res = append(res, v)
	}
	return res
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	lines := make([][]int, 0, 3)
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 {
		return
	}

	nums := lines[0]
	k := lines[1][0]
	maxChanges := lines[2][0]

	positions := make([]int64, 0)
	maxLocalOnes := 0

	for i, v := range nums {
		if v == 1 {
			positions = append(positions, int64(i))

			local := 1
			if i > 0 && nums[i-1] == 1 {
				local++
			}
			if i+1 < len(nums) && nums[i+1] == 1 {
				local++
			}
			if local > maxLocalOnes {
				maxLocalOnes = local
			}
		}
	}

	if maxLocalOnes > k {
		maxLocalOnes = k
	}

	var answer int64

	if maxChanges >= k-maxLocalOnes {
		answer = int64(2 * (k - maxLocalOnes))
		if maxLocalOnes > 0 {
			answer += int64(maxLocalOnes - 1)
		}
	} else {
		requiredOnes := k - maxChanges

		prefix := make([]int64, len(positions)+1)
		for i, p := range positions {
			prefix[i+1] = prefix[i] + p
		}

		const inf int64 = 1<<63 - 1
		minDistance := inf

		for left := 0; left+requiredOnes <= len(positions); left++ {
			right := left + requiredOnes
			mid := left + requiredOnes/2
			median := positions[mid]

			leftCost := median*int64(mid-left) - (prefix[mid] - prefix[left])
			rightCost := (prefix[right] - prefix[mid+1]) -
				median*int64(right-mid-1)

			cost := leftCost + rightCost
			if cost < minDistance {
				minDistance = cost
			}
		}

		answer = minDistance + int64(2*maxChanges)
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
