package main

import (
	"bufio"
	"fmt"
	"os"
)

func countAtMost(nums []int, k int, maxVal int) int64 {
	freq := make([]int, maxVal+1)
	left, distinct := 0, 0
	var count int64

	for right, value := range nums {
		if freq[value] == 0 {
			distinct++
		}
		freq[value]++

		for distinct > k {
			leftValue := nums[left]
			freq[leftValue]--
			if freq[leftValue] == 0 {
				distinct--
			}
			left++
		}

		count += int64(right - left + 1)
	}

	return count
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	nums := make([]int, 0)
	maxVal := 0

	for {
		var value int
		if _, err := fmt.Fscan(in, &value); err != nil {
			break
		}
		nums = append(nums, value)
		if value > maxVal {
			maxVal = value
		}
	}

	n := len(nums)
	if n == 0 {
		return
	}

	totalSubarrays := int64(n) * int64(n+1) / 2
	medianRank := (totalSubarrays + 1) / 2

	low, high := 1, n
	for low < high {
		mid := low + (high-low)/2
		if countAtMost(nums, mid, maxVal) >= medianRank {
			high = mid
		} else {
			low = mid + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, low)
}
