package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

type Entry struct {
	id    int
	count int64
}

type MaxHeap []Entry

func (h MaxHeap) Len() int { return len(h) }
func (h MaxHeap) Less(i, j int) bool {
	return h[i].count > h[j].count
}
func (h MaxHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Entry))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var values []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			if err == io.EOF {
				break
			}
			return
		}
		values = append(values, x)
	}

	if len(values) == 0 {
		return
	}

	start := 0
	n := len(values) / 2

	// Also supports an optional leading array length.
	if len(values)%2 == 1 && int(values[0]) == (len(values)-1)/2 {
		start = 1
		n = int(values[0])
	}

	nums := values[start : start+n]
	freq := values[start+n : start+2*n]

	counts := make(map[int]int64, n)
	h := &MaxHeap{}
	heap.Init(h)

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i := 0; i < n; i++ {
		id := int(nums[i])
		counts[id] += freq[i]

		if counts[id] > 0 {
			heap.Push(h, Entry{id: id, count: counts[id]})
		}

		for h.Len() > 0 {
			top := (*h)[0]
			if counts[top.id] == top.count {
				break
			}
			heap.Pop(h)
		}

		var answer int64
		if h.Len() > 0 {
			answer = (*h)[0].count
		}

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer)
	}
	fmt.Fprintln(out)
}
