			i++
		}
		if i >= len(data) {
			break
		}

		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		nums = append(nums, value)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := len(nums)
	if n == 0 {
		return
	}

	maxValue := 0
	for _, value := range nums {
		if value > maxValue {
			maxValue = value
		}
	}

	seen := make([]bool, maxValue+1)
	uniqueCount := 0
	for _, value := range nums {
		if !seen[value] {
			seen[value] = true
			uniqueCount++
		}
	}

	totalSubarrays := int64(n) * int64(n+1) / 2
	medianRank := (totalSubarrays + 1) / 2

	countAtMost := func(limit int) int64 {
		frequency := make([]int, maxValue+1)
		left, distinct := 0, 0
		var count int64

		for right, value := range nums {
			if frequency[value] == 0 {
				distinct++
			}
			frequency[value]++

			for distinct > limit {
				leftValue := nums[left]
				frequency[leftValue]--
				if frequency[leftValue] == 0 {
					distinct--
				}
				left++
			}

			count += int64(right - left + 1)
		}
		return count
	}

	low, high := 1, uniqueCount
	for low < high {
		mid := low + (high-low)/2
		if countAtMost(mid) >= medianRank {
			high = mid
		} else {
			low = mid + 1
		}
	}

	fmt.Fprintln(out, low)
}
