	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}

	if len(lines) < 2 {
		return
	}

	wordsContainer := strings.Fields(lines[0])
	wordsQuery := strings.Fields(lines[1])

	nodes := make([]trieNode, 1, 500001)
	nodes[0].best = -1

	isBetter := func(candidate int, current int32) bool {
		if current == -1 {
			return true
		}
		cur := int(current)
		if len(wordsContainer[candidate]) != len(wordsContainer[cur]) {
			return len(wordsContainer[candidate]) < len(wordsContainer[cur])
		}
		return candidate < cur
	}

	for i, word := range wordsContainer {
		node := int32(0)
		if isBetter(i, nodes[node].best) {
			nodes[node].best = int32(i)
		}

		for j := len(word) - 1; j >= 0; j-- {
			c := word[j] - 'a'
			next := nodes[node].children[c]
			if next == 0 {
				next = int32(len(nodes))
				nodes[node].children[c] = next
				newNode := trieNode{best: -1}
				nodes = append(nodes, newNode)
			}
			node = next
			if isBetter(i, nodes[node].best) {
				nodes[node].best = int32(i)
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, query := range wordsQuery {
		node := int32(0)
		answer := nodes[node].best

		for j := len(query) - 1; j >= 0; j-- {
			c := query[j] - 'a'
			next := nodes[node].children[c]
			if next == 0 {
				break
			}
			node = next
			answer = nodes[node].best
		}

		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
