package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int {
	result := make([]int, 0)
	value := 0
	inNumber := false

	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			inNumber = true
		} else if inNumber {
			result = append(result, value)
			value = 0
			inNumber = false
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		line := scanner.Text()
		if len(parseInts(line)) > 0 {
			lines = append(lines, line)
			if len(lines) == 2 {
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(lines) < 2 {
		fmt.Fprintln(out, -1)
		return
	}

	nums := parseInts(lines[0])
	andValues := parseInts(lines[1])
	n, m := len(nums), len(andValues)

	if m == 0 || m > n {
		fmt.Fprintln(out, -1)
		return
	}

	const inf int64 = 1 << 60

	// open[j] maps the current AND of the open j-th subarray to
	// the minimum cost of all previously completed subarrays.
	open := make([]map[int]int64, m)

	// closed[j] is the minimum cost after partitioning the current
	// prefix into exactly j completed subarrays.
	closed := make([]int64, m+1)
	for i := range closed {
		closed[i] = inf
	}
	closed[0] = 0

	for _, x := range nums {
		nextOpen := make([]map[int]int64, m)

		for j := 0; j < m; j++ {
			target := andValues[j]

			addState := func(andValue int, cost int64) {
				if andValue&target != target {
					return
				}
				if nextOpen[j] == nil {
					nextOpen[j] = make(map[int]int64)
				}
				old, exists := nextOpen[j][andValue]
				if !exists || cost < old {
					nextOpen[j][andValue] = cost
				}
			}

			// Start the j-th subarray at the current element.
			if closed[j] < inf {
				addState(x, closed[j])
			}

			// Extend an already open j-th subarray.
			for currentAND, cost := range open[j] {
				addState(currentAND&x, cost)
			}
		}

		nextClosed := make([]int64, m+1)
		for i := range nextClosed {
			nextClosed[i] = inf
		}

		// End an open subarray at the current element.
		for j := 0; j < m; j++ {
			if nextOpen[j] == nil {
				continue
			}
			if cost, exists := nextOpen[j][andValues[j]]; exists {
				total := cost + int64(x)
				if total < nextClosed[j+1] {
					nextClosed[j+1] = total
				}
			}
		}

		open = nextOpen
		closed = nextClosed
	}

	if closed[m] == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, closed[m])
	}
}
