package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int {
	result := make([]int, 0)
	for i := 0; i < len(s); {
		if s[i] < '0' || s[i] > '9' {
			i++
			continue
		}
		value := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
		}
		result = append(result, value)
	}
	return result
}

func updateMin(mp map[int]int, key, value int) {
	if old, exists := mp[key]; !exists || value < old {
		mp[key] = value
	}
}

func minimumValueSum(nums, andValues []int) int {
	n, m := len(nums), len(andValues)
	if n < m || m == 0 {
		return -1
	}

	// states[k][a] is the minimum cost of all completed subarrays
	// before the currently open k-th subarray, whose AND is a.
	states := make([]map[int]int, m)
	for i := range states {
		states[i] = make(map[int]int)
	}

	if nums[0]&andValues[0] == andValues[0] {
		states[0][nums[0]] = 0
	}

	for i := 1; i < n; i++ {
		next := make([]map[int]int, m)
		for j := range next {
			next[j] = make(map[int]int)
		}

		for k := 0; k < m; k++ {
			for currentAND, cost := range states[k] {
				// Extend the current subarray.
				extendedAND := currentAND & nums[i]
				if extendedAND&andValues[k] == andValues[k] {
					updateMin(next[k], extendedAND, cost)
				}

				// End the current subarray at i-1 and start the next at i.
				if k+1 < m && currentAND == andValues[k] &&
					nums[i]&andValues[k+1] == andValues[k+1] {
					newCost := cost + nums[i-1]
					updateMin(next[k+1], nums[i], newCost)
				}
			}
		}
		states = next
	}

	cost, exists := states[m-1][andValues[m-1]]
	if !exists {
		return -1
	}
	return cost + nums[n-1]
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	lines := make([][]int, 0, 2)
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
			if len(lines) == 2 {
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(lines) < 2 {
		fmt.Fprintln(out, -1)
		return
	}

	fmt.Fprintln(out, minimumValueSum(lines[0], lines[1]))
}
