package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
)

func extractInts(s string) []int64 {
	var result []int64
	var value int64
	inNumber := false

	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			value = value*10 + int64(ch-'0')
			inNumber = true
		} else if inNumber {
			result = append(result, value)
			value = 0
			inNumber = false
		}
	}
	if inNumber {
		result = append(result, value)
	}
	return result
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int64
	for scanner.Scan() {
		values := extractInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}
	if len(lines) < 2 {
		return
	}

	var coins []int64
	var k int64

	// Supports both:
	// coins on the first line, k on the second line
	// and n on the first line, coins on the second, k on the third.
	if len(lines) >= 3 && len(lines[0]) == 1 && int64(len(lines[1])) == lines[0][0] {
		coins = lines[1]
		k = lines[2][0]
	} else {
		coins = lines[0]
		k = lines[1][0]
	}

	sort.Slice(coins, func(i, j int) bool {
		return coins[i] < coins[j]
	})

	// Remove denominations whose multiples are already covered by a smaller coin.
	filtered := make([]int64, 0, len(coins))
	for _, coin := range coins {
		redundant := false
		for _, smaller := range filtered {
			if coin%smaller == 0 {
				redundant = true
				break
			}
		}
		if !redundant {
			filtered = append(filtered, coin)
		}
	}
	coins = filtered

	upper := coins[0] * k
	n := len(coins)

	// Aggregate inclusion-exclusion coefficients by LCM.
	coefficients := make(map[int64]int64)
	lcms := make([]int64, 1<<n)
	lcms[0] = 1

	for mask := 1; mask < (1 << n); mask++ {
		prev := mask & (mask - 1)
		index := bits.TrailingZeros(uint(mask))
		a := lcms[prev]
		b := coins[index]
		divisor := gcd(a, b)
		factor := b / divisor

		if a > upper/factor {
			lcms[mask] = upper + 1
			continue
		}

		lcm := a * factor
		lcms[mask] = lcm

		if bits.OnesCount(uint(mask))%2 == 1 {
			coefficients[lcm]++
		} else {
			coefficients[lcm]--
		}
	}

	countAmounts := func(limit int64) int64 {
		var count int64
		for lcm, coefficient := range coefficients {
			if coefficient != 0 && lcm <= limit {
				count += coefficient * (limit / lcm)
			}
		}
		return count
	}

	low, high := int64(1), upper
	for low < high {
		mid := low + (high-low)/2
		if countAmounts(mid) >= k {
			high = mid
		} else {
			low = mid + 1
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, low)
}
