import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() (int, error) {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()

	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if err != nil {
		return 0, err
	}

	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
		if err != nil {
			return 0, err
		}
	}

	for c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
		if err != nil {
			if err == io.EOF {
				return sign * value, nil
			}
			return 0, err
		}
	}

	return sign * value, nil
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	rows, err := in.NextInt()
	if err != nil || rows <= 0 {
		return
	}

	values := make([]int, 0)
	for {
		v, err := in.NextInt()
		if err != nil {
			break
		}
		values = append(values, v)
	}

	if len(values) == 0 || len(values)%rows != 0 {
		fmt.Fprintln(out, 0)
		return
	}

	cols := len(values) / rows
	rowCount := make([]int, rows)
	colCount := make([]int, cols)

	for i, value := range values {
		if value == 1 {
			rowCount[i/cols]++
			colCount[i%cols]++
		}
	}

	var triangles int64
	for i, value := range values {
		if value == 1 {
			r, c := i/cols, i%cols
			triangles += int64(rowCount[r]-1) * int64(colCount[c]-1)
		}
	}

	fmt.Fprintln(out, triangles)
}
