type stringReader struct {
	s string
	i int
}

func newStringReader(s string) *stringReader {
	return &stringReader{s: s}
}

func (r *stringReader) Read(p []byte) (int, error) {
	if r.i >= len(r.s) {
		return 0, os.ErrClosed
	}
	n := copy(p, r.s[r.i:])
	r.i += n
	return n, nil
