package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	rows := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		rows, _ = strconv.Atoi(line)
		break
	}

	grid := make([][]byte, 0, rows)
	var colCount []int
	rowCount := make([]int, rows)

	for len(grid) < rows && scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		fields := strings.Fields(line)
		var row []byte

		if len(fields) == 1 && len(fields[0]) > 1 {
			for _, ch := range fields[0] {
				if ch == '0' || ch == '1' {
					row = append(row, byte(ch-'0'))
				}
			}
		} else {
			row = make([]byte, 0, len(fields))
			for _, field := range fields {
				value, _ := strconv.Atoi(field)
				row = append(row, byte(value))
			}
		}

		if colCount == nil {
			colCount = make([]int, len(row))
		}

		r := len(grid)
		for c, value := range row {
			if value == 1 {
				rowCount[r]++
				colCount[c]++
			}
		}
		grid = append(grid, row)
	}

	var triangles int64
	for r, row := range grid {
		for c, value := range row {
			if value == 1 {
				triangles += int64(rowCount[r]-1) * int64(colCount[c]-1)
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, triangles)
}
