func validBlockLength(s string, length int) bool {
	var target [26]int
	for i := 0; i < length; i++ {
		target[s[i]-'a']++
	}

	for start := length; start < len(s); start += length {
		var current [26]int
		for i := start; i < start+length; i++ {
			current[s[i]-'a']++
		}
		if current != target {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	fmt.Fscan(in, &s)

	n := len(s)
	for length := 1; length <= n; length++ {
		if n%length == 0 && validBlockLength(s, length) {
			fmt.Fprintln(out, length)
			return
		}
	}
}
