				distinct++
			}
			counts[c]++
			if counts[c] > maxCount {
				maxCount = counts[c]
			}

			length := j - i + 1
			if length == distinct*maxCount && dp[i]+1 < dp[j+1] {
				dp[j+1] = dp[i] + 1
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[n])
