	"os"
	"strconv"
	"unicode"
)

func parseInts(s string) []int64 {
	var nums []int64
	for i := 0; i < len(s); {
		if s[i] == '-' || unicode.IsDigit(rune(s[i])) {
			start := i
			if s[i] == '-' {
				i++
			}
			if i < len(s) && unicode.IsDigit(rune(s[i])) {
				for i < len(s) && unicode.IsDigit(rune(s[i])) {
					i++
				}
				v, _ := strconv.ParseInt(s[start:i], 10, 64)
				nums = append(nums, v)
				continue
			}
		}
		i++
	}
	return nums
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		nums := parseInts(scanner.Text())
		if len(nums) > 0 {
			lines = append(lines, nums)
		}
	}

	if len(lines) < 2 || len(lines[0]) < 2 {
		return
	}

	skills := lines[0]
	k := lines[1][0]

	champion := 0
	var consecutiveWins int64

	for i := 1; i < len(skills); i++ {
		if skills[champion] > skills[i] {
			consecutiveWins++
		} else {
			champion = i
			consecutiveWins = 1
		}

		if consecutiveWins >= k {
			fmt.Println(champion)
			return
		}
	}

	fmt.Println(champion)
}
