package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func parseInts(line string) []int64 {
	var values []int64
	for i := 0; i < len(line); {
		sign := int64(1)
		if line[i] == '-' && i+1 < len(line) && line[i+1] >= '0' && line[i+1] <= '9' {
			sign = -1
			i++
		}
		if i >= len(line) || line[i] < '0' || line[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(line) && line[i] >= '0' && line[i] <= '9' {
			value = value*10 + int64(line[i]-'0')
			i++
		}
		values = append(values, value*sign)
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 || len(lines[0]) == 0 {
		return
	}

	nums := lines[0]
	cost1 := lines[1][0]
	cost2 := lines[2][0]
	n := int64(len(nums))

	if n == 1 {
		fmt.Println(0)
		return
	}

	minValue, maxValue := nums[0], nums[0]
	var sum int64
	for _, value := range nums {
		sum += value
		if value < minValue {
			minValue = value
		}
		if value > maxValue {
			maxValue = value
		}
	}

	initialDeficit := n*maxValue - sum

	if n == 2 || cost2 >= 2*cost1 {
		fmt.Println((initialDeficit % mod) * (cost1 % mod) % mod)
		return
	}

	best := int64(^uint64(0) >> 1)

	for target := maxValue; target <= 2*maxValue; target++ {
		totalDeficit := n*target - sum
		largestDeficit := target - minValue

		pairs := totalDeficit / 2
		if totalDeficit-largestDeficit < pairs {
			pairs = totalDeficit - largestDeficit
		}

		singles := totalDeficit - 2*pairs
		currentCost := pairs*cost2 + singles*cost1
		if currentCost < best {
			best = currentCost
		}
	}

	fmt.Println(best % mod)
}
