package main

import (
	"bufio"
	"fmt"
	"os"
)

// setBitCount returns the total number of set bits among integers 1 through n.
func setBitCount(n int64) int64 {
	if n <= 0 {
		return 0
	}

	x := n + 1
	var total int64

	for bit := int64(0); bit <= 60; bit++ {
		half := int64(1) << bit
		period := half << 1

		total += (x / period) * half
		remainder := x % period
		if remainder > half {
			total += remainder - half
		}
	}
	return total
}

// exponentSum returns the sum of the positions of all set bits among 1 through n.
func exponentSum(n int64) int64 {
	if n <= 0 {
		return 0
	}

	x := n + 1
	var total int64

	for bit := int64(0); bit <= 60; bit++ {
		half := int64(1) << bit
		period := half << 1

		count := (x / period) * half
		remainder := x % period
		if remainder > half {
			count += remainder - half
		}

		total += bit * count
	}
	return total
}

// prefixExponent returns the sum of exponents in the first k elements of big_nums.
func prefixExponent(k int64) int64 {
	if k <= 0 {
		return 0
	}

	// Find the largest n whose complete powerful arrays fit in k elements.
	var complete int64
	left, right := int64(0), k
	for left <= right {
		mid := left + (right-left)/2
		if setBitCount(mid) <= k {
			complete = mid
			left = mid + 1
		} else {
			right = mid - 1
		}
	}

	result := exponentSum(complete)
	remaining := k - setBitCount(complete)
	next := complete + 1

	// The powerful array is sorted by increasing powers of two.
	for bit := int64(0); remaining > 0; bit++ {
		if next&(int64(1)<<bit) != 0 {
			result += bit
			remaining--
		}
	}

	return result
}

func modPow2(exponent, mod int64) int64 {
	if mod == 1 {
		return 0
	}

	result := int64(1)
	base := int64(2) % mod

	for exponent > 0 {
		if exponent&1 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		exponent >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var q int
	if _, err := fmt.Fscan(in, &q); err != nil {
		return
	}

	for i := 0; i < q; i++ {
		var from, to, mod int64
		fmt.Fscan(in, &from, &to, &mod)

		exponent := prefixExponent(to+1) - prefixExponent(from)
		answer := modPow2(exponent, mod)

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer)
	}
	fmt.Fprintln(out)
}
