package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func parseInts(s string) []int64 {
	var result []int64
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := int64(1)
		if s[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		hasDigit := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) == 0 {
		return
	}

	nums := lines[0]
	var remaining []int64
	for i := 1; i < len(lines); i++ {
		remaining = append(remaining, lines[i]...)
	}

	// Also support input supplied entirely on one line:
	// nums elements followed by cost1 and cost2.
	if len(remaining) < 2 && len(nums) >= 3 {
		remaining = append(remaining, nums[len(nums)-2:]...)
		nums = nums[:len(nums)-2]
	}

	if len(nums) == 0 || len(remaining) < 2 {
		return
	}

	cost1, cost2 := remaining[0], remaining[1]
	n := int64(len(nums))

	minValue, maxValue := nums[0], nums[0]
	var sum int64
	for _, value := range nums {
		sum += value
		if value < minValue {
			minValue = value
		}
		if value > maxValue {
			maxValue = value
		}
	}

	if n == 1 {
		fmt.Println(0)
		return
	}

	totalAtMax := n*maxValue - sum

	// Pair operations cannot improve the answer in these cases.
	if n == 2 || cost2 >= 2*cost1 {
		answer := (totalAtMax % mod) * (cost1 % mod) % mod
		fmt.Println(answer)
		return
	}

	costAtTarget := func(target int64) int64 {
		totalDeficit := n*target - sum
		largestDeficit := target - minValue

		pairs := totalDeficit / 2
		if totalDeficit-largestDeficit < pairs {
			pairs = totalDeficit - largestDeficit
		}
		if pairs < 0 {
			pairs = 0
		}

		singles := totalDeficit - 2*pairs
		return pairs*cost2 + singles*cost1
	}

	best := costAtTarget(maxValue)

	check := func(target int64) {
		if target < maxValue {
			return
		}
		current := costAtTarget(target)
		if current < best {
			best = current
		}
	}

	// Check the first targets and the neighborhood where no single
	// element's deficit exceeds all other deficits combined.
	check(maxValue + 1)
	check(maxValue + 2)

	numerator := sum - 2*minValue
	denominator := n - 2
	boundary := numerator / denominator

	for delta := int64(-3); delta <= 4; delta++ {
		check(boundary + delta)
	}

	fmt.Println(best % mod)
}
