	previous := make([]int64, 0, 32)

	for _, num := range nums {
		current := make([]int64, 0, len(previous)+1)
		current = append(current, num)

		for _, value := range previous {
			combined := value | num
			if current[len(current)-1] != combined {
				current = append(current, combined)
			}
		}

		for _, value := range current {
			diff := value - k
			if diff < 0 {
				diff = -diff
			}
			if diff < answer {
				answer = diff
			}
		}

		if answer == 0 {
			break
		}
		previous = current
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
