package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int, n+1)}
}

func (f *Fenwick) Add(index, delta int) {
	for i := index + 1; i < len(f.tree); i += i & -i {
		f.tree[i] += delta
	}
}

func (f *Fenwick) PrefixSum(index int) int {
	if index < 0 {
		return 0
	}
	sum := 0
	for i := index + 1; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

func (f *Fenwick) RangeSum(left, right int) int {
	if left > right {
		return 0
	}
	return f.PrefixSum(right) - f.PrefixSum(left-1)
}

func parseInts(line string) []int {
	fields := strings.Fields(line)
	values := make([]int, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.Atoi(field)
		if err == nil {
			values = append(values, value)
		}
	}
	return values
}

func nextNonEmptyLine(scanner *bufio.Scanner) string {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line
		}
	}
	return ""
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	numsLine := nextNonEmptyLine(scanner)
	if numsLine == "" {
		return
	}
	nums := parseInts(numsLine)
	n := len(nums)

	queryCountLine := nextNonEmptyLine(scanner)
	if queryCountLine == "" {
		return
	}
	queryCountValues := parseInts(queryCountLine)
	if len(queryCountValues) == 0 {
		return
	}
	queryCount := queryCountValues[0]

	fenwick := NewFenwick(n)
	isPeak := make([]bool, n)

	checkPeak := func(index int) bool {
		return index > 0 && index < n-1 &&
			nums[index] > nums[index-1] &&
			nums[index] > nums[index+1]
	}

	for i := 1; i < n-1; i++ {
		if checkPeak(i) {
			isPeak[i] = true
			fenwick.Add(i, 1)
		}
	}

	answers := make([]int, 0)

	for q := 0; q < queryCount; q++ {
		line := nextNonEmptyLine(scanner)
		query := parseInts(line)
		if len(query) < 3 {
			continue
		}

		queryType, x, y := query[0], query[1], query[2]

		if queryType == 1 {
			left, right := x, y
			if right-left < 2 {
				answers = append(answers, 0)
			} else {
				answers = append(answers, fenwick.RangeSum(left+1, right-1))
			}
		} else if queryType == 2 {
			index, value := x, y
			nums[index] = value

			for candidate := index - 1; candidate <= index+1; candidate++ {
				if candidate <= 0 || candidate >= n-1 {
					continue
				}

				newPeak := checkPeak(candidate)
				if newPeak != isPeak[candidate] {
					if newPeak {
						fenwick.Add(candidate, 1)
					} else {
						fenwick.Add(candidate, -1)
					}
					isPeak[candidate] = newPeak
				}
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	if len(answers) > 0 {
		fmt.Fprintln(writer)
	}
}
