package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const (
	mod    int64 = 1_000_000_007
	negInf int64 = -1 << 60
)

type Node struct {
	dp [4]int64
}

func leaf(value int64) Node {
	node := Node{dp: [4]int64{negInf, negInf, negInf, negInf}}
	node.dp[0] = 0
	node.dp[3] = value
	return node
}

func merge(left, right Node) Node {
	result := Node{dp: [4]int64{negInf, negInf, negInf, negInf}}

	for ls := 0; ls < 4; ls++ {
		if left.dp[ls] == negInf {
			continue
		}
		leftFirst := ls / 2
		leftLast := ls % 2

		for rs := 0; rs < 4; rs++ {
			if right.dp[rs] == negInf {
				continue
			}
			rightFirst := rs / 2
			rightLast := rs % 2

			if leftLast == 1 && rightFirst == 1 {
				continue
			}

			state := leftFirst*2 + rightLast
			sum := left.dp[ls] + right.dp[rs]
			if sum > result.dp[state] {
				result.dp[state] = sum
			}
		}
	}

	return result
}

type SegmentTree struct {
	tree []Node
	n    int
}

func NewSegmentTree(nums []int64) *SegmentTree {
	st := &SegmentTree{
		tree: make([]Node, 4*len(nums)),
		n:    len(nums),
	}
	st.build(1, 0, len(nums)-1, nums)
	return st
}

func (st *SegmentTree) build(node, left, right int, nums []int64) {
	if left == right {
		st.tree[node] = leaf(nums[left])
		return
	}

	mid := left + (right-left)/2
	st.build(node*2, left, mid, nums)
	st.build(node*2+1, mid+1, right, nums)
	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) Update(position int, value int64) {
	st.update(1, 0, st.n-1, position, value)
}

func (st *SegmentTree) update(node, left, right, position int, value int64) {
	if left == right {
		st.tree[node] = leaf(value)
		return
	}

	mid := left + (right-left)/2
	if position <= mid {
		st.update(node*2, left, mid, position, value)
	} else {
		st.update(node*2+1, mid+1, right, position, value)
	}

	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) Maximum() int64 {
	answer := int64(0)
	for _, value := range st.tree[1].dp {
		if value > answer {
			answer = value
		}
	}
	return answer
}

func parseInts(data []byte) []int64 {
	values := make([]int64, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] == ' ' || data[i] == '\n' || data[i] == '\r' || data[i] == '\t') {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, value*sign)
	}
	return values
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil || len(data) == 0 {
		return
	}

	lineEnd := 0
	for lineEnd < len(data) && data[lineEnd] != '\n' {
		lineEnd++
	}

	nums := parseInts(data[:lineEnd])
	remaining := parseInts(data[lineEnd:])

	if len(nums) == 0 || len(remaining) == 0 {
		return
	}

	queryCount := int(remaining[0])
	st := NewSegmentTree(nums)

	var result int64
	index := 1
	for i := 0; i < queryCount && index+1 < len(remaining); i++ {
		position := int(remaining[index])
		value := remaining[index+1]
		index += 2

		st.Update(position, value)
		result = (result + st.Maximum()) % mod
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, result)
}
