package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int, n+1)}
}

func (f *Fenwick) Add(index, delta int) {
	for i := index + 1; i < len(f.tree); i += i & -i {
		f.tree[i] += delta
	}
}

func (f *Fenwick) PrefixSum(index int) int {
	sum := 0
	for i := index + 1; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

func (f *Fenwick) RangeSum(left, right int) int {
	if left > right {
		return 0
	}
	result := f.PrefixSum(right)
	if left > 0 {
		result -= f.PrefixSum(left - 1)
	}
	return result
}

func parseLine(line string) []int {
	fields := strings.Fields(line)
	values := make([]int, len(fields))
	for i, field := range fields {
		values[i], _ = strconv.Atoi(field)
	}
	return values
}

func nextNonEmptyLine(scanner *bufio.Scanner) string {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line
		}
	}
	return ""
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	numsLine := nextNonEmptyLine(scanner)
	if numsLine == "" {
		return
	}
	nums := parseLine(numsLine)
	n := len(nums)

	queryCountLine := nextNonEmptyLine(scanner)
	if queryCountLine == "" {
		return
	}
	queryCount, _ := strconv.Atoi(strings.TrimSpace(queryCountLine))

	fenwick := NewFenwick(n)
	isPeak := make([]bool, n)

	checkPeak := func(index int) bool {
		return index > 0 && index < n-1 &&
			nums[index] > nums[index-1] &&
			nums[index] > nums[index+1]
	}

	for i := 1; i < n-1; i++ {
		if checkPeak(i) {
			isPeak[i] = true
			fenwick.Add(i, 1)
		}
	}

	answers := make([]int, 0)

	for processed := 0; processed < queryCount; {
		line := nextNonEmptyLine(scanner)
		if line == "" {
			break
		}
		query := parseLine(line)
		if len(query) < 3 {
			continue
		}
		processed++

		queryType, x, y := query[0], query[1], query[2]

		if queryType == 1 {
			left, right := x, y
			if right-left < 2 {
				answers = append(answers, 0)
			} else {
				answers = append(answers, fenwick.RangeSum(left+1, right-1))
			}
		} else {
			index, value := x, y

			for i := index - 1; i <= index+1; i++ {
				if i > 0 && i < n-1 && isPeak[i] {
					fenwick.Add(i, -1)
					isPeak[i] = false
				}
			}

			nums[index] = value

			for i := index - 1; i <= index+1; i++ {
				if i > 0 && i < n-1 && checkPeak(i) {
					isPeak[i] = true
					fenwick.Add(i, 1)
				}
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
