package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int64 {
	var result []int64
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := int64(1)
		if s[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		hasDigit := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			result = append(result, sign*value)
		}
	}
	return result
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 2 {
		return
	}

	nums, target := lines[0], lines[1]
	if len(lines) >= 3 && len(lines[0]) == 1 {
		nums, target = lines[1], lines[2]
	}

	n := len(nums)
	if len(target) < n {
		n = len(target)
	}
	if n == 0 {
		fmt.Println(0)
		return
	}

	firstDiff := target[0] - nums[0]
	totalVariation := abs(firstDiff)
	previous := firstDiff

	for i := 1; i < n; i++ {
		current := target[i] - nums[i]
		totalVariation += abs(current - previous)
		previous = current
	}
	totalVariation += abs(previous)

	fmt.Println(totalVariation / 2)
}
