func extractInts(s string) []int {
	result := make([]int, 0)
	for i := 0; i < len(s); {
		if (s[i] >= '0' && s[i] <= '9') || s[i] == '-' {
			start := i
			i++
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
			if value, err := strconv.Atoi(s[start:i]); err == nil {
				result = append(result, value)
			}
		} else {
			i++
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	lines := make([][]int, 0)
	for scanner.Scan() {
		values := extractInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 2 {
		return
	}

	var nums []int
	var k int

	// Supports both:
	// nums on the first line, k on the second line
	// and n on the first line, nums on the second, k on the third.
	if len(lines) >= 3 && len(lines[0]) == 1 && lines[0][0] == len(lines[1]) {
		nums = lines[1]
		k = lines[2][0]
	} else {
		nums = lines[0]
		k = lines[1][0]
	}

	n := len(nums)
	dp := make([][]int, n)
	answer := 0

	for i := 0; i < n; i++ {
		dp[i] = make([]int, k+1)
		for changes := 0; changes <= k; changes++ {
			dp[i][changes] = 1
			for previous := 0; previous < i; previous++ {
				candidate := 0
				if nums[previous] == nums[i] {
					candidate = dp[previous][changes] + 1
				} else if changes > 0 {
					candidate = dp[previous][changes-1] + 1
				}
				if candidate > dp[i][changes] {
					dp[i][changes] = candidate
				}
			}
			if dp[i][changes] > answer {
				answer = dp[i][changes]
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
