		hasDigit := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) == 0 {
		return
	}

	var nums []int
	k := 0

	switch {
	case len(lines) >= 3 && len(lines[0]) == 1 && lines[0][0] == len(lines[1]):
		nums = lines[1]
		k = lines[2][0]
	case len(lines) >= 2:
		nums = lines[0]
		k = lines[1][0]
	default:
		if len(lines[0]) < 2 {
