		fmt.Println(0)
		return
	}
	if k > n-1 {
		k = n - 1
	}

	dp := make([][]int, n)
	answer := 1

	for i := 0; i < n; i++ {
		dp[i] = make([]int, k+1)
		dp[i][0] = 1

		for prev := 0; prev < i; prev++ {
