package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func choose2(x int64) int64 {
	if x < 2 {
		return 0
	}
	return x * (x - 1) / 2
}

// Returns the number of pairs (a, b) such that:
// 0 <= a < left, 0 <= b < right, and a+b < limit.
func countPairsBelow(left, right, limit int64) int64 {
	if limit <= 0 {
		return 0
	}
	s := limit - 1
	return choose2(s+2) -
		choose2(s-left+2) -
		choose2(s-right+2) +
		choose2(s-left-right+2)
}

func main() {
	data, _ := io.ReadAll(os.Stdin)

	// Extract the longest contiguous binary string from the input.
	s := make([]byte, 0)
	for i := 0; i < len(data); {
		if data[i] != '0' && data[i] != '1' {
			i++
			continue
		}
		j := i
		for j < len(data) && (data[j] == '0' || data[j] == '1') {
			j++
		}
		if j-i > len(s) {
			s = append(s[:0], data[i:j]...)
		}
		i = j
	}

	n := len(s)
	if n == 0 {
		fmt.Println(0)
		return
	}

	zeroPositions := make([]int, 0)
	var answer int64

	// Count substrings containing no zeros.
	for i := 0; i < n; {
		if s[i] == '0' {
			zeroPositions = append(zeroPositions, i)
			i++
			continue
		}

		j := i
		for j < n && s[j] == '1' {
			j++
		}
		runLength := int64(j - i)
		answer += runLength * (runLength + 1) / 2
		i = j
	}

	zeroCount := len(zeroPositions)

	// For a substring with z zeros, it must have length at least z²+z.
	for z := 1; z*z+z <= n && z <= zeroCount; z++ {
		requiredLength := int64(z*z + z)

		for first := 0; first+z <= zeroCount; first++ {
			last := first + z - 1

			previousZero := -1
			if first > 0 {
				previousZero = zeroPositions[first-1]
			}

			nextZero := n
			if last+1 < zeroCount {
				nextZero = zeroPositions[last+1]
			}

			leftChoices := int64(zeroPositions[first] - previousZero)
			rightChoices := int64(nextZero - zeroPositions[last])
			coreLength := int64(zeroPositions[last] - zeroPositions[first] + 1)

			requiredExtension := requiredLength - coreLength
			totalChoices := leftChoices * rightChoices
			invalidChoices := countPairsBelow(
				leftChoices,
				rightChoices,
				requiredExtension,
			)

			answer += totalChoices - invalidChoices
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
