package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

type Node struct {
	next  [26]int
	fail  int
	out   int
	depth int
	cost  int
}

func newNode(depth int) Node {
	n := Node{
		out:   -1,
		depth: depth,
		cost:  -1,
	}
	for i := range n.next {
		n.next[i] = -1
	}
	return n
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	if !scanner.Scan() {
		return
	}
	target := scanner.Text()

	var words []string
	var costs []int
	readingCosts := false

	for scanner.Scan() {
		token := scanner.Text()
		if !readingCosts && len(token) > 0 && token[0] >= '0' && token[0] <= '9' {
			readingCosts = true
		}

		if readingCosts {
			value, err := strconv.Atoi(token)
			if err != nil {
				fmt.Println(-1)
				return
			}
			costs = append(costs, value)
		} else {
			words = append(words, token)
		}
	}

	if len(words) != len(costs) {
		fmt.Println(-1)
		return
	}

	nodes := make([]Node, 1, 50001)
	nodes[0] = newNode(0)

	for i, word := range words {
		current := 0
		for _, ch := range word {
			c := int(ch - 'a')
			if nodes[current].next[c] == -1 {
				nodes[current].next[c] = len(nodes)
				nodes = append(nodes, newNode(nodes[current].depth+1))
			}
			current = nodes[current].next[c]
		}

		if nodes[current].cost == -1 || costs[i] < nodes[current].cost {
			nodes[current].cost = costs[i]
		}
	}

	queue := make([]int, 0, len(nodes))

	for c := 0; c < 26; c++ {
		child := nodes[0].next[c]
		if child == -1 {
			nodes[0].next[c] = 0
		} else {
			nodes[child].fail = 0
			nodes[child].out = -1
			queue = append(queue, child)
		}
	}

	for head := 0; head < len(queue); head++ {
		v := queue[head]

		for c := 0; c < 26; c++ {
			child := nodes[v].next[c]
			if child == -1 {
				nodes[v].next[c] = nodes[nodes[v].fail].next[c]
				continue
			}

			failure := nodes[nodes[v].fail].next[c]
			nodes[child].fail = failure

			if nodes[failure].cost != -1 {
				nodes[child].out = failure
			} else {
				nodes[child].out = nodes[failure].out
			}

			queue = append(queue, child)
		}
	}

	const inf int64 = 1 << 60
	dp := make([]int64, len(target)+1)
	for i := 1; i < len(dp); i++ {
		dp[i] = inf
	}

	state := 0
	for i := 0; i < len(target); i++ {
		state = nodes[state].next[int(target[i]-'a')]

		match := state
		for match != -1 {
			if nodes[match].cost != -1 {
				start := i + 1 - nodes[match].depth
				if start >= 0 && dp[start] != inf {
					candidate := dp[start] + int64(nodes[match].cost)
					if candidate < dp[i+1] {
						dp[i+1] = candidate
					}
				}
			}
			match = nodes[match].out
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if dp[len(target)] == inf {
		fmt.Fprintln(writer, -1)
	} else {
		fmt.Fprintln(writer, dp[len(target)])
	}
}
