func main() {
	data, err := os.ReadFile("/dev/stdin")
	if err != nil {
		return
	}

	rawLines := strings.Split(string(data), "\n")
	lines := make([]string, 0, len(rawLines))
	for _, line := range rawLines {
		line = strings.TrimSpace(line)
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 3 {
		return
	}

	targetFields := strings.Fields(lines[0])
	if len(targetFields) == 0 {
		return
	}
	target := targetFields[0]
	words := strings.Fields(lines[1])

	costFields := make([]string, 0)
	for i := 2; i < len(lines); i++ {
		costFields = append(costFields, strings.Fields(lines[i])...)
	}

	if len(words) != len(costFields) {
		return
	}

	costs := make([]int, len(costFields))
	for i, field := range costFields {
		costs[i], err = strconv.Atoi(field)
		if err != nil {
			return
		}
	}

	nodes := make([]node, 1, 50001)
	nodes[0].cost = infCost

	for i, word := range words {
		current := 0
		for j := 0; j < len(word); j++ {
			c := int(word[j] - 'a')
			if nodes[current].next[c] == 0 {
				nodes = append(nodes, node{cost: infCost})
				nodes[current].next[c] = len(nodes) - 1
			}
			current = nodes[current].next[c]
		}
		if costs[i] < nodes[current].cost {
			nodes[current].cost = costs[i]
			nodes[current].length = len(word)
		}
	}

	queue := make([]int, 0, len(nodes))
	for c := 0; c < 26; c++ {
		child := nodes[0].next[c]
		if child != 0 {
			queue = append(queue, child)
		}
	}

	for head := 0; head < len(queue); head++ {
		u := queue[head]
		for c := 0; c < 26; c++ {
			v := nodes[u].next[c]
			if v == 0 {
				nodes[u].next[c] = nodes[nodes[u].fail].next[c]
				continue
			}

			nodes[v].fail = nodes[nodes[u].fail].next[c]
			f := nodes[v].fail
			if nodes[f].cost != infCost {
				nodes[v].output = f
			} else {
				nodes[v].output = nodes[f].output
			}
			queue = append(queue, v)
		}
	}

	const inf int64 = 1 << 60
	dp := make([]int64, len(target)+1)
	for i := 1; i <= len(target); i++ {
		dp[i] = inf
	}

	state := 0
	for i := 1; i <= len(target); i++ {
		state = nodes[state].next[int(target[i-1]-'a')]

		p := state
		if nodes[p].cost == infCost {
			p = nodes[p].output
		}

		for p != 0 {
			start := i - nodes[p].length
			if start >= 0 && dp[start] != inf {
				candidate := dp[start] + int64(nodes[p].cost)
				if candidate < dp[i] {
					dp[i] = candidate
				}
			}
			p = nodes[p].output
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if dp[len(target)] == inf {
		fmt.Fprintln(writer, -1)
	} else {
		fmt.Fprintln(writer, dp[len(target)])
	}
}
