package main

import (
	"bufio"
	"fmt"
	"os"
)

type MaxHeap []int64

func (h *MaxHeap) Push(x int64) {
	*h = append(*h, x)
	i := len(*h) - 1
	for i > 0 {
		parent := (i - 1) / 2
		if (*h)[parent] >= (*h)[i] {
			break
		}
		(*h)[parent], (*h)[i] = (*h)[i], (*h)[parent]
		i = parent
	}
}

func (h *MaxHeap) ReplaceTop(x int64) {
	(*h)[0] = x
	n := len(*h)
	i := 0
	for {
		left := 2*i + 1
		right := left + 1
		largest := i

		if left < n && (*h)[left] > (*h)[largest] {
			largest = left
		}
		if right < n && (*h)[right] > (*h)[largest] {
			largest = right
		}
		if largest == i {
			break
		}

		(*h)[i], (*h)[largest] = (*h)[largest], (*h)[i]
		i = largest
	}
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	distances := make([]int64, n)
	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)
		distances[i] = abs(x) + abs(y)
	}

	var k int
	fmt.Fscan(in, &k)

	h := make(MaxHeap, 0, k)
	for i, distance := range distances {
		if len(h) < k {
			h.Push(distance)
		} else if distance < h[0] {
			h.ReplaceTop(distance)
		}

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		if len(h) < k {
			fmt.Fprint(out, -1)
		} else {
			fmt.Fprint(out, h[0])
		}
	}
	fmt.Fprintln(out)
}
