func parseRow(line string) []byte {
	row := make([]byte, 0, len(line))
	for i := 0; i < len(line); i++ {
		if line[i] == 'X' || line[i] == 'Y' || line[i] == '.' {
			row = append(row, line[i])
		}
	}
	return row
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	n := 0
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 {
			continue
		}
		var err error
		n, err = strconv.Atoi(fields[0])
		if err != nil {
			return
		}
		break
	}

	var diffByColumn []int
	var xByColumn []int
	rowsRead := 0
	var answer int64

	for rowsRead < n && scanner.Scan() {
		row := parseRow(scanner.Text())
		if len(row) == 0 {
			continue
		}

		if diffByColumn == nil {
			diffByColumn = make([]int, len(row))
			xByColumn = make([]int, len(row))
		}

		runningDiff := 0
		runningX := 0

		for j := 0; j < len(diffByColumn); j++ {
			switch row[j] {
			case 'X':
				diffByColumn[j]++
				xByColumn[j]++
			case 'Y':
				diffByColumn[j]--
			}

			runningDiff += diffByColumn[j]
			runningX += xByColumn[j]

			if runningDiff == 0 && runningX > 0 {
				answer++
			}
		}

		rowsRead++
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
