package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int {
	result := make([]int, 0)
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := 1
		if s[i] == '-' {
			sign = -1
			i++
		}

		value := 0
		hasDigit := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		if values := parseInts(scanner.Text()); len(values) > 0 {
			lines = append(lines, scanner.Text())
		}
	}

	if len(lines) < 2 {
		return
	}

	nums := parseInts(lines[0])
	kValues := parseInts(lines[1])
	if len(nums) == 0 || len(kValues) == 0 {
		return
	}
	k := kValues[0]

	pairs := len(nums) / 2
	diffFrequency := make([]int, k+1)
	thresholdFrequency := make([]int, k+1)

	for i := 0; i < pairs; i++ {
		x := nums[i]
		y := nums[len(nums)-1-i]
		if x > y {
			x, y = y, x
		}

		diff := y - x
		threshold := y
		if k-x > threshold {
			threshold = k - x
		}

		diffFrequency[diff]++
		thresholdFrequency[threshold]++
	}

	answer := 2 * pairs
	oneChangePairs := 0

	for x := k; x >= 0; x-- {
		oneChangePairs += thresholdFrequency[x]
		changes := 2*pairs - oneChangePairs - diffFrequency[x]
		if changes < answer {
			answer = changes
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
