package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
)

func parseInts(data []byte) []int {
	var result []int
	for i := 0; i < len(data); {
		if (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
			continue
		}

		sign := 1
		if data[i] == '-' {
			sign = -1
			i++
			if i >= len(data) || data[i] < '0' || data[i] > '9' {
				continue
			}
		}

		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	var rows [][]int
	for _, line := range bytes.Split(data, []byte{'\n'}) {
		values := parseInts(line)
		if len(values) > 0 {
			rows = append(rows, values)
		}
	}
	if len(rows) < 2 {
		return
	}

	var nums []int
	var k int

	// Supports both the specified format and an optional:
	// n
	// nums
	// k
	if len(rows) >= 3 && len(rows[0]) == 1 &&
		rows[0][0] == len(rows[1]) && len(rows[2]) == 1 {
		nums = rows[1]
		k = rows[2][0]
	} else {
		nums = rows[0]
		k = rows[1][0]
	}

	pairs := len(nums) / 2
	diffCount := make([]int, k+1)
	thresholdCount := make([]int, k+1)

	for i := 0; i < pairs; i++ {
		a := nums[i]
		b := nums[len(nums)-1-i]

		low, high := a, b
		if low > high {
			low, high = high, low
		}

		diff := high - low
		threshold := high
		if k-low > threshold {
			threshold = k - low
		}

		diffCount[diff]++
		thresholdCount[threshold]++
	}

	oneChangePossible := make([]int, k+1)
	running := 0
	for x := k; x >= 0; x-- {
		running += thresholdCount[x]
		oneChangePossible[x] = running
	}

	answer := 2 * pairs
	for x := 0; x <= k; x++ {
		changes := 2*pairs - oneChangePossible[x] - diffCount[x]
		if changes < answer {
			answer = changes
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
