		return !unicode.IsDigit(r) && r != '-'
	})
	nums := make([]int64, 0, len(fields))
	for _, field := range fields {
		if v, err := strconv.ParseInt(field, 10, 64); err == nil {
			nums = append(nums, v)
		}
	}
	return nums
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)

	var rows [][]int64
	for scanner.Scan() {
		row := parseInts(scanner.Text())
		if len(row) > 0 {
			rows = append(rows, row)
		}
	}

	var a, b []int64
	switch {
	case len(rows) >= 3 && len(rows[0]) == 1 &&
		int(rows[0][0]) == len(rows[1]) &&
		len(rows[1]) == len(rows[2]):
		a, b = rows[1], rows[2]
	case len(rows) >= 2:
		a, b = rows[0], rows[1]
	case len(rows) == 1:
		values := rows[0]
		if len(values) >= 3 && int(values[0])*2+1 == len(values) {
			n := int(values[0])
			a = values[1 : n+1]
			b = values[n+1:]
		} else {
			n := len(values) / 2
			a = values[:n]
			b = values[n:]
		}
	default:
		return
	}

	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	if n == 0 {
		fmt.Println(0)
		return
	}

	dpA := make([]int64, n)
	dpB := make([]int64, n)
	dpA[0], dpB[0] = a[0], b[0]

	if n >= 2 {
		dpA[1] = dpA[0] + a[1]
		dpB[1] = dpB[0] + b[1]
	}

	for i := 2; i < n; i++ {
		bestA := dpA[i-1]
		if dpB[i-2] > bestA {
			bestA = dpB[i-2]
		}
		dpA[i] = bestA + a[i]

		bestB := dpB[i-1]
		if dpA[i-2] > bestB {
			bestB = dpA[i-2]
		}
		dpB[i] = bestB + b[i]
	}

	answer := dpA[n-1]
	if dpB[n-1] > answer {
		answer = dpB[n-1]
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
