package main

import (
	"bufio"
	"fmt"
	"os"
)

type Line struct {
	m, b int64
}

func (ln Line) value(x int64) int64 {
	return ln.m*x + ln.b
}

type LiChaoTree struct {
	lines []Line
	used  []bool
	n     int
}

func NewLiChaoTree(n int) *LiChaoTree {
	return &LiChaoTree{
		lines: make([]Line, 4*n),
		used:  make([]bool, 4*n),
		n:     n,
	}
}

func (t *LiChaoTree) Add(line Line) {
	t.add(1, 0, t.n-1, line)
}

func (t *LiChaoTree) add(node, left, right int, line Line) {
	if !t.used[node] {
		t.lines[node] = line
		t.used[node] = true
		return
	}

	mid := (left + right) / 2
	current := t.lines[node]

	leftBetter := line.value(int64(left)) > current.value(int64(left))
	midBetter := line.value(int64(mid)) > current.value(int64(mid))

	if midBetter {
		t.lines[node], line = line, t.lines[node]
	}

	if left == right {
		return
	}

	if leftBetter != midBetter {
		t.add(node*2, left, mid, line)
	} else {
		t.add(node*2+1, mid+1, right, line)
	}
}

func (t *LiChaoTree) Query(x int) int64 {
	return t.query(1, 0, t.n-1, x)
}

func (t *LiChaoTree) query(node, left, right, x int) int64 {
	const negInf int64 = -1 << 60

	result := negInf
	if t.used[node] {
		result = t.lines[node].value(int64(x))
	}

	if left == right {
		return result
	}

	mid := (left + right) / 2
	var childResult int64
	if x <= mid {
		childResult = t.query(node*2, left, mid, x)
	} else {
		childResult = t.query(node*2+1, mid+1, right, x)
	}

	if childResult > result {
		result = childResult
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var nums []int64

	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if n <= 1 {
		fmt.Fprintln(out, 0)
		return
	}

	dp := make([]int64, n)
	tree := NewLiChaoTree(n)
	tree.Add(Line{m: nums[0], b: 0})

	for j := 1; j < n; j++ {
		dp[j] = tree.Query(j)
		tree.Add(Line{
			m: nums[j],
			b: dp[j] - int64(j)*nums[j],
		})
	}

	fmt.Fprintln(out, dp[n-1])
}
