package main

import (
	"bufio"
	"fmt"
	"os"
)

type Circle struct {
	x, y, r int64
}

type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}

func (d *DSU) Union(a, b int) {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return
	}
	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}
	d.parent[rb] = ra
	d.size[ra] += d.size[rb]
}

func square(x int64) int64 {
	return x * x
}

func distanceToVerticalSegmentSquared(x, y, edgeX, maxY int64) int64 {
	dx := x - edgeX
	var dy int64
	if y < 0 {
		dy = -y
	} else if y > maxY {
		dy = y - maxY
	}
	return square(dx) + square(dy)
}

func distanceToHorizontalSegmentSquared(x, y, edgeY, maxX int64) int64 {
	dy := y - edgeY
	var dx int64
	if x < 0 {
		dx = -x
	} else if x > maxX {
		dx = x - maxX
	}
	return square(dx) + square(dy)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var xCorner, yCorner int64
	var n int
	if _, err := fmt.Fscan(in, &xCorner, &yCorner, &n); err != nil {
		return
	}

	circles := make([]Circle, n)
	for i := range circles {
		fmt.Fscan(in, &circles[i].x, &circles[i].y, &circles[i].r)
	}

	// Group A represents the left and top edges.
	// Group B represents the bottom and right edges.
	groupA, groupB := n, n+1
	dsu := NewDSU(n + 2)

	for i, c := range circles {
		r2 := square(c.r)

		touchesLeft := distanceToVerticalSegmentSquared(c.x, c.y, 0, yCorner) <= r2
		touchesRight := distanceToVerticalSegmentSquared(c.x, c.y, xCorner, yCorner) <= r2
		touchesBottom := distanceToHorizontalSegmentSquared(c.x, c.y, 0, xCorner) <= r2
		touchesTop := distanceToHorizontalSegmentSquared(c.x, c.y, yCorner, xCorner) <= r2

		if touchesLeft || touchesTop {
			dsu.Union(i, groupA)
		}
		if touchesBottom || touchesRight {
			dsu.Union(i, groupB)
		}
	}

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			a, b := circles[i], circles[j]
			dx := a.x - b.x
			dy := a.y - b.y
			sumR := a.r + b.r

			if square(dx)+square(dy) > square(sumR) {
				continue
			}

			weightedX := a.x*b.r + b.x*a.r
			weightedY := a.y*b.r + b.y*a.r

			if weightedX < xCorner*sumR && weightedY < yCorner*sumR {
				dsu.Union(i, j)
			}
		}
	}

	fmt.Fprintln(out, dsu.Find(groupA) != dsu.Find(groupB))
}
