func readNonEmptyLine(scanner *bufio.Scanner) string {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line
		}
	}
	return ""
}

func parseInts(line string) []int64 {
	fields := strings.Fields(line)
	values := make([]int64, len(fields))
	for i, field := range fields {
		values[i], _ = strconv.ParseInt(field, 10, 64)
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	powerLine := readNonEmptyLine(scanner)
	damageLine := readNonEmptyLine(scanner)
	healthLine := readNonEmptyLine(scanner)

	power, _ := strconv.ParseInt(strings.Fields(powerLine)[0], 10, 64)
	damage := parseInts(damageLine)
	health := parseInts(healthLine)

	enemies := make([]Enemy, len(damage))
	var remainingDamage int64

	for i := range damage {
		enemies[i] = Enemy{
			damage: damage[i],
			attacks: (health[i] + power - 1) / power,
		}
		remainingDamage += damage[i]
	}

	sort.Slice(enemies, func(i, j int) bool {
		left := enemies[i].attacks * enemies[j].damage
		right := enemies[j].attacks * enemies[i].damage
		if left == right {
			return enemies[i].damage > enemies[j].damage
		}
		return left < right
	})

	var answer int64
	for _, enemy := range enemies {
		answer += enemy.attacks * remainingDamage
		remainingDamage -= enemy.damage
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
