package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type enemy struct {
	turns  int64
	damage int64
}

func parseInts(s string) []int64 {
	var nums []int64
	var value int64
	sign := int64(1)
	inNumber := false

	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] == '-' && !inNumber {
			sign = -1
			inNumber = true
			value = 0
		} else if i < len(s) && s[i] >= '0' && s[i] <= '9' {
			if !inNumber {
				inNumber = true
				sign = 1
				value = 0
			}
			value = value*10 + int64(s[i]-'0')
		} else if inNumber {
			nums = append(nums, sign*value)
			inNumber = false
			sign = 1
			value = 0
		}
	}
	return nums
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	lines := make([]string, 0, 3)
	for scanner.Scan() {
		line := scanner.Text()
		if len(parseInts(line)) > 0 {
			lines = append(lines, line)
		}
	}

	if len(lines) < 3 {
		return
	}

	powerValues := parseInts(lines[0])
	damage := parseInts(lines[1])
	health := parseInts(lines[2])

	if len(powerValues) == 0 || len(damage) != len(health) {
		return
	}

	power := powerValues[0]
	enemies := make([]enemy, len(damage))

	for i := range damage {
		enemies[i] = enemy{
			turns:  (health[i] + power - 1) / power,
			damage: damage[i],
		}
	}

	sort.Slice(enemies, func(i, j int) bool {
		left := enemies[i].turns * enemies[j].damage
		right := enemies[j].turns * enemies[i].damage
		if left == right {
			return enemies[i].damage > enemies[j].damage
		}
		return left < right
	})

	var totalDamage int64
	var elapsedTurns int64

	for _, e := range enemies {
		elapsedTurns += e.turns
		totalDamage += elapsedTurns * e.damage
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, totalDamage)
}
