)

const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)
	nums := make([]int, 0)

	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	if len(nums) == 0 {
		return
	}

	dp := make([]int64, nums[0]+1)
	for x := 0; x <= nums[0]; x++ {
		dp[x] = 1
	}

	for i := 1; i < len(nums); i++ {
		prefix := make([]int64, len(dp))
		prefix[0] = dp[0]
		for j := 1; j < len(dp); j++ {
			prefix[j] = (prefix[j-1] + dp[j]) % mod
		}

		next := make([]int64, nums[i]+1)
		for x := 0; x <= nums[i]; x++ {
			limit := x
			if candidate := x + nums[i-1] - nums[i]; candidate < limit {
				limit = candidate
			}
			if limit >= len(dp) {
				limit = len(dp) - 1
			}
			if limit >= 0 {
				next[x] = prefix[limit]
			}
		}
		dp = next
	}

	var answer int64
	for _, count := range dp {
		answer = (answer + count) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
