package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var m int
	if _, err := fmt.Fscan(in, &m); err != nil {
		return
	}

	n := m + 1
	adj := make([][]int, n)
	for i := 0; i < m; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, u)

		for _, v := range adj[u] {
			if v == parent[u] {
				continue
			}
			parent[v] = u
			stack = append(stack, v)
		}
	}

	weight := func(node int) int {
		if node%2 == 0 {
			return 2
		}
		return 1
	}

	// down[u] is the maximum time from u to a node in u's rooted subtree.
	down := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		u := order[i]
		for _, v := range adj[u] {
			if parent[v] == u {
				candidate := weight(v) + down[v]
				if candidate > down[u] {
					down[u] = candidate
				}
			}
		}
	}

	// up[u] is the maximum time from u to a node outside u's subtree.
	up := make([]int, n)
	answer := make([]int, n)

	for _, u := range order {
		best1, best2 := 0, 0
		bestChild := -1

		for _, v := range adj[u] {
			if parent[v] != u {
				continue
			}
			candidate := weight(v) + down[v]
			if candidate > best1 {
				best2 = best1
				best1 = candidate
				bestChild = v
			} else if candidate > best2 {
				best2 = candidate
			}
		}

		answer[u] = down[u]
		if up[u] > answer[u] {
			answer[u] = up[u]
		}

		for _, v := range adj[u] {
			if parent[v] != u {
				continue
			}

			bestExcludingV := best1
			if bestChild == v {
				bestExcludingV = best2
			}
			if up[u] > bestExcludingV {
				bestExcludingV = up[u]
			}

			up[v] = weight(u) + bestExcludingV
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}
