```go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type Fenwick struct {
	n    int
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int64, n+1),
	}
}

func (f *Fenwick) Add(index int, delta int64) {
	for i := index + 1; i <= f.n; i += i & -i {
		f.tree[i] += delta
	}
}

// Prefix returns the sum over indices [0, end).
func (f *Fenwick) Prefix(end int) int64 {
	var sum int64
	for i := end; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

func (f *Fenwick) Total() int64 {
	return f.Prefix(f.n)
}

// Kth returns the zero-based index containing the k-th item, where k is 1-based.
func (f *Fenwick) Kth(k int64) int {
	index := 0
	bit := 1
	for bit<<1 <= f.n {
		bit <<= 1
	}
	for bit > 0 {
		next := index + bit
		if next <= f.n && f.tree[next] < k {
			index = next
			k -= f.tree[next]
		}
		bit >>= 1
	}
	return index
}

func parseInts(line string) []int {
	fields := strings.Fields(line)
	values := make([]int, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.Atoi(field)
		if err == nil {
			values = append(values, value)
		}
	}
	return values
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	var firstLine string
	for {
		line, err := reader.ReadString('\n')
		if len(strings.TrimSpace(line)) > 0 {
			firstLine = line
			break
		}
		if err != nil {
			return
		}
	}

	colors := parseInts(firstLine)
	n := len(colors)
	if n == 0 {
		return
	}

	var queryCount int
	if _, err := fmt.Fscan(reader, &queryCount); err != nil && err != io.EOF {
		return
	}

	positions := NewFenwick(n)
	gapCounts := NewFenwick(n + 1)
	gapSums := NewFenwick(n + 1)

	active := make([]bool, n)
	badCount := 0

	addGap := func(length int, delta int64) {
		gapCounts.Add(length, delta)
		gapSums.Add(length, delta*int64(length))
	}

	clockwiseDistance := func(from, to int) int {
		distance := to - from
		if distance <= 0 {
			distance += n
		}
		return distance
	}

	predecessor := func(x int) int {
		before := positions.Prefix(x)
		if before > 0 {
			return positions.Kth(before)
		}
		return positions.Kth(int64(badCount))
	}

	successor := func(x int) int {
		throughX := positions.Prefix(x + 1)
		if throughX < int64(badCount) {
			return positions.Kth(throughX + 1)
		}
		return positions.Kth(1)
	}

	var insertBad func(int)
	var removeBad func(int)

	insertBad = func(x int) {
		if active[x] {
			return
		}

		if badCount == 0 {
			positions.Add(x, 1)
			active[x] = true
			badCount = 1
			addGap(n, 1)
			return
		}

		pred := predecessor(x)
		succ := successor(x)

		addGap(clockwiseDistance(pred, succ), -1)
		addGap(clockwiseDistance(pred, x), 1)
		addGap(clockwiseDistance(x, succ), 1)

		positions.Add(x, 1)
		active[x] = true
		badCount++
	}

	removeBad = func(x int) {
		if !active[x] {
			return
		}

		if badCount == 1 {
			addGap(n, -1)
			positions.Add(x, -1)
			active[x] = false
			badCount = 0
			return
		}

		pred := predecessor(x)
		succ := successor(x)

		addGap(clockwiseDistance(pred, x), -1)
		addGap(clockwiseDistance(x, succ), -1)
		addGap(clockwiseDistance(pred, succ), 1)

		positions.Add(x, -1)
		active[x] = false
		badCount--
	}

	for i := 0; i < n; i++ {
		if colors[i] == colors[(i+1)%n] {
			insertBad(i)
		}
	}

	answers := make([]int64, 0)

	for q := 0; q < queryCount; q++ {
		var queryType int
		fmt.Fscan(reader, &queryType)

		if queryType == 1 {
			var size int
			fmt.Fscan(reader, &size)

			if badCount == 0 {
				answers = append(answers, int64(n))
				continue
			}

			countBelow := gapCounts.Prefix(size)
			sumBelow := gapSums.Prefix(size)
			countAtLeast := gapCounts.Total() - countBelow
			sumAtLeast := gapSums.Total() - sumBelow

			result := sumAtLeast - int64(size-1)*countAtLeast
			answers = append(answers, result)
		} else {
			var index, newColor int
			fmt.Fscan(reader, &index, &newColor)

			if colors[index] == newColor {
				continue
			}

			leftEdge := (index - 1 + n) % n
			rightEdge := index

			oldLeftBad := colors[leftEdge] == colors[index]
			oldRightBad := colors[index] == colors[(index+1)%n]

			colors[index] = newColor

			newLeftBad := colors[leftEdge] == colors[index]
			newRightBad := colors[index] == colors[(index+1)%n]

			if oldLeftBad != newLeftBad {
				if newLeftBad {
					insertBad(leftEdge)
				} else {
					removeBad(leftEdge)
				}
			}

			if oldRightBad != newRightBad {
				if newRightBad {
					insertBad(rightEdge)
				} else {
					removeBad(rightEdge)
				}
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
