package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var edgeCount int
	if _, err := fmt.Fscan(in, &edgeCount); err != nil {
		return
	}

	n := edgeCount + 1
	adj := make([][]int, n)

	for i := 0; i < edgeCount; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	// The time needed to enter a node depends on its parity.
	weight := func(node int) int {
		if node%2 == 0 {
			return 2
		}
		return 1
	}

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, u)

		for _, v := range adj[u] {
			if v == parent[u] {
				continue
			}
			parent[v] = u
			stack = append(stack, v)
		}
	}

	// down[u] is the maximum marking time from u to a node in u's subtree.
	down := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		u := order[i]
		for _, v := range adj[u] {
			if parent[v] == u {
				candidate := weight(v) + down[v]
				if candidate > down[u] {
					down[u] = candidate
				}
			}
		}
	}

	// up[u] is the maximum marking time from u to a node outside u's subtree.
	up := make([]int, n)
	answer := make([]int, n)

	for _, u := range order {
		if down[u] > up[u] {
			answer[u] = down[u]
		} else {
			answer[u] = up[u]
		}

		best1, best2 := -1, -1
		bestChild := -1

		for _, v := range adj[u] {
			if parent[v] != u {
				continue
			}
			value := weight(v) + down[v]
			if value > best1 {
				best2 = best1
				best1 = value
				bestChild = v
			} else if value > best2 {
				best2 = value
			}
		}

		for _, v := range adj[u] {
			if parent[v] != u {
				continue
			}

			bestFromParent := up[u]
			if bestFromParent < 0 {
				bestFromParent = 0
			}

			siblingBest := best1
			if bestChild == v {
				siblingBest = best2
			}
			if siblingBest > bestFromParent {
				bestFromParent = siblingBest
			}

			up[v] = weight(u) + bestFromParent
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}
