package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PositionFenwick struct {
	n    int
	tree []int
}

func NewPositionFenwick(n int) *PositionFenwick {
	return &PositionFenwick{n: n, tree: make([]int, n+1)}
}

func (f *PositionFenwick) Add(pos, delta int) {
	for i := pos + 1; i <= f.n; i += i & -i {
		f.tree[i] += delta
	}
}

// Prefix returns the sum over positions [0, end).
func (f *PositionFenwick) Prefix(end int) int {
	sum := 0
	for i := end; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

// Kth returns the zero-based position of the k-th present element.
// k is one-based.
func (f *PositionFenwick) Kth(k int) int {
	idx := 0
	step := 1
	for step<<1 <= f.n {
		step <<= 1
	}
	for step > 0 {
		next := idx + step
		if next <= f.n && f.tree[next] < k {
			idx = next
			k -= f.tree[next]
		}
		step >>= 1
	}
	return idx
}

type LengthFenwick struct {
	n    int
	tree []int64
}

func NewLengthFenwick(n int) *LengthFenwick {
	return &LengthFenwick{n: n, tree: make([]int64, n+1)}
}

func (f *LengthFenwick) Add(length int, delta int64) {
	for i := length; i <= f.n; i += i & -i {
		f.tree[i] += delta
	}
}

// Prefix returns the sum for lengths in [1, length].
func (f *LengthFenwick) Prefix(length int) int64 {
	if length > f.n {
		length = f.n
	}
	var sum int64
	for i := length; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

type AlternatingGroups struct {
	n          int
	badCount   int
	positions  *PositionFenwick
	lengthCnt  *LengthFenwick
	lengthSum  *LengthFenwick
}

func NewAlternatingGroups(n int) *AlternatingGroups {
	return &AlternatingGroups{
		n:         n,
		positions: NewPositionFenwick(n),
		lengthCnt: NewLengthFenwick(n),
		lengthSum: NewLengthFenwick(n),
	}
}

func (a *AlternatingGroups) distance(from, to int) int {
	d := to - from
	if d <= 0 {
		d += a.n
	}
	return d
}

func (a *AlternatingGroups) addLength(length, delta int) {
	a.lengthCnt.Add(length, int64(delta))
	a.lengthSum.Add(length, int64(delta*length))
}

func (a *AlternatingGroups) insertBad(pos int) {
	if a.badCount == 0 {
		a.positions.Add(pos, 1)
		a.badCount = 1
		a.addLength(a.n, 1)
		return
	}

	before := a.positions.Prefix(pos)
	var pred int
	if before > 0 {
		pred = a.positions.Kth(before)
	} else {
		pred = a.positions.Kth(a.badCount)
	}

	through := a.positions.Prefix(pos + 1)
	var succ int
	if through < a.badCount {
		succ = a.positions.Kth(through + 1)
	} else {
		succ = a.positions.Kth(1)
	}

	a.addLength(a.distance(pred, succ), -1)
	a.addLength(a.distance(pred, pos), 1)
	a.addLength(a.distance(pos, succ), 1)

	a.positions.Add(pos, 1)
	a.badCount++
}

func (a *AlternatingGroups) removeBad(pos int) {
	if a.badCount == 1 {
		a.positions.Add(pos, -1)
		a.badCount = 0
		a.addLength(a.n, -1)
		return
	}

	before := a.positions.Prefix(pos)
	var pred int
	if before > 0 {
		pred = a.positions.Kth(before)
	} else {
		pred = a.positions.Kth(a.badCount)
	}

	through := a.positions.Prefix(pos + 1)
	var succ int
	if through < a.badCount {
		succ = a.positions.Kth(through + 1)
	} else {
		succ = a.positions.Kth(1)
	}

	a.addLength(a.distance(pred, pos), -1)
	a.addLength(a.distance(pos, succ), -1)
	a.addLength(a.distance(pred, succ), 1)

	a.positions.Add(pos, -1)
	a.badCount--
}

func (a *AlternatingGroups) query(size int) int64 {
	if a.badCount == 0 {
		return int64(a.n)
	}

	countAtLeast := a.lengthCnt.Prefix(a.n) - a.lengthCnt.Prefix(size-1)
	sumAtLeast := a.lengthSum.Prefix(a.n) - a.lengthSum.Prefix(size-1)

	return sumAtLeast - int64(size-1)*countAtLeast
}

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)

	var colorLine string
	for {
		line, err := reader.ReadString('\n')
		if strings.TrimSpace(line) != "" {
			colorLine = line
			break
		}
		if err != nil {
			return
		}
	}

	replacer := strings.NewReplacer("[", " ", "]", " ", ",", " ")
	fields := strings.Fields(replacer.Replace(colorLine))
	colors := make([]int, len(fields))
	for i, field := range fields {
		colors[i], _ = strconv.Atoi(field)
	}

	n := len(colors)
	groups := NewAlternatingGroups(n)

	for i := 0; i < n; i++ {
		if colors[i] == colors[(i+1)%n] {
			groups.insertBad(i)
		}
	}

	var q int
	fmt.Fscan(reader, &q)

	answers := make([]int64, 0)
	for ; q > 0; q-- {
		var queryType int
		fmt.Fscan(reader, &queryType)

		if queryType == 1 {
			var size int
			fmt.Fscan(reader, &size)
			answers = append(answers, groups.query(size))
			continue
		}

		var index, newColor int
		fmt.Fscan(reader, &index, &newColor)

		if colors[index] == newColor {
			continue
		}

		prevEdge := (index - 1 + n) % n
		nextEdge := index

		oldPrevBad := colors[prevEdge] == colors[index]
		oldNextBad := colors[index] == colors[(index+1)%n]

		colors[index] = newColor

		newPrevBad := colors[prevEdge] == colors[index]
		newNextBad := colors[index] == colors[(index+1)%n]

		if oldPrevBad != newPrevBad {
			if newPrevBad {
				groups.insertBad(prevEdge)
			} else {
				groups.removeBad(prevEdge)
			}
		}

		if oldNextBad != newNextBad {
			if newNextBad {
				groups.insertBad(nextEdge)
			} else {
				groups.removeBad(nextEdge)
			}
		}
	}

	writer := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
