package main

import (
	"bufio"
	"fmt"
	"os"
)

func power10(exp int) int64 {
	result := int64(1)
	for i := 0; i < exp; i++ {
		result *= 10
	}
	return result
}

func makePalindrome(half int64, oddLength bool) int64 {
	result := half
	if oddLength {
		half /= 10
	}
	for half > 0 {
		result = result*10 + half%10
		half /= 10
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	halfLength := (n + 1) / 2
	start := power10(halfLength - 1)
	end := power10(halfLength)

	signatures := make(map[[10]int]struct{})

	for half := start; half < end; half++ {
		palindrome := makePalindrome(half, n%2 == 1)
		if palindrome%k != 0 {
			continue
		}

		var counts [10]int
		value := palindrome
		for value > 0 {
			counts[value%10]++
			value /= 10
		}
		signatures[counts] = struct{}{}
	}

	factorial := make([]int64, n+1)
	factorial[0] = 1
	for i := 1; i <= n; i++ {
		factorial[i] = factorial[i-1] * int64(i)
	}

	var answer int64

	for counts := range signatures {
		total := factorial[n]
		for digit := 0; digit < 10; digit++ {
			total /= factorial[counts[digit]]
		}

		var leadingZero int64
		if counts[0] > 0 {
			leadingZero = factorial[n-1]
			leadingZero /= factorial[counts[0]-1]
			for digit := 1; digit < 10; digit++ {
				leadingZero /= factorial[counts[digit]]
			}
		}

		answer += total - leadingZero
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
