	"strings"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)

	var firstLine string
	for {
		line, err := reader.ReadString('\n')
		if strings.TrimSpace(line) != "" {
			firstLine = line
			break
		}
		if err != nil {
			return
		}
	}

	fields := strings.Fields(firstLine)
	nums := make([]uint32, len(fields))
	for i, field := range fields {
		value, _ := strconv.ParseUint(field, 10, 32)
		nums[i] = uint32(value)
	}
	n := len(nums)

	var q int
	fmt.Fscan(reader, &q)

	left := make([]int, q)
	right := make([]int, q)
	for i := 0; i < q; i++ {
		fmt.Fscan(reader, &left[i], &right[i])
	}

	// best[l*n+r] is the maximum XOR score of any subarray in nums[l..r].
	best := make([]uint32, n*n)

	// Scores of intervals of the previous and current lengths.
	prevScore := make([]uint32, n)
	currScore := make([]uint32, n)
	copy(prevScore, nums)

	for i, value := range nums {
		best[i*n+i] = value
	}

	for length := 2; length <= n; length++ {
		limit := n - length + 1
		for l := 0; l < limit; l++ {
			r := l + length - 1
			score := prevScore[l] ^ prevScore[l+1]
			currScore[l] = score

			maxScore := score
			if v := best[l*n+r-1]; v > maxScore {
				maxScore = v
			}
			if v := best[(l+1)*n+r]; v > maxScore {
				maxScore = v
			}
			best[l*n+r] = maxScore
		}
		prevScore, currScore = currScore, prevScore
	}

	writer := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer writer.Flush()

	for i := 0; i < q; i++ {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, best[left[i]*n+right[i]])
	}
	fmt.Fprintln(writer)
}
