		return
	}

	values := make([]int64, 0, m*100)
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		values = append(values, x)
	}

	if m == 0 || len(values)%m != 0 {
		return
	}
	n := len(values) / m

	candidates := make([]cell, 0, 3*m)
	for r := 0; r < m; r++ {
		row := make([]cell, n)
		for c := 0; c < n; c++ {
			row[c] = cell{row: r, col: c, val: values[r*n+c]}
		}
		sort.Slice(row, func(i, j int) bool {
			return row[i].val > row[j].val
		})

		limit := 3
		if n < limit {
			limit = n
		}
		candidates = append(candidates, row[:limit]...)
	}

	const minInt64 = int64(-1 << 63)
	answer := minInt64

	for i := 0; i < len(candidates); i++ {
		a := candidates[i]
		for j := i + 1; j < len(candidates); j++ {
			b := candidates[j]
			if a.row == b.row || a.col == b.col {
				continue
			}
			for k := j + 1; k < len(candidates); k++ {
				c := candidates[k]
				if c.row == a.row || c.row == b.row ||
					c.col == a.col || c.col == b.col {
					continue
				}

				sum := a.val + b.val + c.val
				if sum > answer {
					answer = sum
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
