	scanner.Buffer(make([]byte, 1024), 1024*1024)

	numFields := strings.Fields(readNonEmptyLine(scanner))
	nums := make([]int, len(numFields))
	for i, field := range numFields {
		nums[i], _ = strconv.Atoi(field)
	}

	k, _ := strconv.Atoi(readNonEmptyLine(scanner))
	multiplier, _ := strconv.Atoi(readNonEmptyLine(scanner))

	for operation := 0; operation < k; operation++ {
		minIndex := 0
		for i := 1; i < len(nums); i++ {
			if nums[i] < nums[minIndex] {
				minIndex = i
			}
		}
		nums[minIndex] *= multiplier
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, value := range nums {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, value)
	}
