func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, k int
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	half := (n + 1) / 2

	pow10 := make([]int, n)
	pow10[0] = 1 % k
	for i := 1; i < n; i++ {
		pow10[i] = (pow10[i-1] * 10) % k
	}

	weight := make([]int, half)
	for i := 0; i < half; i++ {
		if i == n-1-i {
			weight[i] = pow10[i]
		} else {
			weight[i] = (pow10[i] + pow10[n-1-i]) % k
		}
	}

	// possible[i*k+r] is true if positions i..half-1 can contribute
	// a remainder of r modulo k.
	possible := make([]bool, (half+1)*k)
	possible[half*k] = true

	for i := half - 1; i >= 0; i-- {
		base := i * k
		next := (i + 1) * k
		for d := 0; d <= 9; d++ {
			add := (d * weight[i]) % k
			for r := 0; r < k; r++ {
				if possible[next+r] {
					possible[base+(add+r)%k] = true
				}
			}
		}
	}

	left := make([]byte, half)
	remainder := 0

	for i := 0; i < half; i++ {
		minDigit := 0
		if i == 0 {
			minDigit = 1
		}

		for d := 9; d >= minDigit; d-- {
			newRemainder := (remainder + d*weight[i]) % k
			needed := (k - newRemainder) % k
			if possible[(i+1)*k+needed] {
				left[i] = byte('0' + d)
				remainder = newRemainder
				break
			}
		}
	}

	answer := make([]byte, n)
	for i := 0; i < half; i++ {
		answer[i] = left[i]
		answer[n-1-i] = left[i]
	}

	fmt.Fprintln(out, string(answer))
}
