	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, k int
	fmt.Fscan(in, &n, &k)

	factorial := make([]int64, n+1)
	factorial[0] = 1
	for i := 1; i <= n; i++ {
		factorial[i] = factorial[i-1] * int64(i)
	}

	halfLen := (n + 1) / 2
	start := int64(1)
	for i := 1; i < halfLen; i++ {
		start *= 10
	}
	end := start * 10

	signatures := make(map[[10]int]struct{})

	for prefix := start; prefix < end; prefix++ {
		palindrome := prefix
		reversedPart := prefix
		if n%2 == 1 {
			reversedPart /= 10
		}

		for reversedPart > 0 {
			palindrome = palindrome*10 + reversedPart%10
			reversedPart /= 10
		}

		if palindrome%int64(k) != 0 {
			continue
		}

		var counts [10]int
		value := palindrome
		for value > 0 {
			counts[value%10]++
			value /= 10
		}
		signatures[counts] = struct{}{}
	}

	var answer int64

	for counts := range signatures {
		total := factorial[n]
		for digit := 0; digit < 10; digit++ {
			total /= factorial[counts[digit]]
		}

		var leadingZero int64
		if counts[0] > 0 {
			leadingZero = factorial[n-1]
			leadingZero /= factorial[counts[0]-1]
			for digit := 1; digit < 10; digit++ {
				leadingZero /= factorial[counts[digit]]
			}
		}

		answer += total - leadingZero
	}

	fmt.Fprintln(out, answer)
}
