	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, k int
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	half := (n + 1) / 2

	pow10 := make([]int, n)
	pow10[0] = 1 % k
	for i := 1; i < n; i++ {
		pow10[i] = (pow10[i-1] * 10) % k
	}

	weights := make([]int, half)
	for i := 0; i < half; i++ {
		mirror := n - 1 - i
		if i == mirror {
			weights[i] = pow10[i]
		} else {
			weights[i] = (pow10[i] + pow10[mirror]) % k
		}
	}

	// suffix[i] is a bitmask of remainders achievable using positions i..half-1.
	suffix := make([]uint16, half+1)
	suffix[half] = 1 // Only remainder 0 is possible with no digits.

	for i := half - 1; i >= 0; i-- {
		var mask uint16
		for remainder := 0; remainder < k; remainder++ {
			if suffix[i+1]&(uint16(1)<<remainder) == 0 {
				continue
			}
			for digit := 0; digit <= 9; digit++ {
				next := (remainder + digit*weights[i]) % k
				mask |= uint16(1) << next
			}
		}
		suffix[i] = mask
	}

	answer := make([]byte, n)
	currentRemainder := 0

	for i := 0; i < half; i++ {
		minDigit := 0
		if i == 0 {
			minDigit = 1
		}

		for digit := 9; digit >= minDigit; digit-- {
			nextRemainder := (currentRemainder + digit*weights[i]) % k
			needed := (k - nextRemainder) % k

			if suffix[i+1]&(uint16(1)<<needed) != 0 {
				answer[i] = byte('0' + digit)
				answer[n-1-i] = byte('0' + digit)
				currentRemainder = nextRemainder
				break
			}
		}
	}

	fmt.Fprintln(out, string(answer))
}
