type candidate struct {
	value int64
	col   int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var m int
	if _, err := fmt.Fscan(in, &m); err != nil {
		return
	}

	var cells []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		cells = append(cells, x)
	}

	if m < 3 || len(cells)%m != 0 {
		return
	}
	n := len(cells) / m
	if n < 3 {
		return
	}

	const negInf int64 = -1 << 62
	top := make([][3]candidate, m)

	for r := 0; r < m; r++ {
		for k := 0; k < 3; k++ {
			top[r][k] = candidate{value: negInf, col: -1}
		}

		for c := 0; c < n; c++ {
			cur := candidate{
				value: cells[r*n+c],
				col:   c,
			}
			for k := 0; k < 3; k++ {
				if cur.value > top[r][k].value {
					for p := 2; p > k; p-- {
						top[r][p] = top[r][p-1]
					}
					top[r][k] = cur
					break
				}
			}
		}
	}

	answer := negInf

	for r1 := 0; r1 < m-2; r1++ {
		for r2 := r1 + 1; r2 < m-1; r2++ {
			for r3 := r2 + 1; r3 < m; r3++ {
				for a := 0; a < 3; a++ {
					for b := 0; b < 3; b++ {
						if top[r1][a].col == top[r2][b].col {
							continue
						}
						for c := 0; c < 3; c++ {
							if top[r1][a].col == top[r3][c].col ||
								top[r2][b].col == top[r3][c].col {
								continue
							}

							sum := top[r1][a].value +
								top[r2][b].value +
								top[r3][c].value
							if sum > answer {
								answer = sum
							}
						}
					}
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
