	"container/list"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Point struct {
	r, c int
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 {
			continue
		}
		values := make([]int, len(fields))
		for i, field := range fields {
			value, err := strconv.Atoi(field)
			if err != nil {
				return
			}
			values[i] = value
		}
		lines = append(lines, values)
	}

	if len(lines) < 3 || len(lines[0]) == 0 {
		return
	}

	m := lines[0][0]
	if m <= 0 || len(lines) < m+2 {
		return
	}

	grid := make([][]int, m)
	for i := 0; i < m; i++ {
		grid[i] = lines[i+1]
	}
	if len(grid[0]) == 0 {
		return
	}
	n := len(grid[0])

	healthLine := lines[m+1]
	if len(healthLine) == 0 {
		return
	}
	health := healthLine[0]

	const inf = int(^uint(0) >> 1)
	dist := make([][]int, m)
	for i := range dist {
		if len(grid[i]) != n {
			return
		}
		dist[i] = make([]int, n)
		for j := range dist[i] {
			dist[i][j] = inf
		}
	}

	dist[0][0] = grid[0][0]
	deque := list.New()
	deque.PushFront(Point{0, 0})

	directions := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	for deque.Len() > 0 {
		front := deque.Front()
		p := front.Value.(Point)
		deque.Remove(front)

		for _, d := range directions {
			nr, nc := p.r+d[0], p.c+d[1]
			if nr < 0 || nr >= m || nc < 0 || nc >= n {
				continue
			}

			newCost := dist[p.r][p.c] + grid[nr][nc]
			if newCost >= dist[nr][nc] {
				continue
			}

			dist[nr][nc] = newCost
			if grid[nr][nc] == 0 {
				deque.PushFront(Point{nr, nc})
			} else {
				deque.PushBack(Point{nr, nc})
			}
		}
	}

	fmt.Println(dist[m-1][n-1] < health)
}
