type TrieNode struct {
	next [26]int
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	fields := splitFields(string(data))
	if len(fields) < 2 {
		return
	}

	words := fields[:len(fields)-1]
	target := fields[len(fields)-1]

	trie := make([]TrieNode, 1)
	for _, word := range words {
		node := 0
		for i := 0; i < len(word); i++ {
			c := int(word[i] - 'a')
			if trie[node].next[c] == 0 {
				trie = append(trie, TrieNode{})
				trie[node].next[c] = len(trie) - 1
			}
			node = trie[node].next[c]
		}
	}

	n := len(target)
	maxLen := make([]int, n)

	for i := 0; i < n; i++ {
		node := 0
		for j := i; j < n; j++ {
			c := int(target[j] - 'a')
			next := trie[node].next[c]
			if next == 0 {
				break
			}
			node = next
			maxLen[i] = j - i + 1
		}
	}

	steps := 0
	currentEnd := 0
	farthest := 0
	answer := -1

	for i := 0; i < n; i++ {
		if i > farthest {
			break
		}
		if i+maxLen[i] > farthest {
			farthest = i + maxLen[i]
		}
		if i == currentEnd {
			if farthest == currentEnd {
				break
			}
			steps++
			currentEnd = farthest
			if currentEnd >= n {
				answer = steps
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

func splitFields(s string) []string {
	var fields []string
	start := -1

	for i := 0; i <= len(s); i++ {
		isSpace := i == len(s) ||
			s[i] == ' ' || s[i] == '\n' || s[i] == '\r' ||
			s[i] == '\t' || s[i] == '\v' || s[i] == '\f'

		if isSpace {
			if start != -1 {
				fields = append(fields, s[start:i])
				start = -1
			}
		} else if start == -1 {
			start = i
		}
	}

	return fields
}
