package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

const boardSize = 50

type Point struct {
	x, y int
}

func knightDistances(start Point) [boardSize][boardSize]int {
	var dist [boardSize][boardSize]int
	for i := 0; i < boardSize; i++ {
		for j := 0; j < boardSize; j++ {
			dist[i][j] = -1
		}
	}

	dx := [8]int{2, 2, -2, -2, 1, 1, -1, -1}
	dy := [8]int{1, -1, 1, -1, 2, -2, 2, -2}

	queue := make([]Point, boardSize*boardSize)
	head, tail := 0, 0
	queue[tail] = start
	tail++
	dist[start.x][start.y] = 0

	for head < tail {
		cur := queue[head]
		head++

		for i := 0; i < 8; i++ {
			nx, ny := cur.x+dx[i], cur.y+dy[i]
			if nx < 0 || nx >= boardSize || ny < 0 || ny >= boardSize {
				continue
			}
			if dist[nx][ny] != -1 {
				continue
			}

			dist[nx][ny] = dist[cur.x][cur.y] + 1
			queue[tail] = Point{nx, ny}
			tail++
		}
	}

	return dist
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var kx, ky, n int
	if _, err := fmt.Fscan(in, &kx); err != nil {
		return
	}
	fmt.Fscan(in, &ky)
	fmt.Fscan(in, &n)

	points := make([]Point, n+1)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &points[i].x, &points[i].y)
	}
	points[n] = Point{kx, ky}

	distance := make([][]int, n+1)
	for i := range distance {
		distance[i] = make([]int, n+1)
		boardDist := knightDistances(points[i])
		for j := 0; j < n+1; j++ {
			distance[i][j] = boardDist[points[j].x][points[j].y]
		}
	}

	maskCount := 1 << n
	memo := make([]int, (n+1)*maskCount)
	for i := range memo {
		memo[i] = -1
	}

	var solve func(pos, mask int) int
	solve = func(pos, mask int) int {
		if mask == 0 {
			return 0
		}

		index := pos*maskCount + mask
		if memo[index] != -1 {
			return memo[index]
		}

		captured := n - bits.OnesCount(uint(mask))
		aliceTurn := captured%2 == 0

		var best int
		if aliceTurn {
			best = -1
			for i := 0; i < n; i++ {
				if mask&(1<<i) != 0 {
					value := distance[pos][i] + solve(i, mask^(1<<i))
					if value > best {
						best = value
					}
				}
			}
		} else {
			best = int(^uint(0) >> 1)
			for i := 0; i < n; i++ {
				if mask&(1<<i) != 0 {
					value := distance[pos][i] + solve(i, mask^(1<<i))
					if value < best {
						best = value
					}
				}
			}
		}

		memo[index] = best
		return best
	}

	fmt.Fprintln(out, solve(n, maskCount-1))
}
