	if _, err := fmt.Fscan(in, &m); err != nil || m <= 0 {
		return
	}

	grid := make([][]int, m)

	// The number of columns is determined from the first matrix row.
	// Since rows are newline-separated, read the remainder of the first line,
	// then scan each row as a line.
	in.ReadString('\n')

	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 1024), 1024*1024)

	for i := 0; i < m; {
		if !scanner.Scan() {
			return
		}

		line := scanner.Text()
		var row []int
		for j := 0; j < len(line); j++ {
			if line[j] == '0' || line[j] == '1' {
				row = append(row, int(line[j]-'0'))
			}
		}

		if len(row) == 0 {
			continue
		}
		grid[i] = row
		i++
	}

	var health int
	for scanner.Scan() {
		line := scanner.Text()
		if _, err := fmt.Sscan(line, &health); err == nil {
			break
		}
	}

	n := len(grid[0])
	remaining := health - grid[0][0]
	if remaining <= 0 {
		fmt.Println(false)
		return
	}

	best := make([][]int, m)
	for i := range best {
		best[i] = make([]int, n)
		for j := range best[i] {
			best[i][j] = -1
		}
	}
	best[0][0] = remaining

	queue := []State{{0, 0, remaining}}
	directions := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

	for head := 0; head < len(queue); head++ {
		cur := queue[head]
		if cur.health < best[cur.r][cur.c] {
			continue
		}
		if cur.r == m-1 && cur.c == n-1 {
			fmt.Println(true)
			return
		}

		for _, d := range directions {
			nr, nc := cur.r+d[0], cur.c+d[1]
			if nr < 0 || nr >= m || nc < 0 || nc >= n {
				continue
			}

			nextHealth := cur.health - grid[nr][nc]
			if nextHealth > 0 && nextHealth > best[nr][nc] {
				best[nr][nc] = nextHealth
				queue = append(queue, State{nr, nc, nextHealth})
			}
		}
	}

	fmt.Println(false)
}
