package main

import (
	"bufio"
	"fmt"
	"os"
)

func vowelIndex(c byte) int {
	switch c {
	case 'a':
		return 0
	case 'e':
		return 1
	case 'i':
		return 2
	case 'o':
		return 3
	case 'u':
		return 4
	default:
		return -1
	}
}

func countAtMost(word string, limit int) int64 {
	if limit < 0 {
		return 0
	}

	last := [5]int{-1, -1, -1, -1, -1}
	left, consonants := 0, 0
	var total int64

	for right := 0; right < len(word); right++ {
		if idx := vowelIndex(word[right]); idx >= 0 {
			last[idx] = right
		} else {
			consonants++
		}

		for consonants > limit {
			if vowelIndex(word[left]) < 0 {
				consonants--
			}
			left++
		}

		minLast := last[0]
		for i := 1; i < 5; i++ {
			if last[i] < minLast {
				minLast = last[i]
			}
		}

		if minLast >= left {
			total += int64(minLast - left + 1)
		}
	}

	return total
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var word string
	var k int
	fmt.Fscan(in, &word, &k)

	answer := countAtMost(word, k) - countAtMost(word, k-1)
	fmt.Fprintln(out, answer)
}
