package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Point struct {
	x, y int
	id   int
}

type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int, n+1)}
}

func (f *Fenwick) Update(i, value int) {
	for i < len(f.tree) {
		if value > f.tree[i] {
			f.tree[i] = value
		}
		i += i & -i
	}
}

func (f *Fenwick) Query(i int) int {
	result := 0
	for i > 0 {
		if f.tree[i] > result {
			result = f.tree[i]
		}
		i -= i & -i
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	points := make([]Point, n)
	ys := make([]int, n)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &points[i].x, &points[i].y)
		points[i].id = i
		ys[i] = points[i].y
	}

	var k int
	fmt.Fscan(in, &k)

	sort.Ints(ys)
	uniqueYs := ys[:0]
	for _, y := range ys {
		if len(uniqueYs) == 0 || uniqueYs[len(uniqueYs)-1] != y {
			uniqueYs = append(uniqueYs, y)
		}
	}

	rank := func(y int) int {
		return sort.SearchInts(uniqueYs, y) + 1
	}

	sort.Slice(points, func(i, j int) bool {
		if points[i].x != points[j].x {
			return points[i].x < points[j].x
		}
		return points[i].y < points[j].y
	})

	m := len(uniqueYs)
	ending := make([]int, n)
	starting := make([]int, n)

	// Longest increasing path ending at each point.
	bit := NewFenwick(m)
	for i := 0; i < n; {
		j := i
		for j < n && points[j].x == points[i].x {
			j++
		}

		// Query before updating so equal-x points cannot follow each other.
		for p := i; p < j; p++ {
			r := rank(points[p].y)
			ending[points[p].id] = bit.Query(r-1) + 1
		}
		for p := i; p < j; p++ {
			r := rank(points[p].y)
			bit.Update(r, ending[points[p].id])
		}

		i = j
	}

	// Longest increasing path starting at each point.
	// Reverse y ranks turn querying y' > y into a Fenwick prefix query.
	bit = NewFenwick(m)
	for i := n - 1; i >= 0; {
		left := i
		for left >= 0 && points[left].x == points[i].x {
			left--
		}
		left++

		// Query before updating so equal-x points cannot follow each other.
		for p := left; p <= i; p++ {
			r := rank(points[p].y)
			reversedRank := m - r + 1
			starting[points[p].id] = bit.Query(reversedRank-1) + 1
		}
		for p := left; p <= i; p++ {
			r := rank(points[p].y)
			reversedRank := m - r + 1
			bit.Update(reversedRank, starting[points[p].id])
		}

		i = left - 1
	}

	fmt.Fprintln(out, ending[k]+starting[k]-1)
}
