```go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner(r io.Reader) *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(r, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var value int64
	var sign int64 = 1

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if err != nil {
		return 0
	}

	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}

	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return value * sign
}

type Interval struct {
	left, right int64
	weight      int64
	index       int
}

type State struct {
	score int64
	ids   [4]int
	length int
	valid bool
}

func lexLess(a [4]int, aLen int, b [4]int, bLen int) bool {
	n := aLen
	if bLen < n {
		n = bLen
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return aLen < bLen
}

func better(a, b State) bool {
	if !a.valid {
		return false
	}
	if !b.valid {
		return true
	}
	if a.score != b.score {
		return a.score > b.score
	}
	return lexLess(a.ids, a.length, b.ids, b.length)
}

func addIndex(base State, index int, weight int64) State {
	result := base
	result.score += weight
	result.valid = true

	pos := result.length
	for pos > 0 && result.ids[pos-1] > index {
		result.ids[pos] = result.ids[pos-1]
		pos--
	}
	result.ids[pos] = index
	result.length++
	return result
}

func main() {
	in := NewFastScanner(os.Stdin)
	n := int(in.NextInt64())

	intervals := make([]Interval, n)
	for i := 0; i < n; i++ {
		intervals[i] = Interval{
			left:   in.NextInt64(),
			right:  in.NextInt64(),
			weight: in.NextInt64(),
			index:  i,
		}
	}

	sort.Slice(intervals, func(i, j int) bool {
		if intervals[i].right != intervals[j].right {
			return intervals[i].right < intervals[j].right
		}
		if intervals[i].left != intervals[j].left {
			return intervals[i].left < intervals[j].left
		}
		return intervals[i].index < intervals[j].index
	})

	ends := make([]int64, n)
	for i := range intervals {
		ends[i] = intervals[i].right
	}

	dp := make([][5]State, n+1)
	dp[0][0] = State{valid: true}

	for i := 1; i <= n; i++ {
		current := intervals[i-1]
		predecessor := sort.Search(i-1, func(j int) bool {
			return ends[j] >= current.left
		})

		dp[i][0] = dp[i-1][0]
		for count := 1; count <= 4; count++ {
			best := dp[i-1][count]

			base := dp[predecessor][count-1]
			if base.valid {
				candidate := addIndex(base, current.index, current.weight)
				if better(candidate, best) {
					best = candidate
				}
			}
			dp[i][count] = best
		}
	}

	answer := dp[n][0]
	for count := 1; count <= 4; count++ {
		if better(dp[n][count], answer) {
			answer = dp[n][count]
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i := 0; i < answer.length; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer.ids[i])
	}
	fmt.Fprintln(out)
}
