package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Interval struct {
	left, right int64
	weight      int64
	index       int
}

type Candidate struct {
	weight  int64
	length  int
	indices [4]int
}

func better(a, b Candidate) Candidate {
	if a.weight != b.weight {
		if a.weight > b.weight {
			return a
		}
		return b
	}

	limit := a.length
	if b.length < limit {
		limit = b.length
	}
	for i := 0; i < limit; i++ {
		if a.indices[i] < b.indices[i] {
			return a
		}
		if a.indices[i] > b.indices[i] {
			return b
		}
	}
	if a.length <= b.length {
		return a
	}
	return b
}

func addInterval(base Candidate, in Interval) Candidate {
	result := base
	result.weight += in.weight

	pos := result.length
	for pos > 0 && result.indices[pos-1] > in.index {
		result.indices[pos] = result.indices[pos-1]
		pos--
	}
	result.indices[pos] = in.index
	result.length++
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	intervals := make([]Interval, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &intervals[i].left, &intervals[i].right, &intervals[i].weight)
		intervals[i].index = i
	}

	sort.Slice(intervals, func(i, j int) bool {
		if intervals[i].right != intervals[j].right {
			return intervals[i].right < intervals[j].right
		}
		if intervals[i].left != intervals[j].left {
			return intervals[i].left < intervals[j].left
		}
		return intervals[i].index < intervals[j].index
	})

	ends := make([]int64, n)
	for i := range intervals {
		ends[i] = intervals[i].right
	}

	dp := make([][5]Candidate, n+1)

	for i := 1; i <= n; i++ {
		current := intervals[i-1]

		// Number of intervals ending strictly before current.left.
		p := sort.Search(n, func(j int) bool {
			return ends[j] >= current.left
		})

		for k := 1; k <= 4; k++ {
			skip := dp[i-1][k]
			take := addInterval(dp[p][k-1], current)
			dp[i][k] = better(skip, take)
		}
	}

	answer := dp[n][4]
	for i := 0; i < answer.length; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer.indices[i])
	}
	fmt.Fprintln(out)
}
