import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	fmt.Fscan(in, &k)

	var stayRows int
	fmt.Fscan(in, &stayRows)
	stayScore := make([][]int, stayRows)
	for i := 0; i < stayRows; i++ {
		stayScore[i] = make([]int, n)
		for j := 0; j < n; j++ {
			fmt.Fscan(in, &stayScore[i][j])
		}
	}

	var travelRows int
	fmt.Fscan(in, &travelRows)
	travelScore := make([][]int, travelRows)
	for i := 0; i < travelRows; i++ {
		travelScore[i] = make([]int, n)
		for j := 0; j < n; j++ {
			fmt.Fscan(in, &travelScore[i][j])
		}
	}

	dp := make([]int, n)

	for day := 0; day < k; day++ {
		next := make([]int, n)
		for dest := 0; dest < n; dest++ {
			best := dp[dest] + stayScore[day][dest]
			for curr := 0; curr < n; curr++ {
				if curr == dest {
					continue
				}
				score := dp[curr] + travelScore[curr][dest]
				if score > best {
					best = score
				}
			}
			next[dest] = best
		}
		dp = next
	}

	answer := dp[0]
	for city := 1; city < n; city++ {
		if dp[city] > answer {
			answer = dp[city]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
