package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func roundScore(bob, alice byte) int {
	if bob == alice {
		return 0
	}
	if (bob == 'F' && alice == 'E') ||
		(bob == 'W' && alice == 'F') ||
		(bob == 'E' && alice == 'W') {
		return 1
	}
	return -1
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	n := len(s)
	width := 2*n + 1
	offset := n
	moves := []byte{'F', 'W', 'E'}

	dp := make([][]int64, 3)
	next := make([][]int64, 3)
	for i := 0; i < 3; i++ {
		dp[i] = make([]int64, width)
		next[i] = make([]int64, width)
		score := roundScore(moves[i], s[0])
		dp[i][offset+score] = 1
	}

	for round := 1; round < n; round++ {
		for i := 0; i < 3; i++ {
			clear(next[i])
		}

		for last := 0; last < 3; last++ {
			for scoreIndex, count := range dp[last] {
				if count == 0 {
					continue
				}
				for move := 0; move < 3; move++ {
					if move == last {
						continue
					}
					newIndex := scoreIndex + roundScore(moves[move], s[round])
					next[move][newIndex] = (next[move][newIndex] + count) % mod
				}
			}
		}
		dp, next = next, dp
	}

	var answer int64
	for last := 0; last < 3; last++ {
		for scoreIndex := offset + 1; scoreIndex < width; scoreIndex++ {
			answer = (answer + dp[last][scoreIndex]) % mod
		}
	}

	fmt.Fprintln(out, answer)
}
