package main

import (
	"bufio"
	"fmt"
	"os"
)

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}
	return a / gcd(a, b) * b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var nums []int64

	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	var best int64
	for removed := -1; removed < len(nums); removed++ {
		var g, l int64
		count := 0

		for i, x := range nums {
			if i == removed {
				continue
			}
			if count == 0 {
				g, l = x, x
			} else {
				g = gcd(g, x)
				l = lcm(l, x)
			}
			count++
		}

		if count > 0 && g*l > best {
			best = g * l
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
}
