const mod int64 = 1_000_000_007

func creature(c byte) int {
	switch c {
	case 'F':
		return 0
	case 'W':
		return 1
	default:
		return 2
	}
}

func score(bob, alice int) int {
	if bob == alice {
		return 0
	}
	if (bob-alice+3)%3 == 1 {
		return 1
	}
	return -1
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	n := len(s)
	offset := n
	size := 2*n + 1

	dp := make([][]int64, 3)
	next := make([][]int64, 3)
	for i := 0; i < 3; i++ {
		dp[i] = make([]int64, size)
		next[i] = make([]int64, size)
	}

	alice := creature(s[0])
	for bob := 0; bob < 3; bob++ {
		dp[bob][offset+score(bob, alice)] = 1
	}

	for round := 1; round < n; round++ {
		for i := 0; i < 3; i++ {
			clear(next[i])
		}

		alice = creature(s[round])
		for last := 0; last < 3; last++ {
			for idx, ways := range dp[last] {
				if ways == 0 {
					continue
				}
				for bob := 0; bob < 3; bob++ {
					if bob == last {
						continue
					}
					newIdx := idx + score(bob, alice)
					next[bob][newIdx] = (next[bob][newIdx] + ways) % mod
				}
			}
		}
		dp, next = next, dp
	}

	var answer int64
	for last := 0; last < 3; last++ {
		for idx := offset + 1; idx < size; idx++ {
			answer = (answer + dp[last][idx]) % mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
