package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var word1, word2 string
	if _, err := fmt.Fscan(in, &word1, &word2); err != nil {
		return
	}

	n, m := len(word1), len(word2)

	// right[j] is the index used for word2[j] in the rightmost exact
	// subsequence embedding of word2[j:] into word1.
	right := make([]int, m)
	p := n - 1
	for j := m - 1; j >= 0; j-- {
		for p >= 0 && word1[p] != word2[j] {
			p--
		}
		if p < 0 {
			right[j] = -1
		} else {
			right[j] = p
			p--
		}
	}

	answer := make([]int, 0, m)
	target := 0
	mismatchUsed := false

	for i := 0; i < n && target < m; i++ {
		if word1[i] == word2[target] {
			answer = append(answer, i)
			target++
		} else if !mismatchUsed &&
			(target == m-1 || right[target+1] > i) {
			answer = append(answer, i)
			target++
			mismatchUsed = true
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if target != m {
		fmt.Fprintln(out)
		return
	}

	for i, index := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, index)
	}
	fmt.Fprintln(out)
}
