	var word1, word2 string
	if _, err := fmt.Fscan(in, &word1, &word2); err != nil {
		return
	}

	n, m := len(word1), len(word2)

	// suffix[j] is the rightmost possible index in word1 that can
	// represent word2[j] while exactly matching word2[j:].
	suffix := make([]int, m)
	pos := n - 1
	for j := m - 1; j >= 0; j-- {
		for pos >= 0 && word1[pos] != word2[j] {
			pos--
		}
		if pos < 0 {
			suffix[j] = -1
		} else {
			suffix[j] = pos
			pos--
		}
	}

	answer := make([]int, 0, m)
	target := 0
	changed := false

	for i := 0; i < n && target < m; i++ {
		if word1[i] == word2[target] {
			answer = append(answer, i)
			target++
		} else if !changed && (target == m-1 || i < suffix[target+1]) {
			answer = append(answer, i)
			target++
			changed = true
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if target != m {
		fmt.Fprintln(out)
		return
	}

	for i, index := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, index)
	}
	fmt.Fprintln(out)
}
