package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, x, y int
	if _, err := fmt.Fscan(in, &n, &x, &y); err != nil {
		return
	}

	limit := n
	if x < limit {
		limit = x
	}

	// dp[k] = Stirling number of the second kind S(n, k).
	dp := make([]int64, limit+1)
	dp[0] = 1

	for i := 1; i <= n; i++ {
		upper := i
		if upper > limit {
			upper = limit
		}
		for k := upper; k >= 1; k-- {
			dp[k] = (dp[k-1] + int64(k)*dp[k]) % mod
		}
		dp[0] = 0
	}

	var answer int64
	fallingStages := int64(1)
	scoreWays := int64(1)

	for k := 1; k <= limit; k++ {
		fallingStages = fallingStages * int64(x-k+1) % mod
		scoreWays = scoreWays * int64(y) % mod

		ways := dp[k] * fallingStages % mod
		ways = ways * scoreWays % mod
		answer = (answer + ways) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
