package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type item struct {
	value int
	count int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var values []int
	for {
		var v int
		if _, err := fmt.Fscan(in, &v); err != nil {
			break
		}
		values = append(values, v)
	}

	if len(values) < 3 {
		return
	}

	nums := values[:len(values)-2]
	k := values[len(values)-2]
	x := values[len(values)-1]

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for left := 0; left+k <= len(nums); left++ {
		frequency := make(map[int]int)
		for i := left; i < left+k; i++ {
			frequency[nums[i]]++
		}

		items := make([]item, 0, len(frequency))
		for value, count := range frequency {
			items = append(items, item{value: value, count: count})
		}

		sort.Slice(items, func(i, j int) bool {
			if items[i].count != items[j].count {
				return items[i].count > items[j].count
			}
