package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	in := bufio.NewReader(os.Stdin)
	nums := make([]int, 0, 200)
	maxVal := 0

	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
		if x > maxVal {
			maxVal = x
		}
	}

	if len(nums) == 0 {
		fmt.Println(0)
		return
	}

	size := maxVal + 1
	gcdTable := make([][]int, size)
	for a := 0; a < size; a++ {
		gcdTable[a] = make([]int, size)
		for b := 1; b < size; b++ {
			gcdTable[a][b] = gcd(a, b)
		}
	}

	dp := make([]int64, size*size)
	dp[0] = 1

	add := func(dst *int64, value int64) {
		*dst += value
		if *dst >= mod {
			*dst -= mod
		}
	}

	for _, x := range nums {
		next := make([]int64, size*size)

		for g1 := 0; g1 < size; g1++ {
			for g2 := 0; g2 < size; g2++ {
				index := g1*size + g2
				count := dp[index]
				if count == 0 {
					continue
				}

				// Do not include x in either subsequence.
				add(&next[index], count)

				// Include x in the first subsequence.
				newG1 := gcdTable[g1][x]
				add(&next[newG1*size+g2], count)

				// Include x in the second subsequence.
				newG2 := gcdTable[g2][x]
				add(&next[g1*size+newG2], count)
			}
		}

		dp = next
	}

	var answer int64
	for g := 1; g < size; g++ {
		answer += dp[g*size+g]
		if answer >= mod {
			answer -= mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
