package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type stackItem struct {
	node int
	exit bool
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}
	fields := strings.Fields(string(data))
	if len(fields) < 2 {
		return
	}

	s := fields[len(fields)-1]
	n := len(fields) - 1
	parent := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i], _ = strconv.Atoi(fields[i])
	}

	children := make([][]int, n)
	for i := 1; i < n; i++ {
		children[parent[i]] = append(children[parent[i]], i)
	}

	start := make([]int, n)
	end := make([]int, n)
	order := make([]byte, 0, n)

	stack := make([]stackItem, 0, 2*n)
	stack = append(stack, stackItem{node: 0})

	for len(stack) > 0 {
		item := stack[len(stack)-1]
		stack = stack[:len(stack)-1]

		x := item.node
		if item.exit {
			order = append(order, s[x])
			end[x] = len(order)
			continue
		}

		start[x] = len(order)
		stack = append(stack, stackItem{node: x, exit: true})
		for i := len(children[x]) - 1; i >= 0; i-- {
			stack = append(stack, stackItem{node: children[x][i]})
		}
	}

	// d1[i] is the radius of the longest odd palindrome centered at i.
	d1 := make([]int, n)
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 1
		if i <= r {
			mirror := l + r - i
			k = min(d1[mirror], r-i+1)
		}
		for i-k >= 0 && i+k < n && order[i-k] == order[i+k] {
			k++
		}
		d1[i] = k
		if i+k-1 > r {
			l = i - k + 1
			r = i + k - 1
		}
	}

	// d2[i] is the radius of the longest even palindrome centered
	// between i-1 and i.
	d2 := make([]int, n)
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 0
		if i <= r {
			mirror := l + r - i + 1
			k = min(d2[mirror], r-i+1)
		}
		for i-k-1 >= 0 && i+k < n && order[i-k-1] == order[i+k] {
			k++
		}
		d2[i] = k
		if i+k-1 > r {
			l = i - k
			r = i + k - 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}

		length := end[i] - start[i]
		isPalindrome := false

		if length%2 == 1 {
			center := start[i] + length/2
			isPalindrome = d1[center] >= length/2+1
		} else {
			center := start[i] + length/2
			isPalindrome = d2[center] >= length/2
		}

		if isPalindrome {
			fmt.Fprint(out, "true")
		} else {
			fmt.Fprint(out, "false")
		}
	}
	fmt.Fprintln(out)
}
