package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	fields := strings.Fields(string(data))
	if len(fields) < 2 {
		return
	}

	s := fields[len(fields)-1]
	nums := make([]int, 0, len(fields)-1)

	for _, field := range fields[:len(fields)-1] {
		field = strings.Trim(field, "[],")
		parts := strings.Split(field, ",")
		for _, part := range parts {
			part = strings.TrimSpace(strings.Trim(part, "[]"))
			if part == "" {
				continue
			}
			if v, err := strconv.Atoi(part); err == nil {
				nums = append(nums, v)
			}
		}
	}

	// Also support input where n is supplied before the parent array.
	if len(nums) >= 2 && nums[0] == len(nums)-1 {
		nums = nums[1:]
	}

	parent := nums
	n := len(parent)
	if n == 0 || len(s) != n {
		return
	}

	children := make([][]int, n)
	for i := 1; i < n; i++ {
		children[parent[i]] = append(children[parent[i]], i)
	}

	// Build the postorder DFS string and record each subtree's interval.
	start := make([]int, n)
	end := make([]int, n)
	postorder := make([]byte, 0, n)

	type frame struct {
		node      int
		nextChild int
	}

	stack := make([]frame, 0, n)
	stack = append(stack, frame{node: 0})
	start[0] = 0

	for len(stack) > 0 {
		top := len(stack) - 1
		x := stack[top].node

		if stack[top].nextChild < len(children[x]) {
			y := children[x][stack[top].nextChild]
			stack[top].nextChild++
			start[y] = len(postorder)
			stack = append(stack, frame{node: y})
		} else {
			postorder = append(postorder, s[x])
			end[x] = len(postorder)
			stack = stack[:top]
		}
	}

	// Manacher's algorithm for exact O(1) palindrome interval queries.
	d1 := make([]int, n) // Odd-length palindrome radii.
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 1
		if i <= r {
			mirror := l + r - i
			k = d1[mirror]
			if r-i+1 < k {
				k = r - i + 1
			}
		}
		for i-k >= 0 && i+k < n && postorder[i-k] == postorder[i+k] {
			k++
		}
		d1[i] = k
		if i+k-1 > r {
			l = i - k + 1
			r = i + k - 1
		}
	}

	d2 := make([]int, n) // Even-length palindrome radii.
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 0
		if i <= r {
			mirror := l + r - i + 1
			k = d2[mirror]
			if r-i+1 < k {
				k = r - i + 1
			}
		}
		for i-k-1 >= 0 && i+k < n && postorder[i-k-1] == postorder[i+k] {
			k++
		}
		d2[i] = k
		if i+k-1 > r {
			l = i - k
			r = i + k - 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i := 0; i < n; i++ {
		l, r := start[i], end[i]
		length := r - l
		isPalindrome := false

		if length%2 == 1 {
			center := (l + r - 1) / 2
			isPalindrome = d1[center] >= length/2+1
		} else {
			center := (l + r) / 2
			isPalindrome = d2[center] >= length/2
		}

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, isPalindrome)
	}
