func parseInts(s string) []int {
	var result []int
	for i := 0; i < len(s); {
		sign := 1
		if s[i] == '-' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			sign = -1
			i++
		}
		if i >= len(s) || s[i] < '0' || s[i] > '9' {
			i++
			continue
		}

		value := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines [][]int
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 || len(lines[0]) == 0 {
		return
	}

	nums := lines[0]
	k := lines[1][0]
	numOperations := lines[2][0]

	sort.Ints(nums)
	n := len(nums)
	answer := 1

	// A target not already present can be reached by all values in a range
	// of width at most 2*k, with every such value requiring an operation.
	left := 0
	for right := 0; right < n; right++ {
		for nums[right]-nums[left] > 2*k {
			left++
		}
		count := right - left + 1
		if count > numOperations {
			count = numOperations
		}
		if count > answer {
			answer = count
		}
	}

	// Check every distinct existing value as the target.
	for i := 0; i < n; {
		j := i + 1
		for j < n && nums[j] == nums[i] {
			j++
		}

		target := nums[i]
		lower := sort.SearchInts(nums, target-k)
		upper := sort.Search(n, func(p int) bool {
			return nums[p] > target+k
		})

		reachable := upper - lower
		existing := j - i
		frequency := existing + numOperations
		if frequency > reachable {
			frequency = reachable
		}
		if frequency > answer {
			answer = frequency
		}

		i = j
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
