package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type State struct {
	time int64
	r, c int
}

type PriorityQueue []State

func (pq PriorityQueue) Len() int           { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].time < pq[j].time }
func (pq PriorityQueue) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i] }

func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(State))
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[:n-1]
	return x
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1024*1024)

	var n int
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		n, _ = strconv.Atoi(fields[0])
		break
	}

	moveTime := make([][]int64, 0, n)
	for len(moveTime) < n && scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		fields := strings.Fields(line)
		row := make([]int64, len(fields))
		for i, field := range fields {
			row[i], _ = strconv.ParseInt(field, 10, 64)
		}
		moveTime = append(moveTime, row)
	}

	if n == 0 || len(moveTime) == 0 || len(moveTime[0]) == 0 {
		return
	}

	m := len(moveTime[0])
	const inf int64 = 1<<63 - 1

	dist := make([][]int64, n)
	for i := range dist {
		dist[i] = make([]int64, m)
		for j := range dist[i] {
			dist[i][j] = inf
		}
	}
	dist[0][0] = 0

	pq := &PriorityQueue{{time: 0, r: 0, c: 0}}
	heap.Init(pq)

	directions := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(State)
		if cur.time != dist[cur.r][cur.c] {
			continue
		}
		if cur.r == n-1 && cur.c == m-1 {
			fmt.Println(cur.time)
			return
		}

		for _, d := range directions {
			nr, nc := cur.r+d[0], cur.c+d[1]
			if nr < 0 || nr >= n || nc < 0 || nc >= m {
				continue
			}

			startTime := cur.time
			if moveTime[nr][nc] > startTime {
				startTime = moveTime[nr][nc]
			}
			arrivalTime := startTime + 1

			if arrivalTime < dist[nr][nc] {
				dist[nr][nc] = arrivalTime
				heap.Push(pq, State{time: arrivalTime, r: nr, c: nc})
			}
		}
	}

	fmt.Println(dist[n-1][m-1])
}
