package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func parseInts(s string) []int {
	var result []int
	for i := 0; i < len(s); {
		sign := 1
		if s[i] == '-' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			sign = -1
			i++
		} else if s[i] < '0' || s[i] > '9' {
			i++
			continue
		}

		value := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines [][]int
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 {
		return
	}

	var nums []int
	var k, numOperations int

	// Supports both:
	// nums on first line, followed by k and numOperations;
	// or n on first line, nums on second line, followed by k and numOperations.
	if len(lines) >= 4 && len(lines[0]) == 1 && lines[0][0] == len(lines[1]) {
		nums = lines[1]
		k = lines[2][0]
		numOperations = lines[3][0]
	} else {
		nums = lines[0]
		k = lines[1][0]
		numOperations = lines[2][0]
	}

	sort.Ints(nums)
	n := len(nums)
	answer := 0

	// Targets not necessarily already present in nums.
	left := 0
	for right := 0; right < n; right++ {
		for nums[right]-nums[left] > 2*k {
			left++
		}
		answer = max(answer, min(right-left+1, numOperations))
	}

	// Targets already present in nums.
	left, right := 0, 0
	for groupStart := 0; groupStart < n; {
		groupEnd := groupStart + 1
		for groupEnd < n && nums[groupEnd] == nums[groupStart] {
			groupEnd++
		}

		target := nums[groupStart]
		for left < n && nums[left] < target-k {
			left++
		}
		if right < groupEnd {
			right = groupEnd
		}
		for right < n && nums[right] <= target+k {
			right++
		}

		existing := groupEnd - groupStart
		reachable := right - left
		answer = max(answer, min(reachable, existing+numOperations))

		groupStart = groupEnd
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
