	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func popcount(x int) int {
	count := 0
	for x > 0 {
		count += x & 1
		x >>= 1
	}
	return count
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s, &k); err != nil {
		return
	}

	n := len(s)

	// Binomial coefficients C[i][j] modulo mod.
	comb := make([][]int64, n+1)
	for i := 0; i <= n; i++ {
		comb[i] = make([]int64, n+1)
		comb[i][0] = 1
		comb[i][i] = 1
		for j := 1; j < i; j++ {
			comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % mod
		}
	}

	// countByOnes[c] is the number of integers in [0, n) with c set bits.
	countByOnes := make([]int64, n+1)
	usedOnes := 0

	for i, ch := range s {
		if ch == '1' {
			remaining := n - i - 1

			// Put 0 here instead of n's 1, then choose the suffix freely.
			for suffixOnes := 0; suffixOnes <= remaining; suffixOnes++ {
				totalOnes := usedOnes + suffixOnes
				countByOnes[totalOnes] += comb[remaining][suffixOnes]
				if countByOnes[totalOnes] >= mod {
					countByOnes[totalOnes] -= mod
				}
			}

			usedOnes++
		}
	}

	// steps[c] is the number of popcount operations needed to reduce c to 1.
	steps := make([]int, n+1)
	for c := 2; c <= n; c++ {
		steps[c] = 1 + steps[popcount(c)]
	}

	var answer int64
	for c := 1; c <= n; c++ {
		// One operation changes x into popcount(x) = c.
		if steps[c] <= k-1 {
			answer = (answer + countByOnes[c]) % mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
