package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func popcount(x int) int {
	count := 0
	for x > 0 {
		count += x & 1
		x >>= 1
	}
	return count
}

func reductionsToOne(x int) int {
	steps := 0
	for x > 1 {
		x = popcount(x)
		steps++
	}
	return steps
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s, &k); err != nil {
		return
	}

	n := len(s)

	// Binomial coefficients C[i][j].
	comb := make([][]int64, n+1)
	for i := 0; i <= n; i++ {
		comb[i] = make([]int64, n+1)
		comb[i][0] = 1
		comb[i][i] = 1
		for j := 1; j < i; j++ {
			comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % mod
		}
	}

	// countByOnes[c] is the number of integers in [0, n) with c set bits.
	countByOnes := make([]int64, n+1)
	ones := 0

	for i := 0; i < n; i++ {
		if s[i] == '1' {
			remaining := n - i - 1

			// Put 0 at this position, making the number strictly less than n.
			for suffixOnes := 0; suffixOnes <= remaining; suffixOnes++ {
				totalOnes := ones + suffixOnes
				countByOnes[totalOnes] += comb[remaining][suffixOnes]
				if countByOnes[totalOnes] >= mod {
					countByOnes[totalOnes] -= mod
				}
			}

			// Continue matching n by putting 1 here.
			ones++
		}
	}

	var answer int64
	for setBits := 1; setBits <= n; setBits++ {
		if reductionsToOne(setBits) <= k-1 {
			answer += countByOnes[setBits]
			answer %= mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
