	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	numsLine := nextNonEmptyLine(scanner)
	if numsLine == "" {
		return
	}
	nums := parseInts(numsLine)

	queryCountLine := nextNonEmptyLine(scanner)
	if queryCountLine == "" {
		return
	}
	queryCount, _ := strconv.Atoi(strings.Fields(queryCountLine)[0])

	queryValues := make([]int, 0, 2*queryCount)
	for scanner.Scan() {
		queryValues = append(queryValues, parseInts(scanner.Text())...)
	}

	diff := make([]int, len(nums)+1)
	for i := 0; i < queryCount; i++ {
		l := queryValues[2*i]
		r := queryValues[2*i+1]
		diff[l]++
		if r+1 < len(diff) {
			diff[r+1]--
		}
	}

	coverage := 0
	possible := true
