		totalSum += digit
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if totalSum%2 != 0 {
		fmt.Fprintln(writer, 0)
		return
	}

	evenSlots := (n + 1) / 2
	oddSlots := n / 2
	target := totalSum / 2

	dp := make([][]int64, evenSlots+1)
	for i := range dp {
		dp[i] = make([]int64, target+1)
	}
	dp[0][0] = 1

	for digit, count := range counts {
		next := make([][]int64, evenSlots+1)
		for i := range next {
			next[i] = make([]int64, target+1)
		}

		for used := 0; used <= evenSlots; used++ {
			for sum := 0; sum <= target; sum++ {
				if dp[used][sum] == 0 {
					continue
				}
				for inEven := 0; inEven <= count && used+inEven <= evenSlots; inEven++ {
					newSum := sum + digit*inEven
					if newSum > target {
						break
					}
					ways := invFact[inEven] * invFact[count-inEven] % mod
					next[used+inEven][newSum] += dp[used][sum] * ways % mod
					next[used+inEven][newSum] %= mod
				}
			}
		}
		dp = next
	}

	answer := dp[evenSlots][target]
	answer = answer * fact[evenSlots] % mod
	answer = answer * fact[oddSlots] % mod

	fmt.Fprintln(writer, answer)
}
