package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type MaxHeap []int

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

type Query struct {
	l, r int
}

func parseInts(line string) []int {
	fields := strings.Fields(line)
	result := make([]int, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.Atoi(field)
		if err == nil {
			result = append(result, value)
		}
	}
	return result
}

func nextNonEmptyLine(scanner *bufio.Scanner) (string, bool) {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line, true
		}
	}
	return "", false
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	numsLine, ok := nextNonEmptyLine(scanner)
	if !ok {
		return
	}
	nums := parseInts(numsLine)

	queryCountLine, ok := nextNonEmptyLine(scanner)
	if !ok {
		return
	}
	queryCountValues := parseInts(queryCountLine)
	if len(queryCountValues) == 0 {
		return
	}
	queryCount := queryCountValues[0]

	queries := make([]Query, 0, queryCount)
	for len(queries) < queryCount {
		line, exists := nextNonEmptyLine(scanner)
		if !exists {
			break
		}
		values := parseInts(line)
		if len(values) >= 2 {
			queries = append(queries, Query{l: values[0], r: values[1]})
		}
	}

	n := len(nums)
	startingAt := make([][]int, n)
	for _, q := range queries {
		startingAt[q.l] = append(startingAt[q.l], q.r)
	}

	expiration := make([]int, n+1)
	activeSelected := 0
	selectedCount := 0
	candidates := &MaxHeap{}
	heap.Init(candidates)

	for i := 0; i < n; i++ {
		activeSelected += expiration[i]

		for _, right := range startingAt[i] {
			heap.Push(candidates, right)
		}

		for activeSelected < nums[i] {
			for candidates.Len() > 0 && (*candidates)[0] < i {
				heap.Pop(candidates)
			}

			if candidates.Len() == 0 {
				fmt.Println(-1)
				return
			}

			right := heap.Pop(candidates).(int)
			activeSelected++
			selectedCount++
			expiration[right+1]--
		}
	}

	fmt.Println(queryCount - selectedCount)
}
