const negInf int64 = -1 << 60

func maxUpperPath(fruits [][]int64, transpose bool) int64 {
	n := len(fruits)
	value := func(i, j int) int64 {
		if transpose {
			return fruits[j][i]
		}
		return fruits[i][j]
	}

	prev := make([]int64, n)
	for i := range prev {
		prev[i] = negInf
	}
	prev[n-1] = value(0, n-1)

	for row := 1; row < n-1; row++ {
		cur := make([]int64, n)
		for i := range cur {
			cur[i] = negInf
		}

		for col := row + 1; col < n; col++ {
			best := prev[col]
			if col > 0 && prev[col-1] > best {
				best = prev[col-1]
			}
			if col+1 < n && prev[col+1] > best {
				best = prev[col+1]
			}
			if best != negInf {
				cur[col] = best + value(row, col)
			}
		}
		prev = cur
	}

	return prev[n-1]
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	fruits := make([][]int64, n)
	var diagonal int64
	for i := 0; i < n; i++ {
		fruits[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			fmt.Fscan(in, &fruits[i][j])
			if i == j {
				diagonal += fruits[i][j]
			}
		}
	}

	topRightChild := maxUpperPath(fruits, false)
	bottomLeftChild := maxUpperPath(fruits, true)

	fmt.Fprintln(out, diagonal+topRightChild+bottomLeftChild)
}
