	"os"
)

const negInf int64 = -1 << 60

func max3(a, b, c int64) int64 {
	if b > a {
		a = b
	}
	if c > a {
		a = c
	}
	return a
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	fruits := make([][]int64, n)
	var diagonal int64
	for i := 0; i < n; i++ {
		fruits[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			fmt.Fscan(in, &fruits[i][j])
			if i == j {
				diagonal += fruits[i][j]
			}
		}
	}

	// Child starting at (0, n-1), progressing one row per move.
	dp := make([]int64, n)
	for j := range dp {
		dp[j] = negInf
	}
	dp[n-1] = fruits[0][n-1]

	for i := 1; i < n; i++ {
		next := make([]int64, n)
		for j := range next {
			next[j] = negInf
		}

		for j := 0; j < n; j++ {
			left, middle, right := negInf, dp[j], negInf
			if j > 0 {
				left = dp[j-1]
			}
			if j+1 < n {
				right = dp[j+1]
			}

			best := max3(left, middle, right)
			if best == negInf {
				continue
			}

			value := fruits[i][j]
			if i == j {
				value = 0
			}
			next[j] = best + value
		}
		dp = next
	}
	topRight := dp[n-1]

	// Child starting at (n-1, 0), progressing one column per move.
	for i := range dp {
		dp[i] = negInf
	}
	dp[n-1] = fruits[n-1][0]

	for j := 1; j < n; j++ {
		next := make([]int64, n)
		for i := range next {
			next[i] = negInf
		}

		for i := 0; i < n; i++ {
			up, middle, down := negInf, dp[i], negInf
			if i > 0 {
				up = dp[i-1]
			}
			if i+1 < n {
				down = dp[i+1]
			}

			best := max3(up, middle, down)
			if best == negInf {
				continue
			}

			value := fruits[i][j]
			if i == j {
				value = 0
			}
			next[i] = best + value
		}
		dp = next
	}
	bottomLeft := dp[n-1]

	fmt.Fprintln(out, diagonal+topRight+bottomLeft)
}
