	"strings"
	"unicode"
)

func parseInts(s string) []int {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return !(unicode.IsDigit(r) || r == '-')
	})
	values := make([]int, 0, len(fields))
	for _, field := range fields {
		if v, err := strconv.Atoi(field); err == nil {
			values = append(values, v)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 4 {
		return
	}

	nums := parseInts(lines[0])
	remaining := make([]int, 0, 3)
	for _, line := range lines[1:] {
		remaining = append(remaining, parseInts(line)...)
	}
	if len(remaining) < 3 {
		return
	}

	k, op1, op2 := remaining[0], remaining[1], remaining[2]

	const inf = int(^uint(0)>>1) / 4
	dp := make([][]int, op1+1)
	for i := range dp {
		dp[i] = make([]int, op2+1)
		for j := range dp[i] {
			dp[i][j] = inf
		}
	}
	dp[0][0] = 0

	for _, x := range nums {
		next := make([][]int, op1+1)
		for i := range next {
			next[i] = make([]int, op2+1)
			for j := range next[i] {
				next[i][j] = inf
			}
		}

		for used1 := 0; used1 <= op1; used1++ {
			for used2 := 0; used2 <= op2; used2++ {
				if dp[used1][used2] == inf {
					continue
				}
				base := dp[used1][used2]

				if base+x < next[used1][used2] {
					next[used1][used2] = base + x
				}

				half := (x + 1) / 2
				if used1 < op1 && base+half < next[used1+1][used2] {
					next[used1+1][used2] = base + half
				}

				if used2 < op2 && x >= k && base+x-k < next[used1][used2+1] {
					next[used1][used2+1] = base + x - k
				}

				if used1 < op1 && used2 < op2 {
					best := inf

					// Operation 1 followed by Operation 2.
					if half >= k {
						best = half - k
					}

					// Operation 2 followed by Operation 1.
					if x >= k {
						value := (x - k + 1) / 2
						if value < best {
							best = value
						}
					}

					if best != inf && base+best < next[used1+1][used2+1] {
						next[used1+1][used2+1] = base + best
					}
				}
			}
		}
		dp = next
	}

	answer := inf
	for i := 0; i <= op1; i++ {
		for j := 0; j <= op2; j++ {
			if dp[i][j] < answer {
				answer = dp[i][j]
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
