func parseInts(s string) []int {
	var result []int
	for i := 0; i < len(s); {
		if (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
			continue
		}

		sign := 1
		if s[i] == '-' {
			sign = -1
			i++
			if i >= len(s) || s[i] < '0' || s[i] > '9' {
				continue
			}
		}

		value := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 4 {
		return
	}

	nums := parseInts(lines[0])
	kValues := parseInts(lines[1])
	op1Values := parseInts(lines[2])
	op2Values := parseInts(lines[3])
	if len(nums) == 0 || len(kValues) == 0 || len(op1Values) == 0 || len(op2Values) == 0 {
		return
	}

	k := kValues[len(kValues)-1]
	op1 := op1Values[len(op1Values)-1]
	op2 := op2Values[len(op2Values)-1]

	const inf int64 = 1 << 60
	dp := make([][]int64, op1+1)
	for i := range dp {
		dp[i] = make([]int64, op2+1)
		for j := range dp[i] {
			dp[i][j] = inf
		}
	}
	dp[0][0] = 0

	for _, x := range nums {
		next := make([][]int64, op1+1)
		for i := range next {
			next[i] = make([]int64, op2+1)
			for j := range next[i] {
				next[i][j] = inf
			}
		}

		for used1 := 0; used1 <= op1; used1++ {
			for used2 := 0; used2 <= op2; used2++ {
				if dp[used1][used2] == inf {
					continue
				}

				if v := dp[used1][used2] + int64(x); v < next[used1][used2] {
					next[used1][used2] = v
				}

				halved := (x + 1) / 2
				if used1 < op1 {
					if v := dp[used1][used2] + int64(halved); v < next[used1+1][used2] {
						next[used1+1][used2] = v
					}
				}

				if used2 < op2 && x >= k {
					if v := dp[used1][used2] + int64(x-k); v < next[used1][used2+1] {
						next[used1][used2+1] = v
					}
				}

				if used1 < op1 && used2 < op2 {
					best := inf

					if x >= k {
						afterSubtractThenHalf := (x - k + 1) / 2
						best = int64(afterSubtractThenHalf)
					}

					if halved >= k {
						afterHalfThenSubtract := halved - k
						if int64(afterHalfThenSubtract) < best {
							best = int64(afterHalfThenSubtract)
						}
					}

					if best != inf {
						if v := dp[used1][used2] + best; v < next[used1+1][used2+1] {
							next[used1+1][used2+1] = v
						}
					}
				}
			}
		}
		dp = next
	}

	answer := inf
	for used1 := 0; used1 <= op1; used1++ {
		for used2 := 0; used2 <= op2; used2++ {
