package main

import (
	"bufio"
	"fmt"
	"os"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	var count [26]int
	maxCount := 0
	for _, ch := range s {
		i := int(ch - 'a')
		count[i]++
		if count[i] > maxCount {
			maxCount = count[i]
		}
	}

	const inf = int(1e9)
	answer := inf

	for target := 1; target <= maxCount; target++ {
		var dp [2]int
		dp[0] = count[0]
		dp[1] = abs(count[0] - target)

		for i := 1; i < 26; i++ {
			next := [2]int{inf, inf}

			for prevUsed := 0; prevUsed <= 1; prevUsed++ {
				prevTarget := prevUsed * target
				excess := count[i-1] - prevTarget
				if excess < 0 {
					excess = 0
				}

				for used := 0; used <= 1; used++ {
					currentTarget := used * target
					cost := dp[prevUsed] + abs(count[i]-currentTarget)

					deficit := currentTarget - count[i]
					if deficit < 0 {
						deficit = 0
					}

					// Converting the previous letter to the current letter
					// replaces one deletion and one insertion with one operation.
					cost -= min(excess, deficit)

					if cost < next[used] {
						next[used] = cost
					}
				}
			}

			dp = next
		}

		answer = min(answer, min(dp[0], dp[1]))
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
