const mod = 1_000_000_007

func readNonEmptyLine(scanner *bufio.Scanner) []string {
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) > 0 {
			return fields
		}
	}
	return nil
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	first := readNonEmptyLine(scanner)
	if len(first) == 0 {
		return
	}

	m, _ := strconv.Atoi(first[0])
	n := 0
	if len(first) > 1 {
		n, _ = strconv.Atoi(first[1])
	}

	var dp [][16]int

	for i := 0; i < m; i++ {
		fields := readNonEmptyLine(scanner)
		if i == 0 {
			if n == 0 {
				n = len(fields)
			}
			dp = make([][16]int, n)
		}

		for j := 0; j < n; j++ {
			value, _ := strconv.Atoi(fields[j])
			var current [16]int

			if i == 0 && j == 0 {
				current[value] = 1
			} else {
				if i > 0 {
					for xorValue, count := range dp[j] {
						if count != 0 {
							nextXOR := xorValue ^ value
							current[nextXOR] += count
							if current[nextXOR] >= mod {
								current[nextXOR] -= mod
							}
						}
					}
				}

				if j > 0 {
					for xorValue, count := range dp[j-1] {
						if count != 0 {
							nextXOR := xorValue ^ value
							current[nextXOR] += count
							if current[nextXOR] >= mod {
								current[nextXOR] -= mod
							}
						}
					}
				}
			}

			dp[j] = current
		}
	}

	kFields := readNonEmptyLine(scanner)
