package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type State struct {
	value int
	cost  int64
}

type PriorityQueue []State

func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].cost < pq[j].cost }
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) { *pq = append(*pq, x.(State)) }

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[:n-1]
	return x
}

func sieve(limit int) []bool {
	prime := make([]bool, limit)
	for i := 2; i < limit; i++ {
		prime[i] = true
	}
	for i := 2; i*i < limit; i++ {
		if prime[i] {
			for j := i * i; j < limit; j += i {
				prime[j] = false
			}
		}
	}
	return prime
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, m int
	if _, err := fmt.Fscan(in, &n, &m); err != nil {
		return
	}

	const limit = 10000
	prime := sieve(limit)

	if prime[n] || prime[m] {
		fmt.Fprintln(out, -1)
		return
	}

	const inf int64 = 1<<63 - 1
	dist := make([]int64, limit)
	for i := range dist {
		dist[i] = inf
	}

	dist[n] = int64(n)
	pq := &PriorityQueue{{value: n, cost: int64(n)}}
	heap.Init(pq)

	for pq.Len() > 0 {
		current := heap.Pop(pq).(State)
		x, cost := current.value, current.cost

		if cost != dist[x] {
			continue
		}
		if x == m {
			fmt.Fprintln(out, cost)
			return
		}

		for place := 1; place <= x; place *= 10 {
			digit := (x / place) % 10

			if digit < 9 {
				next := x + place
				if next < limit && !prime[next] {
					newCost := cost + int64(next)
					if newCost < dist[next] {
						dist[next] = newCost
						heap.Push(pq, State{value: next, cost: newCost})
					}
				}
			}

			if digit > 0 {
				next := x - place
				if !prime[next] {
					newCost := cost + int64(next)
					if newCost < dist[next] {
						dist[next] = newCost
						heap.Push(pq, State{value: next, cost: newCost})
					}
				}
			}
		}
	}

	fmt.Fprintln(out, -1)
}
