package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Edge struct {
	to     int
	weight int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var edgeCount int
	if _, err := fmt.Fscan(in, &edgeCount); err != nil {
		return
	}

	n := edgeCount + 1
	graph := make([][]Edge, n)

	for i := 0; i < edgeCount; i++ {
		var u, v int
		var w int64
		fmt.Fscan(in, &u, &v, &w)
		graph[u] = append(graph[u], Edge{to: v, weight: w})
		graph[v] = append(graph[v], Edge{to: u, weight: w})
	}

	var k int
	fmt.Fscan(in, &k)

	parent := make([]int, n)
	parentWeight := make([]int64, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}

	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, u)

		for _, edge := range graph[u] {
			if edge.to == parent[u] {
				continue
			}
			parent[edge.to] = u
			parentWeight[edge.to] = edge.weight
			stack = append(stack, edge.to)
		}
	}

	// dpWithoutParent[u]: best sum when the edge from u to its parent is absent.
	// dpWithParent[u]: best sum when the edge from u to its parent is retained.
	dpWithoutParent := make([]int64, n)
	dpWithParent := make([]int64, n)

	for i := n - 1; i >= 0; i-- {
		u := order[i]
		var base int64
		gains := make([]int64, 0, len(graph[u]))

		for _, edge := range graph[u] {
			v := edge.to
			if parent[v] != u {
				continue
			}

			base += dpWithoutParent[v]
			gain := edge.weight + dpWithParent[v] - dpWithoutParent[v]
			if gain > 0 {
				gains = append(gains, gain)
			}
		}

		sort.Slice(gains, func(i, j int) bool {
			return gains[i] > gains[j]
		})

		dpWithoutParent[u] = base
		for j := 0; j < len(gains) && j < k; j++ {
			dpWithoutParent[u] += gains[j]
		}

		dpWithParent[u] = base
		for j := 0; j < len(gains) && j < k-1; j++ {
			dpWithParent[u] += gains[j]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dpWithoutParent[0])
}
