type Edge struct {
	to     int
	weight int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var edgeCount int
	if _, err := fmt.Fscan(in, &edgeCount); err != nil {
		return
	}

	n := edgeCount + 1
	graph := make([][]Edge, n)

	for i := 0; i < edgeCount; i++ {
		var u, v int
		var w int64
		fmt.Fscan(in, &u, &v, &w)
		graph[u] = append(graph[u], Edge{to: v, weight: w})
		graph[v] = append(graph[v], Edge{to: u, weight: w})
	}

	var k int
	fmt.Fscan(in, &k)

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}

	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)

		for _, edge := range graph[v] {
			if edge.to == parent[v] {
				continue
			}
			parent[edge.to] = v
			stack = append(stack, edge.to)
		}
	}

	dpWithoutParent := make([]int64, n)
	dpWithParent := make([]int64, n)

	for i := n - 1; i >= 0; i-- {
		v := order[i]
		var base int64
		gains := make([]int64, 0, len(graph[v]))

		for _, edge := range graph[v] {
			child := edge.to
			if parent[child] != v {
				continue
			}

			base += dpWithoutParent[child]
			gain := edge.weight + dpWithParent[child] - dpWithoutParent[child]
			if gain > 0 {
				gains = append(gains, gain)
			}
		}

		sort.Slice(gains, func(i, j int) bool {
			return gains[i] > gains[j]
		})

		dpWithoutParent[v] = base
		for j := 0; j < len(gains) && j < k; j++ {
			dpWithoutParent[v] += gains[j]
		}

		dpWithParent[v] = base
		for j := 0; j < len(gains) && j < k-1; j++ {
			dpWithParent[v] += gains[j]
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, dpWithoutParent[0])
}
