const mod int64 = 1_000_000_007

func modPow(base, exp int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m, k int
	if _, err := fmt.Fscan(in, &n, &m, &k); err != nil {
		return
	}

	size := n - 1
	fact := make([]int64, size+1)
	invFact := make([]int64, size+1)

	fact[0] = 1
	for i := 1; i <= size; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	invFact[size] = modPow(fact[size], mod-2)
	for i := size; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	combinations := fact[size] * invFact[k] % mod
	combinations = combinations * invFact[size-k] % mod

	answer := int64(m) * combinations % mod
	answer = answer * modPow(int64(m-1), int64(size-k)) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
