package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Item struct {
	num  int
	cost int64
}

type PriorityQueue []Item

func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].cost < pq[j].cost }
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) { *pq = append(*pq, x.(Item)) }
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	if _, err := fmt.Fscan(in, &n, &m); err != nil {
		return
	}

	limit := 10
	for x := n; x >= 10; x /= 10 {
		limit *= 10
	}

	isPrime := make([]bool, limit)
	for i := 2; i < limit; i++ {
		isPrime[i] = true
	}
	for i := 2; i*i < limit; i++ {
		if isPrime[i] {
			for j := i * i; j < limit; j += i {
				isPrime[j] = false
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if isPrime[n] || isPrime[m] {
		fmt.Fprintln(out, -1)
		return
	}

	const inf int64 = 1<<63 - 1
	dist := make([]int64, limit)
	for i := range dist {
		dist[i] = inf
	}
	dist[n] = int64(n)

	pq := &PriorityQueue{{num: n, cost: int64(n)}}
	heap.Init(pq)

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(Item)
		if cur.cost != dist[cur.num] {
			continue
		}
		if cur.num == m {
			fmt.Fprintln(out, cur.cost)
			return
		}

		for place := 1; place < limit; place *= 10 {
			if place > cur.num && !(cur.num == 0 && place == 1) {
				break
			}

			digit := (cur.num / place) % 10

			if digit < 9 {
				next := cur.num + place
				if next < limit && !isPrime[next] {
					newCost := cur.cost + int64(next)
					if newCost < dist[next] {
						dist[next] = newCost
						heap.Push(pq, Item{num: next, cost: newCost})
					}
				}
			}

			if digit > 0 {
				next := cur.num - place
				if !isPrime[next] {
					newCost := cur.cost + int64(next)
					if newCost < dist[next] {
						dist[next] = newCost
						heap.Push(pq, Item{num: next, cost: newCost})
					}
				}
			}
		}
	}

	fmt.Fprintln(out, -1)
}
