package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
)

type DSU struct {
	parent []int
	size   []int
}

func newDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) find(x int) int {
	for x != d.parent[x] {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}

func (d *DSU) union(a, b int) bool {
	a = d.find(a)
	b = d.find(b)
	if a == b {
		return false
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	return true
}

func parseInts(data []byte) []int {
	result := make([]int, 0)
	for i := 0; i < len(data); {
		sign := 1
		if data[i] == '-' && i+1 < len(data) && data[i+1] >= '0' && data[i+1] <= '9' {
			sign = -1
			i++
		}
		if i >= len(data) || data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	rawLines := bytes.Split(data, []byte{'\n'})
	lines := make([][]int, 0, len(rawLines))
	for _, line := range rawLines {
		values := parseInts(line)
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	var nums []int
	var threshold int

	// Primary format: first line contains nums, second line contains threshold.
	// Also accepts an optional first line containing n.
	if len(lines) >= 3 && len(lines[0]) == 1 && len(lines[len(lines)-1]) == 1 {
		totalMiddle := 0
		for i := 1; i < len(lines)-1; i++ {
			totalMiddle += len(lines[i])
		}
		if lines[0][0] == totalMiddle {
			nums = make([]int, 0, totalMiddle)
			for i := 1; i < len(lines)-1; i++ {
				nums = append(nums, lines[i]...)
			}
			threshold = lines[len(lines)-1][0]
		}
	}

	if nums == nil {
		all := parseInts(data)
		if len(all) < 2 {
			return
		}
		nums = all[:len(all)-1]
		threshold = all[len(all)-1]
	}

	dsu := newDSU(len(nums))
	owner := make([]int, threshold+1)
	for i := range owner {
		owner[i] = -1
	}

	components := len(nums)

	for i, value := range nums {
		if value > threshold {
			continue
		}
		for multiple := value; multiple <= threshold; multiple += value {
			if owner[multiple] == -1 {
				owner[multiple] = i
			} else if dsu.union(i, owner[multiple]) {
				components--
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, components)
}
