package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const negInf int64 = -1 << 60

type SegmentTree struct {
	n    int
	min  []int64
	max  []int64
	best []int64
	lazy []int64
}

func NewSegmentTree(values []int64) *SegmentTree {
	size := 4 * len(values)
	st := &SegmentTree{
		n:    len(values),
		min:  make([]int64, size),
		max:  make([]int64, size),
		best: make([]int64, size),
		lazy: make([]int64, size),
	}
	st.build(1, 0, len(values)-1, values)
	return st
}

func (st *SegmentTree) build(node, left, right int, values []int64) {
	if left == right {
		st.min[node] = values[left]
		st.max[node] = values[left]
		st.best[node] = negInf
		return
	}

	mid := (left + right) / 2
	st.build(node*2, left, mid, values)
	st.build(node*2+1, mid+1, right, values)
	st.pull(node)
}

func (st *SegmentTree) pull(node int) {
	l, r := node*2, node*2+1

	st.min[node] = st.min[l]
	if st.min[r] < st.min[node] {
		st.min[node] = st.min[r]
	}

	st.max[node] = st.max[l]
	if st.max[r] > st.max[node] {
		st.max[node] = st.max[r]
	}

	st.best[node] = st.best[l]
	if st.best[r] > st.best[node] {
		st.best[node] = st.best[r]
	}
	cross := st.max[r] - st.min[l]
	if cross > st.best[node] {
		st.best[node] = cross
	}
}

func (st *SegmentTree) apply(node int, delta int64) {
	st.min[node] += delta
	st.max[node] += delta
	st.lazy[node] += delta
}

func (st *SegmentTree) push(node int) {
	if st.lazy[node] != 0 {
		delta := st.lazy[node]
		st.apply(node*2, delta)
		st.apply(node*2+1, delta)
		st.lazy[node] = 0
	}
}

func (st *SegmentTree) rangeAdd(ql, qr int, delta int64) {
	st.add(1, 0, st.n-1, ql, qr, delta)
}

func (st *SegmentTree) add(node, left, right, ql, qr int, delta int64) {
	if ql <= left && right <= qr {
		st.apply(node, delta)
		return
	}

	st.push(node)
	mid := (left + right) / 2
	if ql <= mid {
		st.add(node*2, left, mid, ql, qr, delta)
	}
	if qr > mid {
		st.add(node*2+1, mid+1, right, ql, qr, delta)
	}
	st.pull(node)
}

func parseIntegers(data []byte) []int64 {
	nums := make([]int64, 0)
	for i := 0; i < len(data); {
		for i < len(data) && data[i] != '-' && (data[i] < '0' || data[i] > '9') {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		found := false
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
			found = true
		}
		if found {
			nums = append(nums, sign*value)
		}
	}
	return nums
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := parseIntegers(data)
	if len(nums) == 0 {
		return
	}

	n := len(nums)
	prefix := make([]int64, n+1)
	positions := make(map[int64][]int)

	current := nums[0]
	answer := nums[0]

	for i, value := range nums {
		prefix[i+1] = prefix[i] + value

		if i > 0 {
			if current+value > value {
				current += value
			} else {
				current = value
			}
			if current > answer {
				answer = current
			}
		}

		if value < 0 {
			positions[value] = append(positions[value], i+1)
		}
	}

	tree := NewSegmentTree(prefix)

	for value, indices := range positions {
		// Replacing each occurrence of value by zero adds -value
		// to every prefix sum at and after its position.
		for _, index := range indices {
			tree.rangeAdd(index, n, -value)
		}

		candidate := tree.best[1]
		if candidate > 0 && candidate > answer {
			answer = candidate
		}

		// Restore the original prefix sums.
		for _, index := range indices {
			tree.rangeAdd(index, n, value)
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(writer, answer)
	writer.Flush()
}
