	"sort"
)

type Segment struct {
	l, r, c int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	segments := make([]Segment, n)
	for i := range segments {
		fmt.Fscan(in, &segments[i].l, &segments[i].r, &segments[i].c)
	}

	var k int64
	fmt.Fscan(in, &k)

	sort.Slice(segments, func(i, j int) bool {
		return segments[i].l < segments[j].l
	})

	prefix := make([]int64, n+1)
	for i, s := range segments {
		prefix[i+1] = prefix[i] + (s.r-s.l+1)*s.c
	}

	// Returns the total number of coins in bags with coordinates <= x.
	prefixCoins := func(x int64) int64 {
		count := sort.Search(n, func(i int) bool {
			return segments[i].l > x
		})
		if count == 0 {
			return 0
		}

		i := count - 1
		total := prefix[i]
		end := x
		if end > segments[i].r {
			end = segments[i].r
		}
		if end >= segments[i].l {
			total += (end - segments[i].l + 1) * segments[i].c
		}
		return total
	}

	windowCoins := func(start int64) int64 {
		return prefixCoins(start+k-1) - prefixCoins(start-1)
	}

	var answer int64
	for _, s := range segments {
		// An optimal window can be chosen with either its left edge
		// at a segment's left edge or its right edge at a segment's right edge.
		v1 := windowCoins(s.l)
		if v1 > answer {
			answer = v1
		}

		v2 := windowCoins(s.r - k + 1)
		if v2 > answer {
			answer = v2
		}
	}

	fmt.Fprintln(out, answer)
}
