func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := parseIntegers(data)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(nums) == 0 {
		fmt.Fprintln(out, 0)
		return
	}

	// dp[v][d] is the maximum length of a processed subsequence
	// ending in value v whose last difference is at least d.
	dp := make([][]int, maxValue+1)
	for i := range dp {
		dp[i] = make([]int, maxValue)
	}

	seen := make([]bool, maxValue+1)
	answer := 1

	for _, x := range nums {
		exact := make([]int, maxValue)

		for v := 1; v <= maxValue; v++ {
			if !seen[v] {
				continue
			}

			d := x - v
			if d < 0 {
				d = -d
			}

			previous := dp[v][d]
			if previous == 0 {
				previous = 1
			}

			length := previous + 1
			if length > exact[d] {
				exact[d] = length
			}
			if length > answer {
				answer = length
			}
		}

		best := 0
		for d := maxValue - 1; d >= 0; d-- {
			if exact[d] > best {
				best = exact[d]
			}
			if best > dp[x][d] {
				dp[x][d] = best
			}
		}

		seen[x] = true
	}

	fmt.Fprintln(out, answer)
}

func parseIntegers(data []byte) []int {
	nums := make([]int, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
