		if i >= len(data) {
			break
		}

		sign := 1
		if data[i] == '-' {
			sign = -1
			i++
		}

		value := 0
		hasDigit := false
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
			hasDigit = true
		}

		if hasDigit {
			nums = append(nums, sign*value)
		}
	}
	return nums
