package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const mod int64 = 1_000_000_007

func choose(n int64, k int) int64 {
	switch k {
	case 0:
		return 1
	case 1:
		if n < 1 {
			return 0
		}
		return n
	case 2:
		if n < 2 {
			return 0
		}
		return n * (n - 1) / 2
	default:
		return 0
	}
}

func parseInts(data []byte) []int64 {
	nums := make([]int64, 0)
	for i := 0; i < len(data); {
		sign := int64(1)
		if data[i] == '-' && i+1 < len(data) && data[i+1] >= '0' && data[i+1] <= '9' {
			sign = -1
			i++
		} else if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		found := false
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			found = true
			value = value*10 + int64(data[i]-'0')
			i++
		}
		if found {
			nums = append(nums, sign*value)
		}
	}
	return nums
}

func distinctPairs(counts map[int64]int64, excluded int64, total int64) int64 {
	pairs := choose(total, 2)
	for value, count := range counts {
		if value != excluded {
			pairs -= choose(count, 2)
		}
	}
	return pairs
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := parseInts(data)

	if len(nums) < 5 {
		fmt.Println(0)
		return
	}

	left := make(map[int64]int64)
	right := make(map[int64]int64)
	for _, value := range nums {
		right[value]++
	}

	var answer int64

	for i, x := range nums {
		right[x]--
		if right[x] == 0 {
			delete(right, x)
		}

		leftSize := int64(i)
		rightSize := int64(len(nums) - i - 1)
		leftX := left[x]
		rightX := right[x]
		leftNonX := leftSize - leftX
		rightNonX := rightSize - rightX

		// The middle value appears at least three times and is therefore
		// automatically the unique mode.
		for selectedLeftX := 0; selectedLeftX <= 2; selectedLeftX++ {
			for selectedRightX := 0; selectedRightX <= 2; selectedRightX++ {
				if selectedLeftX+selectedRightX < 2 {
					continue
				}
				ways := choose(leftX, selectedLeftX)
				ways *= choose(leftNonX, 2-selectedLeftX)
				ways *= choose(rightX, selectedRightX)
				ways *= choose(rightNonX, 2-selectedRightX)
				answer = (answer + ways) % mod
			}
		}

		// Exactly one additional x is selected from the left. The other
		// three values must all be distinct.
		if leftX > 0 && leftNonX > 0 && rightNonX >= 2 {
			rightDistinctPairs := distinctPairs(right, x, rightNonX)
			var triples int64
			for value, countLeft := range left {
				if value == x {
					continue
				}
				countRight := right[value]
				pairsNotContainingValue := rightDistinctPairs -
					countRight*(rightNonX-countRight)
				triples += countLeft * pairsNotContainingValue
			}
			answer = (answer + (leftX%mod)*(triples%mod)) % mod
		}

		// Exactly one additional x is selected from the right. The other
		// three values must all be distinct.
		if rightX > 0 && rightNonX > 0 && leftNonX >= 2 {
			leftDistinctPairs := distinctPairs(left, x, leftNonX)
			var triples int64
			for value, countRight := range right {
				if value == x {
					continue
				}
				countLeft := left[value]
				pairsNotContainingValue := leftDistinctPairs -
					countLeft*(leftNonX-countLeft)
				triples += countRight * pairsNotContainingValue
			}
			answer = (answer + (rightX%mod)*(triples%mod)) % mod
		}

		left[x]++
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
