func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	d := in.NextInt64()

	a := make([]int64, n)
	b := make([]int64, m)

	for i := range a {
		a[i] = in.NextInt64()
	}
	for i := range b {
		b[i] = in.NextInt64()
	}

	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	sort.Slice(b, func(i, j int) bool { return b[i] < b[j] })

	answer := int64(-1)
	j := 0

	for _, x := range a {
		for j < m && b[j] <= x+d {
			j++
		}
		if j > 0 {
			y := b[j-1]
			if y >= x-d && x+y > answer {
				answer = x + y
			}
		}
	}

	fmt.Fprintln(out, answer)
}
