import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var h, w, T int
	fmt.Fscan(in, &h, &w, &T)

	grid := make([]string, h)
	candies := make([]int, 0, 18)
	start, goal := -1, -1

	for r := 0; r < h; r++ {
		fmt.Fscan(in, &grid[r])
		for c := 0; c < w; c++ {
			pos := r*w + c
			switch grid[r][c] {
			case 'S':
				start = pos
			case 'G':
				goal = pos
			case 'o':
				candies = append(candies, pos)
			}
		}
	}

	n := len(candies)
	points := make([]int, 0, n+2)
	points = append(points, candies...)
	startIndex := len(points)
	points = append(points, start)
	goalIndex := len(points)
	points = append(points, goal)

	m := len(points)
	distBetween := make([][]int, m)
	for i := range distBetween {
		distBetween[i] = make([]int, m)
	}

	cellCount := h * w
	dist := make([]int, cellCount)
	queue := make([]int, cellCount)

	for sourceIndex, source := range points {
		for i := range dist {
			dist[i] = -1
		}

		head, tail := 0, 0
		queue[tail] = source
		tail++
		dist[source] = 0

		for head < tail {
			cur := queue[head]
			head++

			r, c := cur/w, cur%w
			nextDist := dist[cur] + 1

			if r > 0 {
				next := cur - w
				if dist[next] == -1 && grid[r-1][c] != '#' {
					dist[next] = nextDist
					queue[tail] = next
					tail++
				}
			}
			if r+1 < h {
				next := cur + w
				if dist[next] == -1 && grid[r+1][c] != '#' {
					dist[next] = nextDist
					queue[tail] = next
					tail++
				}
			}
			if c > 0 {
				next := cur - 1
				if dist[next] == -1 && grid[r][c-1] != '#' {
					dist[next] = nextDist
					queue[tail] = next
					tail++
				}
			}
			if c+1 < w {
				next := cur + 1
				if dist[next] == -1 && grid[r][c+1] != '#' {
					dist[next] = nextDist
					queue[tail] = next
					tail++
				}
			}
		}

		for targetIndex, target := range points {
			distBetween[sourceIndex][targetIndex] = dist[target]
		}
	}

	if distBetween[startIndex][goalIndex] == -1 ||
		distBetween[startIndex][goalIndex] > T {
		fmt.Println(-1)
		return
	}

	answer := 0
	if n == 0 {
		fmt.Println(answer)
		return
	}

	stateCount := 1 << n
	// dp[mask*n+i] is the minimum number of moves needed to start at S,
	// visit all candies in mask, and finish at candy i.
	// Zero denotes an unreachable state; all valid values are positive.
	dp := make([]int, stateCount*n)

	for i := 0; i < n; i++ {
		d := distBetween[startIndex][i]
		if d >= 0 && d <= T {
			dp[(1<<i)*n+i] = d
		}
	}

	allMask := stateCount - 1

	for mask := 1; mask < stateCount; mask++ {
		base := mask * n
		endpoints := mask

		for endpoints != 0 {
			i := bits.TrailingZeros(uint(endpoints))
			endpoints &= endpoints - 1

			current := dp[base+i]
			if current == 0 {
				continue
			}

			toGoal := distBetween[i][goalIndex]
			if toGoal >= 0 && current+toGoal <= T {
				count := bits.OnesCount(uint(mask))
				if count > answer {
					answer = count
				}
			}

			remaining := allMask ^ mask
			for remaining != 0 {
				j := bits.TrailingZeros(uint(remaining))
				remaining &= remaining - 1

				d := distBetween[i][j]
				if d < 0 {
					continue
				}

				nextCost := current + d
				if nextCost > T {
					continue
				}

				nextMask := mask | (1 << j)
				index := nextMask*n + j
				if dp[index] == 0 || nextCost < dp[index] {
					dp[index] = nextCost
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
