		// State immediately before typing the next character.
		beforeOff := min(dpOff, dpOn+z)
		beforeOn := min(dpOn, dpOff+z)

		if ch == 'a' {
			dpOff = beforeOff + x
			dpOn = beforeOn + y
		} else {
			dpOff = beforeOff + y
			dpOn = beforeOn + x
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, min(dpOff, dpOn))
}

