import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	graph := make([][]int, n)

	for i := 0; i < n-1; i++ {
		u := in.NextInt() - 1
		v := in.NextInt() - 1
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u)
	}

	start := 0
	for i := 0; i < n; i++ {
		if len(graph[i]) == 1 {
			start = i
			break
		}
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}
	dist[start] = 0

	queue := make([]int, 0, n)
	queue = append(queue, start)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, next := range graph[v] {
			if dist[next] == -1 {
				dist[next] = dist[v] + 1
				queue = append(queue, next)
			}
		}
	}

	levels := make([]int, 0)
	for v := 0; v < n; v++ {
		if dist[v]%3 == 1 {
			levels = append(levels, len(graph[v]))
		}
	}

	sort.Ints(levels)

	for i, level := range levels {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, level)
	}
	fmt.Fprintln(out)
}
