type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) Find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.Find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) Union(a, b int) {
	a = d.Find(a)
	b = d.Find(b)
	if a == b {
		return
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
}

func pairKey(a, b int) uint64 {
	if a > b {
		a, b = b, a
	}
	return uint64(a)<<32 | uint64(b)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	dsu := NewDSU(n)
	for i := 0; i < m; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		dsu.Union(u-1, v-1)
	}

	var k int
	fmt.Fscan(in, &k)
	forbidden := make(map[uint64]struct{}, k)
	for i := 0; i < k; i++ {
		var x, y int
		fmt.Fscan(in, &x, &y)
		rx := dsu.Find(x - 1)
		ry := dsu.Find(y - 1)
		forbidden[pairKey(rx, ry)] = struct{}{}
	}

	var q int
	fmt.Fscan(in, &q)
	for i := 0; i < q; i++ {
		var p, r int
		fmt.Fscan(in, &p, &r)
		rp := dsu.Find(p - 1)
		rr := dsu.Find(r - 1)

		if _, exists := forbidden[pairKey(rp, rr)]; exists {
			fmt.Fprintln(out, "No")
		} else {
			fmt.Fprintln(out, "Yes")
		}
	}
}
