	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	// prefix[i] is the total sleep time in [0, a[i]).
	prefix := make([]int64, n)
	for i := 1; i < n; i++ {
		prefix[i] = prefix[i-1]
		if (i-1)%2 == 1 {
			prefix[i] += a[i] - a[i-1]
		}
	}

	sleepUntil := func(x int64) int64 {
		upper := sort.Search(n, func(i int) bool {
			return a[i] > x
		})
		idx := upper - 1

		result := prefix[idx]
		if idx%2 == 1 {
			result += x - a[idx]
		}
		return result
	}

	var q int
	fmt.Fscan(in, &q)
	for ; q > 0; q-- {
		var l, r int64
		fmt.Fscan(in, &l, &r)
		fmt.Fprintln(out, sleepUntil(r)-sleepUntil(l))
	}
