package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Item struct {
	vertex  int
	stamina int
}

type MaxHeap []Item

func (h MaxHeap) Len() int {
	return len(h)
}

func (h MaxHeap) Less(i, j int) bool {
	return h[i].stamina > h[j].stamina
}

func (h MaxHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Item))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, k int
	fmt.Fscan(in, &n, &m, &k)

	graph := make([][]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	best := make([]int, n)
	for i := range best {
		best[i] = -1
	}

	pq := &MaxHeap{}
	heap.Init(pq)

	for i := 0; i < k; i++ {
		var p, stamina int
		fmt.Fscan(in, &p, &stamina)
		p--
		if stamina > best[p] {
			best[p] = stamina
			heap.Push(pq, Item{vertex: p, stamina: stamina})
		}
	}

	for pq.Len() > 0 {
		current := heap.Pop(pq).(Item)
		if current.stamina != best[current.vertex] {
			continue
		}
		if current.stamina == 0 {
			continue
		}

		nextStamina := current.stamina - 1
		for _, next := range graph[current.vertex] {
			if nextStamina > best[next] {
				best[next] = nextStamina
				heap.Push(pq, Item{vertex: next, stamina: nextStamina})
			}
		}
	}

	guardedCount := 0
	for _, stamina := range best {
		if stamina >= 0 {
			guardedCount++
		}
	}

	fmt.Fprintln(out, guardedCount)
	first := true
	for vertex, stamina := range best {
		if stamina >= 0 {
			if !first {
				fmt.Fprint(out, " ")
			}
			fmt.Fprint(out, vertex+1)
			first = false
		}
	}
	fmt.Fprintln(out)
}
