package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Fenwick struct {
	n     int
	count []int
	sum   []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:     n,
		count: make([]int, n+1),
		sum:   make([]int64, n+1),
	}
}

func (f *Fenwick) Add(index, countDelta int, sumDelta int64) {
	for i := index; i <= f.n; i += i & -i {
		f.count[i] += countDelta
		f.sum[i] += sumDelta
	}
}

func (f *Fenwick) PrefixCount(index int) int {
	result := 0
	for i := index; i > 0; i -= i & -i {
		result += f.count[i]
	}
	return result
}

func (f *Fenwick) PrefixSum(index int) int64 {
	var result int64
	for i := index; i > 0; i -= i & -i {
		result += f.sum[i]
	}
	return result
}

// LowerBound returns the smallest index whose prefix count is at least target.
func (f *Fenwick) LowerBound(target int) int {
	index := 0
	accumulated := 0

	step := 1
	for step<<1 <= f.n {
		step <<= 1
	}

	for step > 0 {
		next := index + step
		if next <= f.n && accumulated+f.count[next] < target {
			index = next
			accumulated += f.count[next]
		}
		step >>= 1
	}
	return index + 1
}

type Query struct {
	x int
	y int64
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	k := int(in.NextInt64())
	q := int(in.NextInt64())

	queries := make([]Query, q)
	values := make([]int64, 0, q+1)
	values = append(values, 0)

	for i := 0; i < q; i++ {
		x := int(in.NextInt64()) - 1
		y := in.NextInt64()
		queries[i] = Query{x: x, y: y}
		values = append(values, y)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	unique := values[:0]
	for _, value := range values {
		if len(unique) == 0 || unique[len(unique)-1] != value {
			unique = append(unique, value)
		}
	}
	values = unique

	indexOf := make(map[int64]int, len(values))
	for i, value := range values {
		indexOf[value] = i + 1
	}

	fenwick := NewFenwick(len(values))
	current := make([]int64, n)

	zeroIndex := indexOf[0]
	fenwick.Add(zeroIndex, n, 0)

	var totalSum int64
	smallestCount := n - k

	for _, query := range queries {
		oldValue := current[query.x]
		newValue := query.y

		fenwick.Add(indexOf[oldValue], -1, -oldValue)
		fenwick.Add(indexOf[newValue], 1, newValue)
		current[query.x] = newValue
		totalSum += newValue - oldValue

		var smallestSum int64
		if smallestCount > 0 {
			boundary := fenwick.LowerBound(smallestCount)
			countBefore := fenwick.PrefixCount(boundary - 1)
			sumBefore := fenwick.PrefixSum(boundary - 1)
			smallestSum = sumBefore +
				int64(smallestCount-countBefore)*values[boundary-1]
		}

		fmt.Fprintln(out, totalSum-smallestSum)
	}
}
