package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func isUpper(c byte) bool {
	return c >= 'A' && c <= 'Z'
}

func isLower(c byte) bool {
	return c >= 'a' && c <= 'z'
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var s string
	fmt.Fscan(in, &s)
	n := len(s)

	fact := make([]int64, n+1)
	invFact := make([]int64, n+1)
	pow26 := make([]int64, n+1)

	fact[0] = 1
	pow26[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
		pow26[i] = pow26[i-1] * 26 % mod
	}
	invFact[n] = modPow(fact[n], mod-2)
	for i := n; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(a, b int) int64 {
		if b < 0 || b > a {
			return 0
		}
		return fact[a] * invFact[b] % mod * invFact[a-b] % mod
	}

	var falling [27][27]int64
	for a := 0; a <= 26; a++ {
		falling[a][0] = 1
		for t := 1; t <= a; t++ {
			falling[a][t] = falling[a][t-1] * int64(a-t+1) % mod
		}
	}

	// suffix[i] is the number of replacements of s[i:] whose
	// uppercase/lowercase categories have the form U*L*.
	suffix := make([]int64, n+1)
	nextU, nextL := int64(1), int64(1)
	suffix[n] = 1
	for i := n - 1; i >= 0; i-- {
		var curU, curL int64
		switch {
		case isUpper(s[i]):
			curU = nextU
			curL = 0
		case isLower(s[i]):
			curU = nextL
			curL = nextL
		default:
			curU = 26 * ((nextU + nextL) % mod) % mod
			curL = 26 * nextL % mod
		}
		suffix[i] = curU
		nextU, nextL = curU, curL
	}

	distinctTotal := func(q, fixed int) int64 {
		limit := 26 - fixed
		if q < limit {
			limit = q
		}
		var res int64
		for t := 0; t <= limit; t++ {
			ways := comb(q, t)
			ways = ways * falling[26-fixed][t] % mod
			ways = ways * pow26[q-t] % mod
			res += ways
			if res >= mod {
				res -= mod
			}
		}
		return res
	}

	var seen [26]bool
	fixedCount := 0
	questionCount := 0
	fixedDuplicate := false
	var answer int64

	for i := 0; i < n; i++ {
		c := s[i]
		var triggerWays int64

		if !fixedDuplicate {
			if c == '?' {
				limit := 26 - fixedCount
				if questionCount < limit {
					limit = questionCount
				}
				for t := 0; t <= limit; t++ {
					ways := comb(questionCount, t)
					ways = ways * falling[26-fixedCount][t] % mod
					ways = ways * pow26[questionCount-t] % mod
					ways = ways * int64(fixedCount+t) % mod
					triggerWays += ways
					if triggerWays >= mod {
						triggerWays -= mod
					}
				}
			} else if isUpper(c) {
				idx := int(c - 'A')
				if seen[idx] {
					triggerWays = distinctTotal(questionCount, fixedCount)
				} else {
					limit := 26 - fixedCount
					if questionCount < limit {
						limit = questionCount
					}
					for t := 1; t <= limit; t++ {
						ways := comb(questionCount, t)
						ways = ways * int64(t) % mod
						ways = ways * falling[25-fixedCount][t-1] % mod
						ways = ways * pow26[questionCount-t] % mod
						triggerWays += ways
						if triggerWays >= mod {
							triggerWays -= mod
						}
					}
				}
			}
		}

		answer = (answer + triggerWays*suffix[i+1]) % mod

		if c == '?' {
			questionCount++
		} else if isUpper(c) {
			idx := int(c - 'A')
			if seen[idx] {
				fixedDuplicate = true
			} else {
				seen[idx] = true
				fixedCount++
			}
		}
	}

	if !fixedDuplicate {
		answer += distinctTotal(questionCount, fixedCount)
		answer %= mod
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
