	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Fenwick struct {
	n    int
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int64, n+1),
	}
}

func (f *Fenwick) Add(index int, value int64) {
	for index <= f.n {
		f.tree[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int64 {
	var result int64
	for index > 0 {
		result += f.tree[index]
		index -= index & -index
	}
	return result
}

// LowerBound returns the smallest index whose prefix sum is at least target.
func (f *Fenwick) LowerBound(target int64) int {
	index := 0
	step := 1
	for step<<1 <= f.n {
		step <<= 1
	}
	for step > 0 {
		next := index + step
		if next <= f.n && f.tree[next] < target {
			index = next
			target -= f.tree[next]
		}
		step >>= 1
	}
	return index + 1
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	k := int(in.NextInt64())
	q := int(in.NextInt64())

	x := make([]int, q)
	y := make([]int64, q)
	values := make([]int64, 0, q+1)
	values = append(values, 0)

	for i := 0; i < q; i++ {
		x[i] = int(in.NextInt64()) - 1
		y[i] = in.NextInt64()
		values = append(values, y[i])
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	unique := values[:0]
	for _, v := range values {
		if len(unique) == 0 || unique[len(unique)-1] != v {
			unique = append(unique, v)
		}
	}
	values = unique

	indexOf := func(v int64) int {
		return sort.Search(len(values), func(i int) bool {
			return values[i] >= v
		}) + 1
	}

	countTree := NewFenwick(len(values))
	sumTree := NewFenwick(len(values))

	zeroIndex := indexOf(0)
	countTree.Add(zeroIndex, int64(n))

	current := make([]int64, n)
	var totalSum int64
	smallCount := n - k

	for i := 0; i < q; i++ {
		pos := x[i]
		oldValue := current[pos]
		newValue := y[i]

		oldIndex := indexOf(oldValue)
		newIndex := indexOf(newValue)

		countTree.Add(oldIndex, -1)
		sumTree.Add(oldIndex, -oldValue)
		countTree.Add(newIndex, 1)
		sumTree.Add(newIndex, newValue)

		current[pos] = newValue
		totalSum += newValue - oldValue

		var smallestSum int64
		if smallCount > 0 {
			boundary := countTree.LowerBound(int64(smallCount))
			countBefore := countTree.Sum(boundary - 1)
			sumBefore := sumTree.Sum(boundary - 1)
			remaining := int64(smallCount) - countBefore
			smallestSum = sumBefore + remaining*values[boundary-1]
		}

		fmt.Fprintln(out, totalSum-smallestSum)
	}
}
