```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

type Mask struct {
	lo uint64
	hi uint64
}

type Cell struct {
	r, c int
}

func readSheet(in *bufio.Reader) (int, int, []string) {
	var h, w int
	fmt.Fscan(in, &h, &w)
	grid := make([]string, h)
	for i := range grid {
		fmt.Fscan(in, &grid[i])
	}
	return h, w, grid
}

func blackCells(grid []string) []Cell {
	var cells []Cell
	for r := range grid {
		for c := range grid[r] {
			if grid[r][c] == '#' {
				cells = append(cells, Cell{r, c})
			}
		}
	}
	return cells
}

func addBit(m *Mask, pos int) {
	if pos < 64 {
		m.lo |= uint64(1) << pos
	} else {
		m.hi |= uint64(1) << (pos - 64)
	}
}

func placements(cells []Cell, x []string, hx, wx int) []Mask {
	minR, maxR := cells[0].r, cells[0].r
	minC, maxC := cells[0].c, cells[0].c
	for _, p := range cells {
		if p.r < minR {
			minR = p.r
		}
		if p.r > maxR {
			maxR = p.r
		}
		if p.c < minC {
			minC = p.c
		}
		if p.c > maxC {
			maxC = p.c
		}
	}

	var result []Mask
	seen := make(map[Mask]bool)

	for dr := -minR; dr <= hx-1-maxR; dr++ {
		for dc := -minC; dc <= wx-1-maxC; dc++ {
			var mask Mask
			valid := true

			for _, p := range cells {
				r, c := p.r+dr, p.c+dc
				if r < 0 || r >= hx || c < 0 || c >= wx || x[r][c] != '#' {
					valid = false
					break
				}
				addBit(&mask, r*wx+c)
			}

			if valid && !seen[mask] {
				seen[mask] = true
				result = append(result, mask)
			}
		}
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	_, _, a := readSheet(in)
	_, _, b := readSheet(in)
	hx, wx, x := readSheet(in)

	aCells := blackCells(a)
	bCells := blackCells(b)

	var target Mask
	for r := 0; r < hx; r++ {
		for c := 0; c < wx; c++ {
			if x[r][c] == '#' {
				addBit(&target, r*wx+c)
			}
		}
	}

	aPlacements := placements(aCells, x, hx, wx)
	bPlacements := placements(bCells, x, hx, wx)

	for _, am := range aPlacements {
		for _, bm := range bPlacements {
			if am.lo|bm.lo == target.lo && am.hi|bm.hi == target.hi {
				fmt.Fprintln(out, "Yes")
				return
			}
		}
	}

	fmt.Fprintln(out, "No")
}
