package main

import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	r, c int
}

type Mask [100]bool

func validPlacements(points []Point, sheetH, sheetW, xH, xW int, x []string) []Mask {
	var placements []Mask

	for dr := -(sheetH - 1); dr <= xH-1; dr++ {
		for dc := -(sheetW - 1); dc <= xW-1; dc++ {
			var mask Mask
			valid := true

			for _, p := range points {
				r, c := p.r+dr, p.c+dc
				if r < 0 || r >= xH || c < 0 || c >= xW || x[r][c] != '#' {
					valid = false
					break
				}
				mask[r*xW+c] = true
			}

			if valid {
				placements = append(placements, mask)
			}
		}
	}

	return placements
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var hA, wA int
	fmt.Fscan(in, &hA, &wA)
	a := make([]string, hA)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	var hB, wB int
	fmt.Fscan(in, &hB, &wB)
	b := make([]string, hB)
	for i := range b {
		fmt.Fscan(in, &b[i])
	}

	var hX, wX int
	fmt.Fscan(in, &hX, &wX)
	x := make([]string, hX)
	for i := range x {
		fmt.Fscan(in, &x[i])
	}

	var pointsA, pointsB []Point
	for r := 0; r < hA; r++ {
		for c := 0; c < wA; c++ {
			if a[r][c] == '#' {
				pointsA = append(pointsA, Point{r, c})
			}
		}
	}
	for r := 0; r < hB; r++ {
		for c := 0; c < wB; c++ {
			if b[r][c] == '#' {
				pointsB = append(pointsB, Point{r, c})
			}
		}
	}

	placementsA := validPlacements(pointsA, hA, wA, hX, wX, x)
	placementsB := validPlacements(pointsB, hB, wB, hX, wX, x)

	for _, maskA := range placementsA {
		for _, maskB := range placementsB {
			ok := true
			for r := 0; r < hX && ok; r++ {
				for c := 0; c < wX; c++ {
					black := maskA[r*wX+c] || maskB[r*wX+c]
					if black != (x[r][c] == '#') {
						ok = false
						break
					}
				}
			}
			if ok {
				fmt.Println("Yes")
				return
			}
		}
	}

	fmt.Println("No")
}
