	// Right edge moves down.
	for i := 1; i < n; i++ {
		result[i][n-1] = grid[i-1][n-1]
	}

	// Bottom edge moves left.
	for j := 0; j < n-1; j++ {
		result[n-1][j] = grid[n-1][j+1]
	}

	// Left edge moves up.
	for i := 0; i < n-1; i++ {
		result[i][0] = grid[i+1][0]
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i := 0; i < n; i++ {
		fmt.Fprintln(out, string(result[i]))
