import (
	"bufio"
	"fmt"
	"os"
)

func bfs(graph [][]int, start int) []int {
	dist := make([]int, len(graph))
	for i := range dist {
		dist[i] = -1
	}
	dist[start] = 0

	queue := make([]int, 0, len(graph))
	queue = append(queue, start)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, next := range graph[v] {
			if dist[next] == -1 {
				dist[next] = dist[v] + 1
				queue = append(queue, next)
			}
		}
	}
	return dist
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n1, n2, m int
	fmt.Fscan(in, &n1, &n2, &m)

	n := n1 + n2
	graph := make([][]int, n)

	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	fromFirst := bfs(graph, 0)
	fromLast := bfs(graph, n-1)

	maxFirst := 0
	for i := 0; i < n1; i++ {
		if fromFirst[i] > maxFirst {
			maxFirst = fromFirst[i]
		}
	}

	maxLast := 0
	for i := n1; i < n; i++ {
		if fromLast[i] > maxLast {
			maxLast = fromLast[i]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxFirst+maxLast+1)
}
