package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func bfs(start int, graph [][]int) []int {
	dist := make([]int, len(graph))
	for i := range dist {
		dist[i] = -1
	}

	queue := make([]int, 0, len(graph))
	queue = append(queue, start)
	dist[start] = 0

	for head := 0; head < len(queue); head++ {
		u := queue[head]
		for _, v := range graph[u] {
			if dist[v] == -1 {
				dist[v] = dist[u] + 1
				queue = append(queue, v)
			}
		}
	}
	return dist
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n1 := in.NextInt()
	n2 := in.NextInt()
	m := in.NextInt()
	n := n1 + n2

	graph := make([][]int, n)
	for i := 0; i < m; i++ {
		a := in.NextInt() - 1
		b := in.NextInt() - 1
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	distFromFirst := bfs(0, graph)
	distFromLast := bfs(n-1, graph)

	maxFirst := 0
	for i := 0; i < n1; i++ {
		if distFromFirst[i] > maxFirst {
			maxFirst = distFromFirst[i]
		}
	}

	maxLast := 0
	for i := n1; i < n; i++ {
		if distFromLast[i] > maxLast {
			maxLast = distFromLast[i]
		}
	}

	fmt.Fprintln(out, maxFirst+maxLast+1)
}
