package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353
const states = 1 << 11

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	dp := make([]int64, states)
	dp[1] = 1 // Only sum 0 is initially reachable.

	for i := 0; i < n; i++ {
		var a int
		fmt.Fscan(in, &a)

		next := make([]int64, states)
		limit := a
		if limit > 10 {
			limit = 10
		}
		largeCount := a - limit

		for mask, probability := range dp {
			if probability == 0 {
				continue
			}

			if largeCount > 0 {
				next[mask] = (next[mask] + probability*int64(largeCount)) % MOD
			}

			for value := 1; value <= limit; value++ {
				newMask := (mask | (mask << value)) & (states - 1)
				next[newMask] += probability
				if next[newMask] >= MOD {
					next[newMask] -= MOD
				}
			}
		}

		invA := modPow(int64(a), MOD-2)
		for mask := range next {
			next[mask] = next[mask] * invA % MOD
		}
		dp = next
	}

	var answer int64
	for mask, probability := range dp {
		if mask&(1<<10) != 0 {
			answer += probability
			if answer >= MOD {
				answer -= MOD
			}
		}
	}

	fmt.Fprintln(out, answer)
}
