	const states = 1 << 11
	const maskLimit = states - 1

	dp := make([]int64, states)
	dp[1] = 1 // Initially, only sum 0 is reachable.

	for i := 0; i < n; i++ {
		var a int64
		fmt.Fscan(in, &a)

		nextDP := make([]int64, states)
