		}

		for mask, probability := range dp {
			if probability == 0 {
				continue
			}

			for value := int64(1); value <= limit; value++ {
				nextMask := mask | ((mask << int(value)) & maskLimit)
				nextDP[nextMask] += probability
				if nextDP[nextMask] >= mod {
					nextDP[nextMask] -= mod
				}
			}

			if a > 10 {
				count := (a - 10) % mod
				nextDP[mask] = (nextDP[mask] + probability*count) % mod
			}
		}

		inverseA := modPow(a%mod, mod-2)
		for mask := range nextDP {
			nextDP[mask] = nextDP[mask] * inverseA % mod
		}
		dp = nextDP
