	b := make([]int, m)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	for i := range b {
		fmt.Fscan(in, &b[i])
	}

	sort.Ints(a)
	sort.Ints(b)

	low, high := 0, 1_000_000_001
	for high-low > 1 {
		mid := low + (high-low)/2

		sellers := sort.SearchInts(a, mid+1) // A_i <= mid
		buyers := m - sort.SearchInts(b, mid) // B_i >= mid

		if sellers >= buyers {
			high = mid
		} else {
			low = mid
		}
	}

	fmt.Fprintln(out, high)
}
