import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	fmt.Fscan(in, &n, &m)

	var pullTabs, regulars, openers []int64

	for i := 0; i < n; i++ {
		var t int
		var x int64
		fmt.Fscan(in, &t, &x)

		switch t {
		case 0:
			pullTabs = append(pullTabs, x)
		case 1:
			regulars = append(regulars, x)
		case 2:
			openers = append(openers, x)
		}
	}

	sort.Slice(pullTabs, func(i, j int) bool {
		return pullTabs[i] > pullTabs[j]
	})
	sort.Slice(regulars, func(i, j int) bool {
		return regulars[i] > regulars[j]
	})
	sort.Slice(openers, func(i, j int) bool {
		return openers[i] > openers[j]
	})

	pullPrefix := make([]int64, len(pullTabs)+1)
	for i, x := range pullTabs {
		pullPrefix[i+1] = pullPrefix[i] + x
	}

	regularPrefix := make([]int64, len(regulars)+1)
	for i, x := range regulars {
		regularPrefix[i+1] = regularPrefix[i] + x
	}

	var answer int64
	var capacity int64
	openerCount := 0

	maxRegulars := len(regulars)
	if maxRegulars > m {
		maxRegulars = m
	}

	for regularCount := 0; regularCount <= maxRegulars; regularCount++ {
		for capacity < int64(regularCount) && openerCount < len(openers) {
			capacity += openers[openerCount]
			openerCount++
		}

		if capacity < int64(regularCount) {
			break
		}
		if regularCount+openerCount > m {
			break
		}

		pullCount := m - regularCount - openerCount
		if pullCount > len(pullTabs) {
			pullCount = len(pullTabs)
		}

		happiness := regularPrefix[regularCount] + pullPrefix[pullCount]
		if happiness > answer {
			answer = happiness
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
