type Wheel struct {
	cost    int
	total   int
	rewards []int
	zeros   int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	fmt.Fscan(in, &n, &m)

	wheels := make([]Wheel, n)
	for i := 0; i < n; i++ {
		var c, p int
		fmt.Fscan(in, &c, &p)

		rewards := make([]int, 0, p)
		zeros := 0
		for j := 0; j < p; j++ {
			var s int
			fmt.Fscan(in, &s)
			if s == 0 {
				zeros++
			} else {
				rewards = append(rewards, s)
			}
		}

		wheels[i] = Wheel{
			cost:    c,
			total:   p,
			rewards: rewards,
			zeros:   zeros,
		}
	}

	// dp[x] is the minimum expected cost to earn at least x more points.
	dp := make([]float64, m+1)

	for x := 1; x <= m; x++ {
		best := math.Inf(1)

		for _, wheel := range wheels {
			sum := float64(wheel.cost * wheel.total)

			for _, reward := range wheel.rewards {
				remaining := x - reward
				if remaining > 0 {
					sum += dp[remaining]
				}
			}

			expected := sum / float64(wheel.total-wheel.zeros)
			if expected < best {
				best = expected
			}
		}

		dp[x] = best
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	fmt.Fprintf(out, "%.15f\n", dp[m])
}
