package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) Find(x int) int {
	root := x
	for d.parent[root] != root {
		root = d.parent[root]
	}
	for d.parent[x] != x {
		next := d.parent[x]
		d.parent[x] = root
		x = next
	}
	return root
}

func (d *DSU) Unite(x, y int) int {
	x = d.Find(x)
	y = d.Find(y)
	if d.size[x] < d.size[y] {
		x, y = y, x
	}
	d.parent[y] = x
	d.size[x] += d.size[y]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	n := in.NextInt()

	inv := make([]int64, n+1)
	inv[1] = 1
	for i := 2; i <= n; i++ {
		inv[i] = (mod - (mod/int64(i))*inv[mod%int64(i)]%mod) % mod
	}

	totalNodes := 2*n - 1
	left := make([]int, totalNodes)
	right := make([]int, totalNodes)
	leftWeight := make([]int64, totalNodes)
	rightWeight := make([]int64, totalNodes)
	for i := range left {
		left[i] = -1
		right[i] = -1
	}

	dsu := NewDSU(n)
	componentNode := make([]int, n)
	for i := 0; i < n; i++ {
		componentNode[i] = i
	}

	for i := 0; i < n-1; i++ {
		p := in.NextInt() - 1
		q := in.NextInt() - 1

		rp := dsu.Find(p)
		rq := dsu.Find(q)
		a := dsu.size[rp]
		b := dsu.size[rq]
		node := n + i

		left[node] = componentNode[rp]
		right[node] = componentNode[rq]
		leftWeight[node] = int64(a) * inv[a+b] % mod
		rightWeight[node] = int64(b) * inv[a+b] % mod

		newRoot := dsu.Unite(rp, rq)
		componentNode[newRoot] = node
	}

	root := componentNode[dsu.Find(0)]
	value := make([]int64, totalNodes)
	stack := make([]int, 0, totalNodes)
	stack = append(stack, root)

	for len(stack) > 0 {
		last := len(stack) - 1
		node := stack[last]
		stack = stack[:last]

		if node < n {
			continue
		}

		l, r := left[node], right[node]
		value[l] = (value[node] + leftWeight[node]) % mod
		value[r] = (value[node] + rightWeight[node]) % mod
		stack = append(stack, l, r)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value[i])
	}
	fmt.Fprintln(out)
}
