		p := in.NextInt() - 1
		q := in.NextInt() - 1

		rootP := find(parent, p)
		rootQ := find(parent, q)
		newRoot := n + i

		left[newRoot] = rootP
		right[newRoot] = rootQ

		combinedSize := size[rootP] + size[rootQ]
		value[rootP] = (value[rootP] + int64(size[rootP])*inv[combinedSize]) % MOD
		value[rootQ] = (value[rootQ] + int64(size[rootQ])*inv[combinedSize]) % MOD

