	}

	// Faces perpendicular to the X-axis.
	for x := 1; x < size; x++ {
		var previousRow [size]uint64
		for y := 0; y < size; y++ {
			var left uint64
			for z := 0; z < size; z++ {
				a := owner[index(x-1, y, z)]
				b := owner[index(x, y, z)]
				var key uint64
				if a != 0 && b != 0 && a != b {
					key = pairKey(a, b)
					if key != left && key != previousRow[z] {
						countPair(a, b)
					}
				}
				left = key
				previousRow[z] = key
			}
		}
	}

	// Faces perpendicular to the Y-axis.
	for y := 1; y < size; y++ {
		var previousRow [size]uint64
		for x := 0; x < size; x++ {
			var left uint64
			for z := 0; z < size; z++ {
				a := owner[index(x, y-1, z)]
				b := owner[index(x, y, z)]
				var key uint64
				if a != 0 && b != 0 && a != b {
					key = pairKey(a, b)
					if key != left && key != previousRow[z] {
						countPair(a, b)
					}
				}
				left = key
				previousRow[z] = key
			}
		}
	}

	// Faces perpendicular to the Z-axis.
	for z := 1; z < size; z++ {
		var previousRow [size]uint64
		for x := 0; x < size; x++ {
			var left uint64
			for y := 0; y < size; y++ {
				a := owner[index(x, y, z-1)]
				b := owner[index(x, y, z)]
				var key uint64
				if a != 0 && b != 0 && a != b {
					key = pairKey(a, b)
					if key != left && key != previousRow[y] {
						countPair(a, b)
					}
				}
				left = key
				previousRow[y] = key
			}
		}
	}

	for _, value := range answer {
		fmt.Fprintln(out, value)
	}
