		return fares[i] > fares[j]
	})

	answer := total
	var coveredFare int64

	for batches := 1; batches*d <= n+d-1; batches++ {
		coveredDays := batches * d
		if coveredDays > n {
			coveredDays = n
		}

		for i := (batches - 1) * d; i < coveredDays; i++ {
			coveredFare += fares[i]
		}

		cost := int64(batches)*p + total - coveredFare
		if cost < answer {
			answer = cost
		}
	}

	fmt.Fprintln(out, answer)
}
