func nextInt(r *bufio.Reader) int {
	n := 0
	c, err := r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = r.ReadByte()
	}
	return n
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := nextInt(in)
	a := make([]int, n)
	right := make([]int64, n+1)

	for i := 0; i < n; i++ {
		a[i] = nextInt(in)
		right[a[i]]++
	}

	left := make([]int64, n+1)
	var crossPairs int64
	var answer int64

	for _, x := range a {
		right[x]--
		crossPairs -= left[x]

		answer += crossPairs - left[x]*right[x]

		crossPairs += right[x]
		left[x]++
	}

	fmt.Fprintln(out, answer)
}
