package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner(r io.Reader) *FastScanner {
	data, _ := io.ReadAll(r)
	return &FastScanner{data: data}
}

func (fs *FastScanner) skipSpaces() {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
}

func (fs *FastScanner) NextInt() int {
	fs.skipSpaces()
	n := 0
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		n = n*10 + int(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return n
}

func (fs *FastScanner) NextBytes() []byte {
	fs.skipSpaces()
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func main() {
	in := NewFastScanner(os.Stdin)
	H := in.NextInt()
	W := in.NextInt()

	grid := make([][]byte, H)
	rowCount := make([][26]int, H)
	colCount := make([][26]int, W)
	rowDistinct := make([]int, H)
	colDistinct := make([]int, W)

	for i := 0; i < H; i++ {
		grid[i] = in.NextBytes()
		for j := 0; j < W; j++ {
			color := int(grid[i][j] - 'a')
			if rowCount[i][color] == 0 {
				rowDistinct[i]++
			}
			if colCount[j][color] == 0 {
				colDistinct[j]++
			}
			rowCount[i][color]++
			colCount[j][color]++
		}
	}

	activeRow := make([]bool, H)
	activeCol := make([]bool, W)
	for i := range activeRow {
		activeRow[i] = true
	}
	for j := range activeCol {
		activeCol[j] = true
	}

	activeRows := H
	activeCols := W

	currentRows := make([]int, 0)
	currentCols := make([]int, 0)

	for i := 0; i < H; i++ {
		if W >= 2 && rowDistinct[i] == 1 {
			currentRows = append(currentRows, i)
		}
	}
	for j := 0; j < W; j++ {
		if H >= 2 && colDistinct[j] == 1 {
			currentCols = append(currentCols, j)
		}
	}

	for len(currentRows) > 0 || len(currentCols) > 0 {
		for _, r := range currentRows {
			activeRow[r] = false
			activeRows--
		}
		for _, c := range currentCols {
			activeCol[c] = false
			activeCols--
		}

		// Remove deleted rows' cookies from columns that remain active.
		for _, r := range currentRows {
			for c := 0; c < W; c++ {
				if !activeCol[c] {
					continue
				}
				color := int(grid[r][c] - 'a')
				colCount[c][color]--
				if colCount[c][color] == 0 {
					colDistinct[c]--
				}
			}
		}

		// Remove deleted columns' cookies from rows that remain active.
		for _, c := range currentCols {
			for r := 0; r < H; r++ {
				if !activeRow[r] {
					continue
				}
				color := int(grid[r][c] - 'a')
				rowCount[r][color]--
				if rowCount[r][color] == 0 {
					rowDistinct[r]--
				}
			}
		}

		nextRows := make([]int, 0)
		nextCols := make([]int, 0)

		if len(currentCols) > 0 && activeCols >= 2 {
			for r := 0; r < H; r++ {
				if activeRow[r] && rowDistinct[r] == 1 {
					nextRows = append(nextRows, r)
				}
			}
		}

		if len(currentRows) > 0 && activeRows >= 2 {
			for c := 0; c < W; c++ {
				if activeCol[c] && colDistinct[c] == 1 {
					nextCols = append(nextCols, c)
				}
			}
		}

		currentRows = nextRows
		currentCols = nextCols
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, activeRows*activeCols)
}
