package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

type Point struct {
	x, y float64
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	fmt.Fscan(in, &n)

	points := make([]Point, n)
	for i := range points {
		fmt.Fscan(in, &points[i].x, &points[i].y)
	}

	const skipLimit = 30
	maxSkips := min(n-2, skipLimit)
	inf := math.Inf(1)

	dp := make([][]float64, n)
	for i := range dp {
		dp[i] = make([]float64, maxSkips+1)
		for j := range dp[i] {
			dp[i][j] = inf
		}
	}
	dp[0][0] = 0

	for i := 1; i < n; i++ {
		maxGap := min(i, maxSkips+1)
		for gap := 1; gap <= maxGap; gap++ {
			prev := i - gap
			skipped := gap - 1
			distance := math.Hypot(
				points[i].x-points[prev].x,
				points[i].y-points[prev].y,
			)

			for oldSkips := 0; oldSkips+skipped <= maxSkips; oldSkips++ {
				if math.IsInf(dp[prev][oldSkips], 1) {
					continue
				}
				newSkips := oldSkips + skipped
				candidate := dp[prev][oldSkips] + distance
				if candidate < dp[i][newSkips] {
					dp[i][newSkips] = candidate
				}
			}
		}
	}

	answer := inf
	for skipped := 0; skipped <= maxSkips; skipped++ {
		penalty := 0.0
		if skipped > 0 {
			penalty = math.Pow(2, float64(skipped-1))
		}
		answer = math.Min(answer, dp[n-1][skipped]+penalty)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintf(out, "%.20f\n", answer)
}
