	dfs = func(mask int) {
		if mask == (1<<9)-1 {
			good++
			return
		}

		for cell := 0; cell < 9; cell++ {
			if mask&(1<<cell) != 0 {
				continue
			}

			disappointed := false
			for _, line := range lines {
				pos := -1
				for i := 0; i < 3; i++ {
