	for mask := 0; mask < (1 << 9); mask++ {
		if dp[mask] == 0 {
			continue
		}

		for next := 0; next < 9; next++ {
			if mask&(1<<next) != 0 {
				continue
			}

			valid := true
			for _, line := range lines {
				other := [2]int{}
				count := 0
				containsNext := false

				for _, cell := range line {
					if cell == next {
						containsNext = true
					} else {
						other[count] = cell
						count++
					}
				}

				if containsNext &&
					mask&(1<<other[0]) != 0 &&
					mask&(1<<other[1]) != 0 &&
					values[other[0]] == values[other[1]] &&
					values[next] != values[other[0]] {
					valid = false
					break
				}
			}

			if valid {
				dp[mask|(1<<next)] += dp[mask]
			}
		}
