package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	to   int
	dx   int64
	dy   int64
}

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var sign int64 = 1
	var value int64

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return value * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())

	graph := make([][]Edge, n)
	for i := 0; i < m; i++ {
		a := int(in.NextInt64()) - 1
		b := int(in.NextInt64()) - 1
		x := in.NextInt64()
		y := in.NextInt64()

		graph[a] = append(graph[a], Edge{to: b, dx: x, dy: y})
		graph[b] = append(graph[b], Edge{to: a, dx: -x, dy: -y})
	}

	x := make([]int64, n)
	y := make([]int64, n)
	known := make([]bool, n)

	queue := make([]int, 0, n)
	queue = append(queue, 0)
	known[0] = true

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, e := range graph[v] {
			if known[e.to] {
				continue
			}
			known[e.to] = true
			x[e.to] = x[v] + e.dx
			y[e.to] = y[v] + e.dy
			queue = append(queue, e.to)
		}
	}

	for i := 0; i < n; i++ {
		if known[i] {
			fmt.Fprintf(out, "%d %d\n", x[i], y[i])
		} else {
			fmt.Fprintln(out, "undecidable")
		}
	}
}
