	var m int
	var s [3]string
	fmt.Fscan(in, &m)
	for i := 0; i < 3; i++ {
		fmt.Fscan(in, &s[i])
	}

	permutations := [][3]int{
		{0, 1, 2},
		{0, 2, 1},
		{1, 0, 2},
		{1, 2, 0},
		{2, 0, 1},
		{2, 1, 0},
	}

	const inf = int(1e9)
	answer := inf

	for digit := byte('0'); digit <= byte('9'); digit++ {
		for _, order := range permutations {
			time := -1
			possible := true

			for _, reel := range order {
				next := time + 1
				for next < 3*m && s[reel][next%m] != digit {
					next++
				}
				if next >= 3*m {
					possible = false
					break
				}
				time = next
			}

			if possible && time < answer {
				answer = time
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if answer == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
