package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	x := in.NextInt64()
	y := in.NextInt64()

	const cycle = 840

	var waits [9][cycle]int
	for p := 1; p <= 8; p++ {
		for r := 0; r < cycle; r++ {
			waits[p][r] = (p - r%p) % p
		}
	}

	var delay [cycle]int64
	var residue [cycle]int

	xMod := int(x % cycle)
	for r := 0; r < cycle; r++ {
		delay[r] = x
		residue[r] = r + xMod
		if residue[r] >= cycle {
			residue[r] -= cycle
		}
	}

	for i := 0; i < n-1; i++ {
		p := int(in.NextInt64())
		t := in.NextInt64()
		tMod := int(t % cycle)
		wait := waits[p][:]

		for r := 0; r < cycle; r++ {
			current := residue[r]
			w := wait[current]

			delay[r] += int64(w) + t

			next := current + w + tMod
			if next >= cycle {
				next -= cycle
			}
			residue[r] = next
		}
	}

	q := int(in.NextInt64())
	for i := 0; i < q; i++ {
		start := in.NextInt64()
		answer := start + delay[int(start%cycle)] + y
		fmt.Fprintln(out, answer)
	}
}
