func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var N, K, P int
	fmt.Fscan(in, &N, &K, &P)

	costs := make([]int64, N)
	gains := make([][]int, N)
	for i := 0; i < N; i++ {
		gains[i] = make([]int, K)
		fmt.Fscan(in, &costs[i])
		for j := 0; j < K; j++ {
			fmt.Fscan(in, &gains[i][j])
		}
	}

	base := P + 1
	pow := make([]int, K)
	pow[0] = 1
	for j := 1; j < K; j++ {
		pow[j] = pow[j-1] * base
	}
	stateCount := pow[K-1] * base

	const inf int64 = 1 << 62
	dp := make([]int64, stateCount)
	for i := 1; i < stateCount; i++ {
		dp[i] = inf
	}

	for i := 0; i < N; i++ {
		next := make([]int64, stateCount)
		copy(next, dp)

		for state := 0; state < stateCount; state++ {
			if dp[state] == inf {
				continue
			}

			newState := state
			x := state
			for j := 0; j < K; j++ {
				current := x % base
				x /= base

				updated := current + gains[i][j]
				if updated > P {
					updated = P
				}
				newState += (updated - current) * pow[j]
			}

			newCost := dp[state] + costs[i]
			if newCost < next[newState] {
				next[newState] = newCost
			}
		}
		dp = next
	}

	answer := dp[stateCount-1]
	if answer == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
