import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	r, c int
}

func generatePlacements(shape []Point) []uint16 {
	seen := make(map[uint16]bool)
	current := append([]Point(nil), shape...)

	for rotation := 0; rotation < 4; rotation++ {
		minR, minC := current[0].r, current[0].c
		maxR, maxC := current[0].r, current[0].c

		for _, p := range current {
			if p.r < minR {
				minR = p.r
			}
			if p.c < minC {
				minC = p.c
			}
			if p.r > maxR {
				maxR = p.r
			}
			if p.c > maxC {
				maxC = p.c
			}
		}

		normalized := make([]Point, len(current))
		for i, p := range current {
			normalized[i] = Point{p.r - minR, p.c - minC}
		}

		height := maxR - minR + 1
		width := maxC - minC + 1

		for dr := 0; dr+height <= 4; dr++ {
			for dc := 0; dc+width <= 4; dc++ {
				var mask uint16
				for _, p := range normalized {
					r, c := p.r+dr, p.c+dc
					mask |= uint16(1) << (r*4 + c)
				}
				seen[mask] = true
			}
		}

		next := make([]Point, len(current))
		for i, p := range current {
			next[i] = Point{p.c, -p.r}
		}
		current = next
	}

	placements := make([]uint16, 0, len(seen))
	for mask := range seen {
		placements = append(placements, mask)
	}
	return placements
}

func main() {
	in := bufio.NewReader(os.Stdin)

	shapes := make([][]Point, 3)
	totalArea := 0

	for i := 0; i < 3; i++ {
		for r := 0; r < 4; r++ {
			var row string
			fmt.Fscan(in, &row)
			for c, ch := range row {
				if ch == '#' {
					shapes[i] = append(shapes[i], Point{r, c})
					totalArea++
				}
			}
		}
	}

	if totalArea != 16 {
		fmt.Println("No")
		return
	}

	placements := make([][]uint16, 3)
	for i := 0; i < 3; i++ {
		placements[i] = generatePlacements(shapes[i])
	}

	third := make(map[uint16]bool)
	for _, mask := range placements[2] {
		third[mask] = true
	}

	const full uint16 = (1 << 16) - 1

	for _, a := range placements[0] {
		for _, b := range placements[1] {
			if a&b != 0 {
				continue
			}
			remaining := full ^ (a | b)
			if third[remaining] {
				fmt.Println("Yes")
				return
			}
		}
	}

	fmt.Println("No")
}
