package main

import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	r, c int
}

func normalize(shape []Point) []Point {
	minR, minC := shape[0].r, shape[0].c
	for _, p := range shape {
		if p.r < minR {
			minR = p.r
		}
		if p.c < minC {
			minC = p.c
		}
	}
	res := make([]Point, len(shape))
	for i, p := range shape {
		res[i] = Point{p.r - minR, p.c - minC}
	}
	return res
}

func rotate(shape []Point) []Point {
	res := make([]Point, len(shape))
	for i, p := range shape {
		res[i] = Point{p.c, -p.r}
	}
	return normalize(res)
}

func placements(shape []Point) []uint16 {
	seen := make(map[uint16]bool)
	current := normalize(shape)

	for rotation := 0; rotation < 4; rotation++ {
		maxR, maxC := 0, 0
		for _, p := range current {
			if p.r > maxR {
				maxR = p.r
			}
			if p.c > maxC {
				maxC = p.c
			}
		}

		height, width := maxR+1, maxC+1
		if height <= 4 && width <= 4 {
			for dr := 0; dr+height <= 4; dr++ {
				for dc := 0; dc+width <= 4; dc++ {
					var mask uint16
					for _, p := range current {
						pos := (p.r+dr)*4 + p.c + dc
						mask |= uint16(1) << pos
					}
					seen[mask] = true
				}
			}
		}
		current = rotate(current)
	}

	result := make([]uint16, 0, len(seen))
	for mask := range seen {
		result = append(result, mask)
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	shapes := make([][]Point, 3)
	totalSquares := 0

	for i := 0; i < 3; i++ {
