	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if totalSquares != 16 {
		fmt.Fprintln(out, "No")
		return
	}

	options := make([][]uint16, 3)
	for i := 0; i < 3; i++ {
		options[i] = placements(shapes[i])
	}

	const full uint16 = 0xFFFF
	for _, a := range options[0] {
		for _, b := range options[1] {
			if a&b != 0 {
