package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextUint64() uint64 {
	var n uint64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + uint64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

func descendantCount(n, root, depth uint64) uint64 {
	if root == 0 || root > n || depth >= 63 {
		return 0
	}

	width := uint64(1) << depth
	if root > n/width {
		return 0
	}

	left := root * width
	right := left + width - 1
	if right > n {
		right = n
	}
	return right - left + 1
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := int(in.NextUint64())

	for ; t > 0; t-- {
		n := in.NextUint64()
		x := in.NextUint64()
		k := in.NextUint64()

		answer := descendantCount(n, x, k)

		ancestor := x
		for up := uint64(1); up <= k && ancestor > 1; up++ {
			childOnPath := ancestor
			ancestor >>= 1
			remaining := k - up

			if remaining == 0 {
				answer++
			} else {
				sibling := childOnPath ^ 1
				answer += descendantCount(n, sibling, remaining-1)
			}
		}

		fmt.Fprintln(out, answer)
	}
}
