package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, x int
	fmt.Fscan(in, &n, &x)

	t := make([]int, n)
	for i := range t {
		fmt.Fscan(in, &t[i])
	}

	invN := modPow(int64(n), mod-2)

	// dp[s] is the probability that a song starts at exactly time s.
	dp := make([]int64, x+1)
	dp[0] = 1

	for s := 1; s <= x; s++ {
		var sum int64
		for _, length := range t {
			if s >= length {
				sum += dp[s-length]
				if sum >= mod {
					sum -= mod
				}
			}
		}
		dp[s] = sum * invN % mod
	}

	left := x - t[0] + 1
	if left < 0 {
		left = 0
	}

	var answer int64
	for s := left; s <= x; s++ {
		answer += dp[s]
		if answer >= mod {
			answer -= mod
		}
	}
	answer = answer * invN % mod

	fmt.Fprintln(out, answer)
}
