func isPossible(s, t string) bool {
	if len(s)-len(t) > 1 || len(t)-len(s) > 1 {
		return false
	}

	if len(s) == len(t) {
		diff := 0
		for i := 0; i < len(s); i++ {
			if s[i] != t[i] {
				diff++
				if diff > 1 {
					return false
				}
			}
		}
		return true
	}

	// Make a the shorter string and b the longer string.
	a, b := s, t
	if len(a) > len(b) {
		a, b = b, a
	}

	i, j := 0, 0
	skipped := false
	for i < len(a) && j < len(b) {
		if a[i] == b[j] {
			i++
			j++
		} else {
			if skipped {
				return false
			}
			skipped = true
			j++
		}
	}
	return true
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var received string
	fmt.Fscan(in, &n, &received)

	indices := make([]int, 0)
	for i := 1; i <= n; i++ {
		var s string
		fmt.Fscan(in, &s)
		if isPossible(s, received) {
			indices = append(indices, i)
		}
	}

	fmt.Fprintln(out, len(indices))
	for i, index := range indices {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, index)
	}
	fmt.Fprintln(out)
}
