func nextToken(r *bufio.Reader) string {
	for {
		b, err := r.ReadByte()
		if err != nil {
			return ""
		}
		if b > ' ' {
			buf := []byte{b}
			for {
				b, err = r.ReadByte()
				if err != nil || b <= ' ' {
					return string(buf)
				}
				buf = append(buf, b)
			}
		}
	}
