package main

import (
	"io"
	"os"
	"strconv"
)

func closeEnough(a, b []byte) bool {
	if len(a)-len(b) > 1 || len(b)-len(a) > 1 {
		return false
	}

	if len(a) == len(b) {
		differences := 0
		for i := range a {
			if a[i] != b[i] {
				differences++
				if differences > 1 {
					return false
				}
			}
		}
		return true
	}

	shorter, longer := a, b
	if len(shorter) > len(longer) {
		shorter, longer = longer, shorter
	}

	i, j := 0, 0
	skipped := false
	for i < len(shorter) && j < len(longer) {
		if shorter[i] == longer[j] {
			i++
			j++
		} else {
			if skipped {
				return false
			}
			skipped = true
			j++
		}
	}
	return true
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	pos := 0

	nextToken := func() []byte {
		for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
			pos++
		}
		start := pos
		for pos < len(data) && data[pos] != ' ' && data[pos] != '\n' && data[pos] != '\r' && data[pos] != '\t' {
			pos++
		}
		return data[start:pos]
	}

	nToken := nextToken()
	n := 0
	for _, c := range nToken {
		n = n*10 + int(c-'0')
	}
	target := nextToken()

	answers := make([]int, 0)
	for i := 1; i <= n; i++ {
		s := nextToken()
		if closeEnough(s, target) {
			answers = append(answers, i)
		}
	}

	output := make([]byte, 0, len(answers)*8+20)
	output = strconv.AppendInt(output, int64(len(answers)), 10)
	output = append(output, '\n')
	for i, index := range answers {
		if i > 0 {
			output = append(output, ' ')
		}
		output = strconv.AppendInt(output, int64(index), 10)
	}
	if len(answers) > 0 {
		output = append(output, '\n')
	}

	_, _ = os.Stdout.Write(output)
}
