type slime struct {
	base  int64
	power int
	count int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	slimes := make([]slime, n)
	for i := 0; i < n; i++ {
		var s, c int64
		fmt.Fscan(in, &s, &c)

		power := 0
		for s%2 == 0 {
			s /= 2
			power++
		}
		slimes[i] = slime{base: s, power: power, count: c}
	}

	sort.Slice(slimes, func(i, j int) bool {
		if slimes[i].base != slimes[j].base {
			return slimes[i].base < slimes[j].base
		}
		return slimes[i].power < slimes[j].power
	})

	var answer int64

	for i := 0; i < n; {
		j := i
		base := slimes[i].base
		position := slimes[i].power
		var carry int64

		for j < n && slimes[j].base == base {
			for position < slimes[j].power {
				answer += carry & 1
				carry >>= 1
				position++
			}
			carry += slimes[j].count
			j++
		}

		answer += int64(bits.OnesCount64(uint64(carry)))
		i = j
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
