import (
	"bufio"
	"fmt"
	"os"
)

const inf int64 = 1 << 62

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func dijkstra(n, start int, d []int64, multiplier, extra int64) []int64 {
	dist := make([]int64, n)
	used := make([]bool, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[start] = 0

	for iter := 0; iter < n; iter++ {
		u := -1
		for i := 0; i < n; i++ {
			if !used[i] && (u == -1 || dist[i] < dist[u]) {
				u = i
			}
		}
		if u == -1 || dist[u] == inf {
			break
		}
		used[u] = true

		for v := 0; v < n; v++ {
			if used[v] || u == v {
				continue
			}
			cost := d[u*n+v]*multiplier + extra
			if dist[v] > dist[u]+cost {
				dist[v] = dist[u] + cost
			}
		}
	}
	return dist
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	a := in.NextInt64()
	b := in.NextInt64()
	c := in.NextInt64()

	d := make([]int64, n*n)
	for i := range d {
		d[i] = in.NextInt64()
	}

	carDist := dijkstra(n, 0, d, a, 0)
	trainDist := dijkstra(n, n-1, d, b, c)

	answer := inf
	for i := 0; i < n; i++ {
		if carDist[i]+trainDist[i] < answer {
			answer = carDist[i] + trainDist[i]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
