type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type Edge struct {
	to     int
	beauty int64
	cost   int64
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	graph := make([][]Edge, n)
	high := 0.0

	for i := 0; i < m; i++ {
		u := in.NextInt() - 1
		v := in.NextInt() - 1
		b := in.NextInt()
		c := in.NextInt()

		graph[u] = append(graph[u], Edge{
			to:     v,
			beauty: int64(b),
			cost:   int64(c),
		})

		ratio := float64(b) / float64(c)
		if ratio > high {
			high = ratio
		}
	}

	bestBeauty := make([]int64, n)
	bestCost := make([]int64, n)
	reachable := make([]bool, n)

	isFeasible := func(x float64) bool {
		for i := 0; i < n; i++ {
			reachable[i] = false
		}
		reachable[0] = true
		bestBeauty[0] = 0
		bestCost[0] = 0

		for u := 0; u < n; u++ {
			if !reachable[u] {
				continue
			}
			for _, e := range graph[u] {
				candidateBeauty := bestBeauty[u] + e.beauty
				candidateCost := bestCost[u] + e.cost
				v := e.to

				if !reachable[v] ||
					float64(candidateBeauty)-x*float64(candidateCost) >
						float64(bestBeauty[v])-x*float64(bestCost[v]) {
					reachable[v] = true
					bestBeauty[v] = candidateBeauty
					bestCost[v] = candidateCost
				}
			}
		}

		return reachable[n-1] &&
			float64(bestBeauty[n-1])-x*float64(bestCost[n-1]) >= 0
	}

	low := 0.0
	for i := 0; i < 100; i++ {
		mid := (low + high) / 2
		if isFeasible(mid) {
			low = mid
		} else {
			high = mid
		}
	}

	fmt.Fprintf(out, "%.15f\n", (low+high)/2)
}
