	"fmt"
	"os"
)

type Pattern struct {
	cells []byte
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var r, c string
	fmt.Fscan(in, &n, &r, &c)

	candidates := make([][]Pattern, n)

	for row := 0; row < n; row++ {
		for pa := 0; pa < n; pa++ {
			for pb := 0; pb < n; pb++ {
				if pb == pa {
					continue
				}
				for pc := 0; pc < n; pc++ {
					if pc == pa || pc == pb {
						continue
					}

					cells := make([]byte, n)
					for i := range cells {
						cells[i] = '.'
					}
					cells[pa] = 'A'
					cells[pb] = 'B'
					cells[pc] = 'C'

					left := pa
					if pb < left {
						left = pb
					}
					if pc < left {
						left = pc
					}

					if cells[left] == r[row] {
						candidates[row] = append(candidates[row], Pattern{cells: cells})
					}
				}
			}
		}
	}

	grid := make([][]byte, n)
	columnMask := make([]int, n)

	var dfs func(int) bool
	dfs = func(row int) bool {
		if row == n {
			for col := 0; col < n; col++ {
				if columnMask[col] != 7 {
					return false
				}
			}
			return true
		}

		for _, pattern := range candidates[row] {
			valid := true
			changedCols := make([]int, 0, 3)
			changedBits := make([]int, 0, 3)

			for col, ch := range pattern.cells {
				if ch == '.' {
					continue
				}

				bit := 1 << (ch - 'A')
				if columnMask[col]&bit != 0 {
					valid = false
					break
				}
				if columnMask[col] == 0 && ch != c[col] {
					valid = false
					break
				}

				columnMask[col] |= bit
				changedCols = append(changedCols, col)
				changedBits = append(changedBits, bit)
			}

			if valid {
				remainingRows := n - row - 1
				for col := 0; col < n; col++ {
					filled := 0
					for mask := columnMask[col]; mask > 0; mask >>= 1 {
						filled += mask & 1
					}
					if 3-filled > remainingRows {
						valid = false
						break
					}
				}
			}

			if valid {
				grid[row] = pattern.cells
				if dfs(row + 1) {
					return true
				}
			}

			for i, col := range changedCols {
				columnMask[col] &^= changedBits[i]
			}
		}

		return false
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if !dfs(0) {
		fmt.Fprintln(out, "No")
		return
	}

	fmt.Fprintln(out, "Yes")
	for i := 0; i < n; i++ {
		fmt.Fprintln(out, string(grid[i]))
	}
}
