package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	for {
		c, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if c >= '0' && c <= '9' {
			n = int64(c - '0')
			break
		}
	}
	for {
		c, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if c < '0' || c > '9' {
			return n
		}
		n = n*10 + int64(c-'0')
	}
}

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	a := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		a[i] = in.NextInt64()
	}

	invN := modPow(int64(n), mod-2)
	var suffix int64

	for x := n; x >= 1; x-- {
		expected := suffix * invN % mod
		suffix = (suffix + a[x] + expected) % mod
	}

	answer := suffix * invN % mod
	fmt.Fprintln(out, answer)
}
