package main

import (
	"bufio"
	"fmt"
	"os"
)

type DSU struct {
	parent []int
	size   []int
	parity []int
}

func NewDSU(n int) *DSU {
	d := &DSU{
		parent: make([]int, n),
		size:   make([]int, n),
		parity: make([]int, n),
	}
	for i := 0; i < n; i++ {
		d.parent[i] = i
		d.size[i] = 1
	}
	return d
}

func (d *DSU) find(x int) (int, int) {
	if d.parent[x] == x {
		return x, 0
	}
	root, p := d.find(d.parent[x])
	d.parity[x] ^= p
	d.parent[x] = root
	return root, d.parity[x]
}

func (d *DSU) uniteDifferent(a, b int) bool {
	ra, pa := d.find(a)
	rb, pb := d.find(b)

	if ra == rb {
		return pa^pb == 1
	}

	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}

	d.parent[rb] = ra
	d.parity[rb] = pa ^ pb ^ 1
	d.size[ra] += d.size[rb]
	return true
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	a := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &a[i])
		a[i]--
	}

	dsu := NewDSU(n)
	ok := true

	for i := 0; i < m; i++ {
		var b int
		fmt.Fscan(in, &b)
		b--
		if ok && !dsu.uniteDifferent(a[i], b) {
			ok = false
		}
	}

	if ok {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}
