func repeatedDigit(n int) (int, bool) {
	digit := n % 10
	for n > 0 {
		if n%10 != digit {
			return 0, false
		}
		n /= 10
	}
	return digit, true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	fmt.Fscan(in, &n)

	answer := 0
	for month := 1; month <= n; month++ {
		var days int
		fmt.Fscan(in, &days)

		monthDigit, ok := repeatedDigit(month)
		if !ok {
			continue
		}

		for day := 1; day <= days; day++ {
			dayDigit, ok := repeatedDigit(day)
			if ok && dayDigit == monthDigit {
