import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()

	boxes := make([]map[int]struct{}, n)
	for i := 0; i < n; i++ {
		color := in.NextInt()
		boxes[i] = map[int]struct{}{color: {}}
	}

	for i := 0; i < q; i++ {
		a := in.NextInt() - 1
		b := in.NextInt() - 1

		source := boxes[a]
		destination := boxes[b]

		// Merge the smaller set into the larger set.
		if len(source) > len(destination) {
			source, destination = destination, source
		}
		for color := range source {
			destination[color] = struct{}{}
		}

		boxes[a] = nil
		boxes[b] = destination

		fmt.Fprintln(out, len(destination))
	}
}
