package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	var s, t string
	fmt.Fscan(in, &n, &m)
	fmt.Fscan(in, &s)
	fmt.Fscan(in, &t)

	erased := make([]bool, n)
	used := make([]bool, n-m+1)
	queue := make([]int, 0, n)

	canErase := func(start int) bool {
		hasRemaining := false
		for j := 0; j < m; j++ {
			pos := start + j
			if erased[pos] {
				continue
			}
			hasRemaining = true
			if s[pos] != t[j] {
				return false
			}
		}
		return hasRemaining
	}

	for start := 0; start <= n-m; start++ {
		if canErase(start) {
			used[start] = true
			queue = append(queue, start)
		}
	}

	erasedCount := 0
	for head := 0; head < len(queue); head++ {
		start := queue[head]

		for j := 0; j < m; j++ {
			pos := start + j
			if erased[pos] {
				continue
			}

			erased[pos] = true
			erasedCount++

			left := pos - m + 1
			if left < 0 {
				left = 0
			}
			right := pos
			if right > n-m {
				right = n - m
			}

			for next := left; next <= right; next++ {
				if !used[next] && canErase(next) {
					used[next] = true
					queue = append(queue, next)
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if erasedCount == n {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}
