func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var d int64
	fmt.Fscan(in, &d)

	var y int64
	for (y+1)*(y+1) <= d {
		y++
	}

	answer := d

	for x := int64(0); x*x <= d; x++ {
		for y > 0 && x*x+y*y > d {
			y--
		}

		diff := abs(x*x + y*y - d)
		if diff < answer {
			answer = diff
		}

		diff = abs(x*x + (y+1)*(y+1) - d)
		if diff < answer {
			answer = diff
		}
	}

	fmt.Fprintln(out, answer)
}
