	count := make([]int, n+1)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		if a[i] <= n {
			count[a[i]]++
		}
	}

	missing := &MinHeap{}
	for x := 0; x <= n; x++ {
		if count[x] == 0 {
			*missing = append(*missing, x)
		}
	}
	heap.Init(missing)

	for ; q > 0; q-- {
		var index, x int
		fmt.Fscan(in, &index, &x)
		index--

		old := a[index]
		if old <= n {
			count[old]--
			if count[old] == 0 {
