package main

import (
	"os"
	"strconv"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := os.ReadFile("/dev/stdin")
	return &FastScanner{data: data}
}

func (fs *FastScanner) Next() []byte {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func (fs *FastScanner) NextInt64() int64 {
	token := fs.Next()
	var value int64
	for _, c := range token {
		value = value*10 + int64(c-'0')
	}
	return value
}

func main() {
	in := NewFastScanner()
	n := int(in.NextInt64())
	q := int(in.NextInt64())

	width := n + 1
	prefix := make([]int64, width*width)

	for i := 1; i <= n; i++ {
		row := in.Next()
		for j := 1; j <= n; j++ {
			var black int64
			if row[j-1] == 'B' {
				black = 1
			}
			prefix[i*width+j] = prefix[(i-1)*width+j] +
				prefix[i*width+j-1] -
				prefix[(i-1)*width+j-1] +
				black
		}
	}

	total := prefix[n*width+n]
	countPrefix := func(x, y int64) int64 {
		fullRows := x / int64(n)
		fullCols := y / int64(n)
		remRows := int(x % int64(n))
		remCols := int(y % int64(n))

		return fullRows*fullCols*total +
			fullRows*prefix[n*width+remCols] +
			fullCols*prefix[remRows*width+n] +
			prefix[remRows*width+remCols]
	}

	output := make([]byte, 0, q*20)
	for ; q > 0; q-- {
		a := in.NextInt64()
		b := in.NextInt64()
		c := in.NextInt64()
		d := in.NextInt64()

		answer := countPrefix(c+1, d+1) -
			countPrefix(a, d+1) -
			countPrefix(c+1, b) +
			countPrefix(a, b)

		output = strconv.AppendInt(output, answer, 10)
		output = append(output, '\n')
	}

	_, _ = os.Stdout.Write(output)
}
