package main

import (
	"bufio"
	"fmt"
	"os"
)

type Sensor struct {
	L int64
	C int64
	K int
}

type Option struct {
	a int
	b int
}

func makeOptions(d int64, a, b Sensor) []Option {
	maxA := int((d + a.L - 1) / a.L)
	if maxA > a.K {
		maxA = a.K
	}

	options := make([]Option, 0, maxA+1)
	lastB := b.K + 1

	for countA := 0; countA <= maxA; countA++ {
		remaining := d - int64(countA)*a.L
		countB := 0
		if remaining > 0 {
			countB = int((remaining + b.L - 1) / b.L)
		}
		if countB <= b.K && countB < lastB {
			options = append(options, Option{countA, countB})
			lastB = countB
		}
	}
	return options
}

func buildAllOptions(ds []int64, a, b Sensor) ([][]Option, bool) {
	all := make([][]Option, len(ds))
	for i, d := range ds {
		all[i] = makeOptions(d, a, b)
		if len(all[i]) == 0 {
			return nil, false
		}
	}
	return all, true
}

func optionScore(all [][]Option, k int) int64 {
	var total int64
	for _, options := range all {
		total += int64(len(options))
	}
	return total * int64(k+1)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	ds := make([]int64, n)
	var totalLength int64
	for i := range ds {
		fmt.Fscan(in, &ds[i])
		totalLength += ds[i]
	}

	var s1, s2 Sensor
	fmt.Fscan(in, &s1.L, &s1.C, &s1.K)
	fmt.Fscan(in, &s2.L, &s2.C, &s2.K)

	if totalLength > int64(s1.K)*s1.L+int64(s2.K)*s2.L {
		fmt.Fprintln(out, -1)
		return
	}

	options12, ok12 := buildAllOptions(ds, s1, s2)
	options21, ok21 := buildAllOptions(ds, s2, s1)

	if !ok12 && !ok21 {
		fmt.Fprintln(out, -1)
		return
	}

	a, b := s1, s2
	allOptions := options12

	if !ok12 || (ok21 && optionScore(options21, s2.K) < optionScore(options12, s1.K)) {
		a, b = s2, s1
		allOptions = options21
	}

	inf := b.K + 1
	dp := make([]int, a.K+1)
	next := make([]int, a.K+1)
	for i := range dp {
		dp[i] = inf
	}
	dp[0] = 0
	maxUsedA := 0

	for _, options := range allOptions {
		for i := range next {
			next[i] = inf
		}

		newMax := 0
		maxOptionA := options[len(options)-1].a
		if maxUsedA+maxOptionA < a.K {
			newMax = maxUsedA + maxOptionA
		} else {
			newMax = a.K
		}

		for usedA := 0; usedA <= maxUsedA; usedA++ {
			if dp[usedA] > b.K {
				continue
			}
			for _, option := range options {
				newA := usedA + option.a
				if newA > a.K {
					break
				}
				newB := dp[usedA] + option.b
				if newB <= b.K && newB < next[newA] {
					next[newA] = newB
				}
			}
		}

		dp, next = next, dp
		maxUsedA = newMax
	}

	const infCost int64 = 1<<63 - 1
	answer := infCost
	for countA, countB := range dp {
		if countB > b.K {
			continue
		}
		cost := int64(countA)*a.C + int64(countB)*b.C
		if cost < answer {
			answer = cost
		}
	}

	if answer == infCost {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
	}
}
