	fmt.Fscan(in, &A, &M, &L, &R)

	minK := ceilDiv(L-A, M)
	maxK := floorDiv(R-A, M)

	var answer int64
	if minK <= maxK {
		answer = maxK - minK + 1
	}

	fmt.Fprintln(out, answer)
}
