package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	t := make([]int, n)
	x := make([]int, n)

	for i := 0; i < n; i++ {
		t[i] = in.NextInt()
		x[i] = in.NextInt()
	}

	need := make([]int, n+1)
	selected := make([]bool, n)
	unmatched := 0

	for i := n - 1; i >= 0; i-- {
		if t[i] == 2 {
			need[x[i]]++
			unmatched++
		} else if need[x[i]] > 0 {
			selected[i] = true
			need[x[i]]--
			unmatched--
		}
	}

	if unmatched > 0 {
		fmt.Fprintln(out, -1)
		return
	}

	current, maxPotions := 0, 0
	for i := 0; i < n; i++ {
		if t[i] == 1 {
			if selected[i] {
				current++
				if current > maxPotions {
					maxPotions = current
				}
			}
		} else {
			current--
		}
	}

	fmt.Fprintln(out, maxPotions)

	first := true
	for i := 0; i < n; i++ {
		if t[i] != 1 {
			continue
		}
		if !first {
			fmt.Fprint(out, " ")
		}
		first = false
		if selected[i] {
			fmt.Fprint(out, 1)
		} else {
			fmt.Fprint(out, 0)
		}
	}
	fmt.Fprintln(out)
}
