	needed := make([]int, n+1)
	take := make([]bool, n)

	for i := n - 1; i >= 0; i-- {
		if t[i] == 2 {
			needed[x[i]]++
		} else if needed[x[i]] > 0 {
			take[i] = true
			needed[x[i]]--
		}
	}

	for typ := 1; typ <= n; typ++ {
		if needed[typ] > 0 {
			fmt.Fprintln(out, -1)
			return
		}
	}

	current, maxPotions := 0, 0
	for i := 0; i < n; i++ {
		if t[i] == 1 {
			if take[i] {
				current++
				if current > maxPotions {
					maxPotions = current
				}
			}
		} else {
			current--
		}
	}

	fmt.Fprintln(out, maxPotions)

	first := true
	for i := 0; i < n; i++ {
		if t[i] != 1 {
			continue
		}
		if !first {
			fmt.Fprint(out, " ")
		}
		first = false
		if take[i] {
			fmt.Fprint(out, 1)
		} else {
			fmt.Fprint(out, 0)
		}
	}
	fmt.Fprintln(out)
}
