package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) Next() []byte {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func (fs *FastScanner) NextInt() int {
	token := fs.Next()
	n := 0
	for _, c := range token {
		n = n*10 + int(c-'0')
	}
	return n
}

type DSU struct {
	parent []int
}

func (d *DSU) Find(x int) int {
	root := x
	for d.parent[root] >= 0 {
		root = d.parent[root]
	}
	for x != root {
		next := d.parent[x]
		d.parent[x] = root
		x = next
	}
	return root
}

func (d *DSU) Union(a, b int) bool {
	a = d.Find(a)
	b = d.Find(b)
	if a == b {
		return false
	}
	if d.parent[a] > d.parent[b] {
		a, b = b, a
	}
	d.parent[a] += d.parent[b]
	d.parent[b] = a
	return true
}

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := NewFastScanner()
	h := in.NextInt()
	w := in.NextInt()
	n := h * w

	grid := make([]byte, n)
	parent := make([]int, n)
	components := 0
	redCount := 0

	for i := 0; i < h; i++ {
		row := in.Next()
		for j := 0; j < w; j++ {
			idx := i*w + j
			grid[idx] = row[j]
			if row[j] == '#' {
				parent[idx] = -1
				components++
			} else {
				redCount++
			}
		}
	}

	dsu := DSU{parent: parent}

	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			idx := i*w + j
			if grid[idx] != '#' {
				continue
			}
			if i > 0 {
				up := idx - w
				if grid[up] == '#' && dsu.Union(idx, up) {
					components--
				}
			}
			if j > 0 {
				left := idx - 1
				if grid[left] == '#' && dsu.Union(idx, left) {
					components--
				}
			}
		}
	}

	directions := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
	var total int64

	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			idx := i*w + j
			if grid[idx] != '.' {
				continue
			}

			var roots [4]int
			distinct := 0

			for _, d := range directions {
				ni, nj := i+d[0], j+d[1]
				if ni < 0 || ni >= h || nj < 0 || nj >= w {
					continue
				}
				next := ni*w + nj
				if grid[next] != '#' {
					continue
				}

				root := dsu.Find(next)
				found := false
				for k := 0; k < distinct; k++ {
					if roots[k] == root {
						found = true
						break
					}
				}
				if !found {
					roots[distinct] = root
					distinct++
				}
			}

			total += int64(components + 1 - distinct)
		}
	}

	answer := (total % mod) * modPow(int64(redCount), mod-2) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
