	}

	right[n-1] = min(a[n-1], 1)
	for i := n - 2; i >= 0; i-- {
		right[i] = min(a[i], right[i+1]+1)
	}

	var answer int64
	for i := 0; i < n; i++ {
		size := min(left[i], right[i])
		if size > answer {
			answer = size
		}
	}

	fmt.Fprintln(out, answer)
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
