	fmt.Fscan(in, &n, &k)

	a := make([]int64, k)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	const inf int64 = 1 << 60
	dp := make([][2]int64, k+1)
	for i := range dp {
		dp[i][0] = inf
		dp[i][1] = inf
	}
	dp[0][0] = 0

	for i := 0; i < k; i++ {
		for skipped := 0; skipped <= 1; skipped++ {
			if dp[i][skipped] == inf {
				continue
			}

			if skipped == 0 && dp[i][0] < dp[i+1][1] {
				dp[i+1][1] = dp[i][0]
			}

			if i+1 < k {
				cost := dp[i][skipped] + a[i+1] - a[i]
				if cost < dp[i+2][skipped] {
					dp[i+2][skipped] = cost
				}
			}
		}
	}

	fmt.Fprintln(out, dp[k][k%2])
}
