	var answer int64
	for servingsA := int64(0); servingsA <= maxA; servingsA++ {
		maxB := inf
		for i := 0; i < n; i++ {
			if b[i] > 0 {
				remaining := q[i] - servingsA*a[i]
				maxB = min(maxB, remaining/b[i])
			}
		}
		answer = max(answer, servingsA+maxB)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
