package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	x := make([]int, m)
	for i := range x {
		fmt.Fscan(in, &x[i])
	}

	diff := make([]int64, n+2)
	var base int64

	addRange := func(l, r int, value int64) {
		if l > r {
			return
		}
		diff[l] += value
		diff[r+1] -= value
	}

	for i := 0; i+1 < m; i++ {
		a, b := x[i], x[i+1]
		d := (b - a + n) % n
		base += int64(d)

		change := int64(n - 2*d)
		if a < b {
			addRange(a, b-1, change)
		} else {
			addRange(a, n, change)
			addRange(1, b-1, change)
		}
	}

	answer := int64(1<<63 - 1)
	var adjustment int64
	for edge := 1; edge <= n; edge++ {
		adjustment += diff[edge]
		total := base + adjustment
		if total < answer {
			answer = total
		}
	}

	fmt.Fprintln(out, answer)
}
