		l, r := x[i], x[i+1]
		if l > r {
			l, r = r, l
		}

		d := r - l
		base += int64(d)

		change := int64(n - 2*d)
		diff[l] += change
		diff[r] -= change
	}

	answer := int64(1<<62)
	var change int64
	for edge := 1; edge <= n; edge++ {
		change += diff[edge]
		cost := base + change
		if cost < answer {
			answer = cost
		}
	}

	fmt.Fprintln(out, answer)
}
