type Fenwick struct {
	n    int
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int64, n+1),
	}
}

func (f *Fenwick) Add(index int, value int64) {
	for i := index + 1; i <= f.n; i += i & -i {
		f.tree[i] += value
	}
}

func (f *Fenwick) PrefixSum(index int) int64 {
	var sum int64
	for i := index + 1; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

func (f *Fenwick) RangeAdd(left, right int, value int64) {
	if left > right {
		return
	}
	f.Add(left, value)
	if right+1 < f.n {
		f.Add(right+1, -value)
	}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	fw := NewFenwick(n)
	var previous int64
	for i := 0; i < n; i++ {
		var value int64
		fmt.Fscan(in, &value)
		fw.Add(i, value-previous)
		previous = value
	}

	for i := 0; i < m; i++ {
		var b int
		fmt.Fscan(in, &b)

		balls := fw.PrefixSum(b)
		fw.RangeAdd(b, b, -balls)

		fullRounds := balls / int64(n)
		remainder := int(balls % int64(n))

		if fullRounds > 0 {
			fw.RangeAdd(0, n-1, fullRounds)
		}

		if remainder > 0 {
			start := (b + 1) % n
			end := start + remainder - 1

			if end < n {
				fw.RangeAdd(start, end, 1)
			} else {
				fw.RangeAdd(start, n-1, 1)
				fw.RangeAdd(0, end%n, 1)
			}
		}
	}

	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, fw.PrefixSum(i))
	}
	fmt.Fprintln(out)
}
