	moves := make([][4]int, m)
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			pos := r*n + c
			for d := 0; d < 4; d++ {
				nr, nc := r+dr[d], c+dc[d]
				if nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != '#' {
					moves[pos][d] = nr*n + nc
				} else {
					moves[pos][d] = pos
				}
			}
		}
