		a, b = b, a
	}

	totalStates := m * m
	visited := make([]uint64, (totalStates+63)/64)

	startCode := a*m + b
	visited[startCode>>6] |= uint64(1) << uint(startCode&63)

	maxPairs := m * (m + 1) / 2
	queue := make([]int32, 1, maxPairs)
	queue[0] = int32(startCode)

	head := 0
	distance := 0

	for head < len(queue) {
		levelEnd := len(queue)

		for head < levelEnd {
			code := int(queue[head])
			head++

			p1 := code / m
			p2 := code % m

			for d := 0; d < 4; d++ {
				next1 := moves[p1][d]
				next2 := moves[p2][d]

				if next1 == next2 {
					fmt.Fprintln(out, distance+1)
					return
				}

				if next1 > next2 {
					next1, next2 = next2, next1
				}

				nextCode := next1*m + next2
				word := nextCode >> 6
				mask := uint64(1) << uint(nextCode&63)

				if visited[word]&mask == 0 {
					visited[word] |= mask
					queue = append(queue, int32(nextCode))
				}
			}
		}

		distance++
	}

	fmt.Fprintln(out, -1)
}
