package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Fenwick struct {
	n   int
	bit []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:   n,
		bit: make([]int64, n+1),
	}
}

func (f *Fenwick) Add(index int, value int64) {
	for i := index + 1; i <= f.n; i += i & -i {
		f.bit[i] += value
	}
}

func (f *Fenwick) RangeAdd(left, right int, value int64) {
	if left >= right {
		return
	}
	f.Add(left, value)
	if right < f.n {
		f.Add(right, -value)
	}
}

func (f *Fenwick) Get(index int) int64 {
	var result int64
	for i := index + 1; i > 0; i -= i & -i {
		result += f.bit[i]
	}
	return result
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())

	fenwick := NewFenwick(n)
	for i := 0; i < n; i++ {
		value := in.NextInt64()
		fenwick.RangeAdd(i, i+1, value)
	}

	operations := make([]int, m)
	for i := 0; i < m; i++ {
		operations[i] = int(in.NextInt64())
	}

	for _, box := range operations {
		balls := fenwick.Get(box)
		fenwick.RangeAdd(box, box+1, -balls)

		each := balls / int64(n)
		remaining := int(balls % int64(n))

		if each > 0 {
			fenwick.RangeAdd(0, n, each)
		}

		if remaining > 0 {
			start := (box + 1) % n
			end := start + remaining
			if end <= n {
				fenwick.RangeAdd(start, end, 1)
			} else {
				fenwick.RangeAdd(start, n, 1)
				fenwick.RangeAdd(0, end-n, 1)
			}
		}
	}

	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, fenwick.Get(i))
	}
	fmt.Fprintln(out)
}
