	fmt.Fscan(in, &n, &m, &k)

	lcm := n / gcd(n, m) * m

	count := func(x int64) int64 {
		return x/n + x/m - 2*(x/lcm)
	}

	minNM := n
	if m < minNM {
		minNM = m
	}

	low, high := int64(0), 2*k*minNM
	for high-low > 1 {
		mid := low + (high-low)/2
		if count(mid) >= k {
			high = mid
		} else {
			low = mid
		}
	}

	fmt.Fprintln(out, high)
}
