	sum := 0
	for index > 0 {
		sum += f.tree[index]
		index -= index & -index
	}
	return sum
}

func (f *Fenwick) RangeSum(left, right int) int {
	if left > right {
		return 0
	}
	return f.PrefixSum(right) - f.PrefixSum(left-1)
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()
	s := in.Next()

	// bad[i] is true when the i-th and (i+1)-th characters are equal.
	bad := make([]bool, n)
	fenwick := NewFenwick(n - 1)

	for i := 1; i < n; i++ {
		if s[i-1] == s[i] {
			bad[i] = true
			fenwick.Add(i, 1)
		}
	}

	toggleBoundary := func(index int) {
		if index < 1 || index >= n {
			return
		}
		if bad[index] {
			bad[index] = false
			fenwick.Add(index, -1)
		} else {
			bad[index] = true
			fenwick.Add(index, 1)
		}
	}

	for ; q > 0; q-- {
		queryType := in.NextInt()
		left := in.NextInt()
		right := in.NextInt()

		if queryType == 1 {
			toggleBoundary(left - 1)
			toggleBoundary(right)
		} else {
			if fenwick.RangeSum(left, right-1) == 0 {
				fmt.Fprintln(out, "Yes")
			} else {
				fmt.Fprintln(out, "No")
			}
		}
	}
}
