package main

import (
	"bufio"
	"fmt"
	"os"
)

type Fenwick struct {
	n   int
	bit []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:   n,
		bit: make([]int, n+1),
	}
}

func (f *Fenwick) Add(index, value int) {
	for index <= f.n {
		f.bit[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int {
	result := 0
	for index > 0 {
		result += f.bit[index]
		index -= index & -index
	}
	return result
}

func (f *Fenwick) RangeSum(left, right int) int {
	if left > right {
		return 0
	}
	return f.Sum(right) - f.Sum(left-1)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	var s string
	fmt.Fscan(in, &n, &q)
	fmt.Fscan(in, &s)

	fenwick := NewFenwick(n)
	bad := make([]bool, n)

	// Edge i represents the pair S[i] and S[i+1] in 1-based indexing.
	for i := 1; i < n; i++ {
		if s[i-1] == s[i] {
			bad[i] = true
			fenwick.Add(i, 1)
		}
	}

	toggleEdge := func(edge int) {
		if bad[edge] {
			bad[edge] = false
			fenwick.Add(edge, -1)
		} else {
			bad[edge] = true
			fenwick.Add(edge, 1)
		}
	}

	for ; q > 0; q-- {
		var queryType, l, r int
		fmt.Fscan(in, &queryType, &l, &r)

		if queryType == 1 {
			// Flipping [l, r] only changes equality at its boundary edges.
			if l > 1 {
				toggleEdge(l - 1)
			}
			if r < n {
				toggleEdge(r)
			}
		} else {
			if fenwick.RangeSum(l, r-1) == 0 {
				fmt.Fprintln(out, "Yes")
			} else {
				fmt.Fprintln(out, "No")
			}
		}
	}
}
