func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var H, W, N int
	var T string
	fmt.Fscan(in, &H, &W, &N)
	fmt.Fscan(in, &T)

	words := (W + 63) / 64
	land := make([]uint64, H*words)

	for r := 0; r < H; r++ {
		var s string
		fmt.Fscan(in, &s)
		for c := 0; c < W; c++ {
			if s[c] == '.' {
				land[r*words+c/64] |= uint64(1) << (c % 64)
			}
		}
	}

	cur := make([]uint64, len(land))
	copy(cur, land)
	next := make([]uint64, len(land))

	for _, move := range T {
		switch move {
		case 'L':
			for r := 0; r < H; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					v := cur[base+k] >> 1
					if k+1 < words {
						v |= cur[base+k+1] << 63
					}
					next[base+k] = v & land[base+k]
				}
			}
		case 'R':
			for r := 0; r < H; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					v := cur[base+k] << 1
					if k > 0 {
						v |= cur[base+k-1] >> 63
					}
					next[base+k] = v & land[base+k]
				}
			}
		case 'U':
			for r := 0; r < H; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					if r+1 < H {
						next[base+k] = cur[(r+1)*words+k] & land[base+k]
					} else {
						next[base+k] = 0
					}
				}
			}
		case 'D':
			for r := 0; r < H; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					if r > 0 {
						next[base+k] = cur[(r-1)*words+k] & land[base+k]
					} else {
						next[base+k] = 0
					}
				}
			}
		}
		cur, next = next, cur
	}

	answer := 0
	for _, v := range cur {
		answer += bits.OnesCount64(v)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
