	fmt.Fscan(in, &n)

	const maxA = 200000
	spf := make([]int, maxA+1)
	for i := 2; i <= maxA; i++ {
		if spf[i] == 0 {
			spf[i] = i
			if i <= maxA/i {
				for j := i * i; j <= maxA; j += i {
					if spf[j] == 0 {
						spf[j] = i
					}
				}
			}
		}
