	count := make([]int64, maxA+1)
	var answer, zeros, seen int64

	for i := 0; i < n; i++ {
		var x int
		fmt.Fscan(in, &x)

		if x == 0 {
			answer += seen
			zeros++
			seen++
			continue
		}

		kernel := 1
		value := x
		for value > 1 {
			p := spf[value]
			exponent := 0
			for value%p == 0 {
				value /= p
				exponent++
			}
			if exponent%2 == 1 {
				kernel *= p
			}
		}

		answer += zeros + count[kernel]
		count[kernel]++
		seen++
	}

	fmt.Fprintln(out, answer)
