package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	sign := int64(1)
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func (fs *FastScanner) NextInt() int {
	return int(fs.NextInt64())
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	graph := make([][]int, n)
	for i := 0; i < m; i++ {
		u := in.NextInt() - 1
		v := in.NextInt() - 1
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u)
	}

	weights := make([]int, n)
	for i := range weights {
		weights[i] = in.NextInt()
	}

	pieces := make([]int64, n)
	for i := range pieces {
		pieces[i] = in.NextInt64()
	}

	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		return weights[order[i]] < weights[order[j]]
	})

	value := make([]int64, n)

	for _, x := range order {
		capacity := weights[x] - 1
		dp := make([]int64, capacity+1)

		for _, y := range graph[x] {
			cost := weights[y]
			if cost >= weights[x] {
				continue
			}
			for c := capacity; c >= cost; c-- {
				candidate := dp[c-cost] + value[y]
				if candidate > dp[c] {
					dp[c] = candidate
				}
			}
		}

		value[x] = dp[capacity] + 1
	}

	var answer int64
	for i := 0; i < n; i++ {
		answer += pieces[i] * value[i]
	}

	fmt.Fprintln(out, answer)
}
