		dp := make([]int64, capacity+1)

		for _, u := range adj[v] {
			if weights[u] >= weights[v] {
				continue
			}

			itemWeight := weights[u]
			itemValue := value[u]
			for c := capacity; c >= itemWeight; c-- {
				candidate := dp[c-itemWeight] + itemValue
				if candidate > dp[c] {
					dp[c] = candidate
				}
			}
		}

		value[v] = dp[capacity] + 1
	}

	var answer int64
	for i := 0; i < n; i++ {
		answer += pieces[i] * value[i]
	}

	fmt.Fprintln(out, answer)
}
