package main

import (
	"bufio"
	"fmt"
	"io"
	"math/bits"
	"os"
)

const inf int64 = 1 << 60

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt64() int64 {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] == ' ' || fs.data[fs.pos] == '\n' || fs.data[fs.pos] == '\r' || fs.data[fs.pos] == '\t') {
		fs.pos++
	}

	sign := int64(1)
	if fs.data[fs.pos] == '-' {
		sign = -1
		fs.pos++
	}

	var value int64
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		value = value*10 + int64(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return value * sign
}

func main() {
	in := NewFastScanner()
	n := int(in.NextInt64())
	m := int(in.NextInt64())

	dist := make([]int64, n*n)
	for i := range dist {
		dist[i] = inf
	}
	for i := 0; i < n; i++ {
		dist[i*n+i] = 0
	}

	for i := 0; i < m; i++ {
		u := int(in.NextInt64()) - 1
		v := int(in.NextInt64()) - 1
		w := in.NextInt64()
		dist[u*n+v] = w
	}

	// All-pairs shortest paths.
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			dik := dist[i*n+k]
			if dik == inf {
				continue
			}
			for j := 0; j < n; j++ {
				dkj := dist[k*n+j]
				if dkj == inf {
					continue
				}
				if candidate := dik + dkj; candidate < dist[i*n+j] {
					dist[i*n+j] = candidate
				}
			}
		}
	}

	totalMasks := 1 << n
	dp := make([]int64, totalMasks*n)

	// dp[mask][v]: minimum cost of visiting all vertices in mask and ending at v.
	for mask := 1; mask < totalMasks; mask++ {
		base := mask * n
		for remaining := mask; remaining != 0; remaining &= remaining - 1 {
			v := bits.TrailingZeros(uint(remaining))
			previousMask := mask ^ (1 << v)

			if previousMask == 0 {
				dp[base+v] = 0
				continue
			}

			best := inf
			previousBase := previousMask * n
			for candidates := previousMask; candidates != 0; candidates &= candidates - 1 {
				u := bits.TrailingZeros(uint(candidates))
				if dp[previousBase+u] == inf || dist[u*n+v] == inf {
					continue
				}
				cost := dp[previousBase+u] + dist[u*n+v]
				if cost < best {
					best = cost
				}
			}
			dp[base+v] = best
		}
	}

	fullMask := totalMasks - 1
	answer := inf
	base := fullMask * n
	for v := 0; v < n; v++ {
		if dp[base+v] < answer {
			answer = dp[base+v]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if answer == inf {
		fmt.Fprintln(out, "No")
	} else {
		fmt.Fprintln(out, answer)
	}
}
