package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

type Edge struct {
	from    int
	first   int64
	interval int64
	count   int64
	duration int64
}

type Item struct {
	station int
	time    int64
}

type MaxHeap []Item

func (h MaxHeap) Len() int {
	return len(h)
}

func (h MaxHeap) Less(i, j int) bool {
	return h[i].time > h[j].time
}

func (h MaxHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Item))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())

	incoming := make([][]Edge, n)

	for i := 0; i < m; i++ {
		l := in.NextInt64()
		d := in.NextInt64()
		k := in.NextInt64()
		c := in.NextInt64()
		a := int(in.NextInt64()) - 1
		b := int(in.NextInt64()) - 1

		incoming[b] = append(incoming[b], Edge{
			from:     a,
			first:    l,
			interval: d,
			count:    k,
			duration: c,
		})
	}

	const inf int64 = 1<<63 - 1

	latest := make([]int64, n)
	for i := range latest {
		latest[i] = -1
	}
	latest[n-1] = inf

	pq := &MaxHeap{{station: n - 1, time: inf}}
	heap.Init(pq)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(Item)
		v := item.station
		if item.time != latest[v] {
			continue
		}

		for _, e := range incoming[v] {
			deadline := item.time - e.duration
			if deadline < e.first {
				continue
			}

			index := (deadline - e.first) / e.interval
			if index >= e.count {
				index = e.count - 1
			}

			departure := e.first + index*e.interval
			if departure > latest[e.from] {
				latest[e.from] = departure
				heap.Push(pq, Item{
					station: e.from,
					time:    departure,
				})
			}
		}
	}

	for i := 0; i < n-1; i++ {
		if latest[i] == -1 {
			fmt.Fprintln(out, "Unreachable")
		} else {
			fmt.Fprintln(out, latest[i])
		}
	}
}
