package main

import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	x, y, z int
	overlap int
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func overlapLength(a, b int) int {
	l := max(a, b)
	r := min(a+7, b+7)
	if r <= l {
		return 0
	}
	return r - l
}

func intersection2(a, b Point) int {
	return overlapLength(a.x, b.x) *
		overlapLength(a.y, b.y) *
		overlapLength(a.z, b.z)
}

func tripleLength(a, b int) int {
	l := max(0, max(a, b))
	r := min(7, min(a+7, b+7))
	if r <= l {
		return 0
	}
	return r - l
}

func intersection3(a, b Point) int {
	return tripleLength(a.x, b.x) *
		tripleLength(a.y, b.y) *
		tripleLength(a.z, b.z)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var v1, v2, v3 int
	fmt.Fscan(in, &v1, &v2, &v3)

	const cubeVolume = 343
	if v1+2*v2+3*v3 != 3*cubeVolume {
		fmt.Fprintln(out, "No")
		return
	}

	origin := Point{0, 0, 0, 0}
	points := make([]Point, 0, 15*15*15)

	for x := -7; x <= 7; x++ {
		for y := -7; y <= 7; y++ {
			for z := -7; z <= 7; z++ {
				p := Point{x: x, y: y, z: z}
				p.overlap = intersection2(origin, p)
				points = append(points, p)
			}
		}
	}

	targetPairSum := v2 + 3*v3

	for _, p2 := range points {
		for _, p3 := range points {
			pairSum := p2.overlap + p3.overlap + intersection2(p2, p3)
			if pairSum != targetPairSum {
				continue
			}
			if intersection3(p2, p3) != v3 {
				continue
			}

			fmt.Fprintln(out, "Yes")
			fmt.Fprintf(out, "0 0 0 %d %d %d %d %d %d\n",
				p2.x, p2.y, p2.z, p3.x, p3.y, p3.z)
			return
		}
	}

	fmt.Fprintln(out, "No")
}
