package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	next := make(map[int]int, n)
	prev := make(map[int]int, n)

	head := 0
	last := 0
	for i := 0; i < n; i++ {
		x := in.NextInt()
		if i == 0 {
			head = x
		} else {
			next[last] = x
			prev[x] = last
		}
		last = x
	}

	q := in.NextInt()
	for i := 0; i < q; i++ {
		queryType := in.NextInt()
		x := in.NextInt()

		if queryType == 1 {
			y := in.NextInt()
			nxt := next[x]

			next[x] = y
			prev[y] = x
			next[y] = nxt

			if nxt != 0 {
				prev[nxt] = y
			}
		} else {
			p := prev[x]
			nxt := next[x]

			if p == 0 {
				head = nxt
			} else {
				next[p] = nxt
			}
			if nxt != 0 {
				prev[nxt] = p
			}

			delete(next, x)
			delete(prev, x)
		}
	}

	first := true
	for current := head; current != 0; current = next[current] {
		if !first {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, current)
		first = false
	}
	fmt.Fprintln(out)
}
