package main

import (
	"bufio"
	"fmt"
	"os"
)

type Tile struct {
	h, w int
}

var (
	n, H, W int
	tiles   []Tile
	covered [10][10]bool
)

func dfs(used int, filled int) bool {
	if filled == H*W {
		return true
	}

	remainingArea := 0
	for i := 0; i < n; i++ {
		if used&(1<<i) == 0 {
			remainingArea += tiles[i].h * tiles[i].w
		}
	}
	if filled+remainingArea < H*W {
		return false
	}

	r, c := -1, -1
	for i := 0; i < H && r == -1; i++ {
		for j := 0; j < W; j++ {
			if !covered[i][j] {
				r, c = i, j
				break
			}
		}
	}

	for i := 0; i < n; i++ {
		if used&(1<<i) != 0 {
			continue
		}

		orientations := [][2]int{
			{tiles[i].h, tiles[i].w},
		}
		if tiles[i].h != tiles[i].w {
			orientations = append(orientations, [2]int{tiles[i].w, tiles[i].h})
		}

		for _, o := range orientations {
			th, tw := o[0], o[1]
			if r+th > H || c+tw > W {
				continue
			}

			canPlace := true
			for x := r; x < r+th && canPlace; x++ {
				for y := c; y < c+tw; y++ {
					if covered[x][y] {
						canPlace = false
						break
					}
				}
			}
			if !canPlace {
				continue
			}

			for x := r; x < r+th; x++ {
				for y := c; y < c+tw; y++ {
					covered[x][y] = true
				}
			}

			if dfs(used|(1<<i), filled+th*tw) {
				return true
			}

			for x := r; x < r+th; x++ {
				for y := c; y < c+tw; y++ {
					covered[x][y] = false
				}
			}
		}
	}

	return false
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &H, &W)

	tiles = make([]Tile, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &tiles[i].h, &tiles[i].w)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if dfs(0, 0) {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}
