		}
		if s[i] != expected1 {
			prefix1[i+1] += cost[i]
		}
	}

	const inf int64 = 1<<63 - 1
	answer := inf

	for split := 1; split < n; split++ {
		// The prefix follows alternating pattern 0, and the suffix
		// follows its complement.
		costA := prefix0[split] + (prefix1[n] - prefix1[split])

		// The prefix follows alternating pattern 1, and the suffix
		// follows its complement.
		costB := prefix1[split] + (prefix0[n] - prefix0[split])

		if costA < answer {
			answer = costA
		}
		if costB < answer {
			answer = costB
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
