		return low&(uint64(1)<<pos) != 0
	}
	return high&(uint64(1)<<(pos-64)) != 0
}

func remainingAreaPossible(used uint8, remaining int) bool {
	unused := make([]int, 0, n)
	for i := 0; i < n; i++ {
		if used&(1<<i) == 0 {
			unused = append(unused, tiles[i].area)
		}
	}

	for mask := 0; mask < (1 << len(unused)); mask++ {
		sum := 0
		for i, area := range unused {
			if mask&(1<<i) != 0 {
				sum += area
			}
		}
		if sum == remaining {
			return true
		}
	}
	return false
}

func dfs(low, high uint64, used uint8, covered int) bool {
	if low == fullLow && high == fullHigh {
		return true
	}

	state := State{low: low, high: high, used: used}
	if failed[state] {
		return false
	}

	remaining := h*w - covered
	if !remainingAreaPossible(used, remaining) {
		failed[state] = true
		return false
	}

	first := -1
	for pos := 0; pos < h*w; pos++ {
		if !isOccupied(low, high, pos) {
			first = pos
			break
		}
	}

	row, col := first/w, first%w

	for i, tile := range tiles {
		if used&(1<<i) != 0 {
			continue
		}

		orientations := [][2]int{{tile.a, tile.b}}
		if tile.a != tile.b {
			orientations = append(orientations, [2]int{tile.b, tile.a})
		}

		for _, size := range orientations {
			th, tw := size[0], size[1]
			if row+th > h || col+tw > w {
				continue
			}

			newLow, newHigh := low, high
			ok := true

			for r := row; r < row+th && ok; r++ {
				for c := col; c < col+tw; c++ {
					pos := r*w + c
					if isOccupied(newLow, newHigh, pos) {
						ok = false
						break
					}
					if pos < 64 {
						newLow |= uint64(1) << pos
					} else {
						newHigh |= uint64(1) << (pos - 64)
					}
				}
			}

			if ok && dfs(newLow, newHigh, used|(1<<i), covered+tile.area) {
				return true
			}
		}
	}

	failed[state] = true
	return false
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &h, &w)

	tiles = make([]Tile, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &tiles[i].a, &tiles[i].b)
		tiles[i].area = tiles[i].a * tiles[i].b
	}

	cells := h * w
	if cells >= 64 {
		fullLow = ^uint64(0)
		remaining := cells - 64
		if remaining == 64 {
			fullHigh = ^uint64(0)
		} else {
			fullHigh = (uint64(1) << remaining) - 1
		}
	} else {
		fullLow = (uint64(1) << cells) - 1
		fullHigh = 0
	}

	failed = make(map[State]bool)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if dfs(0, 0, 0, 0) {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}
