type interval struct {
	l, r uint64
}

func highestPowerOfTwoLE(x uint64) uint64 {
	return uint64(1) << (bits.Len64(x) - 1)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var L, R uint64
	fmt.Fscan(in, &L, &R)

	ans := make([]interval, 0, 120)

	for L < R {
		remaining := R - L
		var length uint64

		if L == 0 {
			length = highestPowerOfTwoLE(remaining)
		} else {
			length = L & (^L + 1) // Largest power of two dividing L.
			if length > remaining {
				length = highestPowerOfTwoLE(remaining)
			}
		}

		ans = append(ans, interval{L, L + length})
		L += length
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintln(out, len(ans))
	for _, p := range ans {
		fmt.Fprintln(out, p.l, p.r)
	}
}
