package main

import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	x, y, z int
	overlap int
}

func overlapLength(a, b int) int {
	d := a - b
	if d < 0 {
		d = -d
	}
	if d >= 7 {
		return 0
	}
	return 7 - d
}

func tripleLength(a, b int) int {
	minPos := 0
	if a < minPos {
		minPos = a
	}
	if b < minPos {
		minPos = b
	}

	maxPos := 0
	if a > maxPos {
		maxPos = a
	}
	if b > maxPos {
		maxPos = b
	}

	length := 7 + minPos - maxPos
	if length < 0 {
		return 0
	}
	return length
