	if v1+2*v2+3*v3 != 3*cubeVolume {
		fmt.Fprintln(out, "No")
		return
	}

	points := make([]Point, 0, 15*15*15)
	for x := -7; x <= 7; x++ {
		for y := -7; y <= 7; y++ {
			for z := -7; z <= 7; z++ {
				o := overlapLength(0, x) *
					overlapLength(0, y) *
					overlapLength(0, z)
				points = append(points, Point{x, y, z, o})
			}
		}
	}

	targetPairSum := v2 + 3*v3

	for _, p2 := range points {
		for _, p3 := range points {
			needed := targetPairSum - p2.overlap - p3.overlap
			if needed < 0 || needed > cubeVolume {
				continue
			}

			overlap23 := overlapLength(p2.x, p3.x) *
				overlapLength(p2.y, p3.y) *
				overlapLength(p2.z, p3.z)
			if overlap23 != needed {
