			}

			triple := tripleLength(p2.x, p3.x) *
				tripleLength(p2.y, p3.y) *
				tripleLength(p2.z, p3.z)
			if triple != v3 {
				continue
			}

			fmt.Fprintln(out, "Yes")
			fmt.Fprintf(out, "0 0 0 %d %d %d %d %d %d\n",
				p2.x, p2.y, p2.z, p3.x, p3.y, p3.z)
			return
		}
	}

	fmt.Fprintln(out, "No")
