func main() {
	in := bufio.NewReader(os.Stdin)

	var values [9]int64
	for i := 0; i < 9; i++ {
		fmt.Fscan(in, &values[i])
	}

	winLines := []int{
		0b000000111,
		0b000111000,
		0b111000000,
		0b001001001,
		0b010010010,
		0b100100100,
		0b100010001,
		0b001010100,
	}

	hasLine := func(mask int) bool {
		for _, line := range winLines {
			if mask&line == line {
				return true
			}
		}
		return false
	}

	memo := make([]int8, 512*512)

	var dfs func(int, int) bool
	dfs = func(tMask, aMask int) bool {
		index := tMask*512 + aMask
		if memo[index] != 0 {
			return memo[index] == 1
		}

		if hasLine(tMask) {
			memo[index] = 1
			return true
		}
		if hasLine(aMask) {
			memo[index] = -1
			return false
		}

		used := tMask | aMask
		if used == 0b111111111 {
			var takahashiScore, aokiScore int64
			for i := 0; i < 9; i++ {
				bit := 1 << i
				if tMask&bit != 0 {
					takahashiScore += values[i]
				} else {
					aokiScore += values[i]
				}
			}

			if takahashiScore > aokiScore {
				memo[index] = 1
				return true
			}
			memo[index] = -1
			return false
		}

		movesPlayed := 0
		for x := used; x != 0; x &= x - 1 {
			movesPlayed++
		}

		if movesPlayed%2 == 0 {
			for i := 0; i < 9; i++ {
				bit := 1 << i
				if used&bit == 0 && dfs(tMask|bit, aMask) {
					memo[index] = 1
					return true
				}
			}
			memo[index] = -1
			return false
		}

		for i := 0; i < 9; i++ {
			bit := 1 << i
			if used&bit == 0 && !dfs(tMask, aMask|bit) {
				memo[index] = -1
				return false
			}
		}
		memo[index] = 1
		return true
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if dfs(0, 0) {
		fmt.Fprintln(out, "Takahashi")
	} else {
		fmt.Fprintln(out, "Aoki")
	}
}
