package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type State struct {
	pos    int
	energy int
}

type MaxHeap []State

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i].energy > h[j].energy }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(State))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var h, w int
	fmt.Fscan(in, &h, &w)

	grid := make([]string, h)
	start, goal := -1, -1

	for r := 0; r < h; r++ {
		fmt.Fscan(in, &grid[r])
		for c := 0; c < w; c++ {
			switch grid[r][c] {
			case 'S':
				start = r*w + c
			case 'T':
				goal = r*w + c
			}
		}
	}

	medicine := make([]int, h*w)
	var n int
	fmt.Fscan(in, &n)
	for i := 0; i < n; i++ {
		var r, c, e int
		fmt.Fscan(in, &r, &c, &e)
		r--
		c--
		medicine[r*w+c] = e
	}

	best := make([]int, h*w)
	for i := range best {
		best[i] = -1
	}

	initialEnergy := medicine[start]
	best[start] = initialEnergy

	pq := &MaxHeap{}
	heap.Init(pq)
	heap.Push(pq, State{pos: start, energy: initialEnergy})

	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(State)
		if cur.energy != best[cur.pos] {
			continue
		}
		if cur.pos == goal {
			fmt.Fprintln(out, "Yes")
			return
		}
		if cur.energy == 0 {
			continue
		}

		r, c := cur.pos/w, cur.pos%w
		for d := 0; d < 4; d++ {
			nr, nc := r+dr[d], c+dc[d]
			if nr < 0 || nr >= h || nc < 0 || nc >= w {
				continue
			}
			if grid[nr][nc] == '#' {
				continue
			}

			nextPos := nr*w + nc
			nextEnergy := cur.energy - 1
			if medicine[nextPos] > nextEnergy {
				nextEnergy = medicine[nextPos]
			}

			if nextEnergy > best[nextPos] {
				best[nextPos] = nextEnergy
				heap.Push(pq, State{pos: nextPos, energy: nextEnergy})
			}
		}
	}

	fmt.Fprintln(out, "No")
}
