	if used == (1<<9)-1 {
		var redScore, blueScore int64
		for i := 0; i < 9; i++ {
			if red&(1<<i) != 0 {
				redScore += values[i]
			} else {
				blueScore += values[i]
			}
		}
		if redScore > blueScore {
			memo[key] = 1
			return true
		}
		memo[key] = -1
		return false
	}

	takahashiTurn := bits.OnesCount(uint(used))%2 == 0

	if takahashiTurn {
		for i := 0; i < 9; i++ {
