		diceCost := 6 * y
		for b := int64(2); b <= 6; b++ {
			diceCost += solve(v / b)
		}
		diceCost /= 5

		result := math.Min(fixedCost, diceCost)
		memo[v] = result
		return result
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintf(out, "%.15f\n", solve(n))
