type Fenwick struct {
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int64, n+1)}
}

func (f *Fenwick) Add(index int, value int64) {
	for index < len(f.tree) {
		f.tree[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int64 {
	var result int64
	for index > 0 {
		result += f.tree[index]
		index -= index & -index
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

