	values := make([]int, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
		values[i] = a[i]
	}

	sort.Ints(values)
	unique := values[:0]
	for _, v := range values {
		if len(unique) == 0 || unique[len(unique)-1] != v {
			unique = append(unique, v)
		}
	}

	countTree := NewFenwick(len(unique))
	sumTree := NewFenwick(len(unique))

	var answer int64
	for _, value := range a {
		rank := sort.SearchInts(unique, value) + 1

		countLess := countTree.Sum(rank - 1)
		sumLess := sumTree.Sum(rank - 1)
		answer += int64(value)*countLess - sumLess

		countTree.Add(rank, 1)
		sumTree.Add(rank, int64(value))
	}

	fmt.Fprintln(out, answer)
