		for j := 0; j < k; j++ {
			vertices[j] = int(in.NextInt64()) - 1
		}
		operations[i] = Operation{c: c, vertices: vertices}
	}

	sort.Slice(operations, func(i, j int) bool {
		return operations[i].c < operations[j].c
	})

	dsu := NewDSU(n)
