	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, k int
	fmt.Fscan(in, &n, &k)

	pos := make([]int, n+1)
	for i := 1; i <= n; i++ {
		var value int
		fmt.Fscan(in, &value)
		pos[value] = i
	}

	minDeque := make([]int, n)
	maxDeque := make([]int, n)
	minHead, minTail := 0, 0
	maxHead, maxTail := 0, 0
	answer := n

	for value := 1; value <= n; value++ {
		for minHead < minTail && pos[minDeque[minTail-1]] >= pos[value] {
			minTail--
		}
		minDeque[minTail] = value
		minTail++

		for maxHead < maxTail && pos[maxDeque[maxTail-1]] <= pos[value] {
			maxTail--
		}
		maxDeque[maxTail] = value
		maxTail++

		left := value - k + 1
		if left < 1 {
			continue
		}

		for minHead < minTail && minDeque[minHead] < left {
			minHead++
		}
		for maxHead < maxTail && maxDeque[maxHead] < left {
			maxHead++
		}

		span := pos[maxDeque[maxHead]] - pos[minDeque[minHead]]
		if span < answer {
			answer = span
		}
	}

	fmt.Fprintln(out, answer)
}
