	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	var prefixSum, answer int64

	for j := 0; j < n; j++ {
		var a int64
		fmt.Fscan(in, &a)

		if j > 0 {
			pow10 := int64(10)
			for x := a; x >= 10; x /= 10 {
				pow10 = pow10 * 10 % mod
			}

			contribution := (prefixSum*pow10 + int64(j)*(a%mod)) % mod
			answer = (answer + contribution) % mod
		}

		prefixSum = (prefixSum + a) % mod
	}

	fmt.Fprintln(out, answer)
}
