package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

func nextToken(data []byte, pos *int) []byte {
	for *pos < len(data) && data[*pos] <= ' ' {
		*pos++
	}
	start := *pos
	for *pos < len(data) && data[*pos] > ' ' {
		*pos++
	}
	return data[start:*pos]
}

func parseInt(token []byte) int {
	n := 0
	for _, c := range token {
		n = n*10 + int(c-'0')
	}
	return n
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	pos := 0

	h := parseInt(nextToken(data, &pos))
	w := parseInt(nextToken(data, &pos))
	n := h * w

	grid := make([]byte, n)
	for r := 0; r < h; r++ {
		row := nextToken(data, &pos)
		copy(grid[r*w:(r+1)*w], row)
	}

	// danger[i] is true if cell i is adjacent to at least one magnet.
	danger := make([]bool, n)
	for r := 0; r < h; r++ {
		for c := 0; c < w; c++ {
			idx := r*w + c
			if grid[idx] != '#' {
				continue
			}
			if r > 0 {
				danger[idx-w] = true
			}
			if r+1 < h {
				danger[idx+w] = true
			}
			if c > 0 {
				danger[idx-1] = true
			}
			if c+1 < w {
				danger[idx+1] = true
			}
		}
	}

	visited := make([]bool, n)
	boundaryMark := make([]int32, n)
	var componentID int32
	queue := make([]int, 0, 1024)
	answer := 1

	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for start := 0; start < n; start++ {
		if grid[start] == '#' || danger[start] || visited[start] {
			continue
		}

		componentID++
		queue = queue[:0]
		queue = append(queue, start)
		visited[start] = true
		reachable := 0

		for head := 0; head < len(queue); head++ {
			cur := queue[head]
			reachable++

			r := cur / w
			c := cur - r*w

			for d := 0; d < 4; d++ {
				nr, nc := r+dr[d], c+dc[d]
				if nr < 0 || nr >= h || nc < 0 || nc >= w {
					continue
				}

				next := nr*w + nc
				if grid[next] == '#' {
					continue
				}

				if danger[next] {
					if boundaryMark[next] != componentID {
						boundaryMark[next] = componentID
						reachable++
					}
				} else if !visited[next] {
					visited[next] = true
					queue = append(queue, next)
				}
			}
		}

		if reachable > answer {
			answer = reachable
		}
	}

	out := bufio.NewWriter(os.Stdout)
	out.WriteString(strconv.Itoa(answer))
	out.WriteByte('\n')
	out.Flush()
}
