package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) nextToken() []byte {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func (fs *FastScanner) nextInt() int {
	token := fs.nextToken()
	n := 0
	for _, c := range token {
		n = n*10 + int(c-'0')
	}
	return n
}

func main() {
	in := NewFastScanner()
	h := in.nextInt()
	w := in.nextInt()

	stride := w + 2
	total := (h + 2) * stride

	// 0: safe empty cell
	// 1: magnet
	// 2: empty cell adjacent to a magnet
	// 3: visited safe cell
	// 4: outside wall
	state := make([]byte, total)

	for c := 0; c < stride; c++ {
		state[c] = 4
		state[(h+1)*stride+c] = 4
	}
	for r := 0; r < h+2; r++ {
		state[r*stride] = 4
		state[r*stride+w+1] = 4
	}

	for r := 1; r <= h; r++ {
		row := in.nextToken()
		for c := 1; c <= w; c++ {
			if row[c-1] == '#' {
				state[r*stride+c] = 1
			}
		}
	}

	dirs := [4]int{-stride, stride, -1, 1}

	for r := 1; r <= h; r++ {
		for c := 1; c <= w; c++ {
			p := r*stride + c
			if state[p] != 1 {
				continue
			}
			for _, d := range dirs {
				np := p + d
				if state[np] == 0 {
					state[np] = 2
				}
			}
		}
	}

	boundaryStamp := make([]int32, total)
	var componentID int32
	queue := make([]int, 0)
	answer := 1

	for r := 1; r <= h; r++ {
		for c := 1; c <= w; c++ {
			start := r*stride + c
			if state[start] != 0 {
				continue
			}

			componentID++
			queue = queue[:0]
			queue = append(queue, start)
			state[start] = 3

			safeCount := 0
			boundaryCount := 0

			for head := 0; head < len(queue); head++ {
				p := queue[head]
				safeCount++

				for _, d := range dirs {
					np := p + d
					switch state[np] {
					case 0:
						state[np] = 3
						queue = append(queue, np)
					case 2:
						if boundaryStamp[np] != componentID {
							boundaryStamp[np] = componentID
							boundaryCount++
						}
					}
				}
			}

			reachable := safeCount + boundaryCount
			if reachable > answer {
				answer = reachable
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
