type Node struct {
	next  [26]int32
	count int32
}

func nextToken(r *bufio.Reader) string {
	buf := make([]byte, 0, 32)
	for {
		b, err := r.ReadByte()
		if err != nil {
			return string(buf)
		}
		if b > ' ' {
			buf = append(buf, b)
			break
		}
	}
	for {
		b, err := r.ReadByte()
		if err != nil || b <= ' ' {
			return string(buf)
		}
		buf = append(buf, b)
	}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Sscan(nextToken(in), &n)

	nodes := make([]Node, 1, 300001)
	var answer int64

	for i := 0; i < n; i++ {
		s := nextToken(in)
		current := int32(0)

		for j := 0; j < len(s); j++ {
			c := s[j] - 'a'
			child := nodes[current].next[c]

			if child == 0 {
				child = int32(len(nodes))
				nodes[current].next[c] = child
				nodes = append(nodes, Node{})
			}

			current = child
			answer += int64(nodes[current].count)
			nodes[current].count++
		}
	}

	fmt.Fprintln(out, answer)
}
