	size := 1 << n
	win := make([]bool, size)

	for mask := 1; mask < size; mask++ {
		for _, p := range pairs {
			bits := (1 << p.i) | (1 << p.j)
			if mask&bits == bits && !win[mask^bits] {
				win[mask] = true
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if win[size-1] {
		fmt.Fprintln(out, "Takahashi")
	} else {
		fmt.Fprintln(out, "Aoki")
