var pattern = [2][4]int64{
	{2, 1, 0, 1},
	{1, 2, 1, 0},
}

func prefix(x, y int64) int64 {
	var sum int64
	for j := int64(0); j < 2; j++ {
		countY := y / 2
		if j < y%2 {
			countY++
		}
		for i := int64(0); i < 4; i++ {
			countX := x / 4
			if i < x%4 {
				countX++
			}
			sum += countX * countY * pattern[j][i]
		}
	}
	return sum
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var a, b, c, d int64
	fmt.Fscan(in, &a, &b, &c, &d)

	const shift int64 = 1_000_000_000
	a += shift
	b += shift
	c += shift
	d += shift

	answer := prefix(c, d) - prefix(a, d) - prefix(c, b) + prefix(a, b)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
