type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	const limit = 1_000_000

	freq := make([]int64, limit+1)
	maxA := 0
	for i := 0; i < n; i++ {
		a := in.NextInt()
		freq[a]++
		if a > maxA {
			maxA = a
		}
	}

	prefix := make([]int64, maxA+1)
	for value := 1; value <= maxA; value++ {
		prefix[value] = prefix[value-1] + freq[value]
	}

	var answer int64

	for x := 1; x <= maxA; x++ {
		if freq[x] == 0 {
			continue
		}

		// Pairs whose two values are both x contribute 1 each.
		answer += freq[x] * (freq[x] - 1) / 2

		// Count pairs where x is the smaller value.
		for left, quotient := x; left <= maxA; left, quotient = left+x, quotient+1 {
			lo := left
			if lo <= x {
				lo = x + 1
			}
			if lo > maxA {
				continue
			}

			hi := left + x - 1
			if hi > maxA {
				hi = maxA
			}

			count := prefix[hi] - prefix[lo-1]
			answer += freq[x] * count * int64(quotient)
		}
	}

	fmt.Fprintln(out, answer)
}
