	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	next := make([]int, n)
	indegree := make([]int, n)

	for i := 0; i < n; i++ {
		next[i] = in.NextInt() - 1
		indegree[next[i]]++
	}

	queue := make([]int, 0, n)
	for i := 0; i < n; i++ {
		if indegree[i] == 0 {
			queue = append(queue, i)
		}
	}

	order := make([]int, 0, n)
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		order = append(order, u)
		v := next[u]
		indegree[v]--
		if indegree[v] == 0 {
			queue = append(queue, v)
		}
	}

	reachable := make([]int64, n)
	visited := make([]bool, n)

	for i := 0; i < n; i++ {
		if indegree[i] > 0 && !visited[i] {
			cycle := make([]int, 0)
			u := i
			for !visited[u] {
				visited[u] = true
				cycle = append(cycle, u)
				u = next[u]
			}

			cycleSize := int64(len(cycle))
			for _, v := range cycle {
				reachable[v] = cycleSize
			}
		}
	}

	for i := len(order) - 1; i >= 0; i-- {
		u := order[i]
		reachable[u] = reachable[next[u]] + 1
	}

	var answer int64
	for _, count := range reachable {
		answer += count
	}

	fmt.Fprintln(out, answer)
}
