package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)

	var N, L, R int
	if _, err := fmt.Fscan(in, &N, &L, &R); err != nil {
		return
	}

	size := 1 << N
	start, goal := L, R+1

	parent := make([]int, size+1)
	for i := range parent {
		parent[i] = -1
	}
	parent[start] = start

	queue := make([]int, 0, size+1)
	queue = append(queue, start)

	for head := 0; head < len(queue) && parent[goal] == -1; head++ {
		x := queue[head]

		for i := 0; i <= N; i++ {
			d := 1 << i
			if x%d != 0 {
				continue
			}

			if y := x - d; y >= 0 && parent[y] == -1 {
				parent[y] = x
				queue = append(queue, y)
			}
			if y := x + d; y <= size && parent[y] == -1 {
				parent[y] = x
				queue = append(queue, y)
			}
		}
	}

	path := make([]int, 0)
	for cur := goal; ; cur = parent[cur] {
		path = append(path, cur)
		if cur == start {
			break
		}
	}
	for left, right := 0, len(path)-1; left < right; left, right = left+1, right-1 {
		path[left], path[right] = path[right], path[left]
	}

	answer := 0
	for k := 0; k+1 < len(path); k++ {
		u, v := path[k], path[k+1]
		diff := u - v
		if diff < 0 {
			diff = -diff
		}

		i := bits.TrailingZeros(uint(diff))
		left := u
		if v < left {
			left = v
		}
		j := left / diff

		fmt.Fprintf(out, "? %d %d\n", i, j)
		out.Flush()

