package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const mod uint64 = 998244353

type geom struct {
	pow uint64 // q^length
	sum uint64 // 1 + q + ... + q^(length-1)
}

func combine(a, b geom) geom {
	return geom{
		pow: a.pow * b.pow % mod,
		sum: (a.sum + a.pow*b.sum%mod) % mod,
	}
}

func modPow(base, exp uint64) uint64 {
	result := uint64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	fmt.Fscan(in, &s)

	n, _ := strconv.ParseUint(s, 10, 64)
	q := modPow(10, uint64(len(s)))

	result := geom{pow: 1, sum: 0}
	current := geom{pow: q, sum: 1}

	count := n
	for count > 0 {
		if count&1 == 1 {
			result = combine(result, current)
		}
		current = combine(current, current)
		count >>= 1
	}

	answer := (n % mod) * result.sum % mod
	fmt.Fprintln(out, answer)
}
