package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, l, r int
	if _, err := fmt.Fscan(in, &n, &l, &r); err != nil {
		return
	}

	size := 1 << n
	start, goal := l, r+1

	prev := make([]int, size+1)
	for i := range prev {
		prev[i] = -2
	}
	prev[start] = -1

	queue := make([]int, 0, size+1)
	queue = append(queue, start)

	for head := 0; head < len(queue) && prev[goal] == -2; head++ {
		x := queue[head]

		for i := 0; i <= n; i++ {
			step := 1 << i
			if x%step != 0 {
				break
			}

			if x-step >= 0 && prev[x-step] == -2 {
				prev[x-step] = x
				queue = append(queue, x-step)
			}
			if x+step <= size && prev[x+step] == -2 {
				prev[x+step] = x
				queue = append(queue, x+step)
			}
		}
	}

	path := make([]int, 0)
	for x := goal; x != -1; x = prev[x] {
		path = append(path, x)
	}
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}

	answer := 0
	for k := 0; k+1 < len(path); k++ {
		u, v := path[k], path[k+1]
		lo, diff := u, v-u
		sign := 1

		if diff < 0 {
			lo = v
			diff = -diff
			sign = -1
		}

		i := 0
		for (1 << i) < diff {
			i++
		}
		j := lo / diff

		fmt.Fprintf(out, "? %d %d\n", i, j)
		out.Flush()

		var t int
		if _, err := fmt.Fscan(in, &t); err != nil || t == -1 {
			return
		}
		answer += sign * t
	}

	answer %= 100
	if answer < 0 {
		answer += 100
	}

	fmt.Fprintf(out, "! %d\n", answer)
	out.Flush()
}
