package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var K int
	fmt.Fscan(in, &K)

	counts := make([]int, 26)
	for i := range counts {
		fmt.Fscan(in, &counts[i])
		if counts[i] > K {
			counts[i] = K
		}
	}

	fact := make([]int64, K+1)
	invFact := make([]int64, K+1)
	fact[0] = 1
	for i := 1; i <= K; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	invFact[K] = modPow(fact[K], mod-2)
	for i := K; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	dp := make([]int64, K+1)
	dp[0] = 1
	currentMax := 0

	for _, limit := range counts {
		next := make([]int64, K+1)
		for used := 0; used <= currentMax; used++ {
			if dp[used] == 0 {
				continue
			}
			maxAdd := limit
			if maxAdd > K-used {
				maxAdd = K - used
			}
			for add := 0; add <= maxAdd; add++ {
				value := dp[used] * invFact[add] % mod
				next[used+add] += value
				if next[used+add] >= mod {
					next[used+add] -= mod
				}
			}
		}
		currentMax += limit
		if currentMax > K {
			currentMax = K
		}
		dp = next
	}

	var answer int64
	for length := 1; length <= K; length++ {
		answer = (answer + dp[length]*fact[length]) % mod
	}

	fmt.Fprintln(out, answer)
}
