package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod = 998244353

func isPalindrome(mask, length int) bool {
	for i := 0; i < length/2; i++ {
		if ((mask >> i) & 1) != ((mask >> (length - 1 - i)) & 1) {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	var s string
	fmt.Fscan(in, &n, &k)
	fmt.Fscan(in, &s)

	stateCount := 1 << (k - 1)
	stateMask := stateCount - 1

	dp := make([]int, stateCount)
	dp[0] = 1

	for i := 0; i < n; i++ {
		next := make([]int, stateCount)

		for mask, count := range dp {
			if count == 0 {
				continue
			}

			for bit := 0; bit < 2; bit++ {
				if s[i] == 'A' && bit != 0 {
					continue
				}
				if s[i] == 'B' && bit != 1 {
					continue
				}

				combined := (mask << 1) | bit
				if i+1 >= k && isPalindrome(combined, k) {
					continue
				}

				newMask := combined & stateMask
				next[newMask] += count
				if next[newMask] >= mod {
					next[newMask] -= mod
				}
			}
		}

		dp = next
	}

	answer := 0
	for _, count := range dp {
		answer += count
		if answer >= mod {
			answer -= mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
