	"fmt"
	"os"
)

const mod = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	var s string
	fmt.Fscan(in, &n, &k)
	fmt.Fscan(in, &s)

	stateCount := 1 << (k - 1)
	stateMask := stateCount - 1

	palindrome := make([]bool, 1<<k)
	for mask := 0; mask < (1 << k); mask++ {
		ok := true
		for left, right := 0, k-1; left < right; left, right = left+1, right-1 {
			if ((mask >> left) & 1) != ((mask >> right) & 1) {
				ok = false
				break
			}
		}
		palindrome[mask] = ok
	}

	dp := make([]int, stateCount)
	dp[0] = 1

	for i := 0; i < n; i++ {
		next := make([]int, stateCount)

		for state, count := range dp {
			if count == 0 {
				continue
			}

			for bit := 0; bit <= 1; bit++ {
				if s[i] == 'A' && bit != 0 {
					continue
				}
				if s[i] == 'B' && bit != 1 {
					continue
				}

				fullMask := (state << 1) | bit
				if i >= k-1 && palindrome[fullMask] {
					continue
				}

				nextState := fullMask & stateMask
				next[nextState] += count
				if next[nextState] >= mod {
					next[nextState] -= mod
				}
			}
		}

		dp = next
	}

	answer := 0
	for _, count := range dp {
		answer += count
		if answer >= mod {
			answer -= mod
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
