package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var k int
	fmt.Fscan(in, &k)

	counts := make([]int, 26)
	for i := range counts {
		fmt.Fscan(in, &counts[i])
		if counts[i] > k {
			counts[i] = k
		}
	}

	fact := make([]int64, k+1)
	invFact := make([]int64, k+1)
	fact[0] = 1
	for i := 1; i <= k; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	invFact[k] = modPow(fact[k], mod-2)
	for i := k; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	dp := make([]int64, k+1)
	dp[0] = 1
	maxLen := 0

	for _, c := range counts {
		next := make([]int64, k+1)
		for used := 0; used <= maxLen; used++ {
			if dp[used] == 0 {
				continue
			}
			limit := c
			if limit > k-used {
				limit = k - used
			}
			for add := 0; add <= limit; add++ {
				value := dp[used] * invFact[add] % mod
				next[used+add] += value
				if next[used+add] >= mod {
					next[used+add] -= mod
				}
			}
		}
		maxLen += c
		if maxLen > k {
			maxLen = k
		}
		dp = next
	}

	var answer int64
	for length := 1; length <= k; length++ {
		answer += dp[length] * fact[length] % mod
		if answer >= mod {
			answer -= mod
		}
	}

	fmt.Fprintln(out, answer)
}
