type State struct {
	config string
	hole   int
	dist   int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s, t string
	fmt.Fscan(in, &n, &s, &t)

	start := s + ".."
	target := t + ".."

	queue := make([]State, 0)
	queue = append(queue, State{config: start, hole: n, dist: 0})

	visited := make(map[string]bool)
	visited[start] = true

	answer := -1
	for head := 0; head < len(queue); head++ {
		cur := queue[head]
		if cur.config == target {
			answer = cur.dist
			break
		}

		for x := 0; x <= n; x++ {
			if cur.config[x] == '.' || cur.config[x+1] == '.' {
				continue
			}

			next := []byte(cur.config)
			next[cur.hole] = next[x]
			next[cur.hole+1] = next[x+1]
			next[x] = '.'
			next[x+1] = '.'

			nextConfig := string(next)
			if !visited[nextConfig] {
				visited[nextConfig] = true
				queue = append(queue, State{
					config: nextConfig,
					hole:   x,
					dist:   cur.dist + 1,
				})
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
