	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	var s, t string
	fmt.Fscan(in, &n, &s, &t)

	start := s + ".."
	target := t + ".."

	if start == target {
		fmt.Fprintln(out, 0)
		return
	}

	dist := map[string]int{start: 0}
	queue := make([]string, 1, 65536)
	queue[0] = start

	for head := 0; head < len(queue); head++ {
		current := queue[head]
		d := dist[current]

		empty := 0
		for current[empty] != '.' {
			empty++
		}

		for x := 0; x <= n; x++ {
			if current[x] == '.' || current[x+1] == '.' {
				continue
			}

			nextBytes := []byte(current)
			nextBytes[empty] = current[x]
			nextBytes[empty+1] = current[x+1]
			nextBytes[x] = '.'
			nextBytes[x+1] = '.'
			next := string(nextBytes)

			if _, visited := dist[next]; visited {
				continue
			}

			if next == target {
				fmt.Fprintln(out, d+1)
				return
			}

			dist[next] = d + 1
			queue = append(queue, next)
		}
	}

	fmt.Fprintln(out, -1)
}
