	dy := a.y - b.y
	return dx*dx + dy*dy
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var a, b, c Point
	fmt.Fscan(in, &a.x, &a.y)
	fmt.Fscan(in, &b.x, &b.y)
	fmt.Fscan(in, &c.x, &c.y)

	sides := []int64{
		squaredDistance(a, b),
		squaredDistance(b, c),
		squaredDistance(c, a),
	}

	if sides[0]+sides[1] == sides[2] ||
		sides[1]+sides[2] == sides[0] ||
		sides[2]+sides[0] == sides[1] {
