package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	values := make([]int64, 0, n)
	counts := make([]int64, 0, n)

	var sum int64
	for i := 0; i < n; i++ {
		h := in.NextInt64()
		count := int64(1)

		for len(values) > 0 && values[len(values)-1] <= h {
			last := len(values) - 1
			sum -= values[last] * counts[last]
			count += counts[last]
			values = values[:last]
			counts = counts[:last]
		}

		values = append(values, h)
		counts = append(counts, count)
		sum += h * count

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, sum+1)
	}
	fmt.Fprintln(out)
}
