package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Edge struct {
	to     int
	weight int64
}

type Item struct {
	vertex int
	dist   int64
}

type PriorityQueue []Item

func (pq PriorityQueue) Len() int {
	return len(pq)
}

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].dist < pq[j].dist
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}

func (pq *PriorityQueue) Push(x any) {
	*pq = append(*pq, x.(Item))
}

func (pq *PriorityQueue) Pop() any {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	vertexWeight := make([]int64, n)
	for i := range vertexWeight {
		fmt.Fscan(in, &vertexWeight[i])
	}

	graph := make([][]Edge, n)
	for i := 0; i < m; i++ {
		var u, v int
		var b int64
		fmt.Fscan(in, &u, &v, &b)
		u--
		v--
		graph[u] = append(graph[u], Edge{to: v, weight: b})
		graph[v] = append(graph[v], Edge{to: u, weight: b})
	}

	const inf int64 = 1 << 62
	dist := make([]int64, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[0] = vertexWeight[0]

	pq := &PriorityQueue{{vertex: 0, dist: dist[0]}}
	heap.Init(pq)

	for pq.Len() > 0 {
		current := heap.Pop(pq).(Item)
		if current.dist != dist[current.vertex] {
			continue
		}

		for _, edge := range graph[current.vertex] {
			nextDist := current.dist + edge.weight + vertexWeight[edge.to]
			if nextDist < dist[edge.to] {
				dist[edge.to] = nextDist
				heap.Push(pq, Item{vertex: edge.to, dist: nextDist})
			}
		}
	}

	for i := 1; i < n; i++ {
		if i > 1 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, dist[i])
	}
	fmt.Fprintln(out)
}
