func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	var s string
	fmt.Fscan(in, &n, &k)
	fmt.Fscan(in, &s)

	counts := make([]int, 26)
	for _, ch := range s {
		counts[ch-'a']++
	}

	current := make([]byte, n)
	var answer int64

	var dfs func(int)
	dfs = func(pos int) {
		if pos == n {
			answer++
			return
		}

		for c := 0; c < 26; c++ {
			if counts[c] == 0 {
				continue
			}

			current[pos] = byte(c)
			counts[c]--

			valid := true
			if pos+1 >= k {
				left, right := pos-k+1, pos
				for left < right {
					if current[left] != current[right] {
						break
					}
					left++
					right--
				}
				if left >= right {
					valid = false
				}
			}

			if valid {
				dfs(pos + 1)
			}
			counts[c]++
		}
	}

	dfs(0)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
