package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	// dp[i][d][length] is the number of arithmetic subsequences
	// ending at position i with common difference d.
	dp := make([]map[int64][]int, n)
	for i := range dp {
		dp[i] = make(map[int64][]int)
	}

	ans := make([]int, n+1)
	ans[1] = n

	for i := 0; i < n; i++ {
		for j := 0; j < i; j++ {
			d := a[i] - a[j]

			cur := dp[i][d]
			if cur == nil {
				cur = make([]int, n+1)
				dp[i][d] = cur
			}

			// The pair (j, i) forms an arithmetic subsequence of length 2.
			cur[2]++
			if cur[2] >= mod {
				cur[2] -= mod
			}
			ans[2]++
			if ans[2] >= mod {
				ans[2] -= mod
			}

			// Extend arithmetic subsequences ending at j with difference d.
			if prev := dp[j][d]; prev != nil {
				for length := 2; length < n; length++ {
					if prev[length] == 0 {
						continue
					}
					cur[length+1] += prev[length]
					if cur[length+1] >= mod {
						cur[length+1] -= mod
					}
					ans[length+1] += prev[length]
					if ans[length+1] >= mod {
						ans[length+1] -= mod
					}
				}
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for k := 1; k <= n; k++ {
		if k > 1 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, ans[k])
	}
	fmt.Fprintln(out)
}
