	var sum int64

	for i := 0; i < n; i++ {
		var h int64
		fmt.Fscan(in, &h)

		count := int64(1)
		for len(stack) > 0 && stack[len(stack)-1].value <= h {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			sum -= top.value * top.count
			count += top.count
		}

		stack = append(stack, Entry{value: h, count: count})
		sum += h * count

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, sum+1)
	}
	fmt.Fprintln(out)
