func pow10(n int) uint64 {
	var result uint64 = 1
	for i := 0; i < n; i++ {
		result *= 10
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n uint64
	fmt.Fscan(in, &n)

	if n == 1 {
		fmt.Fprintln(out, 0)
		return
	}

	remaining := n - 1 // Exclude 0.
	length := 1

	for {
		halfLength := (length + 1) / 2
		count := uint64(9) * pow10(halfLength-1)

		if remaining <= count {
			firstHalf := pow10(halfLength-1) + remaining - 1
			s := strconv.FormatUint(firstHalf, 10)

			result := []byte(s)
			i := len(s) - 1
			if length%2 == 1 {
				i--
			}
			for ; i >= 0; i-- {
				result = append(result, s[i])
			}

			fmt.Fprintln(out, string(result))
			return
		}

		remaining -= count
		length++
	}
}
