package main

import (
	"bufio"
	"fmt"
	"os"
)

func integerSqrt(n uint64) uint64 {
	var low uint64
	high := uint64(1_000_000_001)
	for low+1 < high {
		mid := (low + high) / 2
		if mid <= n/mid {
			low = mid
		} else {
			high = mid
		}
	}
	return low
}

func integerCubeRoot(n uint64) uint64 {
	var low uint64
	high := uint64(1_000_001)
	for low+1 < high {
		mid := (low + high) / 2
		if mid*mid <= n/mid {
			low = mid
		} else {
			high = mid
		}
	}
	return low
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n uint64
	fmt.Fscan(in, &n)

	// Every square, including 1, is a valid perfect power.
	answer := integerSqrt(n)

	// A non-square perfect power has a representation a^b
	// with both a non-square and b odd (b >= 3).
	maxBase := integerCubeRoot(n)
	powers := make(map[uint64]struct{}, int(maxBase)+10000)

	nextSquareRoot := uint64(2)
	nextSquare := uint64(4)

	for a := uint64(2); a <= maxBase; a++ {
		if a == nextSquare {
			nextSquareRoot++
			nextSquare = nextSquareRoot * nextSquareRoot
			continue
		}

		step := a * a
		value := step * a // a^3

		for {
			powers[value] = struct{}{}

			if value > n/step {
				break
			}
			value *= step // a^3, a^5, a^7, ...
		}
	}

	answer += uint64(len(powers))
	fmt.Fprintln(out, answer)
}
