package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	h := in.NextInt()
	w := in.NextInt()
	yMax := in.NextInt()

	n := h * w
	elevation := make([]int, n)
	for i := 0; i < n; i++ {
		elevation[i] = in.NextInt()
	}

	buckets := make([][]int, yMax+1)
	exposed := make([]bool, n)

	addBoundary := func(index int) {
		if exposed[index] {
			return
		}
		exposed[index] = true
		if elevation[index] <= yMax {
			buckets[elevation[index]] = append(buckets[elevation[index]], index)
		}
	}

	for col := 0; col < w; col++ {
		addBoundary(col)
		addBoundary((h-1)*w + col)
	}
	for row := 0; row < h; row++ {
		addBoundary(row * w)
		addBoundary(row*w + w - 1)
	}

	remaining := n
	directions := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	for level := 1; level <= yMax; level++ {
		queue := buckets[level]

		for head := 0; head < len(queue); head++ {
			index := queue[head]
			remaining--

			row := index / w
			col := index % w

			for _, d := range directions {
				nr, nc := row+d[0], col+d[1]
				if nr < 0 || nr >= h || nc < 0 || nc >= w {
					continue
				}

				next := nr*w + nc
				if exposed[next] {
					continue
				}
				exposed[next] = true

				height := elevation[next]
				if height <= level {
					queue = append(queue, next)
				} else if height <= yMax {
					buckets[height] = append(buckets[height], next)
				}
			}
		}

		fmt.Fprintln(out, remaining)
	}
}
