type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	h := in.NextInt()
	w := in.NextInt()
	yMax := in.NextInt()

	n := h * w
	elevation := make([]int, n)
	maxElevation := 0
	for i := 0; i < n; i++ {
		elevation[i] = in.NextInt()
		if elevation[i] > maxElevation {
			maxElevation = elevation[i]
		}
	}

	maxLevel := maxElevation
	if yMax > maxLevel {
		maxLevel = yMax
	}

	head := make([]int, maxLevel+1)
	for i := range head {
		head[i] = -1
	}
	next := make([]int, n)
	discovered := make([]bool, n)

	add := func(id, level int) {
		if discovered[id] {
			return
		}
		discovered[id] = true
		next[id] = head[level]
		head[level] = id
	}

	for col := 0; col < w; col++ {
		top := col
		bottom := (h-1)*w + col
		add(top, elevation[top])
		add(bottom, elevation[bottom])
	}
	for row := 0; row < h; row++ {
		left := row * w
		right := row*w + w - 1
		add(left, elevation[left])
		add(right, elevation[right])
	}

	remaining := n
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for level := 1; level <= yMax; level++ {
		for head[level] != -1 {
			id := head[level]
			head[level] = next[id]
			remaining--

			row := id / w
			col := id % w

			for d := 0; d < 4; d++ {
				nr := row + dr[d]
				nc := col + dc[d]
				if nr < 0 || nr >= h || nc < 0 || nc >= w {
					continue
				}

				nid := nr*w + nc
				if discovered[nid] {
					continue
				}

				sinkLevel := elevation[nid]
				if sinkLevel < level {
					sinkLevel = level
				}
				add(nid, sinkLevel)
			}
		}
		fmt.Fprintln(out, remaining)
	}
}
