	fmt.Fscan(in, &n, &x, &y)

	const inf = int(1e9)
	dp := make([][]int, n+1)
	for k := 0; k <= n; k++ {
		dp[k] = make([]int, x+1)
		for s := 0; s <= x; s++ {
			dp[k][s] = inf
		}
	}
	dp[0][0] = 0

	for i := 0; i < n; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)

		for k := i; k >= 0; k-- {
			for s := 0; s+a <= x; s++ {
				if dp[k][s] == inf || dp[k][s]+b > y {
					continue
				}
				if dp[k][s]+b < dp[k+1][s+a] {
					dp[k+1][s+a] = dp[k][s] + b
				}
			}
		}
	}

	maxSafe := 0
	for k := 0; k <= n; k++ {
		for s := 0; s <= x; s++ {
			if dp[k][s] <= y {
				maxSafe = k
				break
			}
		}
