package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt64() int64 {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] == ' ' || fs.data[fs.pos] == '\n' || fs.data[fs.pos] == '\r' || fs.data[fs.pos] == '\t') {
		fs.pos++
	}

	sign := int64(1)
	if fs.data[fs.pos] == '-' {
		sign = -1
		fs.pos++
	}

	var value int64
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		value = value*10 + int64(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return value * sign
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := NewFastScanner()
	n := int(in.NextInt64())
	q := int(in.NextInt64())

	a := make([]int64, n)
	for i := range a {
		a[i] = in.NextInt64()
	}
	sort.Slice(a, func(i, j int) bool {
		return a[i] < a[j]
	})

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	const inf int64 = 1 << 60

	for ; q > 0; q-- {
		b := in.NextInt64()
		k := int(in.NextInt64())

		p := sort.Search(n, func(i int) bool {
			return a[i] >= b
		})

		leftLen := p
		rightLen := n - p

		low := maxInt(0, k-rightLen)
		high := minInt(k, leftLen)
		var answer int64

		for low <= high {
			takeLeft := (low + high) / 2
			takeRight := k - takeLeft

			leftTaken := int64(-1)
			if takeLeft > 0 {
				leftTaken = b - a[p-takeLeft]
			}

			leftNext := inf
			if takeLeft < leftLen {
				leftNext = b - a[p-1-takeLeft]
			}

			rightTaken := int64(-1)
			if takeRight > 0 {
				rightTaken = a[p+takeRight-1] - b
			}

			rightNext := inf
			if takeRight < rightLen {
				rightNext = a[p+takeRight] - b
			}

			if leftTaken > rightNext {
				high = takeLeft - 1
			} else if rightTaken > leftNext {
				low = takeLeft + 1
			} else {
				if leftTaken > rightTaken {
					answer = leftTaken
				} else {
					answer = rightTaken
				}
				break
			}
		}

		fmt.Fprintln(out, answer)
	}
}
