				continue
			}

			score := 0
			if move == win {
				score = 1
			}

			if i == 0 {
				next[move] = score
				continue
			}

			for prev := 0; prev < 3; prev++ {
				if prev != move && dp[prev] != neg {
					value := dp[prev] + score
					if value > next[move] {
						next[move] = value
					}
				}
			}
		}
		dp = next
	}

	answer := dp[0]
	for i := 1; i < 3; i++ {
		if dp[i] > answer {
			answer = dp[i]
		}
