	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, x, y int
	fmt.Fscan(in, &n, &x, &y)

	a := make([]int, n)
	b := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i], &b[i])
	}

	// Use the smaller limit as the explicit DP dimension.
	capacity, otherLimit := x, y
	first, second := a, b
	if y < x {
		capacity, otherLimit = y, x
		first, second = b, a
	}

	const inf = int(1e9)
	width := capacity + 1
	dp := make([]int, (n+1)*width)
	for i := range dp {
		dp[i] = inf
	}
	dp[0] = 0

	maxFeasible := 0

	for i := 0; i < n; i++ {
		p, q := first[i], second[i]
		if p > capacity || q > otherLimit {
			continue
		}

		oldMax := maxFeasible
		newMax := oldMax

		for count := oldMax + 1; count >= 1; count-- {
			dstBase := count * width
			srcBase := (count - 1) * width

			for sum := capacity; sum >= p; sum-- {
				prev := dp[srcBase+sum-p]
				if prev == inf || prev+q > otherLimit {
					continue
				}

				if prev+q < dp[dstBase+sum] {
					dp[dstBase+sum] = prev + q
					if count > newMax {
						newMax = count
					}
				}
			}
		}

		maxFeasible = newMax
	}

	answer := maxFeasible + 1
	if answer > n {
		answer = n
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
