```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) Find(x int) int {
	root := x
	for d.parent[root] != root {
		root = d.parent[root]
	}
	for d.parent[x] != x {
		next := d.parent[x]
		d.parent[x] = root
		x = next
	}
	return root
}

func (d *DSU) Union(a, b int) bool {
	a = d.Find(a)
	b = d.Find(b)
	if a == b {
		return false
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	return true
}

type Query struct {
	l, r int
	c    int64
	id   int
}

func findNext(parent []int, x int) int {
	root := x
	for parent[root] != root {
		root = parent[root]
	}
	for parent[x] != x {
		next := parent[x]
		parent[x] = root
		x = next
	}
	return root
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	q := in.NextInt()

	queries := make([]Query, q)
	for i := 0; i < q; i++ {
		l := in.NextInt() - 1
		r := in.NextInt() - 1
		c := int64(in.NextInt())
		queries[i] = Query{l: l, r: r, c: c, id: i}
	}

	sort.Slice(queries, func(i, j int) bool {
		return queries[i].c < queries[j].c
	})

	dsu := NewDSU(n + q)

	// Boundary k is between base vertices k and k+1.
	// Removed boundaries are skipped by this successor structure.
	next := make([]int, n)
	for i := range next {
		next[i] = i
	}

	var answer int64
	merged := 0

	for _, query := range queries {
		queryVertex := n + query.id

		if dsu.Union(queryVertex, query.l) {
			answer += query.c
			merged++
		}

		k := findNext(next, query.l)
		for k < query.r {
			if dsu.Union(queryVertex, k+1) {
				answer += query.c
				merged++
			}

			next[k] = findNext(next, k+1)
			k = findNext(next, k)
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	if merged == n+q-1 {
		fmt.Fprintln(out, answer)
	} else {
		fmt.Fprintln(out, -1)
	}
}
