	c    int64
	id   int
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	q := in.NextInt()

	queries := make([]Query, q)
	for i := 0; i < q; i++ {
		queries[i] = Query{
			l:  in.NextInt() - 1,
			r:  in.NextInt() - 1,
			c:  int64(in.NextInt()),
			id: n + i,
		}
