	dsu := NewDSU(n + q)
	seg := make([]int, 4*n)

	var build func(node, left, right int)
	build = func(node, left, right int) {
		if left == right {
			seg[node] = left
			return
		}
		mid := (left + right) / 2
		build(node*2, left, mid)
		build(node*2+1, mid+1, right)
		seg[node] = -1
	}
	build(1, 0, n-1)

	var answer int64
	usedEdges := 0

	var connect func(node, left, right, ql, qr, queryID int, cost int64)
	connect = func(node, left, right, ql, qr, queryID int, cost int64) {
