		connect(node*2, left, mid, ql, qr, queryID, cost)
		connect(node*2+1, mid+1, right, ql, qr, queryID, cost)

		a := seg[node*2]
		b := seg[node*2+1]
		if a >= 0 && b >= 0 && dsu.Find(a) == dsu.Find(b) {
			seg[node] = a
		} else {
			seg[node] = -1
		}
	}

	for _, query := range queries {
		connect(1, 0, n-1, query.l, query.r, query.id, query.c)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

