package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type candidate struct {
	q int64
	x int64
}

func reverseNoZero(x int64) (int64, bool) {
	var rev int64
	for x > 0 {
		d := x % 10
		if d == 0 {
			return 0, false
		}
		rev = rev*10 + d
		x /= 10
	}
	return rev, true
}

func isValidPalindrome(x int64) bool {
	s := strconv.FormatInt(x, 10)
	for i, j := 0, len(s)-1; i <= j; i, j = i+1, j-1 {
		if s[i] == '0' || s[j] == '0' || s[i] != s[j] {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	candidates := make([]candidate, 0)
	seen := make(map[int64]bool)

	for x := int64(2); x <= 999999; x++ {
		rev, ok := reverseNoZero(x)
		if !ok {
			continue
		}
		q := x * rev
		if q <= n && n%q == 0 && !seen[q] {
			seen[q] = true
			candidates = append(candidates, candidate{q: q, x: x})
		}
	}

	failed := make(map[int64]bool)
	choice := make(map[int64]candidate)

	var dfs func(int64) bool
	dfs = func(rem int64) bool {
		if isValidPalindrome(rem) {
			return true
		}
		if failed[rem] {
			return false
		}

		for _, c := range candidates {
			if rem%c.q == 0 && dfs(rem/c.q) {
				choice[rem] = c
				return true
			}
		}

		failed[rem] = true
		return false
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if !dfs(n) {
		fmt.Fprintln(out, -1)
		return
	}

	var outer []int64
	rem := n
	for !isValidPalindrome(rem) {
		c := choice[rem]
		outer = append(outer, c.x)
		rem /= c.q
	}

	var result strings.Builder
	for _, x := range outer {
		result.WriteString(strconv.FormatInt(x, 10))
		result.WriteByte('*')
	}

	result.WriteString(strconv.FormatInt(rem, 10))

	for i := len(outer) - 1; i >= 0; i-- {
		rev, _ := reverseNoZero(outer[i])
		result.WriteByte('*')
		result.WriteString(strconv.FormatInt(rev, 10))
	}

	fmt.Fprintln(out, result.String())
}
