package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Factor struct {
	q   int64
	a   int64
	rev int64
}

func reverseNumber(n int64) int64 {
	var r int64
	for n > 0 {
		r = r*10 + n%10
		n /= 10
	}
	return r
}

func hasNoZero(n int64) bool {
	for n > 0 {
		if n%10 == 0 {
			return false
		}
		n /= 10
	}
	return true
}

func isGoodCenter(n int64) bool {
	if !hasNoZero(n) {
		return false
	}
	return n == reverseNumber(n)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int64
	fmt.Fscan(in, &n)

	if isGoodCenter(n) {
		fmt.Fprintln(out, n)
		return
	}

	factors := make([]Factor, 0)
	seenQ := make(map[int64]bool)

	for a := int64(2); a <= 999999; a++ {
		if !hasNoZero(a) {
			continue
		}
		r := reverseNumber(a)
		q := a * r
		if q <= n && n%q == 0 && !seenQ[q] {
			seenQ[q] = true
			factors = append(factors, Factor{q: q, a: a, rev: r})
		}
	}

	sort.Slice(factors, func(i, j int) bool {
		return factors[i].q > factors[j].q
	})

	failed := make(map[int64]bool)
	choice := make(map[int64]Factor)

	var dfs func(int64) bool
	dfs = func(x int64) bool {
		if isGoodCenter(x) {
			return true
		}
		if failed[x] {
			return false
		}

		for _, f := range factors {
			if f.q <= x && x%f.q == 0 {
				if dfs(x / f.q) {
					choice[x] = f
					return true
				}
			}
		}

		failed[x] = true
		return false
	}

	if !dfs(n) {
		fmt.Fprintln(out, -1)
		return
	}

	path := make([]Factor, 0)
	x := n
	for !isGoodCenter(x) {
		f := choice[x]
		path = append(path, f)
		x /= f.q
	}

	parts := make([]string, 0, len(path)*2+1)
	for _, f := range path {
		parts = append(parts, strconv.FormatInt(f.a, 10))
	}
	parts = append(parts, strconv.FormatInt(x, 10))
	for i := len(path) - 1; i >= 0; i-- {
		parts = append(parts, strconv.FormatInt(path[i].rev, 10))
	}

	fmt.Fprintln(out, strings.Join(parts, "*"))
}
