package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	sign := int64(1)
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Function struct {
	a, b int64
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	k := int(in.NextInt64())

	functions := make([]Function, n)
	for i := range functions {
		functions[i] = Function{
			a: in.NextInt64(),
			b: in.NextInt64(),
		}
	}

	// If i is outside j, i should precede j when
	// f_i(f_j(x)) >= f_j(f_i(x)).
	sort.Slice(functions, func(i, j int) bool {
		fi, fj := functions[i], functions[j]
		return fi.b*(fj.a-1) < fj.b*(fi.a-1)
	})

	dp := make([]int64, k+1)
	for i := 1; i <= k; i++ {
		dp[i] = -1
	}
	dp[0] = 1

	// Process from the innermost side to the outermost side.
	for i := n - 1; i >= 0; i-- {
		f := functions[i]
		for used := k - 1; used >= 0; used-- {
			if dp[used] < 0 {
				continue
			}
			candidate := f.a*dp[used] + f.b
			if candidate > dp[used+1] {
				dp[used+1] = candidate
			}
		}
	}

	fmt.Fprintln(out, dp[k])
}
