type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var sign, value int64 = 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func costFrequency(values []int, d int64) []int64 {
	n := len(values)
	sort.Ints(values)

	extension := d / int64(n)
	left := int64(values[0]) - extension
	right := int64(values[n-1]) + extension

	var cost int64
	for _, v := range values {
		diff := left - int64(v)
		if diff < 0 {
			diff = -diff
		}
		cost += diff
	}

	freq := make([]int64, int(d)+1)
	index := 0

	for x := left; x <= right; x++ {
		for index < n && int64(values[index]) <= x {
			index++
		}

		if cost <= d {
			freq[int(cost)]++
		}

		if x < right {
			cost += int64(2*index - n)
		}
	}

	return freq
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	d := in.NextInt64()

	xs := make([]int, n)
	ys := make([]int, n)

	for i := 0; i < n; i++ {
		xs[i] = int(in.NextInt64())
		ys[i] = int(in.NextInt64())
	}

	freqX := costFrequency(xs, d)
	freqY := costFrequency(ys, d)

	prefixY := make([]int64, len(freqY))
	var sum int64
	for i, count := range freqY {
		sum += count
		prefixY[i] = sum
	}

	var answer int64
	for xCost, count := range freqX {
		if count > 0 {
			answer += count * prefixY[int(d)-xCost]
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
