package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	rows := make([]uint64, n)
	for i := 0; i < m; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		u--
		v--
		rows[u] |= uint64(1) << uint(v)
		rows[v] |= uint64(1) << uint(u)
	}

	// Reduce the adjacency matrix over GF(2) to reduced row echelon form.
	pivotCols := make([]int, 0, n)
	rank := 0

	for col := 0; col < n && rank < n; col++ {
		pivot := -1
		for row := rank; row < n; row++ {
			if (rows[row]>>uint(col))&1 != 0 {
				pivot = row
				break
			}
		}
		if pivot == -1 {
			continue
		}

		rows[rank], rows[pivot] = rows[pivot], rows[rank]

		for row := 0; row < n; row++ {
			if row != rank && ((rows[row]>>uint(col))&1 != 0) {
				rows[row] ^= rows[rank]
			}
		}

		pivotCols = append(pivotCols, col)
		rank++
	}

	isPivot := make([]bool, n)
	for _, col := range pivotCols {
		isPivot[col] = true
	}

	// Construct a basis of the nullspace.
	basis := make([]uint64, 0, n-rank)
	for freeCol := 0; freeCol < n; freeCol++ {
		if isPivot[freeCol] {
			continue
		}

		vec := uint64(1) << uint(freeCol)
		for row, pivotCol := range pivotCols {
			if (rows[row]>>uint(freeCol))&1 != 0 {
				vec |= uint64(1) << uint(pivotCol)
			}
		}
		basis = append(basis, vec)
	}

	// Encode membership in each nullspace basis vector as a bit.
	answer := make([]uint64, n)
	for bit, vec := range basis {
		for vertex := 0; vertex < n; vertex++ {
			if (vec>>uint(vertex))&1 != 0 {
				answer[vertex] |= uint64(1) << uint(bit)
			}
		}
	}

	for _, x := range answer {
		if x == 0 {
			fmt.Println("No")
			return
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintln(out, "Yes")
	for i, x := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, x)
	}
	fmt.Fprintln(out)
}
