	// omega[x] is the number of prime factors of x, counted with multiplicity.
	omega := make([]int, maxA+1)
	smallestPrime := make([]int, maxA+1)
	primes := make([]int, 0)

	for x := 2; x <= maxA; x++ {
		if smallestPrime[x] == 0 {
			smallestPrime[x] = x
			primes = append(primes, x)
		}
		omega[x] = omega[x/smallestPrime[x]] + 1

		for _, p := range primes {
			if p > smallestPrime[x] || x*p > maxA {
				break
			}
			smallestPrime[x*p] = p
		}
	}

	xorSum := 0
	for _, x := range a {
		xorSum ^= omega[x]
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if xorSum != 0 {
