	hash2 := make([]uint64, n+1)
	for v := 1; v <= n; v++ {
		hash1[v] = splitmix64(uint64(v) + 0x123456789abcdef0)
		hash2[v] = splitmix64(uint64(v) + 0xfedcba9876543210)
	}

	prefixA1 := make([]uint64, n+1)
	prefixA2 := make([]uint64, n+1)
	prefixB1 := make([]uint64, n+1)
	prefixB2 := make([]uint64, n+1)

	for i := 1; i <= n; i++ {
