package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	x1 := in.NextInt64()

	a := make([]int, m)
	b := make([]int, m)
	s := make([]int64, m)
	t := make([]int64, m)
	x := make([]int64, m)

	for i := 0; i < m; i++ {
		a[i] = int(in.NextInt64()) - 1
		b[i] = int(in.NextInt64()) - 1
		s[i] = in.NextInt64()
		t[i] = in.NextInt64()
	}
	x[0] = x1

	departureOrder := make([]int, m)
	arrivalOrder := make([]int, m)
	for i := 0; i < m; i++ {
		departureOrder[i] = i
		arrivalOrder[i] = i
	}

	sort.Slice(departureOrder, func(i, j int) bool {
		if s[departureOrder[i]] != s[departureOrder[j]] {
			return s[departureOrder[i]] < s[departureOrder[j]]
		}
		return departureOrder[i] < departureOrder[j]
	})
	sort.Slice(arrivalOrder, func(i, j int) bool {
		if t[arrivalOrder[i]] != t[arrivalOrder[j]] {
			return t[arrivalOrder[i]] < t[arrivalOrder[j]]
		}
		return arrivalOrder[i] < arrivalOrder[j]
	})

	maxArrival := make([]int64, n)
	for i := range maxArrival {
		maxArrival[i] = -1
	}

	arrivalPtr := 0
	for _, train := range departureOrder {
		for arrivalPtr < m && t[arrivalOrder[arrivalPtr]] <= s[train] {
			prev := arrivalOrder[arrivalPtr]
			value := t[prev] + x[prev]
			if value > maxArrival[b[prev]] {
				maxArrival[b[prev]] = value
			}
			arrivalPtr++
		}

		if train == 0 {
			continue
		}

		required := maxArrival[a[train]] - s[train]
		if required > 0 {
			x[train] = required
		}
	}

