type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Arrival struct {
	time  int64
	value int64
	city  int
}

type ArrivalHeap []Arrival

func (h ArrivalHeap) Len() int           { return len(h) }
func (h ArrivalHeap) Less(i, j int) bool { return h[i].time < h[j].time }
func (h ArrivalHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *ArrivalHeap) Push(x any) {
	*h = append(*h, x.(Arrival))
}

func (h *ArrivalHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	x1 := in.NextInt64()

	a := make([]int, m)
	b := make([]int, m)
	s := make([]int64, m)
	t := make([]int64, m)
	x := make([]int64, m)

	for i := 0; i < m; i++ {
		a[i] = int(in.NextInt64()) - 1
		b[i] = int(in.NextInt64()) - 1
		s[i] = in.NextInt64()
		t[i] = in.NextInt64()
	}
	x[0] = x1

	order := make([]int, m)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		if s[order[i]] == s[order[j]] {
			return order[i] < order[j]
		}
		return s[order[i]] < s[order[j]]
	})

	maxArrival := make([]int64, n)
	pq := &ArrivalHeap{}
	heap.Init(pq)

	for _, i := range order {
		for pq.Len() > 0 && (*pq)[0].time <= s[i] {
			arr := heap.Pop(pq).(Arrival)
			if arr.value > maxArrival[arr.city] {
				maxArrival[arr.city] = arr.value
			}
		}

		if i != 0 && maxArrival[a[i]] > s[i] {
			x[i] = maxArrival[a[i]] - s[i]
		}

		heap.Push(pq, Arrival{
			time:  t[i],
			value: t[i] + x[i],
			city:  b[i],
		})
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i := 1; i < m; i++ {
		if i > 1 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, x[i])
	}
	fmt.Fprintln(out)
}
