package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 4_000_000_000_000_000_000

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

type SegmentTree struct {
	n    int
	sum  []int64
	need []int64
	a    []int64
	b    []int64
}

func threshold(a, b int64) int64 {
	if b == 1 {
		return INF
	}
	d := b - 1
	return a/d + boolToInt64(a%d != 0)
}

func boolToInt64(v bool) int64 {
	if v {
		return 1
	}
	return 0
}

func NewSegmentTree(a, b []int64) *SegmentTree {
	n := len(a) - 1
	st := &SegmentTree{
		n:    n,
		sum:  make([]int64, 4*n+5),
		need: make([]int64, 4*n+5),
		a:    a,
		b:    b,
	}
	st.build(1, 1, n)
	return st
}

func (st *SegmentTree) pull(node int) {
	left := node * 2
	right := left + 1

	st.sum[node] = st.sum[left] + st.sum[right]
	rightNeed := st.need[right] - st.sum[left]
	if st.need[left] < rightNeed {
		st.need[node] = st.need[left]
	} else {
		st.need[node] = rightNeed
	}
}

func (st *SegmentTree) build(node, l, r int) {
	if l == r {
		st.sum[node] = st.a[l]
		st.need[node] = threshold(st.a[l], st.b[l])
		return
	}

	mid := (l + r) / 2
	st.build(node*2, l, mid)
	st.build(node*2+1, mid+1, r)
	st.pull(node)
}

func (st *SegmentTree) update(pos int) {
	st.updateRec(1, 1, st.n, pos)
}

func (st *SegmentTree) updateRec(node, l, r, pos int) {
	if l == r {
		st.sum[node] = st.a[l]
		st.need[node] = threshold(st.a[l], st.b[l])
		return
	}

	mid := (l + r) / 2
	if pos <= mid {
		st.updateRec(node*2, l, mid, pos)
	} else {
		st.updateRec(node*2+1, mid+1, r, pos)
	}
	st.pull(node)
}

// findFirst finds the first index in [ql, qr] where multiplication is at
// least as good as addition. All preceding additions are applied to *value.
// If no such index exists, all additions in [ql, qr] are applied and -1 is returned.
func (st *SegmentTree) findFirst(node, l, r, ql, qr int, value *int64) int {
	if r < ql || qr < l {
		return -1
	}

	if ql <= l && r <= qr && st.need[node] > *value {
		*value += st.sum[node]
		return -1
	}

	if l == r {
		return l
	}

	mid := (l + r) / 2
	res := st.findFirst(node*2, l, mid, ql, qr, value)
	if res != -1 {
		return res
	}
	return st.findFirst(node*2+1, mid+1, r, ql, qr, value)
}

func (st *SegmentTree) Query(l, r int) int64 {
	var value int64
	pos := l

	for pos <= r {
		idx := st.findFirst(1, 1, st.n, pos, r, &value)
		if idx == -1 {
			break
		}
		value *= st.b[idx]
		pos = idx + 1
	}

	return value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	a := make([]int64, n+1)
	b := make([]int64, n+1)

	for i := 1; i <= n; i++ {
		a[i] = in.NextInt64()
	}
	for i := 1; i <= n; i++ {
		b[i] = in.NextInt64()
	}

	st := NewSegmentTree(a, b)

	q := int(in.NextInt64())
	for ; q > 0; q-- {
		t := int(in.NextInt64())
		x := int(in.NextInt64())
		y := in.NextInt64()

		switch t {
		case 1:
			st.a[x] = y
			st.update(x)
		case 2:
			st.b[x] = y
			st.update(x)
		case 3:
			fmt.Fprintln(out, st.Query(x, int(y)))
		}
	}
}
