package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	mod  int64 = 998244353
	bits       = 20
	size       = 1 << bits
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func modPow(a int64, e int) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func normalize(x int64) int64 {
	x %= mod
	if x < 0 {
		x += mod
	}
	return x
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	m := in.NextInt()
	k := in.NextInt()

	frequency := make([]int, size)
	for i := 0; i < n; i++ {
		a := in.NextInt()
		frequency[a]++
	}

	// Walsh-Hadamard transform of the frequency array.
	// Afterwards frequency[s] = sum_i (-1)^{popcount(A_i & s)}.
	for length := 1; length < size; length <<= 1 {
		step := length << 1
		for start := 0; start < size; start += step {
			for j := 0; j < length; j++ {
				u := frequency[start+j]
				v := frequency[start+j+length]
				frequency[start+j] = u + v
				frequency[start+j+length] = u - v
			}
		}
	}

	// p stores the coefficients of (1+y)^n grouped by exponent modulo m.
	p := make([]int64, m)
	inverses := make([]int64, n+1)
	if n >= 1 {
		inverses[1] = 1
		for i := 2; i <= n; i++ {
			inverses[i] = mod - (mod/int64(i))*inverses[int(mod%int64(i))]%mod
		}
	}

	comb := int64(1)
	for j := 0; j <= n; j++ {
		p[j%m] += comb
		if p[j%m] >= mod {
			p[j%m] -= mod
		}
		if j < n {
			comb = comb * int64(n-j) % mod
			comb = comb * inverses[j+1] % mod
		}
	}

	// g[t] is the sum of coefficients whose exponents are divisible by m in
	// (1+y)^(n-t) (1-y)^t.
	g := make([]int64, n+1)
	g[0] = p[0]

	d := make([]int64, m)
	q := make([]int64, m)
	inv2 := (mod + 1) / 2
	invM := modPow(int64(m), int(mod-2))
	pow2N := modPow(2, n)

	for t := 0; t < n; t++ {
		for r := 0; r < m; r++ {
			prev := r - 1
			if prev < 0 {
				prev += m
			}
			d[r] = p[r] - p[prev]
			if d[r] < 0 {
				d[r] += mod
			}
		}

		var q0 int64
		if m&1 == 1 {
			var rest int64
			for i := 1; i < m; i++ {
				if i&1 == 1 {
					rest -= d[i]
				} else {
					rest += d[i]
				}
			}
			q0 = normalize(d[0]-normalize(rest)) * inv2 % mod
		} else {
			var rest int64
			for i := 1; i < m; i++ {
				term := int64(m-i) * d[i] % mod
				if i&1 == 1 {
					rest -= term
				} else {
					rest += term
				}
			}
			target := int64(0)
			if t+1 == n {
				target = pow2N
			}
			q0 = normalize(target-normalize(rest)) * invM % mod
		}

		q[0] = q0
		for r := 1; r < m; r++ {
			q[r] = d[r] - q[r-1]
			if q[r] < 0 {
				q[r] += mod
			}
		}

		p, q = q, p
		g[t+1] = p[0]
	}

	// Walsh-Hadamard transform of f(x) = x^k.
	values := make([]int64, size)
	for x := 0; x < size; x++ {
		values[x] = modPow(int64(x), k)
	}

	for length := 1; length < size; length <<= 1 {
		step := length << 1
		for start := 0; start < size; start += step {
			for j := 0; j < length; j++ {
				u := values[start+j]
				v := values[start+j+length]

				sum := u + v
				if sum >= mod {
					sum -= mod
				}
				diff := u - v
				if diff < 0 {
					diff += mod
				}

				values[start+j] = sum
				values[start+j+length] = diff
			}
		}
	}

	var answer int64
	for s := 0; s < size; s++ {
		minusCount := (n - frequency[s]) / 2
		term := values[s] * g[minusCount] % mod
		answer += term
		if answer >= mod {
			answer -= mod
		}
	}

	answer = answer * modPow(size, int(mod-2)) % mod

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	fmt.Fprintln(out, answer)
	out.Flush()
}
