package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	u := make([]int, m)
	v := make([]int, m)
	t := make([]int64, m)

	dist := make([]int64, n*n)
	for i := range dist {
		dist[i] = INF
	}
	for i := 0; i < n; i++ {
		dist[i*n+i] = 0
	}

	for i := 0; i < m; i++ {
		u[i] = in.NextInt() - 1
		v[i] = in.NextInt() - 1
		t[i] = int64(in.NextInt())

		a, b := u[i], v[i]
		if t[i] < dist[a*n+b] {
			dist[a*n+b] = t[i]
			dist[b*n+a] = t[i]
		}
	}

	// All-pairs shortest paths.
	for k := 0; k < n; k++ {
		kBase := k * n
		for i := 0; i < n; i++ {
			iBase := i * n
			dik := dist[iBase+k]
			if dik == INF {
				continue
			}
			for j := 0; j < n; j++ {
				dkj := dist[kBase+j]
				if dkj == INF {
					continue
				}
				if candidate := dik + dkj; candidate < dist[iBase+j] {
					dist[iBase+j] = candidate
				}
			}
		}
	}

	q := in.NextInt()
	for ; q > 0; q-- {
		k := in.NextInt()
		bridges := make([]int, k)
		for i := 0; i < k; i++ {
			bridges[i] = in.NextInt() - 1
		}

		// For each required bridge, store both possible traversal directions.
		states := 2 * k
		start := make([]int, states)
		end := make([]int, states)
		cost := make([]int64, states)

		for i, bridge := range bridges {
			start[2*i] = u[bridge]
			end[2*i] = v[bridge]
			cost[2*i] = t[bridge]

			start[2*i+1] = v[bridge]
			end[2*i+1] = u[bridge]
			cost[2*i+1] = t[bridge]
		}

		maskCount := 1 << k
		dp := make([]int64, maskCount*states)
		for i := range dp {
			dp[i] = INF
		}

		for p := 0; p < states; p++ {
			bridgeIndex := p / 2
			mask := 1 << bridgeIndex
			dp[mask*states+p] = dist[start[p]] + cost[p]
		}

		for mask := 1; mask < maskCount; mask++ {
			for p := 0; p < states; p++ {
				cur := dp[mask*states+p]
				if cur == INF {
					continue
				}

				for nextBridge := 0; nextBridge < k; nextBridge++ {
					if mask&(1<<nextBridge) != 0 {
						continue
					}
					nextMask := mask | (1 << nextBridge)

					for direction := 0; direction < 2; direction++ {
						nextState := 2*nextBridge + direction
						candidate := cur +
							dist[end[p]*n+start[nextState]] +
							cost[nextState]

						index := nextMask*states + nextState
						if candidate < dp[index] {
							dp[index] = candidate
						}
					}
				}
			}
		}

		fullMask := maskCount - 1
		answer := INF
		for p := 0; p < states; p++ {
			candidate := dp[fullMask*states+p] + dist[end[p]*n+(n-1)]
			if candidate < answer {
				answer = candidate
			}
		}

		fmt.Fprintln(out, answer)
	}
}
