func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return value * sign
}

func modPow(a int64, e int) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func walshMod(a []int64) {
	n := len(a)
	for length := 1; length < n; length <<= 1 {
		step := length << 1
		for i := 0; i < n; i += step {
			for j := 0; j < length; j++ {
				u, v := a[i+j], a[i+j+length]

				x := u + v
				if x >= mod {
					x -= mod
				}
				y := u - v
				if y < 0 {
					y += mod
				}

				a[i+j] = x
				a[i+j+length] = y
			}
		}
	}
}

func walshInt(a []int) {
	n := len(a)
	for length := 1; length < n; length <<= 1 {
		step := length << 1
		for i := 0; i < n; i += step {
			for j := 0; j < length; j++ {
				u, v := a[i+j], a[i+j+length]
				a[i+j] = u + v
				a[i+j+length] = u - v
			}
		}
	}
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	m := in.NextInt()
	k := in.NextInt()

	frequency := make([]int, xorSize)
	for i := 0; i < n; i++ {
		a := in.NextInt()
		frequency[a]++
	}

	maxFact := n
	if m > maxFact {
		maxFact = m
	}

	fact := make([]int64, maxFact+1)
	invFact := make([]int64, maxFact+1)
	fact[0] = 1
	for i := 1; i <= maxFact; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxFact] = modPow(fact[maxFact], int(mod-2))
	for i := maxFact; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(a, b int) int64 {
		if b < 0 || b > a {
			return 0
		}
		return fact[a] * invFact[b] % mod * invFact[a-b] % mod
	}

	calculateH := func(c int) int64 {
		var result int64
		for degree := 0; degree <= n; degree += m {
			low := degree - (n - c)
			if low < 0 {
				low = 0
			}
			high := degree
			if high > c {
				high = c
			}
			for chosenNegative := low; chosenNegative <= high; chosenNegative++ {
				term := comb(c, chosenNegative) *
					comb(n-c, degree-chosenNegative) % mod
				if chosenNegative&1 == 1 {
					result -= term
					if result < 0 {
						result += mod
					}
				} else {
					result += term
					if result >= mod {
						result -= mod
					}
				}
			}
		}
		return result
	}

	h := make([]int64, n+1)
	degree := m
	if m&1 == 0 {
		degree = m - 1
	}

	if n < degree {
		for c := 0; c <= n; c++ {
			h[c] = calculateH(c)
		}
	} else {
		for c := 0; c < degree; c++ {
			h[c] = calculateH(c)
		}

		leadingInv := modPow(comb(m, degree), int(mod-2))
		for c := degree; c <= n; c++ {
			var sum int64
			for j := 1; j < degree; j += 2 {
				sum += comb(m, j) * h[c-degree+j] % mod
				if sum >= mod {
					sum -= mod
				}
			}
			h[c] = (mod - sum) % mod * leadingInv % mod
		}

		if m&1 == 0 {
			correction := modPow(2, n) * modPow(int64(m), int(mod-2)) % mod
			h[n] += correction
			if h[n] >= mod {
				h[n] -= mod
			}
		}
	}

	values := make([]int64, xorSize)
	for x := 0; x < xorSize; x++ {
		values[x] = modPow(int64(x), k)
	}

	walshMod(values)
	walshInt(frequency)

	var answer int64
	for mask := 0; mask < xorSize; mask++ {
		oddCount := (n - frequency[mask]) / 2
		answer += values[mask] * h[oddCount] % mod
		if answer >= mod {
			answer -= mod
		}
	}

	answer = answer * modPow(xorSize, int(mod-2)) % mod

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
