package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 62

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var c byte
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b >= '0' && b <= '9' {
			c = b
			break
		}
	}
	n = int64(c - '0')
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b < '0' || b > '9' {
			return n
		}
		n = n*10 + int64(b-'0')
	}
}

type SegmentTree struct {
	n   int
	sum []int64
	min []int64
	a   []int64
	b   []int64
}

func NewSegmentTree(a, b []int64) *SegmentTree {
	n := len(a)
	st := &SegmentTree{
		n:   n,
		sum: make([]int64, 4*n),
		min: make([]int64, 4*n),
		a:   a,
		b:   b,
	}
	st.build(1, 0, n-1)
	return st
}

func threshold(a, b int64) int64 {
	if b == 1 {
		return INF
	}
	return a / (b - 1)
}

func (st *SegmentTree) pull(node int) {
	left := node * 2
	right := left + 1

	st.sum[node] = st.sum[left] + st.sum[right]
	st.min[node] = st.min[left]

	if st.min[right] != INF {
		candidate := st.min[right] - st.sum[left]
		if candidate < st.min[node] {
			st.min[node] = candidate
		}
	}
}

func (st *SegmentTree) build(node, l, r int) {
	if l == r {
		st.sum[node] = st.a[l]
		st.min[node] = threshold(st.a[l], st.b[l])
		return
	}

	mid := (l + r) / 2
	st.build(node*2, l, mid)
	st.build(node*2+1, mid+1, r)
	st.pull(node)
}

func (st *SegmentTree) Update(pos int) {
	st.update(1, 0, st.n-1, pos)
}

func (st *SegmentTree) update(node, l, r, pos int) {
	if l == r {
		st.sum[node] = st.a[l]
		st.min[node] = threshold(st.a[l], st.b[l])
		return
	}

	mid := (l + r) / 2
	if pos <= mid {
		st.update(node*2, l, mid, pos)
	} else {
		st.update(node*2+1, mid+1, r, pos)
	}
	st.pull(node)
}

// consume adds A_i for consecutive positions in [ql, qr] until it finds
// the first position where multiplication is strictly better.
// It returns that position, or -1 if all positions were consumed by addition.
func (st *SegmentTree) consume(node, l, r, ql, qr int, v *int64) int {
	if r < ql || qr < l {
		return -1
	}

	if ql <= l && r <= qr && st.min[node] >= *v {
		*v += st.sum[node]
		return -1
	}

	if l == r {
		return l
	}

	mid := (l + r) / 2
	pos := st.consume(node*2, l, mid, ql, qr, v)
	if pos != -1 {
		return pos
	}
	return st.consume(node*2+1, mid+1, r, ql, qr, v)
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	a := make([]int64, n)
	b := make([]int64, n)

	for i := range a {
		a[i] = in.NextInt64()
	}
	for i := range b {
		b[i] = in.NextInt64()
	}

	st := NewSegmentTree(a, b)

	q := int(in.NextInt64())
	for ; q > 0; q-- {
		typ := int(in.NextInt64())
		switch typ {
		case 1:
			i := int(in.NextInt64()) - 1
			x := in.NextInt64()
			a[i] = x
			st.Update(i)

		case 2:
			i := int(in.NextInt64()) - 1
			x := in.NextInt64()
			b[i] = x
			st.Update(i)

		case 3:
			l := int(in.NextInt64()) - 1
			r := int(in.NextInt64()) - 1

			var v int64
			pos := l
			for pos <= r {
				next := st.consume(1, 0, n-1, pos, r, &v)
				if next == -1 {
					break
				}
				v *= b[next]
				pos = next + 1
			}

			fmt.Fprintln(out, v)
		}
	}
}
