```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())

	u := make([]int, m)
	v := make([]int, m)
	t := make([]int64, m)

	dist := make([]int64, n*n)
	for i := range dist {
		dist[i] = INF
	}
	for i := 0; i < n; i++ {
		dist[i*n+i] = 0
	}

	for i := 0; i < m; i++ {
		u[i] = int(in.NextInt64()) - 1
		v[i] = int(in.NextInt64()) - 1
		t[i] = in.NextInt64()

		a, b := u[i], v[i]
		if t[i] < dist[a*n+b] {
			dist[a*n+b] = t[i]
			dist[b*n+a] = t[i]
		}
	}

	// All-pairs shortest paths.
	for k := 0; k < n; k++ {
		kBase := k * n
		for i := 0; i < n; i++ {
			iBase := i * n
			dik := dist[iBase+k]
			if dik == INF {
				continue
			}
			for j := 0; j < n; j++ {
				nd := dik + dist[kBase+j]
				if nd < dist[iBase+j] {
					dist[iBase+j] = nd
				}
			}
		}
	}

	q := int(in.NextInt64())
	for ; q > 0; q-- {
		k := int(in.NextInt64())
		bridges := make([]int, k)
		for i := 0; i < k; i++ {
			bridges[i] = int(in.NextInt64()) - 1
		}

		states := 1 << k
		dp := make([]int64, states*k*2)
		for i := range dp {
			dp[i] = INF
		}

		index := func(mask, last, dir int) int {
			return (mask*k+last)*2 + dir
		}

		for i, bridgeID := range bridges {
			// Direction 0: u -> v
			dp[index(1<<i, i, 0)] = dist[u[bridgeID]] + t[bridgeID]
			// Direction 1: v -> u
			dp[index(1<<i, i, 1)] = dist[v[bridgeID]] + t[bridgeID]
		}

		for mask := 1; mask < states; mask++ {
			for last := 0; last < k; last++ {
				if mask&(1<<last) == 0 {
					continue
				}
				lastID := bridges[last]

				for dir := 0; dir < 2; dir++ {
					curCost := dp[index(mask, last, dir)]
					if curCost == INF {
						continue
					}

					end := v[lastID]
					if dir == 1 {
						end = u[lastID]
					}

					for next := 0; next < k; next++ {
						if mask&(1<<next) != 0 {
							continue
						}
						nextID := bridges[next]
						nextMask := mask | (1 << next)

						// Cross the next bridge from u to v.
						cost0 := curCost + dist[end*n+u[nextID]] + t[nextID]
						idx0 := index(nextMask, next, 0)
						if cost0 < dp[idx0] {
							dp[idx0] = cost0
						}

						// Cross the next bridge from v to u.
						cost1 := curCost + dist[end*n+v[nextID]] + t[nextID]
						idx1 := index(nextMask, next, 1)
						if cost1 < dp[idx1] {
							dp[idx1] = cost1
						}
					}
				}
			}
		}

		fullMask := states - 1
		answer := INF
		for last := 0; last < k; last++ {
			bridgeID := bridges[last]

			cost0 := dp[index(fullMask, last, 0)] + dist[v[bridgeID]*n+(n-1)]
			if cost0 < answer {
				answer = cost0
			}

			cost1 := dp[index(fullMask, last, 1)] + dist[u[bridgeID]*n+(n-1)]
			if cost1 < answer {
				answer = cost1
			}
		}

		fmt.Fprintln(out, answer)
	}
}
