type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func find(parent []int, x int) int {
	if x == -1 {
		return -1
	}

	root := x
	for root != -1 && parent[root] != root {
		root = parent[root]
	}

	for x != -1 && parent[x] != x {
		next := parent[x]
		parent[x] = root
		x = next
	}
	return root
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	h := in.NextInt()
	w := in.NextInt()
	q := in.NextInt()

	n := h * w
	alive := make([]bool, n)
	left := make([]int, n)
	right := make([]int, n)
	up := make([]int, n)
	down := make([]int, n)

	for i := 0; i < n; i++ {
		alive[i] = true
		left[i] = i
		right[i] = i
		up[i] = i
		down[i] = i
	}

	remaining := n

	destroy := func(id int) {
		if id < 0 || !alive[id] {
			return
		}

		alive[id] = false
		remaining--

		row := id / w
		col := id % w

		if col > 0 {
			left[id] = find(left, id-1)
		} else {
			left[id] = -1
		}

		if col+1 < w {
			right[id] = find(right, id+1)
		} else {
			right[id] = -1
		}

		if row > 0 {
			up[id] = find(up, id-w)
		} else {
			up[id] = -1
		}

		if row+1 < h {
			down[id] = find(down, id+w)
		} else {
			down[id] = -1
		}
	}

	for ; q > 0; q-- {
		r := in.NextInt() - 1
		c := in.NextInt() - 1
		id := r*w + c

		if alive[id] {
			destroy(id)
			continue
		}

		targets := [4]int{
			find(up, id),
			find(down, id),
			find(left, id),
			find(right, id),
		}

		for _, target := range targets {
			if target != -1 {
				destroy(target)
			}
		}
	}

	fmt.Fprintln(out, remaining)
}
