type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Edge struct {
	to int
	w  int64
}

type HeapNode struct {
	value       int64
	left, right int
	rank        int
}

var heap []HeapNode

func meld(a, b int) int {
	if a == 0 {
		return b
	}
	if b == 0 {
		return a
	}
	if heap[a].value < heap[b].value {
		a, b = b, a
	}
	heap[a].right = meld(heap[a].right, b)
	if heap[heap[a].left].rank < heap[heap[a].right].rank {
		heap[a].left, heap[a].right = heap[a].right, heap[a].left
	}
	heap[a].rank = heap[heap[a].right].rank + 1
	return a
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	n := int(in.NextInt64())

	graph := make([][]Edge, n+1)
	for i := 0; i < n-1; i++ {
		u := int(in.NextInt64())
		v := int(in.NextInt64())
		w := in.NextInt64()
		graph[u] = append(graph[u], Edge{to: v, w: w})
		graph[v] = append(graph[v], Edge{to: u, w: w})
	}

	parent := make([]int, n+1)
	parentEdge := make([]int64, n+1)
	order := make([]int, 0, n)
	order = append(order, 1)
	parent[1] = -1

	for i := 0; i < len(order); i++ {
		v := order[i]
		for _, e := range graph[v] {
			if e.to == parent[v] {
				continue
			}
			parent[e.to] = v
			parentEdge[e.to] = e.w
			order = append(order, e.to)
		}
	}

	heap = make([]HeapNode, n+1)
	heapRoot := make([]int, n+1)
	nodeCount := 0

	for i := n - 1; i >= 0; i-- {
		v := order[i]
		root := 0

		for _, e := range graph[v] {
			if parent[e.to] == v {
				root = meld(root, heapRoot[e.to])
			}
		}

		if v != 1 {
			if root == 0 {
				nodeCount++
				heap[nodeCount] = HeapNode{
					value: parentEdge[v],
					rank:  1,
				}
				root = nodeCount
			} else {
				heap[root].value += parentEdge[v]
			}
		}

		heapRoot[v] = root
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	root := heapRoot[1]
	var total int64

	for k := 1; k <= n; k++ {
		if root != 0 {
			total += heap[root].value
			root = meld(heap[root].left, heap[root].right)
		}
		fmt.Fprintln(out, total*2)
	}
}
