package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	n, sign := 0, 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Grid struct {
	h, w      int
	alive     []bool
	right     []int
	left      []int
	down      []int
	up        []int
	remaining int
}

func find(parent []int, x int) int {
	root := x
	for parent[root] != root {
		root = parent[root]
	}
	for parent[x] != x {
		next := parent[x]
		parent[x] = root
		x = next
	}
	return root
}

func NewGrid(h, w int) *Grid {
	n := h * w
	horizontalSize := h * (w + 1)
	verticalSize := w * (h + 1)

	g := &Grid{
		h:         h,
		w:         w,
		alive:     make([]bool, n),
		right:     make([]int, horizontalSize),
		left:      make([]int, horizontalSize),
		down:      make([]int, verticalSize),
		up:        make([]int, verticalSize),
		remaining: n,
	}

	for i := range g.alive {
		g.alive[i] = true
	}
	for i := range g.right {
		g.right[i] = i
		g.left[i] = i
	}
	for i := range g.down {
		g.down[i] = i
		g.up[i] = i
	}

	return g
}

func (g *Grid) destroy(r, c int) {
	id := r*g.w + c
	if !g.alive[id] {
		return
	}
	g.alive[id] = false
	g.remaining--

	hBase := r * (g.w + 1)
	vBase := c * (g.h + 1)

	// Remove from the structure finding cells to the right.
	x := hBase + c
	g.right[x] = find(g.right, x+1)

	// Remove from the structure finding cells to the left.
	x = hBase + c + 1
	g.left[x] = find(g.left, x-1)

	// Remove from the structure finding cells below.
	x = vBase + r
	g.down[x] = find(g.down, x+1)

	// Remove from the structure finding cells above.
	x = vBase + r + 1
	g.up[x] = find(g.up, x-1)
}

func (g *Grid) bomb(r, c int) {
	if g.alive[r*g.w+c] {
		g.destroy(r, c)
		return
	}

	hBase := r * (g.w + 1)
	vBase := c * (g.h + 1)

	upPos := find(g.up, vBase+r) - vBase
	downPos := find(g.down, vBase+r+1) - vBase
	leftPos := find(g.left, hBase+c) - hBase
	rightPos := find(g.right, hBase+c+1) - hBase

	if upPos > 0 {
		g.destroy(upPos-1, c)
	}
	if downPos < g.h {
		g.destroy(downPos, c)
	}
	if leftPos > 0 {
		g.destroy(r, leftPos-1)
	}
	if rightPos < g.w {
		g.destroy(r, rightPos)
	}
}

func main() {
	in := NewFastScanner()
	h := in.NextInt()
	w := in.NextInt()
	q := in.NextInt()

	grid := NewGrid(h, w)

	for i := 0; i < q; i++ {
		r := in.NextInt() - 1
		c := in.NextInt() - 1
		grid.bomb(r, c)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, grid.remaining)
}
