```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type SegmentTree struct {
	n       int
	sum     []int64
	minimum []int64
	maximum []int64
	lazy    []int64
	hasLazy []bool
}

func NewSegmentTree(values []int64) *SegmentTree {
	n := len(values) - 1
	st := &SegmentTree{
		n:       n,
		sum:     make([]int64, 4*n+5),
		minimum: make([]int64, 4*n+5),
		maximum: make([]int64, 4*n+5),
		lazy:    make([]int64, 4*n+5),
		hasLazy: make([]bool, 4*n+5),
	}
	st.build(1, 1, n, values)
	return st
}

func (st *SegmentTree) build(node, left, right int, values []int64) {
	if left == right {
		v := values[left]
		st.sum[node] = v
		st.minimum[node] = v
		st.maximum[node] = v
		return
	}
	mid := (left + right) / 2
	st.build(node*2, left, mid, values)
	st.build(node*2+1, mid+1, right, values)
	st.pull(node)
}

func (st *SegmentTree) pull(node int) {
	st.sum[node] = st.sum[node*2] + st.sum[node*2+1]

	st.minimum[node] = st.minimum[node*2]
	if st.minimum[node*2+1] < st.minimum[node] {
		st.minimum[node] = st.minimum[node*2+1]
	}

	st.maximum[node] = st.maximum[node*2]
	if st.maximum[node*2+1] > st.maximum[node] {
		st.maximum[node] = st.maximum[node*2+1]
	}
}

func (st *SegmentTree) apply(node, left, right int, value int64) {
	st.sum[node] = value * int64(right-left+1)
	st.minimum[node] = value
	st.maximum[node] = value
	st.lazy[node] = value
	st.hasLazy[node] = true
}

func (st *SegmentTree) push(node, left, right int) {
	if !st.hasLazy[node] || left == right {
		return
	}
	mid := (left + right) / 2
	value := st.lazy[node]
	st.apply(node*2, left, mid, value)
	st.apply(node*2+1, mid+1, right, value)
	st.hasLazy[node] = false
}

func (st *SegmentTree) Assign(queryLeft, queryRight int, value int64) {
	if queryLeft > queryRight {
		return
	}
	st.assign(1, 1, st.n, queryLeft, queryRight, value)
}

func (st *SegmentTree) assign(node, left, right, queryLeft, queryRight int, value int64) {
	if queryLeft <= left && right <= queryRight {
		st.apply(node, left, right, value)
		return
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if queryLeft <= mid {
		st.assign(node*2, left, mid, queryLeft, queryRight, value)
	}
	if queryRight > mid {
		st.assign(node*2+1, mid+1, right, queryLeft, queryRight, value)
	}
	st.pull(node)
}

func (st *SegmentTree) QuerySum(queryLeft, queryRight int) int64 {
	if queryLeft > queryRight {
		return 0
	}
	return st.querySum(1, 1, st.n, queryLeft, queryRight)
}

func (st *SegmentTree) querySum(node, left, right, queryLeft, queryRight int) int64 {
	if queryLeft <= left && right <= queryRight {
		return st.sum[node]
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	var result int64
	if queryLeft <= mid {
		result += st.querySum(node*2, left, mid, queryLeft, queryRight)
	}
	if queryRight > mid {
		result += st.querySum(node*2+1, mid+1, right, queryLeft, queryRight)
	}
	return result
}

func (st *SegmentTree) FirstGreater(value int64) int {
	if st.maximum[1] <= value {
		return st.n + 1
	}
	return st.firstGreater(1, 1, st.n, value)
}

func (st *SegmentTree) firstGreater(node, left, right int, value int64) int {
	if left == right {
		return left
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if st.maximum[node*2] > value {
		return st.firstGreater(node*2, left, mid, value)
	}
	return st.firstGreater(node*2+1, mid+1, right, value)
}

func (st *SegmentTree) LastLess(value int64) int {
	if st.minimum[1] >= value {
		return 0
	}
	return st.lastLess(1, 1, st.n, value)
}

func (st *SegmentTree) lastLess(node, left, right int, value int64) int {
	if left == right {
		return left
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if st.minimum[node*2+1] < value {
		return st.lastLess(node*2+1, mid+1, right, value)
	}
	return st.lastLess(node*2, left, mid, value)
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	values := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		x := in.NextInt64()
		values[i] = x - int64(i)
	}

	st := NewSegmentTree(values)
	q := int(in.NextInt64())

	var answer int64

	for ; q > 0; q-- {
		t := int(in.NextInt64())
		g := in.NextInt64() - int64(t)

		// For indices 1..t, replace values greater than g with g.
		first := st.FirstGreater(g)
		if first <= t {
			oldSum := st.QuerySum(first, t)
			newSum := g * int64(t-first+1)
			answer += oldSum - newSum
			st.Assign(first, t, g)
		}

		// For indices t..N, replace values less than g with g.
		last := st.LastLess(g)
		if last >= t {
			oldSum := st.QuerySum(t, last)
			newSum := g * int64(last-t+1)
			answer += newSum - oldSum
			st.Assign(t, last, g)
		}
	}

	fmt.Fprintln(out, answer)
