package main

import (
	"bufio"
	"fmt"
	"os"
)

type factor struct {
	prime int
	exp   int
	power int64
}

func extendedGCD(a, b int64) (int64, int64, int64) {
	if b == 0 {
		return a, 1, 0
	}
	g, x1, y1 := extendedGCD(b, a%b)
	return g, y1, x1-(a/b)*y1
}

func modInverse(a, mod int64) int64 {
	_, x, _ := extendedGCD(a, mod)
	x %= mod
	if x < 0 {
		x += mod
	}
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	p := make([]int, n)
	a := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	// Smallest prime factors.
	spf := make([]int, n+1)
	primes := make([]int, 0)
	for i := 2; i <= n; i++ {
		if spf[i] == 0 {
			spf[i] = i
			primes = append(primes, i)
		}
		for _, prime := range primes {
			if prime > spf[i] || i*prime > n {
				break
			}
			spf[i*prime] = prime
		}
	}

	factorize := func(x int) []factor {
		result := make([]factor, 0)
		for x > 1 {
			prime := spf[x]
			exp := 0
			power := int64(1)
			for x%prime == 0 {
				x /= prime
				exp++
				power *= int64(prime)
			}
			result = append(result, factor{prime, exp, power})
		}
		return result
	}

	// For each prime, k is fixed modulo prime^knownExp[prime].
	knownExp := make([]int, n+1)
	knownResidue := make([]int64, n+1)

	visited := make([]bool, n)
	answer := make([]int, n)

	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		cycle := make([]int, 0)
		cur := start
		for !visited[cur] {
			visited[cur] = true
			cycle = append(cycle, cur)
			cur = p[cur]
		}

		length := len(cycle)
		factors := factorize(length)

		// Reconstruct the already fixed residue modulo gcd(M, length),
		// where M is the LCM of previously processed cycle lengths.
		var residue int64
		modulus := int64(1)

		for _, f := range factors {
			commonExp := f.exp
			if knownExp[f.prime] < commonExp {
				commonExp = knownExp[f.prime]
			}
			if commonExp == 0 {
				continue
			}

			commonPower := int64(1)
			for i := 0; i < commonExp; i++ {
				commonPower *= int64(f.prime)
			}
			target := knownResidue[f.prime] % commonPower

			delta := (target - residue) % commonPower
			if delta < 0 {
				delta += commonPower
			}
			inverse := modInverse(modulus%commonPower, commonPower)
			coefficient := delta * inverse % commonPower

			residue += modulus * coefficient
			modulus *= commonPower
		}

		// Feasible exponents are residue + q * modulus modulo length.
		bestExponent := int(residue)
		bestValue := a[cycle[bestExponent]]
		for exponent := bestExponent + int(modulus); exponent < length; exponent += int(modulus) {
			value := a[cycle[exponent]]
			if value < bestValue {
				bestValue = value
				bestExponent = exponent
			}
		}

		// This cycle's final values are now determined.
		for i, position := range cycle {
			answer[position] = a[cycle[(i+bestExponent)%length]]
		}

		// Add k ≡ bestExponent (mod length) to the prime-power constraints.
		for _, f := range factors {
			if f.exp > knownExp[f.prime] {
				knownExp[f.prime] = f.exp
				knownResidue[f.prime] = int64(bestExponent) % f.power
			}
		}
	}

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}
