package main

import (
	"bufio"
	"fmt"
	"os"
)

const limit = 10

type DSU struct {
	parent []int
	size   []int
	count  []int
	top    [][limit]int
}

func NewDSU(n int) *DSU {
	d := &DSU{
		parent: make([]int, n+1),
		size:   make([]int, n+1),
		count:  make([]int, n+1),
		top:    make([][limit]int, n+1),
	}
	for i := 1; i <= n; i++ {
		d.parent[i] = i
		d.size[i] = 1
		d.count[i] = 1
		d.top[i][0] = i
	}
	return d
}

func (d *DSU) Find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.Find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) Union(a, b int) {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return
	}
	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}

	d.parent[rb] = ra
	d.size[ra] += d.size[rb]

	var merged [limit]int
	i, j, m := 0, 0, 0
	for m < limit && (i < d.count[ra] || j < d.count[rb]) {
		if j >= d.count[rb] || (i < d.count[ra] && d.top[ra][i] > d.top[rb][j]) {
			merged[m] = d.top[ra][i]
			i++
		} else {
			merged[m] = d.top[rb][j]
			j++
		}
		m++
	}
	d.top[ra] = merged
	d.count[ra] = m
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	fmt.Fscan(in, &n, &q)

	dsu := NewDSU(n)

	for ; q > 0; q-- {
		var queryType, a, b int
		fmt.Fscan(in, &queryType, &a, &b)

		if queryType == 1 {
			dsu.Union(a, b)
		} else {
			root := dsu.Find(a)
			k := b
			if dsu.count[root] < k {
				fmt.Fprintln(out, -1)
			} else {
				fmt.Fprintln(out, dsu.top[root][k-1])
			}
		}
	}
}
