	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var c byte

	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b >= '0' && b <= '9' {
			c = b
			break
		}
	}

	n = int64(c - '0')
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b < '0' || b > '9' {
			return n
		}
		n = n*10 + int64(b-'0')
	}
}

func main() {
	in := NewFastScanner()
	n := int(in.NextInt64())
	k := int(in.NextInt64())

	a := make([]int64, n)
	var total int64
	for i := 0; i < n; i++ {
		a[i] = in.NextInt64()
		total += a[i]
	}

	m := 2 * n
	head := make([]int, m+1)
	sibling := make([]int, m)
	stackNode := make([]int, m+1)
	stackEdge := make([]int, m+1)

	countEligible := func(x int64, stopAtOne bool) int {
		for i := 0; i <= m; i++ {
			head[i] = -1
		}

		right := 0
		var sum int64

		for left := 0; left < m; left++ {
			for right < m && sum < x {
				sum += a[right%n]
				right++
			}

			parent := m
			if sum >= x {
				parent = right
			}

			sibling[left] = head[parent]
			head[parent] = left

			if right > left {
				sum -= a[left%n]
			}
		}

		count := 0
		top := 0
		stackNode[0] = m
		stackEdge[0] = head[m]

		for top >= 0 {
			edge := stackEdge[top]
			if edge == -1 {
				top--
				continue
			}

			stackEdge[top] = sibling[edge]

			child := edge
			top++
			stackNode[top] = child
			stackEdge[top] = head[child]

			if child < n && top >= k {
				end := stackNode[top-k]
				if end <= child+n {
					count++
					if stopAtOne {
						return count
					}
				}
			}
		}

		return count
	}

	low := int64(0)
	high := total/int64(k) + 1

	for high-low > 1 {
		mid := (low + high) / 2
		if countEligible(mid, true) > 0 {
			low = mid
		} else {
			high = mid
		}
	}

	cuttable := countEligible(low, false)
	neverCut := n - cuttable

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintf(out, "%d %d\n", low, neverCut)
}
