package main

import (
	"bufio"
	"fmt"
	"os"
)

const maxK = 10

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type DSU struct {
	parent []int
	size   []int
	count  []int
	top    [][maxK]int
}

func NewDSU(n int) *DSU {
	d := &DSU{
		parent: make([]int, n+1),
		size:   make([]int, n+1),
		count:  make([]int, n+1),
		top:    make([][maxK]int, n+1),
	}
	for i := 1; i <= n; i++ {
		d.parent[i] = i
		d.size[i] = 1
		d.count[i] = 1
		d.top[i][0] = i
	}
	return d
}

func (d *DSU) Find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.Find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) Union(a, b int) {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return
	}
	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}

	var merged [maxK]int
	i, j, m := 0, 0, 0
	for m < maxK && (i < d.count[ra] || j < d.count[rb]) {
		if j >= d.count[rb] || (i < d.count[ra] && d.top[ra][i] > d.top[rb][j]) {
			merged[m] = d.top[ra][i]
			i++
		} else {
			merged[m] = d.top[rb][j]
			j++
		}
		m++
	}

	d.parent[rb] = ra
	d.size[ra] += d.size[rb]
	d.top[ra] = merged
	d.count[ra] = m
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()
	dsu := NewDSU(n)

	for ; q > 0; q-- {
		queryType := in.NextInt()
		if queryType == 1 {
			u := in.NextInt()
			v := in.NextInt()
			dsu.Union(u, v)
		} else {
			v := in.NextInt()
			k := in.NextInt()
			root := dsu.Find(v)
			if dsu.count[root] < k {
				fmt.Fprintln(out, -1)
			} else {
				fmt.Fprintln(out, dsu.top[root][k-1])
			}
		}
	}
}
