```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

type Result struct {
	total int64
	bad   int64
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var N int64
	var M int
	fmt.Fscan(in, &N, &M)

	sqrtN := int64(0)
	for (sqrtN+1)*(sqrtN+1) <= N {
		sqrtN++
	}
	for sqrtN*sqrtN > N {
		sqrtN--
	}
	S := int(sqrtN)

	// Enumerate primes up to sqrt(N).
	isComposite := make([]bool, S+1)
	primes := make([]int, 0)
	for i := 2; i <= S; i++ {
		if !isComposite[i] {
			primes = append(primes, i)
			if int64(i)*int64(i) <= int64(S) {
				for j := i * i; j <= S; j += i {
					isComposite[j] = true
				}
			}
		}
	}

	// Distinct values floor(N/i), in descending order.
	values := make([]int64, 0, 2*S+5)
	smallID := make([]int, S+1)
	largeID := make([]int, S+1)

	for l := int64(1); l <= N; {
		v := N / l
		r := N / v
		idx := len(values)
		values = append(values, v)
		if v <= sqrtN {
			smallID[int(v)] = idx
		} else {
			largeID[int(N/v)] = idx
		}
		l = r + 1
	}

	getID := func(x int64) int {
		if x <= sqrtN {
			return smallID[int(x)]
		}
		return largeID[int(N/x)]
	}

	// primeCount[x] and primeChi[x], where
	// chi(n) = 0 if 3|n, 1 if n=1 mod 3, -1 if n=2 mod 3.
	primeCount := make([]int64, len(values))
	primeChi := make([]int64, len(values))

	for i, v := range values {
		primeCount[i] = v - 1 // Integers in [2, v].

		// Sum chi(k), 1 <= k <= v, equals 1 iff v mod 3 == 1.
		sum := int64(0)
		if v%3 == 1 {
			sum = 1
		}
		primeChi[i] = sum - 1 // Exclude k=1.
	}

	for _, pi := range primes {
		p := int64(pi)
		p2 := p * p
		if p2 > N {
			break
		}

		preID := getID(p - 1)
		preCount := primeCount[preID]
		preChi := primeChi[preID]

		var chiP int64
		switch p % 3 {
		case 1:
			chiP = 1
		case 2:
			chiP = -1
		default:
			chiP = 0
		}

		for i, v := range values {
			if v < p2 {
				break
			}
			divID := getID(v / p)
			primeCount[i] -= primeCount[divID] - preCount
			primeChi[i] -= chiP * (primeChi[divID] - preChi)
		}
	}

	getPrimeStats := func(x int64) (int64, int64) {
		if x < 2 {
			return 0, 0
		}
		id := getID(x)
		return primeCount[id], primeChi[id]
	}

	// Number of primes <= x whose first power is allowed in a "bad"
	// integer: p=3 or p=1 mod 3.
	badPrimeCount := func(x int64) int64 {
		if x < 2 {
			return 0
		}
		cnt, chi := getPrimeStats(x)
		hasThree := int64(0)
		if x >= 3 {
			hasThree = 1
		}
		return hasThree + (cnt-hasThree+chi)/2
	}

	// c[e] = C(M+e-1, e), the number of ways to distribute a prime's
	// exponent e among M ordered factors.
	maxExp := 0
	for x := N; x >= 2; x /= 2 {
		maxExp++
	}
	coef := make([]int64, maxExp+1)
	coef[0] = 1
	for e := 1; e <= maxExp; e++ {
		numerator := (int64(M) + int64(e) - 1) % MOD
		coef[e] = coef[e-1] * numerator % MOD
		coef[e] = coef[e] * modPow(int64(e), MOD-2) % MOD
	}

	allowedBadPower := func(p int64, e int) bool {
		if p == 3 {
			return true
		}
		if p%3 == 1 {
			return e%3 != 2
		}
		return e%2 == 0
	}

	mMod := int64(M) % MOD

	var dfs func(int64, int) Result
	dfs = func(n int64, idx int) Result {
		if idx >= len(primes) || int64(primes[idx]) > n {
			return Result{total: 1, bad: 1}
		}

		prev := int64(1)
		if idx > 0 {
			prev = int64(primes[idx-1])
		}

		cntN, _ := getPrimeStats(n)
		cntPrev, _ := getPrimeStats(prev)
		primeDelta := cntN - cntPrev

		badDelta := badPrimeCount(n) - badPrimeCount(prev)

		res := Result{
			total: (1 + (primeDelta%MOD)*mMod) % MOD,
			bad:   (1 + (badDelta%MOD)*mMod) % MOD,
		}

		for i := idx; i < len(primes); i++ {
			p := int64(primes[i])
			if p*p > n {
				break
			}

			power := p
			for e := 1; e <= maxExp && power <= n; e++ {
				sub := dfs(n/power, i+1)

				totalSub := sub.total
				badSub := sub.bad
				if e == 1 {
					totalSub--
					badSub--
					if totalSub < 0 {
						totalSub += MOD
					}
					if badSub < 0 {
						badSub += MOD
					}
				}

				res.total += coef[e] * totalSub % MOD
				if res.total >= MOD {
					res.total -= MOD
				}

				if allowedBadPower(p, e) {
					res.bad += coef[e] * badSub % MOD
					if res.bad >= MOD {
						res.bad -= MOD
					}
				}

				if power > n/p {
					break
				}
				power *= p
			}
		}

		return res
	}

	result := dfs(N, 0)
	answer := result.total - result.bad
	answer %= MOD
	if answer < 0 {
		answer += MOD
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
