```go
package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

const MOD int64 = 998244353

type Counts struct {
	r [3]int64
}

type Pair struct {
	total int64
	bad   int64
}

type Solver struct {
	n       int64
	root    int
	primes  []int64
	values  []int64
	counts  []Counts
	idSmall []int
	idLarge []int
	weight  []int64
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func floorSqrt(n int64) int {
	r := int64(math.Sqrt(float64(n)))
	for (r+1)*(r+1) <= n {
		r++
	}
	for r*r > n {
		r--
	}
	return int(r)
}

func generatePrimes(limit int) []int64 {
	if limit < 2 {
		return nil
	}
	composite := make([]bool, limit+1)
	primes := make([]int64, 0)
	for i := 2; i <= limit; i++ {
		if !composite[i] {
			primes = append(primes, int64(i))
			if i <= limit/i {
				for j := i * i; j <= limit; j += i {
					composite[j] = true
				}
			}
		}
	}
	return primes
}

func (s *Solver) getID(x int64) int {
	if x <= int64(s.root) {
		return s.idSmall[int(x)]
	}
	return s.idLarge[int(s.n/x)]
}

func (s *Solver) getCounts(x int64) Counts {
	return s.counts[s.getID(x)]
}

func (s *Solver) buildPrimeCounts() {
	for l := int64(1); l <= s.n; {
		v := s.n / l
		idx := len(s.values)
		s.values = append(s.values, v)

		if v <= int64(s.root) {
			s.idSmall[int(v)] = idx
		} else {
			s.idLarge[int(s.n/v)] = idx
		}

		var c Counts
		c.r[0] = v / 3
		c.r[1] = (v+2)/3 - 1 // Exclude 1.
		c.r[2] = (v + 1) / 3
		s.counts = append(s.counts, c)

		l = s.n/v + 1
	}

	for _, p := range s.primes {
		p2 := p * p
		base := s.getCounts(p - 1)
		pm := int(p % 3)

		for idx, v := range s.values {
			if v < p2 {
				break
			}

			source := s.getCounts(v / p)
			target := &s.counts[idx]

			d0 := source.r[0] - base.r[0]
			d1 := source.r[1] - base.r[1]
			d2 := source.r[2] - base.r[2]

			target.r[(0*pm)%3] -= d0
			target.r[(1*pm)%3] -= d1
			target.r[(2*pm)%3] -= d2
		}
	}
}

func (s *Solver) badPrimePowerWeight(p int64, e int) int64 {
	switch p % 3 {
	case 0:
		return s.weight[e]
	case 1:
		if e%3 == 2 {
			return 0
		}
		return s.weight[e]
	default:
		if e%2 == 1 {
			return 0
		}
		return s.weight[e]
	}
}

// dfs returns sums over integers k in [2, x] whose prime factors are all
// at least primes[start].
func (s *Solver) dfs(x int64, start int) Pair {
	cur := s.getCounts(x)
	var prev Counts
	if start > 0 {
		prev = s.getCounts(s.primes[start-1])
	}

	totalPrimeCount := (cur.r[0] + cur.r[1] + cur.r[2]) -
		(prev.r[0] + prev.r[1] + prev.r[2])
	badPrimeCount := (cur.r[0] + cur.r[1]) -
		(prev.r[0] + prev.r[1])

	m := s.weight[1]
	ans := Pair{
		total: (totalPrimeCount % MOD) * m % MOD,
		bad:   (badPrimeCount % MOD) * m % MOD,
	}

	for i := start; i < len(s.primes); i++ {
		p := s.primes[i]
		if p*p > x {
			break
		}

		pe := p
		e := 1
		for pe*p <= x {
			child := s.dfs(x/pe, i+1)

			totalWeight := s.weight[e]
			badWeight := s.badPrimePowerWeight(p, e)
			nextTotalWeight := s.weight[e+1]
			nextBadWeight := s.badPrimePowerWeight(p, e+1)

			ans.total += totalWeight*child.total%MOD + nextTotalWeight
			ans.total %= MOD

			ans.bad += badWeight*child.bad%MOD + nextBadWeight
			ans.bad %= MOD

			pe *= p
			e++
		}
	}

	return ans
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int64
	var m int
	fmt.Fscan(in, &n, &m)

	root := floorSqrt(n)
	s := &Solver{
		n:       n,
		root:    root,
		primes:  generatePrimes(root),
		idSmall: make([]int, root+1),
		idLarge: make([]int, root+1),
		weight:  make([]int64, 64),
	}

	s.weight[0] = 1
	for e := 1; e < len(s.weight); e++ {
		numerator := (int64(m) + int64(e) - 1) % MOD
		s.weight[e] = s.weight[e-1] * numerator % MOD
		s.weight[e] = s.weight[e] * modPow(int64(e), MOD-2) % MOD
	}

	s.buildPrimeCounts()
	result := s.dfs(n, 0)

	answer := (result.total - result.bad) % MOD
	if answer < 0 {
		answer += MOD
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
