package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, k int
	fmt.Fscan(in, &n, &m, &k)

	x := make([]int, m)
	y := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &x[i], &y[i])
		x[i]--
		y[i]--
	}

	// dp[v] is stored at state[(v-offset) mod n].
	state := make([]int64, n)
	state[0] = 1

	sourceValues := make([]int64, m)
	offset := 0
	total := int64(1)

	for step := 0; step < k; step++ {
		var extra int64

		// Save all values before performing this step.
		for i := 0; i < m; i++ {
			idx := x[i] - offset
			if idx < 0 {
				idx += n
			}
			sourceValues[i] = state[idx]
			extra += sourceValues[i]
			if extra >= mod {
				extra -= mod
			}
		}

		// Every cycle edge moves v to v+1.
		offset++
		if offset == n {
			offset = 0
		}

		// Add transitions through the extra edges.
		for i := 0; i < m; i++ {
			idx := y[i] - offset
			if idx < 0 {
				idx += n
			}
			state[idx] += sourceValues[i]
			if state[idx] >= mod {
				state[idx] -= mod
			}
		}

		total += extra
		if total >= mod {
			total -= mod
		}
	}

	fmt.Fprintln(out, total)
}
