package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Candidate struct {
	v   int64
	idx int
}

func lowerBound(a []int64, left int, x int64) int {
	lo, hi := left, len(a)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if a[mid] >= x {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	var k int64
	fmt.Fscan(in, &n, &m, &k)

	candidates := make([]Candidate, n)
	var counted int64
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &candidates[i].v)
		candidates[i].idx = i
		counted += candidates[i].v
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	if m == n {
		for i := 0; i < n; i++ {
			if i > 0 {
				fmt.Fprint(out, " ")
			}
			fmt.Fprint(out, 0)
		}
		fmt.Fprintln(out)
		return
	}

	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].v == candidates[j].v {
			return candidates[i].idx < candidates[j].idx
		}
		return candidates[i].v < candidates[j].v
	})

	values := make([]int64, n)
	rank := make([]int, n)
	prefix := make([]int64, n+1)
	for i, c := range candidates {
		values[i] = c.v
		rank[c.idx] = i
		prefix[i+1] = prefix[i] + c.v
	}

	remaining := k - counted
	answer := make([]int64, n)
	cutoff := n - m

	costSuffix := func(left int, target int64) int64 {
		pos := lowerBound(values, left, target)
		return target*int64(pos-left) - (prefix[pos] - prefix[left])
	}

	for original := 0; original < n; original++ {
		p := rank[original]
		base := values[p]

		guaranteed := func(x int64) bool {
			target := base + x + 1
			var cost int64

			if p < cutoff {
				// Candidate is not among the current top M candidates.
				cost = costSuffix(cutoff, target)
			} else {
				// Take the top M+1 candidates, then exclude this candidate.
				cost = costSuffix(cutoff-1, target)
				if target > base {
					cost -= target - base
				}
			}

			return cost > remaining-x
		}

		if !guaranteed(remaining) {
			answer[original] = -1
			continue
		}

		lo, hi := int64(-1), remaining
		for hi-lo > 1 {
			mid := lo + (hi-lo)/2
			if guaranteed(mid) {
				hi = mid
			} else {
				lo = mid
			}
		}
		answer[original] = hi
	}

	for i, v := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v)
	}
	fmt.Fprintln(out)
}
