	return math.Hypot(a.x-b.x, a.y-b.y)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s, t float64
	fmt.Fscan(in, &n, &s, &t)

	segments := make([]Segment, n)
	for i := 0; i < n; i++ {
		var ax, ay, bx, by float64
		fmt.Fscan(in, &ax, &ay, &bx, &by)
		segments[i] = Segment{
			a:      Point{ax, ay},
			b:      Point{bx, by},
			length: math.Hypot(ax-bx, ay-by),
		}
	}

	best := math.Inf(1)

	var dfs func(mask int, current Point, elapsed float64)
	dfs = func(mask int, current Point, elapsed float64) {
		if elapsed >= best {
			return
		}
		if mask == (1<<n)-1 {
			best = elapsed
			return
		}

		for i, seg := range segments {
			if mask&(1<<i) != 0 {
				continue
			}

			// Print from endpoint a to endpoint b.
			timeAB := elapsed + distance(current, seg.a)/s + seg.length/t
			dfs(mask|(1<<i), seg.b, timeAB)

			// Print from endpoint b to endpoint a.
			timeBA := elapsed + distance(current, seg.b)/s + seg.length/t
			dfs(mask|(1<<i), seg.a, timeBA)
		}
	}

	dfs(0, Point{0, 0}, 0)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintf(out, "%.15f\n", best)
