package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

type Point struct {
	x, y float64
}

func distance(a, b Point) float64 {
	return math.Hypot(a.x-b.x, a.y-b.y)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s, t float64
	fmt.Fscan(in, &n, &s, &t)

	segments := make([][2]Point, n)
	drawingTime := 0.0

	for i := 0; i < n; i++ {
		var a, b, c, d float64
		fmt.Fscan(in, &a, &b, &c, &d)
		segments[i][0] = Point{a, b}
		segments[i][1] = Point{c, d}
		drawingTime += distance(segments[i][0], segments[i][1]) / t
	}

	size := 1 << n
	inf := math.Inf(1)

	// dp[mask][i][orientation] is the minimum non-printing travel time
	// after printing segment i last. orientation is the endpoint from
	// which segment i was started, so the current position is orientation^1.
	dp := make([][][2]float64, size)
	for mask := 0; mask < size; mask++ {
		dp[mask] = make([][2]float64, n)
		for i := 0; i < n; i++ {
			dp[mask][i][0] = inf
			dp[mask][i][1] = inf
		}
	}

	origin := Point{0, 0}
	for i := 0; i < n; i++ {
		for orientation := 0; orientation < 2; orientation++ {
			dp[1<<i][i][orientation] = distance(origin, segments[i][orientation]) / s
		}
	}

	for mask := 1; mask < size; mask++ {
		for last := 0; last < n; last++ {
			if mask&(1<<last) == 0 {
				continue
			}
			for orientation := 0; orientation < 2; orientation++ {
				currentTime := dp[mask][last][orientation]
				if math.IsInf(currentTime, 1) {
					continue
				}

				currentPosition := segments[last][orientation^1]

				for next := 0; next < n; next++ {
					if mask&(1<<next) != 0 {
						continue
					}
					nextMask := mask | (1 << next)

					for nextOrientation := 0; nextOrientation < 2; nextOrientation++ {
						travelTime := distance(currentPosition, segments[next][nextOrientation]) / s
						candidate := currentTime + travelTime
						if candidate < dp[nextMask][next][nextOrientation] {
							dp[nextMask][next][nextOrientation] = candidate
						}
					}
				}
			}
		}
	}

	minTravelTime := inf
	fullMask := size - 1
	for last := 0; last < n; last++ {
		for orientation := 0; orientation < 2; orientation++ {
			minTravelTime = math.Min(minTravelTime, dp[fullMask][last][orientation])
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintf(out, "%.20f\n", drawingTime+minTravelTime)
}
