package main

import (
	"bufio"
	"fmt"
	"os"
)

type Process struct {
	a, p, b, q int64
}

func minCost(w int64, m Process) int64 {
	const inf int64 = 1 << 62
	best := inf

	for s := int64(0); s < m.b; s++ {
		remaining := w - s*m.a
		t := int64(0)
		if remaining > 0 {
			t = (remaining + m.b - 1) / m.b
		}
		cost := s*m.p + t*m.q
		if cost < best {
			best = cost
		}
	}

	for t := int64(0); t < m.a; t++ {
		remaining := w - t*m.b
		s := int64(0)
		if remaining > 0 {
			s = (remaining + m.a - 1) / m.a
		}
		cost := s*m.p + t*m.q
		if cost < best {
			best = cost
		}
	}

	return best
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var x int64
	fmt.Fscan(in, &n, &x)

	processes := make([]Process, n)
	for i := range processes {
		fmt.Fscan(in, &processes[i].a, &processes[i].p, &processes[i].b, &processes[i].q)
	}

	feasible := func(w int64) bool {
		var total int64
		for _, process := range processes {
			total += minCost(w, process)
			if total > x {
				return false
			}
		}
		return true
	}

	var low int64
	high := int64(1_000_000_001)

	for high-low > 1 {
		mid := low + (high-low)/2
		if feasible(mid) {
			low = mid
		} else {
			high = mid
		}
	}

	fmt.Fprintln(out, low)
}
