package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Line struct {
	m int64
	b int64
}

func value(line Line, x int64) int64 {
	return line.m*x + line.b
}

func redundant(a, b, c Line) bool {
	return (a.b-b.b)*(c.m-b.m) >= (b.b-c.b)*(b.m-a.m)
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	W := int(in.NextInt64())

	dp := make([]int64, W+1)
	next := make([]int64, W+1)
	hull := make([]Line, W+1)

	for i := 0; i < n; i++ {
		w := int(in.NextInt64())
		v := in.NextInt64()

		for r := 0; r < w && r <= W; r++ {
			head, tail := 0, 0
			t := 0

			for j := r; j <= W; j += w {
				s := int64(t)
				line := Line{
					m: 2 * s,
					b: dp[j] - s*v - s*s,
				}

				for tail-head >= 2 && redundant(hull[tail-2], hull[tail-1], line) {
					tail--
				}
				hull[tail] = line
				tail++

				for tail-head >= 2 &&
					value(hull[head], s) <= value(hull[head+1], s) {
					head++
				}

				next[j] = s*v - s*s + value(hull[head], s)
				t++
			}
		}

		dp, next = next, dp
	}

	fmt.Fprintln(out, dp[W])
}
