package main

import (
	"bufio"
	"fmt"
	"os"
)

type Process struct {
	a, p, b, q int64
}

func minCost(w int64, proc Process) int64 {
	best := int64(1 << 62)

	// Enumerate the number of S machines over a sufficient bounded range.
	for s := int64(0); s <= proc.b; s++ {
		remaining := w - s*proc.a
		t := int64(0)
		if remaining > 0 {
			t = (remaining + proc.b - 1) / proc.b
		}
		cost := s*proc.p + t*proc.q
		if cost < best {
			best = cost
		}
	}

	// Enumerate the number of T machines over a sufficient bounded range.
	for t := int64(0); t <= proc.a; t++ {
		remaining := w - t*proc.b
		s := int64(0)
		if remaining > 0 {
			s = (remaining + proc.a - 1) / proc.a
		}
		cost := s*proc.p + t*proc.q
		if cost < best {
			best = cost
		}
	}

	return best
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var x int64
	fmt.Fscan(in, &n, &x)

	processes := make([]Process, n)
	for i := range processes {
		fmt.Fscan(in, &processes[i].a, &processes[i].p,
			&processes[i].b, &processes[i].q)
	}

	canAchieve := func(w int64) bool {
		totalCost := int64(0)
		for _, proc := range processes {
			totalCost += minCost(w, proc)
			if totalCost > x {
				return false
			}
		}
		return true
	}

	low, high := int64(0), int64(1_000_000_001)
	for high-low > 1 {
		mid := low + (high-low)/2
		if canAchieve(mid) {
			low = mid
		} else {
			high = mid
		}
	}

	fmt.Fprintln(out, low)
}
