package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Line struct {
	a, b, k int64
}

type HullLine struct {
	line           Line
	startNum       int64
	startDen       int64
}

func cmpUint128(ahi, alo, bhi, blo uint64) int {
	if ahi < bhi {
		return -1
	}
	if ahi > bhi {
		return 1
	}
	if alo < blo {
		return -1
	}
	if alo > blo {
		return 1
	}
	return 0
}

// Returns whether n1/d1 <= n2/d2, where d1,d2 > 0.
func fracLE(n1, d1, n2, d2 int64) bool {
	if n1 < 0 && n2 >= 0 {
		return true
	}
	if n1 >= 0 && n2 < 0 {
		return false
	}

	if n1 >= 0 {
		h1, l1 := bits.Mul64(uint64(n1), uint64(d2))
		h2, l2 := bits.Mul64(uint64(n2), uint64(d1))
		return cmpUint128(h1, l1, h2, l2) <= 0
	}

	u1 := uint64(-n1)
	u2 := uint64(-n2)
	h1, l1 := bits.Mul64(u1, uint64(d2))
	h2, l2 := bits.Mul64(u2, uint64(d1))
	return cmpUint128(h1, l1, h2, l2) >= 0
}

func ceilDiv(n, d int64) int64 {
	if n >= 0 {
		return (n + d - 1) / d
	}
	return n / d
}

func triangular(n int64) int64 {
	if n%2 == 0 {
		return (n / 2) * (n - 1)
	}
	return n * ((n - 1) / 2)
}

// Computes sum_{i=0}^{n-1} floor((a*i+b)/m), with nonnegative arguments.
func floorSum(n, m, a, b int64) int64 {
	var ans int64
	for {
		if a >= m {
			ans += triangular(n) * (a / m)
			a %= m
		}
		if b >= m {
			ans += n * (b / m)
			b %= m
		}

		yMax := a*n + b
		if yMax < m {
			break
		}

		n = yMax / m
		b = yMax % m
		m, a = a, m
	}
	return ans
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	T := int(in.NextInt64())
	for ; T > 0; T-- {
		n := int(in.NextInt64())
		lines := make([]Line, 0, n)
		possible := true
		var maxX int64 = 1<<63 - 1

		for i := 0; i < n; i++ {
			a := in.NextInt64()
			b := in.NextInt64()
			c := in.NextInt64()
			k := c - 1 - a - b

			if k < 0 {
				possible = false
			}
			if k >= 0 {
				x := k / a
				if x < maxX {
					maxX = x
				}
			}
			lines = append(lines, Line{a: a, b: b, k: k})
		}

		if !possible {
			fmt.Fprintln(out, 0)
			continue
		}

		sort.Slice(lines, func(i, j int) bool {
			left := lines[i].a * lines[j].b
			right := lines[j].a * lines[i].b
			if left != right {
				return left < right
			}
			return lines[i].k*lines[j].b < lines[j].k*lines[i].b
		})

		unique := make([]Line, 0, len(lines))
		for _, ln := range lines {
			if len(unique) == 0 {
				unique = append(unique, ln)
				continue
			}
			last := unique[len(unique)-1]
			if ln.a*last.b == last.a*ln.b {
				if ln.k*last.b < last.k*ln.b {
					unique[len(unique)-1] = ln
				}
			} else {
				unique = append(unique, ln)
			}
		}

		hull := make([]HullLine, 0, len(unique))
		for _, ln := range unique {
			for {
				if len(hull) == 0 {
					hull = append(hull, HullLine{line: ln})
					break
				}

				prev := hull[len(hull)-1].line
				num := ln.k*prev.b - prev.k*ln.b
				den := ln.a*prev.b - prev.a*ln.b

				if len(hull) > 1 {
					last := hull[len(hull)-1]
					if fracLE(num, den, last.startNum, last.startDen) {
						hull = hull[:len(hull)-1]
						continue
					}
				}

				hull = append(hull, HullLine{
					line:     ln,
					startNum: num,
					startDen: den,
				})
				break
			}
		}

		var answer int64
		for i := 0; i < len(hull); i++ {
			var left int64
			if i > 0 {
				left = ceilDiv(hull[i].startNum, hull[i].startDen)
			}

			right := maxX
			if i+1 < len(hull) {
				right = ceilDiv(hull[i+1].startNum, hull[i+1].startDen) - 1
				if right > maxX {
					right = maxX
				}
			}

			if left < 0 {
				left = 0
			}
			if left > right {
				continue
			}

			ln := hull[i].line
			count := right - left + 1
			base := ln.k - ln.a*right
			answer += floorSum(count, ln.b, ln.a, base) + count
		}

		fmt.Fprintln(out, answer)
	}
}
