package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Point struct {
	x, y  int64
	color int // 0: P, 1: Q
	index int
}

func cross(ax, ay, bx, by int64) int64 {
	return ax*by - ay*bx
}

func solve(points []Point, answer []int) {
	if len(points) == 0 {
		return
	}

	pivotPos := 0
	for i := 1; i < len(points); i++ {
		if points[i].x < points[pivotPos].x ||
			(points[i].x == points[pivotPos].x && points[i].y < points[pivotPos].y) {
			pivotPos = i
		}
	}
	pivot := points[pivotPos]

	others := make([]Point, 0, len(points)-1)
	for i, p := range points {
		if i != pivotPos {
			others = append(others, p)
		}
	}

	sort.Slice(others, func(i, j int) bool {
		ax := others[i].x - pivot.x
		ay := others[i].y - pivot.y
		bx := others[j].x - pivot.x
		by := others[j].y - pivot.y
		return cross(ax, ay, bx, by) > 0
	})

	balance := 0
	matePos := -1
	for i, p := range others {
		if p.color != pivot.color && balance == 0 {
			matePos = i
			break
		}
		if p.color == pivot.color {
			balance++
		} else {
			balance--
		}
	}

	mate := others[matePos]
	if pivot.color == 0 {
		answer[pivot.index] = mate.index
	} else {
		answer[mate.index] = pivot.index
	}

	solve(others[:matePos], answer)
	solve(others[matePos+1:], answer)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	points := make([]Point, 0, 2*n)
	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)
		points = append(points, Point{x: x, y: y, color: 0, index: i})
	}
	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)
		points = append(points, Point{x: x, y: y, color: 1, index: i})
	}

	answer := make([]int, n)
	solve(points, answer)

	for i, v := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v+1)
	}
	fmt.Fprintln(out)
}
