package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

const inf int64 = 1 << 62

func prune(states map[int64]int64) {
	times := make([]int64, 0, len(states))
	for t := range states {
		times = append(times, t)
	}
	sort.Slice(times, func(i, j int) bool {
		return times[i] < times[j]
	})

	bestCost := inf
	for _, t := range times {
		cost := states[t]
		if cost >= bestCost {
			delete(states, t)
		} else {
			bestCost = cost
		}
	}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, k int
	var x int64
	fmt.Fscan(in, &n, &k, &x)

	t := make([]int64, n)
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &t[i])
		prefix[i+1] = prefix[i] + t[i]
	}

	// dp[i][s] is the minimum dissatisfaction after shipping the first i
	// orders, where the latest shipment was made on day s.
	dp := make([]map[int64]int64, n+1)
	for i := range dp {
		dp[i] = make(map[int64]int64)
	}

	// The first shipment contains orders 1 through j.
	firstLimit := k
	if firstLimit > n {
		firstLimit = n
	}
	for j := 1; j <= firstLimit; j++ {
		shipDay := t[j-1]
		cost := int64(j)*shipDay - prefix[j]
		dp[j][shipDay] = cost
	}

	for i := 1; i < n; i++ {
		if len(dp[i]) == 0 {
			continue
		}
		prune(dp[i])

		maxLen := k
		if n-i < maxLen {
			maxLen = n - i
		}

		for lastDay, currentCost := range dp[i] {
			for length := 1; length <= maxLen; length++ {
				j := i + length
				shipDay := lastDay + x
				if t[j-1] > shipDay {
					shipDay = t[j-1]
				}

				orderSum := prefix[j] - prefix[i]
				newCost := currentCost + int64(length)*shipDay - orderSum

				oldCost, exists := dp[j][shipDay]
				if !exists || newCost < oldCost {
					dp[j][shipDay] = newCost
				}
			}
		}
	}

	answer := inf
	for _, cost := range dp[n] {
		if cost < answer {
			answer = cost
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
