			pos++
		}

		for c := 0; c < n; c++ {
			color := data[pos+c]

			layer := r
			if c < layer {
				layer = c
			}
			if n-1-r < layer {
				layer = n - 1 - r
			}
			if n-1-c < layer {
				layer = n - 1 - c
			}

			rotations := (layer + 1) % 4
			dr, dc := r, c

			switch rotations {
			case 1:
				dr, dc = c, n-1-r
			case 2:
				dr, dc = n-1-r, n-1-c
			case 3:
				dr, dc = n-1-c, r
			}

			result[dr*n+dc] = color
		}
		pos += n
	}

	out := bufio.NewWriterSize(os.Stdout, n*n+n)
	defer out.Flush()

	for r := 0; r < n; r++ {
		out.Write(result[r*n : (r+1)*n])
		out.WriteByte('\n')
	}
}
