package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Point struct {
	x, y int64
}

type Ref struct {
	kind int // 0: P, 1: Q
	id   int
}

var (
	pPoints []Point
	qPoints []Point
	answer  []int
)

func getPoint(r Ref) Point {
	if r.kind == 0 {
		return pPoints[r.id]
	}
	return qPoints[r.id]
}

func cross(ax, ay, bx, by int64) int64 {
	return ax*by - ay*bx
}

func solve(ps, qs []int) bool {
	m := len(ps)
	if m == 0 {
		return true
	}

	// Choose the lexicographically smallest point. All other points are in
	// an angular interval of width less than pi around this point.
	pivot := Ref{kind: 0, id: ps[0]}
	pivotPoint := getPoint(pivot)

	updatePivot := func(r Ref) {
		pt := getPoint(r)
		if pt.x < pivotPoint.x || (pt.x == pivotPoint.x && pt.y < pivotPoint.y) {
			pivot = r
			pivotPoint = pt
		}
	}

	for _, id := range ps {
		updatePivot(Ref{kind: 0, id: id})
	}
	for _, id := range qs {
		updatePivot(Ref{kind: 1, id: id})
	}

	others := make([]Ref, 0, 2*m-1)
	for _, id := range ps {
		if !(pivot.kind == 0 && pivot.id == id) {
			others = append(others, Ref{kind: 0, id: id})
		}
	}
	for _, id := range qs {
		if !(pivot.kind == 1 && pivot.id == id) {
			others = append(others, Ref{kind: 1, id: id})
		}
	}

	sort.Slice(others, func(i, j int) bool {
		a := getPoint(others[i])
		b := getPoint(others[j])
		ax, ay := a.x-pivotPoint.x, a.y-pivotPoint.y
		bx, by := b.x-pivotPoint.x, b.y-pivotPoint.y
		return cross(ax, ay, bx, by) > 0
	})

	balance := 0
	candidateIndex := -1
	for i, r := range others {
		if r.kind != pivot.kind && balance == 0 {
			candidateIndex = i
			break
		}
		if r.kind == 0 {
			balance++
		} else {
			balance--
		}
	}

	if candidateIndex == -1 {
		return false
	}

	candidate := others[candidateIndex]
	if pivot.kind == 0 {
		answer[pivot.id] = candidate.id + 1
	} else {
		answer[candidate.id] = pivot.id + 1
	}

	leftP := make([]int, 0)
	leftQ := make([]int, 0)
	rightP := make([]int, 0)
	rightQ := make([]int, 0)

	for i, r := range others {
		if i == candidateIndex {
			continue
		}
		if i < candidateIndex {
			if r.kind == 0 {
				leftP = append(leftP, r.id)
			} else {
				leftQ = append(leftQ, r.id)
			}
		} else {
			if r.kind == 0 {
				rightP = append(rightP, r.id)
			} else {
				rightQ = append(rightQ, r.id)
			}
		}
	}

	if len(leftP) != len(leftQ) || len(rightP) != len(rightQ) {
		return false
	}

	return solve(leftP, leftQ) && solve(rightP, rightQ)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	pPoints = make([]Point, n)
	qPoints = make([]Point, n)
	answer = make([]int, n)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &pPoints[i].x, &pPoints[i].y)
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &qPoints[i].x, &qPoints[i].y)
	}

	ps := make([]int, n)
	qs := make([]int, n)
	for i := 0; i < n; i++ {
		ps[i] = i
		qs[i] = i
	}

	if !solve(ps, qs) {
		fmt.Fprintln(out, -1)
		return
	}

	for i, v := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v)
	}
	fmt.Fprintln(out)
}
