	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	people := make([]Person, n)
	total := 0
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &people[i].team, &people[i].strength)
		total += people[i].strength
	}

	if total%3 != 0 {
		fmt.Fprintln(out, -1)
		return
	}

	target := total / 3
	width := target + 1
	size := width * width

	dp := make([]int, size)
	next := make([]int, size)
	for i := range dp {
		dp[i] = -1
	}
	dp[0] = 0

	processed := 0
	for _, p := range people {
		for i := range next {
			next[i] = -1
		}

		for s1 := 0; s1 <= target; s1++ {
			base := s1 * width
			for s2 := 0; s2 <= target; s2++ {
				idx := base + s2
				cur := dp[idx]
				if cur < 0 {
					continue
				}

				s3 := processed - s1 - s2

				if s1+p.strength <= target {
					nextIdx := idx + p.strength*width
					value := cur
					if p.team == 1 {
						value++
					}
					if value > next[nextIdx] {
						next[nextIdx] = value
					}
				}

				if s2+p.strength <= target {
					nextIdx := idx + p.strength
					value := cur
					if p.team == 2 {
						value++
					}
					if value > next[nextIdx] {
						next[nextIdx] = value
					}
				}

				if s3+p.strength <= target {
