					if p.team == 3 {
						value++
					}
					if value > next[idx] {
						next[idx] = value
					}
				}
			}
		}

		dp, next = next, dp
		processed += p.strength
	}

	maxUnchanged := dp[target*width+target]
	if maxUnchanged < 0 {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, n-maxUnchanged)
	}
}
