package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

type Edge struct {
	a, b int
	c    int64
}

type Query struct {
	t, x, y int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, q int
	fmt.Fscan(in, &n, &m, &q)

	edges := make([]Edge, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &edges[i].a, &edges[i].b, &edges[i].c)
		edges[i].a--
		edges[i].b--
	}

	queries := make([]Query, q)
	closed := make([]bool, m)

	for i := 0; i < q; i++ {
		fmt.Fscan(in, &queries[i].t)
		if queries[i].t == 1 {
			fmt.Fscan(in, &queries[i].x)
			queries[i].x--
			closed[queries[i].x] = true
		} else {
			fmt.Fscan(in, &queries[i].x, &queries[i].y)
			queries[i].x--
			queries[i].y--
		}
	}

	dist := make([][]int64, n)
	for i := 0; i < n; i++ {
		dist[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			dist[i][j] = INF
		}
		dist[i][i] = 0
	}

	for i, e := range edges {
		if !closed[i] {
			dist[e.a][e.b] = e.c
			dist[e.b][e.a] = e.c
		}
	}

	// All-pairs shortest paths after every road that will be closed has closed.
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			if dist[i][k] == INF {
				continue
			}
			for j := 0; j < n; j++ {
				if dist[k][j] == INF {
					continue
				}
				candidate := dist[i][k] + dist[k][j]
				if candidate < dist[i][j] {
					dist[i][j] = candidate
				}
			}
		}
	}

	answers := make([]int64, q)

	// Process backwards: closing a road becomes adding it.
	for qi := q - 1; qi >= 0; qi-- {
		query := queries[qi]

		if query.t == 2 {
			answers[qi] = dist[query.x][query.y]
			continue
		}

		e := edges[query.x]
		a, b, c := e.a, e.b, e.c

		toA := make([]int64, n)
		toB := make([]int64, n)
		fromA := make([]int64, n)
		fromB := make([]int64, n)

		for i := 0; i < n; i++ {
			toA[i] = dist[i][a]
			toB[i] = dist[i][b]
			fromA[i] = dist[a][i]
			fromB[i] = dist[b][i]
		}

		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				best := dist[i][j]

				if toA[i] != INF && fromB[j] != INF {
					candidate := toA[i] + c + fromB[j]
					if candidate < best {
						best = candidate
					}
				}

				if toB[i] != INF && fromA[j] != INF {
					candidate := toB[i] + c + fromA[j]
					if candidate < best {
						best = candidate
					}
				}

				dist[i][j] = best
			}
		}
	}

	for i, query := range queries {
		if query.t == 2 {
			if answers[i] == INF {
				fmt.Fprintln(out, -1)
			} else {
				fmt.Fprintln(out, answers[i])
			}
		}
	}
}
