package main

import (
	"bufio"
	"fmt"
	"os"
)

type Item struct {
	start int
	end   int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	const V = 26
	reach := make([][]bool, V)
	for i := 0; i < V; i++ {
		reach[i] = make([]bool, V)
		reach[i][i] = true
	}

	edges := make([][2]int, n)
	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		u := int(s[0] - 'A')
		v := int(s[1] - 'A')
		edges[i] = [2]int{u, v}
		reach[u][v] = true
	}

	for k := 0; k < V; k++ {
		for i := 0; i < V; i++ {
			if !reach[i][k] {
				continue
			}
			for j := 0; j < V; j++ {
				if reach[k][j] {
					reach[i][j] = true
				}
			}
		}
	}

	comp := make([]int, V)
	for i := range comp {
		comp[i] = -1
	}
	compCount := 0
	for i := 0; i < V; i++ {
		if comp[i] != -1 {
			continue
		}
		for j := i; j < V; j++ {
			if comp[j] == -1 && reach[i][j] && reach[j][i] {
				comp[j] = compCount
			}
		}
		compCount++
	}

	compReach := make([][]bool, compCount)
	for i := 0; i < compCount; i++ {
		compReach[i] = make([]bool, compCount)
		compReach[i][i] = true
	}
	for i := 0; i < V; i++ {
		for j := 0; j < V; j++ {
			if reach[i][j] {
				compReach[comp[i]][comp[j]] = true
			}
		}
	}

	hasInternalEdge := make([]bool, compCount)
	items := make([]Item, 0, n+compCount)

	for _, e := range edges {
		a, b := comp[e[0]], comp[e[1]]
		if a == b {
			hasInternalEdge[a] = true
		} else {
			items = append(items, Item{start: a, end: b})
		}
	}
	for c := 0; c < compCount; c++ {
		if hasInternalEdge[c] {
			items = append(items, Item{start: c, end: c})
		}
	}

	m := len(items)
	matchRight := make([]int, m)
	for i := range matchRight {
		matchRight[i] = -1
	}

	var dfs func(int, []bool) bool
	dfs = func(left int, seen []bool) bool {
		for right := 0; right < m; right++ {
			if left == right ||
				!compReach[items[left].end][items[right].start] ||
				seen[right] {
				continue
			}
			seen[right] = true
			if matchRight[right] == -1 || dfs(matchRight[right], seen) {
				matchRight[right] = left
				return true
			}
		}
		return false
	}

	matching := 0
	for left := 0; left < m; left++ {
		seen := make([]bool, m)
		if dfs(left, seen) {
			matching++
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, m-matching)
}
