package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Road struct {
	a, b int
	c    int64
}

type Query struct {
	typ int
	a   int
	b   int
	ans int64
}

func addRoad(dist [][]int64, a, b int, c int64) {
	n := len(dist)

	// An already existing route no longer than this road makes it redundant.
	if dist[a][b] <= c {
		return
	}

	toA := make([]int64, n)
	toB := make([]int64, n)
	for i := 0; i < n; i++ {
		toA[i] = dist[i][a]
		toB[i] = dist[i][b]
	}

	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			best := dist[i][j]

			if toA[i] < INF && toB[j] < INF {
				candidate := toA[i] + c + toB[j]
				if candidate < best {
					best = candidate
				}
			}
			if toB[i] < INF && toA[j] < INF {
				candidate := toB[i] + c + toA[j]
				if candidate < best {
					best = candidate
				}
			}

			dist[i][j] = best
		}
	}
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	q := int(in.NextInt64())

	roads := make([]Road, m)
	for i := 0; i < m; i++ {
		roads[i] = Road{
			a: int(in.NextInt64()) - 1,
			b: int(in.NextInt64()) - 1,
			c: in.NextInt64(),
		}
	}

	queries := make([]Query, q)
	closedEventually := make([]bool, m)

	for i := 0; i < q; i++ {
		typ := int(in.NextInt64())
		if typ == 1 {
			roadID := int(in.NextInt64()) - 1
			queries[i] = Query{typ: 1, a: roadID}
			closedEventually[roadID] = true
		} else {
			x := int(in.NextInt64()) - 1
			y := int(in.NextInt64()) - 1
			queries[i] = Query{typ: 2, a: x, b: y}
		}
	}

	dist := make([][]int64, n)
	for i := 0; i < n; i++ {
		dist[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			if i == j {
				dist[i][j] = 0
			} else {
				dist[i][j] = INF
			}
		}
	}

	for i, road := range roads {
		if !closedEventually[i] {
			dist[road.a][road.b] = road.c
			dist[road.b][road.a] = road.c
		}
	}

	// Compute shortest paths after all closures.
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			if dist[i][k] == INF {
				continue
			}
			for j := 0; j < n; j++ {
				if dist[k][j] == INF {
					continue
				}
				candidate := dist[i][k] + dist[k][j]
				if candidate < dist[i][j] {
					dist[i][j] = candidate
				}
			}
		}
	}

	// Reverse time: each closure becomes a road addition.
	for i := q - 1; i >= 0; i-- {
		if queries[i].typ == 2 {
			queries[i].ans = dist[queries[i].a][queries[i].b]
		} else {
			road := roads[queries[i].a]
			addRoad(dist, road.a, road.b, road.c)
		}
	}

	for i := 0; i < q; i++ {
		if queries[i].typ == 2 {
			if queries[i].ans == INF {
				fmt.Fprintln(out, -1)
			} else {
				fmt.Fprintln(out, queries[i].ans)
			}
		}
	}
}
