package main

import (
	"bufio"
	"fmt"
	"os"
)

const inf = int(1e9)

type Edge struct {
	to, rev, cap, cost int
}

type MinCostFlow struct {
	g [][]Edge
}

func NewMinCostFlow(n int) *MinCostFlow {
	return &MinCostFlow{g: make([][]Edge, n)}
}

func (m *MinCostFlow) AddEdge(from, to, cap, cost int) {
	fwd := Edge{to: to, rev: len(m.g[to]), cap: cap, cost: cost}
	rev := Edge{to: from, rev: len(m.g[from]), cap: 0, cost: -cost}
	m.g[from] = append(m.g[from], fwd)
	m.g[to] = append(m.g[to], rev)
}

func (m *MinCostFlow) Flow(s, t, required int) int {
	n := len(m.g)
	totalFlow, totalCost := 0, 0

	for totalFlow < required {
		dist := make([]int, n)
		prevV := make([]int, n)
		prevE := make([]int, n)
		inQueue := make([]bool, n)
		for i := range dist {
			dist[i] = inf
			prevV[i] = -1
			prevE[i] = -1
		}

		queue := make([]int, 0, n)
		dist[s] = 0
		queue = append(queue, s)
		inQueue[s] = true

		for head := 0; head < len(queue); head++ {
			v := queue[head]
			inQueue[v] = false

			for i, e := range m.g[v] {
				if e.cap > 0 && dist[e.to] > dist[v]+e.cost {
					dist[e.to] = dist[v] + e.cost
					prevV[e.to] = v
					prevE[e.to] = i
					if !inQueue[e.to] {
						inQueue[e.to] = true
						queue = append(queue, e.to)
					}
				}
			}
		}

		if dist[t] == inf {
			break
		}

		add := required - totalFlow
		for v := t; v != s; v = prevV[v] {
			e := m.g[prevV[v]][prevE[v]]
			if e.cap < add {
				add = e.cap
			}
		}

		for v := t; v != s; v = prevV[v] {
			pv, pe := prevV[v], prevE[v]
			rev := m.g[pv][pe].rev
			m.g[pv][pe].cap -= add
			m.g[v][rev].cap += add
		}

		totalFlow += add
		totalCost += add * dist[t]
	}

	return totalCost
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	const letters = 26
	adj := make([][]int, letters)
	radj := make([][]int, letters)
	usedEdge := make([][]bool, letters)
	for i := range usedEdge {
		usedEdge[i] = make([]bool, letters)
	}

	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		u := int(s[0] - 'A')
		v := int(s[1] - 'A')
		usedEdge[u][v] = true
		adj[u] = append(adj[u], v)
		radj[v] = append(radj[v], u)
	}

	visited := make([]bool, letters)
	order := make([]int, 0, letters)

	var dfs1 func(int)
	dfs1 = func(v int) {
		visited[v] = true
		for _, to := range adj[v] {
			if !visited[to] {
				dfs1(to)
			}
		}
		order = append(order, v)
	}

	for v := 0; v < letters; v++ {
		if !visited[v] {
			dfs1(v)
		}
	}

	comp := make([]int, letters)
	for i := range comp {
		comp[i] = -1
	}

	var dfs2 func(int, int)
	dfs2 = func(v, id int) {
		comp[v] = id
		for _, to := range radj[v] {
			if comp[to] == -1 {
				dfs2(to, id)
			}
		}
	}

	compCount := 0
	for i := len(order) - 1; i >= 0; i-- {
		v := order[i]
		if comp[v] == -1 {
			dfs2(v, compCount)
			compCount++
		}
	}

	cross := make([][]int, compCount)
	for i := range cross {
		cross[i] = make([]int, compCount)
	}
	involved := make([]bool, compCount)
	hasCrossing := make([]bool, compCount)

	for u := 0; u < letters; u++ {
		for v := 0; v < letters; v++ {
			if !usedEdge[u][v] {
				continue
			}
			cu, cv := comp[u], comp[v]
			involved[cu] = true
			involved[cv] = true
			if cu != cv {
				cross[cu][cv]++
				hasCrossing[cu] = true
				hasCrossing[cv] = true
			}
		}
	}

	answer := 0
	for c := 0; c < compCount; c++ {
		if involved[c] && !hasCrossing[c] {
			answer++
		}
	}

	root := compCount
	superSource := compCount + 1
	superSink := compCount + 2
	mcf := NewMinCostFlow(compCount + 3)

	balance := make([]int, compCount)

	for u := 0; u < compCount; u++ {
		for v := 0; v < compCount; v++ {
			if cross[u][v] == 0 {
				continue
			}
			lower := cross[u][v]
			balance[u] -= lower
			balance[v] += lower
			mcf.AddEdge(u, v, inf, 0)
		}
	}

	for v := 0; v < compCount; v++ {
		// Starting a walk at v costs one.
		mcf.AddEdge(root, v, inf, 1)
		// Ending a walk at v costs nothing.
		mcf.AddEdge(v, root, inf, 0)
	}

	requiredFlow := 0
	for v := 0; v < compCount; v++ {
		if balance[v] > 0 {
			mcf.AddEdge(superSource, v, balance[v], 0)
			requiredFlow += balance[v]
		} else if balance[v] < 0 {
			mcf.AddEdge(v, superSink, -balance[v], 0)
		}
	}

	answer += mcf.Flow(superSource, superSink, requiredFlow)
	fmt.Fprintln(out, answer)
}
