package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

type Edge struct {
	a, b int
	w    int64
}

type GraphEdge struct {
	to int
	w  int64
}

type ShortestEdge struct {
	to int
	id int
}

type HeapNode struct {
	v    int
	dist int64
}

type MinHeap []HeapNode

func (h MinHeap) Len() int            { return len(h) }
func (h MinHeap) Less(i, j int) bool  { return h[i].dist < h[j].dist }
func (h MinHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *MinHeap) Push(x interface{}) { *h = append(*h, x.(HeapNode)) }
func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func dijkstra(start int, graph [][]GraphEdge) []int64 {
	n := len(graph)
	dist := make([]int64, n)
	for i := range dist {
		dist[i] = INF
	}
	dist[start] = 0

	pq := &MinHeap{{v: start, dist: 0}}
	heap.Init(pq)

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(HeapNode)
		if cur.dist != dist[cur.v] {
			continue
		}
		for _, e := range graph[cur.v] {
			nd := cur.dist + e.w
			if nd < dist[e.to] {
				dist[e.to] = nd
				heap.Push(pq, HeapNode{v: e.to, dist: nd})
			}
		}
	}
	return dist
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	edges := make([]Edge, m)
	graph := make([][]GraphEdge, n)

	for i := 0; i < m; i++ {
		var a, b int
		var c int64
		fmt.Fscan(in, &a, &b, &c)
		a--
		b--
		edges[i] = Edge{a: a, b: b, w: c}
		graph[a] = append(graph[a], GraphEdge{to: b, w: c})
		graph[b] = append(graph[b], GraphEdge{to: a, w: c})
	}

	distFromStart := dijkstra(0, graph)
	distFromGoal := dijkstra(n-1, graph)
	shortestDistance := distFromStart[n-1]

	// Build the undirected subgraph consisting of all edges that belong
	// to at least one shortest path from city 1 to city N.
	shortestGraph := make([][]ShortestEdge, n)
	for i, e := range edges {
		onShortestPath := false

		if distFromStart[e.a] < INF && distFromGoal[e.b] < INF &&
			distFromStart[e.a]+e.w+distFromGoal[e.b] == shortestDistance {
			onShortestPath = true
		}
		if distFromStart[e.b] < INF && distFromGoal[e.a] < INF &&
			distFromStart[e.b]+e.w+distFromGoal[e.a] == shortestDistance {
			onShortestPath = true
		}

		if onShortestPath {
			shortestGraph[e.a] = append(shortestGraph[e.a], ShortestEdge{to: e.b, id: i})
			shortestGraph[e.b] = append(shortestGraph[e.b], ShortestEdge{to: e.a, id: i})
		}
	}

	// An edge occurs in every shortest path exactly when it is a bridge
	// in the shortest-path subgraph.
	tin := make([]int, n)
	low := make([]int, n)
	for i := range tin {
		tin[i] = -1
	}
	isBridge := make([]bool, m)
	timer := 0

	var dfs func(v, parentEdge int)
	dfs = func(v, parentEdge int) {
		tin[v] = timer
		low[v] = timer
		timer++

		for _, e := range shortestGraph[v] {
			if e.id == parentEdge {
				continue
			}
			if tin[e.to] != -1 {
				if tin[e.to] < low[v] {
					low[v] = tin[e.to]
				}
				continue
			}

			dfs(e.to, e.id)
			if low[e.to] < low[v] {
				low[v] = low[e.to]
			}
			if low[e.to] > tin[v] {
				isBridge[e.id] = true
			}
		}
	}

	for v := 0; v < n; v++ {
		if tin[v] == -1 {
			dfs(v, -1)
		}
	}

	for i := 0; i < m; i++ {
		if isBridge[i] {
			fmt.Fprintln(out, "Yes")
		} else {
			fmt.Fprintln(out, "No")
		}
	}
}
