func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Pair struct {
	a, b int64
}

type MaxHeap []int64

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int64))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := int(in.NextInt64())
	for ; t > 0; t-- {
		n := int(in.NextInt64())
		k := int(in.NextInt64())

		pairs := make([]Pair, n)
		for i := 0; i < n; i++ {
			pairs[i].a = in.NextInt64()
		}
		for i := 0; i < n; i++ {
			pairs[i].b = in.NextInt64()
		}

		sort.Slice(pairs, func(i, j int) bool {
			return pairs[i].a < pairs[j].a
		})

		h := &MaxHeap{}
		heap.Init(h)

		var sum int64
		const inf int64 = 1<<63 - 1
		answer := inf

		for _, p := range pairs {
			heap.Push(h, p.b)
			sum += p.b

			if h.Len() > k {
				sum -= heap.Pop(h).(int64)
			}

			if h.Len() == k {
				value := p.a * sum
				if value < answer {
					answer = value
				}
			}
		}

		fmt.Fprintln(out, answer)
	}
}
