func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var c byte
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b >= '0' && b <= '9' {
			c = b
			break
		}
	}
	n = int64(c - '0')
	for {
		b, err := fs.r.ReadByte()
		if err != nil || b < '0' || b > '9' {
			return n
		}
		n = n*10 + int64(b-'0')
	}
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt64()
	m := int(in.NextInt64())

	dr := [8]int64{2, 1, -1, -2, -2, -1, 1, 2}
	dc := [8]int64{1, 2, 2, 1, -1, -2, -2, -1}

	unavailable := make(map[int64]struct{}, m*9)

	for k := 0; k < m; k++ {
		r := in.NextInt64()
		c := in.NextInt64()

		unavailable[(r-1)*n+(c-1)] = struct{}{}

		for d := 0; d < 8; d++ {
			nr := r + dr[d]
			nc := c + dc[d]
			if nr >= 1 && nr <= n && nc >= 1 && nc <= n {
				unavailable[(nr-1)*n+(nc-1)] = struct{}{}
			}
		}
	}

	answer := n*n - int64(len(unavailable))
