```go
package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

const INF int64 = 1 << 62

type Edge struct {
	a, b int
	w    int64
}

type AdjEdge struct {
	to int
	w  int64
	id int
}

type DagEdge struct {
	to int
	id int
}

type HeapItem struct {
	v    int
	dist int64
}

type MinHeap []HeapItem

func (h MinHeap) Len() int            { return len(h) }
func (h MinHeap) Less(i, j int) bool  { return h[i].dist < h[j].dist }
func (h MinHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *MinHeap) Push(x interface{}) { *h = append(*h, x.(HeapItem)) }
func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func dijkstra(start int, graph [][]AdjEdge, needParent bool) ([]int64, []int, []int) {
	n := len(graph)
	dist := make([]int64, n)
	parent := make([]int, n)
	parentEdge := make([]int, n)
	for i := 0; i < n; i++ {
		dist[i] = INF
		parent[i] = -1
		parentEdge[i] = -1
	}

	dist[start] = 0
	pq := &MinHeap{{v: start, dist: 0}}
	heap.Init(pq)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(HeapItem)
		v := item.v
		if item.dist != dist[v] {
			continue
		}
		for _, e := range graph[v] {
			nd := item.dist + e.w
			if nd < dist[e.to] {
				dist[e.to] = nd
				if needParent {
					parent[e.to] = v
					parentEdge[e.to] = e.id
				}
				heap.Push(pq, HeapItem{v: e.to, dist: nd})
			}
		}
	}

	return dist, parent, parentEdge
}

func reverseInts(a []int) {
	for i, j := 0, len(a)-1; i < j; i, j = i+1, j-1 {
		a[i], a[j] = a[j], a[i]
	}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	edges := make([]Edge, m)
	graph := make([][]AdjEdge, n)

	for i := 0; i < m; i++ {
		var a, b int
		var c int64
		fmt.Fscan(in, &a, &b, &c)
		a--
		b--
		edges[i] = Edge{a: a, b: b, w: c}
		graph[a] = append(graph[a], AdjEdge{to: b, w: c, id: i})
		graph[b] = append(graph[b], AdjEdge{to: a, w: c, id: i})
	}

	distS, parent, parentEdge := dijkstra(0, graph, true)
	distT, _, _ := dijkstra(n-1, graph, false)
	shortest := distS[n-1]

	// Choose one shortest path from city 1 to city N.
	pathVertices := make([]int, 0)
	pathEdges := make([]int, 0)
	for v := n - 1; v != -1; v = parent[v] {
		pathVertices = append(pathVertices, v)
		if v != 0 {
			pathEdges = append(pathEdges, parentEdge[v])
		}
	}
	reverseInts(pathVertices)
	reverseInts(pathEdges)

	k := len(pathEdges)
	isPathEdge := make([]bool, m)
	for _, id := range pathEdges {
		isPathEdge[id] = true
	}

	// Build the DAG consisting of all edges that can belong to a shortest path.
	dag := make([][]DagEdge, n)
	for id, e := range edges {
		if distS[e.a] != INF && distT[e.b] != INF &&
			distS[e.a]+e.w+distT[e.b] == shortest {
			dag[e.a] = append(dag[e.a], DagEdge{to: e.b, id: id})
		}
		if distS[e.b] != INF && distT[e.a] != INF &&
			distS[e.b]+e.w+distT[e.a] == shortest {
			dag[e.b] = append(dag[e.b], DagEdge{to: e.a, id: id})
		}
	}

	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		return distS[order[i]] < distS[order[j]]
	})

	// latest[v]: largest path index whose path vertex can reach v in the DAG.
	latest := make([]int, n)
	// earliest[v]: smallest path index reachable from v in the DAG.
	earliest := make([]int, n)
	for i := 0; i < n; i++ {
		latest[i] = -1
		earliest[i] = k + 1
	}
	for i, v := range pathVertices {
		latest[v] = i
		earliest[v] = i
	}

	for _, u := range order {
		if latest[u] < 0 {
			continue
		}
		for _, e := range dag[u] {
			if latest[u] > latest[e.to] {
				latest[e.to] = latest[u]
			}
		}
	}

	for i := n - 1; i >= 0; i-- {
		u := order[i]
		for _, e := range dag[u] {
			if earliest[e.to] < earliest[u] {
				earliest[u] = earliest[e.to]
			}
		}
	}

	// Every non-path DAG edge provides a detour around an interval of path edges.
	diff := make([]int, k+1)
	for u := 0; u < n; u++ {
		for _, e := range dag[u] {
			if isPathEdge[e.id] {
				continue
			}
			l := latest[u]
			r := earliest[e.to]
			if 0 <= l && l < r && r <= k {
				diff[l]++
				diff[r]--
			}
		}
	}

	answerYes := make([]bool, m)
	cover := 0
	for i := 0; i < k; i++ {
		cover += diff[i]
		if cover == 0 {
			answerYes[pathEdges[i]] = true
		}
	}

	for i := 0; i < m; i++ {
		if answerYes[i] {
			fmt.Fprintln(out, "Yes")
		} else {
			fmt.Fprintln(out, "No")
		}
	}
}
