func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	trie := make([]Node, 1, 200001)
	trie[0].minLen = inf

	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		length := len(s)

		answer := length // Cost to make the string empty.
		v := 0

		if trie[v].minLen != inf {
			cost := length + trie[v].minLen
			if cost < answer {
				answer = cost
			}
		}

		for depth := 1; depth <= length; depth++ {
			c := int(s[depth-1] - 'a')
			to := trie[v].next[c]
			if to == 0 {
				break
			}
			v = to

			if trie[v].minLen != inf {
				cost := length + trie[v].minLen - 2*depth
				if cost < answer {
					answer = cost
				}
			}
		}

		fmt.Fprintln(out, answer)

		v = 0
		if length < trie[v].minLen {
			trie[v].minLen = length
		}

		for j := 0; j < length; j++ {
			c := int(s[j] - 'a')
			if trie[v].next[c] == 0 {
				trie = append(trie, Node{minLen: inf})
				trie[v].next[c] = len(trie) - 1
			}
			v = trie[v].next[c]
			if length < trie[v].minLen {
				trie[v].minLen = length
