func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int64
	var m int
	fmt.Fscan(in, &n, &m)

	rows := make([]int64, 0, m)
	cols := make([]int64, 0, m)
	sums := make([]int64, 0, m)
	diffs := make([]int64, 0, m)

	rowSet := make(map[int64]bool)
	colSet := make(map[int64]bool)
	sumSet := make(map[int64]bool)
	diffSet := make(map[int64]bool)

	for k := 0; k < m; k++ {
		var a, b int64
		fmt.Fscan(in, &a, &b)

		if !rowSet[a] {
			rowSet[a] = true
			rows = append(rows, a)
		}
		if !colSet[b] {
			colSet[b] = true
			cols = append(cols, b)
		}

		s := a + b
		if !sumSet[s] {
			sumSet[s] = true
			sums = append(sums, s)
		}

		d := a - b
		if !diffSet[d] {
			diffSet[d] = true
			diffs = append(diffs, d)
		}
	}

	allowedRows := n - int64(len(rows))
	allowedCols := n - int64(len(cols))
	total := allowedRows * allowedCols

	// Count cells on forbidden i+j diagonals after excluding forbidden rows/columns.
	var forbiddenSum int64
	for _, s := range sums {
		if s <= n+1 {
			forbiddenSum += s - 1
		} else {
			forbiddenSum += 2*n - s + 1
		}

		for _, r := range rows {
			c := s - r
			if 1 <= c && c <= n {
				forbiddenSum--
			}
		}
		for _, c := range cols {
			r := s - c
			if 1 <= r && r <= n {
				forbiddenSum--
			}
		}
	}

	// Restore cells subtracted both by their row and column.
	for _, r := range rows {
		for _, c := range cols {
			if sumSet[r+c] {
				forbiddenSum++
			}
		}
	}

	// Count cells on forbidden i-j diagonals after excluding forbidden rows/columns.
	var forbiddenDiff int64
	for _, d := range diffs {
		if d >= 0 {
			forbiddenDiff += n - d
		} else {
			forbiddenDiff += n + d
		}

		for _, r := range rows {
			c := r - d
			if 1 <= c && c <= n {
				forbiddenDiff--
			}
		}
		for _, c := range cols {
			r := c + d
			if 1 <= r && r <= n {
				forbiddenDiff--
			}
		}
	}

	// Restore cells subtracted both by their row and column.
	for _, r := range rows {
		for _, c := range cols {
			if diffSet[r-c] {
				forbiddenDiff++
			}
		}
	}

	// Count intersections of forbidden sum and difference diagonals.
	var intersections int64
	for _, s := range sums {
		for _, d := range diffs {
			if (s+d)%2 != 0 {
				continue
			}

			r := (s + d) / 2
			c := (s - d) / 2
			if r < 1 || r > n || c < 1 || c > n {
				continue
			}
			if rowSet[r] || colSet[c] {
				continue
			}
			intersections++
		}
	}

	answer := total - forbiddenSum - forbiddenDiff + intersections
	fmt.Fprintln(out, answer)
}
