package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var c byte
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b >= '0' && b <= '9' {
			c = b
			break
		}
	}
	n = int64(c - '0')
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b < '0' || b > '9' {
			return n
		}
		n = n*10 + int64(b-'0')
	}
}

type Item struct {
	id      int
	version int
	weight  int64
	length  int64
}

type PriorityQueue []Item

func (pq PriorityQueue) Len() int {
	return len(pq)
}

func (pq PriorityQueue) Less(i, j int) bool {
	left := pq[i].weight * pq[j].length
	right := pq[j].weight * pq[i].length
	if left != right {
		return left > right
	}
	return pq[i].id < pq[j].id
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}

func (pq *PriorityQueue) Push(x any) {
	*pq = append(*pq, x.(Item))
}

func (pq *PriorityQueue) Pop() any {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func find(dsu []int, x int) int {
	root := x
	for dsu[root] != root {
		root = dsu[root]
	}
	for dsu[x] != x {
		next := dsu[x]
		dsu[x] = root
		x = next
	}
	return root
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := int(in.NextInt64())
	for ; t > 0; t-- {
		n := int(in.NextInt64())

		parent := make([]int, n+1)
		for i := 1; i <= n; i++ {
			parent[i] = int(in.NextInt64())
		}

		weight := make([]int64, n+1)
		length := make([]int64, n+1)
		cost := make([]int64, n+1)
		dsu := make([]int, n+1)
		version := make([]int, n+1)

		totalWeight := int64(0)
		pq := make(PriorityQueue, 0, 2*n)

		dsu[0] = 0
		for i := 1; i <= n; i++ {
			a := in.NextInt64()
			weight[i] = a
			length[i] = 1
			cost[i] = a
			dsu[i] = i
			totalWeight += a
			pq = append(pq, Item{
				id:      i,
				version: 0,
				weight:  a,
				length:  1,
			})
		}
		heap.Init(&pq)

		merged := 0
		for merged < n {
			item := heap.Pop(&pq).(Item)
			x := item.id
			if find(dsu, x) != x || version[x] != item.version {
				continue
			}

			y := find(dsu, parent[x])

			cost[y] += cost[x] + length[y]*weight[x]
			weight[y] += weight[x]
			length[y] += length[x]
			dsu[x] = y
			version[y]++
			merged++

			if y != 0 {
				heap.Push(&pq, Item{
					id:      y,
					version: version[y],
					weight:  weight[y],
					length:  length[y],
				})
			}
		}

		answer := (cost[0] % mod) * modPow(totalWeight%mod, mod-2) % mod
		fmt.Fprintln(out, answer)
	}
}
