package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 60

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	fmt.Fscan(in, &n, &q)

	dp := make([]int64, n)
	for i := range dp {
		dp[i] = INF
	}

	// Initially, the left hand is fixed at part 1,
	// and the right hand is at part 2.
	currentHand := byte('L')
	currentPos := 0
	dp[1] = 0

	for query := 0; query < q; query++ {
		var hs string
		var target int
		fmt.Fscan(in, &hs, &target)
		target--

		next := make([]int64, n)
		for i := range next {
			next[i] = INF
		}

		for freePos, baseCost := range dp {
			if baseCost == INF {
				continue
			}

			var movingStart, blocker int
			if hs[0] == currentHand {
				movingStart = currentPos
				blocker = freePos
			} else {
				movingStart = freePos
				blocker = currentPos
			}

			for _, dir := range []int{1, -1} {
				var moveDist, blockerDist int
				if dir == 1 {
					moveDist = (target - movingStart + n) % n
					blockerDist = (blocker - movingStart + n) % n
				} else {
					moveDist = (movingStart - target + n) % n
					blockerDist = (movingStart - blocker + n) % n
				}

				endBlocker := blocker
				cost := int64(moveDist)

				// The blocker lies on the chosen path, so it must be
				// pushed one position beyond the target.
				if moveDist > 0 && blockerDist <= moveDist {
					endBlocker = (target + dir + n) % n

					var blockerMove int
					if dir == 1 {
						blockerMove = (endBlocker - blocker + n) % n
					} else {
						blockerMove = (blocker - endBlocker + n) % n
					}
					cost += int64(blockerMove)
				}

				total := baseCost + cost
				if total < next[endBlocker] {
					next[endBlocker] = total
				}
			}
		}

		dp = next
		currentHand = hs[0]
		currentPos = target
	}

	answer := INF
	for _, cost := range dp {
		if cost < answer {
			answer = cost
		}
	}
	fmt.Fprintln(out, answer)
}
