package main

import (
	"bufio"
	"fmt"
	"os"
)

const inf int64 = 1 << 60

func distance(n, from, to, direction int) int {
	if direction == 1 {
		return (to - from + n) % n
	}
	return (from - to + n) % n
}

func move(n, hand, other, target, direction int) (int, int) {
	handDistance := distance(n, hand, target, direction)
	otherDistance := distance(n, hand, other, direction)

	if otherDistance > 0 && otherDistance <= handDistance {
		newOther := (target + direction + n) % n
		cost := handDistance + distance(n, other, newOther, direction)
		return cost, newOther
	}

	return handDistance, other
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	fmt.Fscan(in, &n, &q)

	dp := make([]int64, n)
	nextDP := make([]int64, n)
	for i := range dp {
		dp[i] = inf
	}

	var previousHand byte
	previousTarget := -1

	for query := 0; query < q; query++ {
		var handString string
		var target int
		fmt.Fscan(in, &handString, &target)
		hand := handString[0]
		target--

		for i := range nextDP {
			nextDP[i] = inf
		}

		if query == 0 {
			current, other := 0, 1
			if hand == 'R' {
				current, other = 1, 0
			}

			for _, direction := range []int{-1, 1} {
				cost, newOther := move(n, current, other, target, direction)
				if int64(cost) < nextDP[newOther] {
					nextDP[newOther] = int64(cost)
				}
			}
		} else {
			for otherPosition, currentCost := range dp {
				if currentCost == inf {
					continue
				}

				var current, other int
				if hand == previousHand {
					current = previousTarget
					other = otherPosition
				} else {
					current = otherPosition
					other = previousTarget
				}

				for _, direction := range []int{-1, 1} {
					cost, newOther := move(n, current, other, target, direction)
					newCost := currentCost + int64(cost)
					if newCost < nextDP[newOther] {
						nextDP[newOther] = newCost
					}
				}
			}
		}

		dp, nextDP = nextDP, dp
		previousHand = hand
		previousTarget = target
	}

	answer := inf
	for _, cost := range dp {
		if cost < answer {
			answer = cost
		}
	}

	fmt.Fprintln(out, answer)
}
