func main() {
	in := bufio.NewReader(os.Stdin)

	var h, w, k int
	fmt.Fscan(in, &h, &w, &k)

	grid := make([]string, h)
	for i := range grid {
		fmt.Fscan(in, &grid[i])
	}

	n := h * w
	adj := make([][]int, n)
	empty := make([]int, 0, n)
	directions := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	for r := 0; r < h; r++ {
		for c := 0; c < w; c++ {
			if grid[r][c] == '#' {
				continue
			}
			id := r*w + c
			empty = append(empty, id)

			for _, d := range directions {
				nr, nc := r+d[0], c+d[1]
				if nr >= 0 && nr < h && nc >= 0 && nc < w && grid[nr][nc] == '.' {
					adj[id] = append(adj[id], nr*w+nc)
				}
			}
		}
	}

	visited := make([]bool, n)

	var dfs func(int, int) int64
	dfs = func(current, moves int) int64 {
		if moves == k {
			return 1
		}

		var count int64
		for _, next := range adj[current] {
			if visited[next] {
				continue
			}
			visited[next] = true
			count += dfs(next, moves+1)
			visited[next] = false
		}
		return count
	}

	var answer int64
	for _, start := range empty {
		visited[start] = true
		answer += dfs(start, 0)
		visited[start] = false
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
