	}

	visited := make([]bool, h*w)
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	var dfs func(int, int, int) int64
	dfs = func(r, c, moves int) int64 {
		if moves == k {
			return 1
		}

		var count int64
		for d := 0; d < 4; d++ {
			nr, nc := r+dr[d], c+dc[d]
			if nr < 0 || nr >= h || nc < 0 || nc >= w {
				continue
			}

			id := nr*w + nc
			if grid[nr][nc] == '#' || visited[id] {
				continue
			}

			visited[id] = true
			count += dfs(nr, nc, moves+1)
			visited[id] = false
		}
		return count
	}

	var answer int64
	for r := 0; r < h; r++ {
		for c := 0; c < w; c++ {
			if grid[r][c] == '#' {
				continue
			}

			id := r*w + c
			visited[id] = true
			answer += dfs(r, c, 0)
			visited[id] = false
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
