type Fenwick struct {
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int64, n+1)}
}

func (f *Fenwick) Add(index int, value int64) {
	for index < len(f.tree) {
		f.tree[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int64 {
	var result int64
	for index > 0 {
		result += f.tree[index]
		index -= index & -index
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	bit := NewFenwick(int(m))
	bit.Add(1, 1) // Initial prefix sum residue: 0

	var answer int64
	var prefix int64
	var sumPreviousResidues int64

	for j := 1; j <= n; j++ {
		var a int64
		fmt.Fscan(in, &a)

		prefix = (prefix + a%m) % m

		previousCount := int64(j)
		countLessOrEqual := bit.Sum(int(prefix) + 1)
		countGreater := previousCount - countLessOrEqual

		answer += previousCount*prefix - sumPreviousResidues + m*countGreater

		sumPreviousResidues += prefix
		bit.Add(int(prefix)+1, 1)
	}

	fmt.Fprintln(out, answer)
}
