package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type Item struct {
	id      int
	version int
	weight  int64
	length  int64
}

type MaxHeap []Item

func (h MaxHeap) Len() int {
	return len(h)
}

func (h MaxHeap) Less(i, j int) bool {
	left := h[i].weight * h[j].length
	right := h[j].weight * h[i].length
	if left != right {
		return left > right
	}
	if h[i].id != h[j].id {
		return h[i].id < h[j].id
	}
	return h[i].version > h[j].version
}

func (h MaxHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Item))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func find(dsu []int, x int) int {
	root := x
	for dsu[root] != root {
		root = dsu[root]
	}
	for dsu[x] != x {
		next := dsu[x]
		dsu[x] = root
		x = next
	}
	return root
}

func modPow(base, exp int64) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := in.NextInt()
	for ; t > 0; t-- {
		n := in.NextInt()

		parent := make([]int, n+1)
		for i := 1; i <= n; i++ {
			parent[i] = in.NextInt()
		}

		dsu := make([]int, n+1)
		version := make([]int, n+1)
		length := make([]int64, n+1)
		weight := make([]int64, n+1)
		cost := make([]int64, n+1)

		h := make(MaxHeap, 0, n)
		var totalWeight int64

		dsu[0] = 0
		for i := 1; i <= n; i++ {
			a := int64(in.NextInt())
			dsu[i] = i
			length[i] = 1
			weight[i] = a
			cost[i] = a % mod
			totalWeight += a
			h = append(h, Item{
				id:      i,
				version: 0,
				weight:  a,
				length:  1,
			})
		}
		heap.Init(&h)

		merged := 0
		for merged < n {
			item := heap.Pop(&h).(Item)
			id := item.id

			if find(dsu, id) != id || version[id] != item.version {
				continue
			}

			parRep := find(dsu, parent[id])

			cross := (length[parRep] % mod) * (weight[id] % mod) % mod
			cost[parRep] = (cost[parRep] + cost[id] + cross) % mod
			length[parRep] += length[id]
			weight[parRep] += weight[id]

			dsu[id] = parRep
			version[parRep]++
			merged++

			if parRep != 0 {
				heap.Push(&h, Item{
					id:      parRep,
					version: version[parRep],
					weight:  weight[parRep],
					length:  length[parRep],
				})
			}
		}

		answer := cost[0] * modPow(totalWeight%mod, mod-2) % mod
		fmt.Fprintln(out, answer)
	}
}
