}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	graph := make([][]int, n)

	for i := 0; i < n-1; i++ {
		u := in.NextInt() - 1
		v := in.NextInt() - 1
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u)
	}

	visited := make([]bool, n)
	stack := make([]int, 0, n)
	var answer int64

	for start := 0; start < n; start++ {
		if visited[start] || len(graph[start]) != 3 {
			continue
		}

		visited[start] = true
		stack = append(stack[:0], start)
		var boundary int64

		for len(stack) > 0 {
			v := stack[len(stack)-1]
			stack = stack[:len(stack)-1]

			for _, to := range graph[v] {
				degree := len(graph[to])
				if degree == 2 {
					boundary++
				} else if degree == 3 && !visited[to] {
					visited[to] = true
					stack = append(stack, to)
				}
			}
		}

		answer += boundary * (boundary - 1) / 2
	}

