```go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) Next() string {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return string(fs.data[start:fs.pos])
}

func (fs *FastScanner) NextInt() int {
	n := 0
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		n = n*10 + int(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return n
}

type CentroidEntry struct {
	centroid int32
	distance int32
}

type DFSItem struct {
	node     int
	parent   int
	distance int
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()

	// Trie transitions. Node 0 is the root; zero also represents no transition.
	children := make([]int32, 26)
	parent := []int{-1}
	terminal := make([]int, n)

	for i := 0; i < n; i++ {
		s := in.Next()
		cur := 0
		for j := 0; j < len(s); j++ {
			c := int(s[j] - 'a')
			next := int(children[cur*26+c])
			if next == 0 {
				next = len(parent)
				parent = append(parent, cur)
				children = append(children, make([]int32, 26)...)
				children[cur*26+c] = int32(next)
			}
			cur = next
		}
		terminal[i] = cur
	}

	nodeCount := len(parent)

	// Build the trie tree in CSR adjacency form.
	degree := make([]int, nodeCount)
	for v := 1; v < nodeCount; v++ {
		degree[v]++
		degree[parent[v]]++
	}

	offset := make([]int, nodeCount+1)
	for i := 0; i < nodeCount; i++ {
		offset[i+1] = offset[i] + degree[i]
	}

	adj := make([]int, offset[nodeCount])
	position := make([]int, nodeCount)
	copy(position, offset[:nodeCount])

	for v := 1; v < nodeCount; v++ {
		p := parent[v]
		adj[position[v]] = p
		position[v]++
		adj[position[p]] = v
		position[p]++
	}

	children = nil
	degree = nil
	position = nil
	parent = nil

	paths := make([][]CentroidEntry, nodeCount)
	removed := make([]bool, nodeCount)
	tempParent := make([]int, nodeCount)
	subtreeSize := make([]int, nodeCount)

	work := make([]int, 0, nodeCount)
	stack := make([]DFSItem, 0, nodeCount)

	var decompose func(int)
	decompose = func(start int) {
		work = work[:0]
		work = append(work, start)
		tempParent[start] = -1

		for i := 0; i < len(work); i++ {
			v := work[i]
			for e := offset[v]; e < offset[v+1]; e++ {
				to := adj[e]
				if removed[to] || to == tempParent[v] {
					continue
				}
				tempParent[to] = v
				work = append(work, to)
			}
		}

		total := len(work)
		for i := total - 1; i >= 0; i-- {
			v := work[i]
			subtreeSize[v] = 1
			for e := offset[v]; e < offset[v+1]; e++ {
				to := adj[e]
				if removed[to] || tempParent[to] != v {
					continue
				}
				subtreeSize[v] += subtreeSize[to]
			}
		}

		centroid := start
		for _, v := range work {
			maxPart := total - subtreeSize[v]
			for e := offset[v]; e < offset[v+1]; e++ {
				to := adj[e]
				if removed[to] {
					continue
				}
				if tempParent[to] == v && subtreeSize[to] > maxPart {
					maxPart = subtreeSize[to]
				}
			}
			if maxPart*2 <= total {
				centroid = v
				break
			}
		}

		stack = stack[:0]
		stack = append(stack, DFSItem{node: centroid, parent: -1, distance: 0})
		for len(stack) > 0 {
			last := len(stack) - 1
			item := stack[last]
			stack = stack[:last]

			paths[item.node] = append(paths[item.node], CentroidEntry{
				centroid: int32(centroid),
				distance: int32(item.distance),
			})

			for e := offset[item.node]; e < offset[item.node+1]; e++ {
				to := adj[e]
				if removed[to] || to == item.parent {
					continue
				}
				stack = append(stack, DFSItem{
					node:     to,
					parent:   item.node,
					distance: item.distance + 1,
				})
			}
		}

		removed[centroid] = true
		for e := offset[centroid]; e < offset[centroid+1]; e++ {
			to := adj[e]
			if !removed[to] {
				decompose(to)
			}
		}
	}

	decompose(0)

	const inf = int(1 << 60)
	best := make([]int, nodeCount)
	for i := range best {
		best[i] = inf
	}

	update := func(v int) {
		for _, entry := range paths[v] {
			c := int(entry.centroid)
			d := int(entry.distance)
			if d < best[c] {
				best[c] = d
			}
		}
	}

	query := func(v int) int {
		answer := inf
		for _, entry := range paths[v] {
			c := int(entry.centroid)
			d := int(entry.distance)
			if best[c]+d < answer {
				answer = best[c] + d
			}
		}
		return answer
	}

	// The empty string corresponds to the trie root and is always available.
	update(0)

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for _, v := range terminal {
		fmt.Fprintln(out, query(v))
		update(v)
	}
}
