	for i := 0; i < n; i++ {
		digit := int64(s[i] - '0')
		weightedSum += digit * int64(i+1)
	}

	result := make([]byte, 0, n+32)
	var carry int64

	for i := n - 1; i >= 0; i-- {
		value := weightedSum + carry
		result = append(result, byte(value%10)+'0')
		carry = value / 10

		digit := int64(s[i] - '0')
		weightedSum -= digit * int64(i+1)
	}

	for carry > 0 {
		result = append(result, byte(carry%10)+'0')
		carry /= 10
	}

	for left, right := 0, len(result)-1; left < right; left, right = left+1, right-1 {
		result[left], result[right] = result[right], result[left]
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	fmt.Fprintln(out, string(result))
}
