package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type SegmentTree struct {
	size int
	data []int
}

func NewSegmentTree(values []int) *SegmentTree {
	size := 1
	for size < len(values) {
		size <<= 1
	}
	data := make([]int, size*2)
	for i, v := range values {
		data[size+i] = v
	}
	for i := size - 1; i >= 1; i-- {
		if data[i<<1] > data[i<<1|1] {
			data[i] = data[i<<1]
		} else {
			data[i] = data[i<<1|1]
		}
	}
	return &SegmentTree{size: size, data: data}
}

func (st *SegmentTree) Max(left, right int) int {
	left += st.size
	right += st.size
	result := 0

	for left < right {
		if left&1 == 1 {
			if st.data[left] > result {
				result = st.data[left]
			}
			left++
		}
		if right&1 == 1 {
			right--
			if st.data[right] > result {
				result = st.data[right]
			}
		}
		left >>= 1
		right >>= 1
	}
	return result
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()

	heights := make([]int, n)
	for i := range heights {
		heights[i] = in.NextInt()
	}

	// nextGreater[i] is the nearest building east of i that is taller than i.
	nextGreater := make([]int, n+1)
	nextGreater[n] = n
	stack := make([]int, 0, n)

	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && heights[stack[len(stack)-1]] < heights[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) == 0 {
			nextGreater[i] = n
		} else {
			nextGreater[i] = stack[len(stack)-1]
		}
		stack = append(stack, i)
	}

	// chainLength[i] is the number of buildings in the next-greater chain
	// starting at i.
	chainLength := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		chainLength[i] = 1 + chainLength[nextGreater[i]]
	}

	log := 1
	for (1 << log) <= n {
		log++
	}

	jump := make([][]int, log)
	jump[0] = make([]int, n+1)
	copy(jump[0], nextGreater)

	for b := 1; b < log; b++ {
		jump[b] = make([]int, n+1)
		for i := 0; i <= n; i++ {
			jump[b][i] = jump[b-1][jump[b-1][i]]
		}
	}

	segmentTree := NewSegmentTree(heights)

	for ; q > 0; q-- {
		l := in.NextInt()
		r := in.NextInt()

		// If r is the easternmost building, there are no candidates.
		if r == n {
			fmt.Fprintln(out, 0)
			continue
		}

		// In zero-based indexing, buildings l+1 through r are [l, r).
		threshold := segmentTree.Max(l, r)
		start := r // Building r+1 in zero-based indexing.

		if heights[start] > threshold {
			fmt.Fprintln(out, chainLength[start])
			continue
		}

		current := start
		for b := log - 1; b >= 0; b-- {
			next := jump[b][current]
			if next < n && heights[next] <= threshold {
				current = next
			}
		}

		firstHigher := nextGreater[current]
		if firstHigher == n {
			fmt.Fprintln(out, 0)
		} else {
			fmt.Fprintln(out, chainLength[firstHigher])
		}
	}
}
