package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type DSU struct {
	parent []int
	size   []int
	left   []int
	right  []int
	color  []int
}

func NewDSU(n int) *DSU {
	d := &DSU{
		parent: make([]int, n+1),
		size:   make([]int, n+1),
		left:   make([]int, n+1),
		right:  make([]int, n+1),
		color:  make([]int, n+1),
	}
	for i := 1; i <= n; i++ {
		d.parent[i] = i
		d.size[i] = 1
		d.left[i] = i
		d.right[i] = i
		d.color[i] = i
	}
	return d
}

func (d *DSU) Find(x int) int {
	root := x
	for d.parent[root] != root {
		root = d.parent[root]
	}
	for d.parent[x] != x {
		next := d.parent[x]
		d.parent[x] = root
		x = next
	}
	return root
}

func (d *DSU) Union(a, b int) int {
	a = d.Find(a)
	b = d.Find(b)
	if a == b {
		return a
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	if d.left[b] < d.left[a] {
		d.left[a] = d.left[b]
	}
	if d.right[b] > d.right[a] {
		d.right[a] = d.right[b]
	}
	return a
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()

	dsu := NewDSU(n)
	colorCount := make([]int, n+1)
	for i := 1; i <= n; i++ {
		colorCount[i] = 1
	}

	for ; q > 0; q-- {
		queryType := in.NextInt()

		if queryType == 1 {
			x := in.NextInt()
			newColor := in.NextInt()

			root := dsu.Find(x)
			oldColor := dsu.color[root]
			if oldColor == newColor {
				continue
			}

			componentSize := dsu.size[root]
			colorCount[oldColor] -= componentSize
			colorCount[newColor] += componentSize
			dsu.color[root] = newColor

			if dsu.left[root] > 1 {
				leftRoot := dsu.Find(dsu.left[root] - 1)
				if dsu.color[leftRoot] == newColor {
					root = dsu.Union(root, leftRoot)
					dsu.color[root] = newColor
				}
			}

			if dsu.right[root] < n {
				rightRoot := dsu.Find(dsu.right[root] + 1)
				if dsu.color[rightRoot] == newColor {
					root = dsu.Union(root, rightRoot)
					dsu.color[root] = newColor
				}
			}
		} else {
			c := in.NextInt()
			fmt.Fprintln(out, colorCount[c])
		}
	}
