package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type Fenwick struct {
	n   int
	bit []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:   n,
		bit: make([]int64, n+1),
	}
}

func (f *Fenwick) Add(i int, delta int64) {
	for i <= f.n {
		f.bit[i] += delta
		i += i & -i
	}
}

func (f *Fenwick) Sum(i int) int64 {
	var res int64
	for i > 0 {
		res += f.bit[i]
		i -= i & -i
	}
	return res
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, k int
	fmt.Fscan(in, &n, &k)

	p := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
	}

	// Count inversions of the entire permutation.
	totalBIT := NewFenwick(n)
	var totalInv int64
	for i, x := range p {
		totalInv += int64(i) - totalBIT.Sum(x)
		totalBIT.Add(x, 1)
	}

	// Count the sum of inversion numbers over all length-K windows.
	windowBIT := NewFenwick(n)
	var windowInv int64
	for i := 0; i < k; i++ {
		x := p[i]
		windowInv += int64(i) - windowBIT.Sum(x)
		windowBIT.Add(x, 1)
	}

	sumWindowInv := windowInv
	windowCount := n - k + 1

	for left := 0; left+k < n; left++ {
		removed := p[left]

		// The removed element was the leftmost, so its inversions are
		// exactly the remaining elements smaller than it.
		windowInv -= windowBIT.Sum(removed - 1)
		windowBIT.Add(removed, -1)

		added := p[left+k]

		// The added element is the rightmost, so new inversions are
		// existing elements greater than it.
		currentSize := int64(k - 1)
		windowInv += currentSize - windowBIT.Sum(added)
		windowBIT.Add(added, 1)

		sumWindowInv += windowInv
	}

	// For each selected window:
	// expected inversions = totalInv - original internal inversions
	//                       + K(K-1)/4.
	ans := totalInv % mod

	randomInternal := int64(k) % mod
	randomInternal = randomInternal * int64(k-1) % mod
	randomInternal = randomInternal * modPow(4, mod-2) % mod
	ans = (ans + randomInternal) % mod

	averageOriginalInternal := (sumWindowInv % mod) *
		modPow(int64(windowCount), mod-2) % mod
	ans = (ans - averageOriginalInternal + mod) % mod

	fmt.Fprintln(out, ans)
}
