func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, l int
	fmt.Fscan(in, &n, &m, &l)

	k := n + m + l
	values := make([]int64, k)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &values[i])
	}
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &values[n+i])
	}
	for i := 0; i < l; i++ {
		fmt.Fscan(in, &values[n+m+i])
	}

	pow3 := make([]int, k+1)
	pow3[0] = 1
	for i := 1; i <= k; i++ {
		pow3[i] = pow3[i-1] * 3
	}
	stateCount := pow3[k]

	// Ternary digit: 0 = table, 1 = Takahashi, 2 = Aoki.
	initial := 0
	for i := 0; i < n; i++ {
		initial += pow3[i]
	}
	for i := n; i < n+m; i++ {
		initial += 2 * pow3[i]
	}

	takahashiMask := make([]uint16, stateCount)
	aokiMask := make([]uint16, stateCount)
	for state := 1; state < stateCount; state++ {
		q := state / 3
		digit := state % 3
		takahashiMask[state] = takahashiMask[q] << 1
		aokiMask[state] = aokiMask[q] << 1
		if digit == 1 {
			takahashiMask[state] |= 1
		} else if digit == 2 {
			aokiMask[state] |= 1
		}
	}

	lowerMask := make([]uint16, k)
	for i := 0; i < k; i++ {
		for j := 0; j < k; j++ {
			if values[j] < values[i] {
				lowerMask[i] |= uint16(1) << j
			}
		}
	}

	allMask := uint16((1 << k) - 1)
	// 0 = unknown, 1 = winning, -1 = losing.
	memo := make([]int8, stateCount*2)

	var win func(state, turn int) bool
	win = func(state, turn int) bool {
		key := state*2 + turn
		if memo[key] != 0 {
			return memo[key] == 1
		}

		var hand uint16
		owner := 1
		if turn == 0 {
			hand = takahashiMask[state]
		} else {
			hand = aokiMask[state]
			owner = 2
		}

		remaining := hand
		for remaining != 0 {
			i := bits.TrailingZeros16(remaining)
			remaining &= remaining - 1

			// Play card i onto the table without taking another card.
			baseState := state - owner*pow3[i]
			if !win(baseState, 1-turn) {
				memo[key] = 1
				return true
			}

			table := allMask ^ (takahashiMask[baseState] | aokiMask[baseState])
			candidates := table & lowerMask[i]
			for candidates != 0 {
				j := bits.TrailingZeros16(candidates)
				candidates &= candidates - 1

				nextState := baseState + owner*pow3[j]
				if !win(nextState, 1-turn) {
					memo[key] = 1
					return true
				}
			}
		}

		memo[key] = -1
		return false
	}

	if win(initial, 0) {
		fmt.Fprintln(out, "Takahashi")
	} else {
		fmt.Fprintln(out, "Aoki")
	}
}
