package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func transform(src []int64, edges int, initialState int) []int64 {
	n := len(src)
	cur0 := make([]int64, n) // Next selected output increment is -1.
	cur1 := make([]int64, n) // Next selected output increment is +1.

	if initialState == 0 {
		copy(cur0, src)
	} else {
		copy(cur1, src)
	}

	for bit := 0; bit < edges; bit++ {
		next0 := make([]int64, n)
		next1 := make([]int64, n)
		b := 1 << bit

		for mask := 0; mask < n; mask++ {
			// Do not flip this increment.
			next0[mask] += cur0[mask]
			next1[mask] += cur1[mask]

			if mask&b != 0 {
				// Input increment +1, output increment -1.
				// State changes from expecting -1 to expecting +1.
				out := mask ^ b
				next1[out] += cur0[mask]
				if next1[out] >= mod {
					next1[out] -= mod
				}
			} else {
				// Input increment -1, output increment +1.
				// State changes from expecting +1 to expecting -1.
				out := mask ^ b
				next0[out] += cur1[mask]
				if next0[out] >= mod {
					next0[out] -= mod
				}
			}
		}

		cur0, cur1 = next0, next1
	}

	result := make([]int64, n)
	for i := 0; i < n; i++ {
		result[i] = cur0[i] + cur1[i]
		if result[i] >= mod {
			result[i] -= mod
		}
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var h, w int
	fmt.Fscan(in, &h, &w)

	grid := make([][]byte, h)
	for i := 0; i < h; i++ {
		var s string
		fmt.Fscan(in, &s)
		grid[i] = []byte(s)
	}

	// Use the smaller dimension as the row width.
	if w > h {
		transposed := make([][]byte, w)
		for i := 0; i < w; i++ {
			transposed[i] = make([]byte, h)
			for j := 0; j < h; j++ {
				transposed[i][j] = grid[j][i]
			}
		}
		grid = transposed
		h, w = w, h
	}

	edges := w - 1
	masks := 1 << edges
	states := 3 * masks

	allowed := make([][]bool, h)
	for r := 0; r < h; r++ {
		allowed[r] = make([]bool, states)

		for first := 0; first < 3; first++ {
			for mask := 0; mask < masks; mask++ {
				color := first
				ok := grid[r][0] == '?' || int(grid[r][0]-'1') == color

				for j := 1; j < w && ok; j++ {
					if mask&(1<<(j-1)) != 0 {
						color++
						if color == 3 {
							color = 0
						}
					} else {
						color--
						if color == -1 {
							color = 2
						}
					}

					if grid[r][j] != '?' && int(grid[r][j]-'1') != color {
						ok = false
					}
				}

				if ok {
					allowed[r][first*masks+mask] = true
				}
			}
		}
	}

	dp := make([]int64, states)
	for state := 0; state < states; state++ {
		if allowed[0][state] {
			dp[state] = 1
		}
	}

	for r := 1; r < h; r++ {
		next := make([]int64, states)

		for firstA := 0; firstA < 3; firstA++ {
			src := dp[firstA*masks : (firstA+1)*masks]

			for firstB := 0; firstB < 3; firstB++ {
				if firstA == firstB {
					continue
				}

				diff := firstB - firstA
				if diff < 0 {
					diff += 3
				}

				// If the initial vertical difference is +1, the first
				// selected output increment must be -1, and vice versa.
				initialState := 0
				if diff == 2 {
					initialState = 1
				}

				values := transform(src, edges, initialState)
				offset := firstB * masks
				for mask, value := range values {
					next[offset+mask] += value
					if next[offset+mask] >= mod {
						next[offset+mask] -= mod
					}
				}
			}
		}

		for state := 0; state < states; state++ {
			if !allowed[r][state] {
				next[state] = 0
			}
		}
		dp = next
	}

	var answer int64
	for _, value := range dp {
		answer += value
		if answer >= mod {
			answer -= mod
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
