)

const mod int64 = 998244353

func generateCompatible(top []uint8, width, multiplier, pos, first, prev, bits int, edges *[]int32) {
	if pos == width {
		*edges = append(*edges, int32(first*multiplier+bits))
		return
	}

	c1 := prev + 1
	if c1 >= 3 {
		c1 -= 3
	}
	if c1 != int(top[pos]) {
		generateCompatible(top, width, multiplier, pos+1, first, c1, bits, edges)
	}

	c2 := prev + 2
	if c2 >= 3 {
		c2 -= 3
	}
	if c2 != int(top[pos]) {
		generateCompatible(top, width, multiplier, pos+1, first, c2, bits|(1<<(pos-1)), edges)
	}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var originalH, originalW int
	fmt.Fscan(in, &originalH, &originalW)

	original := make([][]byte, originalH)
	for i := 0; i < originalH; i++ {
		var s string
		fmt.Fscan(in, &s)
		original[i] = []byte(s)
	}

	var grid [][]byte
	var rows, width int
	if originalW <= originalH {
		rows, width = originalH, originalW
		grid = original
	} else {
		rows, width = originalW, originalH
		grid = make([][]byte, rows)
		for i := 0; i < rows; i++ {
			grid[i] = make([]byte, width)
			for j := 0; j < width; j++ {
				grid[i][j] = original[j][i]
			}
		}
	}

	// Detect immediate conflicts between adjacent fixed cells.
	for i := 0; i < rows; i++ {
		for j := 0; j < width; j++ {
			if grid[i][j] == '?' {
				continue
			}
			if i+1 < rows && grid[i+1][j] == grid[i][j] {
				fmt.Println(0)
				return
			}
			if j+1 < width && grid[i][j+1] == grid[i][j] {
				fmt.Println(0)
				return
			}
		}
	}

	multiplier := 1 << (width - 1)
	stateCount := 3 * multiplier

	// Every proper row is encoded by its first color and one bit per edge:
	// 0 means adding 1 modulo 3, and 1 means adding 2 modulo 3.
	digits := make([]uint8, stateCount*width)
	for first := 0; first < 3; first++ {
		for bits := 0; bits < multiplier; bits++ {
			state := first*multiplier + bits
			base := state * width
			color := first
			digits[base] = uint8(color)
			for j := 1; j < width; j++ {
				if ((bits >> (j - 1)) & 1) == 0 {
					color++
					if color >= 3 {
						color -= 3
					}
				} else {
					color += 2
					if color >= 3 {
						color -= 3
					}
				}
				digits[base+j] = uint8(color)
			}
		}
	}

	allowed := make([][]int32, rows)
	for r := 0; r < rows; r++ {
		states := make([]int32, 0, stateCount)
		for state := 0; state < stateCount; state++ {
			ok := true
			base := state * width
			for c := 0; c < width; c++ {
				if grid[r][c] != '?' &&
					digits[base+c] != uint8(grid[r][c]-'1') {
					ok = false
					break
				}
			}
			if ok {
				states = append(states, int32(state))
			}
		}
		if len(states) == 0 {
			fmt.Println(0)
			return
		}
		allowed[r] = states
	}

	if rows == 1 {
		fmt.Println(len(allowed[0]))
		return
	}

	pow3 := 1
	for i := 1; i < width; i++ {
		pow3 *= 3
	}
	expectedEdges := 6 * pow3

	offsets := make([]int, stateCount+1)
	edges := make([]int32, 0, expectedEdges)

	for state := 0; state < stateCount; state++ {
		offsets[state] = len(edges)
		top := digits[state*width : (state+1)*width]
		topFirst := int(top[0])

		first1 := topFirst + 1
		if first1 >= 3 {
			first1 -= 3
		}
		generateCompatible(top, width, multiplier, 1, first1, first1, 0, &edges)

		first2 := topFirst + 2
		if first2 >= 3 {
			first2 -= 3
		}
		generateCompatible(top, width, multiplier, 1, first2, first2, 0, &edges)
	}
	offsets[stateCount] = len(edges)

	dp := make([]int64, stateCount)
	next := make([]int64, stateCount)
	for _, state := range allowed[0] {
		dp[int(state)] = 1
	}

	for r := 1; r < rows; r++ {
		clear(next)
		nonzero := false

		for _, encodedState := range allowed[r] {
			state := int(encodedState)
			var sum int64
			for p := offsets[state]; p < offsets[state+1]; p++ {
				sum += dp[int(edges[p])]
			}
			next[state] = sum % mod
			if next[state] != 0 {
				nonzero = true
			}
		}

		if !nonzero {
			fmt.Println(0)
			return
		}
		dp, next = next, dp
	}

	var answer int64
	for _, state := range allowed[rows-1] {
		answer += dp[int(state)]
	}
	fmt.Println(answer % mod)
}
