	"os"
	"sort"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	var s string
	fmt.Fscan(in, &n, &q)
	fmt.Fscan(in, &s)

	prefixOne := make([]int, n+1)
	prefixTwo := make([]int, n+1)
	slashes := make([]int, 0)

	for i := 1; i <= n; i++ {
		prefixOne[i] = prefixOne[i-1]
		prefixTwo[i] = prefixTwo[i-1]

		switch s[i-1] {
		case '1':
			prefixOne[i]++
		case '2':
			prefixTwo[i]++
		case '/':
			slashes = append(slashes, i)
		}
	}

	for ; q > 0; q-- {
		var l, r int
		fmt.Fscan(in, &l, &r)

		lo := sort.Search(len(slashes), func(i int) bool {
			return slashes[i] >= l
		})
		hi := sort.Search(len(slashes), func(i int) bool {
			return slashes[i] > r
		})

		if lo == hi {
			fmt.Fprintln(out, 0)
			continue
		}

		// Find the first slash where the number of available 1s
		// on its left is at least the number of available 2s on its right.
		cross := lo + sort.Search(hi-lo, func(i int) bool {
			p := slashes[lo+i]
			ones := prefixOne[p-1] - prefixOne[l-1]
			twos := prefixTwo[r] - prefixTwo[p]
			return ones >= twos
		})

		best := 0
		check := func(index int) {
			if index < lo || index >= hi {
				return
			}
			p := slashes[index]
			ones := prefixOne[p-1] - prefixOne[l-1]
			twos := prefixTwo[r] - prefixTwo[p]
			if twos < ones {
				ones = twos
			}
			if ones > best {
				best = ones
			}
		}

		check(cross)
		check(cross - 1)

		fmt.Fprintln(out, 2*best+1)
	}
}
