		case '1':
			pref1[i]++
			pos1 = append(pos1, i)
		case '2':
			pref2[i]++
			pos2 = append(pos2, i)
		case '/':
			prefSlash[i]++
		}
	}

	for ; q > 0; q-- {
		var l, r int
		fmt.Fscan(in, &l, &r)

		if prefSlash[r]-prefSlash[l-1] == 0 {
