			continue
		}

		count1 := pref1[r] - pref1[l-1]
		count2 := pref2[r] - pref2[l-1]
		maxK := count1
		if count2 < maxK {
			maxK = count2
		}

		lo, hi := 0, maxK+1
		for hi-lo > 1 {
