package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Bar struct {
	r, c, l int
	id      int
}

type SegmentTree struct {
	n    int
	min  []int
	lazy []int
}

func NewSegmentTree(n, initial int) *SegmentTree {
	st := &SegmentTree{
		n:    n,
		min:  make([]int, 4*n),
		lazy: make([]int, 4*n),
	}
	st.build(1, 0, n, initial)
	return st
}

func (st *SegmentTree) build(node, left, right, initial int) {
	st.min[node] = initial
	st.lazy[node] = initial
	if right-left == 1 {
		return
	}
	mid := (left + right) / 2
	st.build(node*2, left, mid, initial)
	st.build(node*2+1, mid, right, initial)
}

func (st *SegmentTree) apply(node, value int) {
	st.min[node] = value
	st.lazy[node] = value
}

func (st *SegmentTree) push(node int) {
	if st.lazy[node] != -1 {
		st.apply(node*2, st.lazy[node])
		st.apply(node*2+1, st.lazy[node])
		st.lazy[node] = -1
	}
}

func (st *SegmentTree) Assign(ql, qr, value int) {
	st.assign(1, 0, st.n, ql, qr, value)
}

func (st *SegmentTree) assign(node, left, right, ql, qr, value int) {
	if qr <= left || right <= ql {
		return
	}
	if ql <= left && right <= qr {
		st.apply(node, value)
		return
	}
	st.push(node)
	mid := (left + right) / 2
	st.assign(node*2, left, mid, ql, qr, value)
	st.assign(node*2+1, mid, right, ql, qr, value)
	st.min[node] = min(st.min[node*2], st.min[node*2+1])
}

func (st *SegmentTree) QueryMin(ql, qr int) int {
	return st.queryMin(1, 0, st.n, ql, qr)
}

func (st *SegmentTree) queryMin(node, left, right, ql, qr int) int {
	if qr <= left || right <= ql {
		return int(^uint(0) >> 1)
	}
	if ql <= left && right <= qr {
		return st.min[node]
	}
	st.push(node)
	mid := (left + right) / 2
	return min(
		st.queryMin(node*2, left, mid, ql, qr),
		st.queryMin(node*2+1, mid, right, ql, qr),
	)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var H, W, N int
	fmt.Fscan(in, &H, &W, &N)

	bars := make([]Bar, N)
	for i := 0; i < N; i++ {
		fmt.Fscan(in, &bars[i].r, &bars[i].c, &bars[i].l)
		bars[i].id = i
	}

	sort.Slice(bars, func(i, j int) bool {
		if bars[i].r != bars[j].r {
			return bars[i].r > bars[j].r
		}
		return bars[i].id < bars[j].id
	})

	const noAssignment = -1
	sentinel := H + 1
	st := NewSegmentTree(W, sentinel)
	for i := range st.lazy {
		if st.lazy[i] == 0 {
			st.lazy[i] = noAssignment
		}
	}
	st.lazy[1] = sentinel

	answer := make([]int, N)

	for _, bar := range bars {
		left := bar.c - 1
		right := left + bar.l

		below := st.QueryMin(left, right)
		finalRow := H
		if below != sentinel {
			finalRow = below - 1
		}

		answer[bar.id] = finalRow
		st.Assign(left, right, finalRow)
	}

	for _, row := range answer {
		fmt.Fprintln(out, row)
	}
}
