func integerSqrt(n int64) int64 {
	var low, high int64 = 0, 2_000_001
	for low+1 < high {
		mid := (low + high) / 2
		if mid <= n/mid {
			low = mid
		} else {
			high = mid
		}
	}
	return low
}

func powerLE(base, exponent, limit int64) bool {
	result := int64(1)
	for i := int64(0); i < exponent; i++ {
		if result > limit/base {
			return false
		}
		result *= base
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	fmt.Fscan(in, &n)

	limit := int(integerSqrt(n))

	isPrime := make([]bool, limit+1)
	for i := 2; i <= limit; i++ {
		isPrime[i] = true
	}
	for i := 2; i <= limit/i; i++ {
		if isPrime[i] {
			for j := i * i; j <= limit; j += i {
				isPrime[j] = false
			}
		}
	}

	primes := make([]int, 0)
	for i := 2; i <= limit; i++ {
		if isPrime[i] {
			primes = append(primes, i)
		}
	}

	var answer int64

	// Numbers of the form p^8.
	for _, p := range primes {
		if powerLE(int64(p), 8, n) {
			answer++
		} else {
			break
		}
	}

	// Numbers of the form p^2*q^2 for distinct primes p and q.
	j := len(primes) - 1
	for i := 0; i < len(primes); i++ {
		for j > i && int64(primes[i])*int64(primes[j]) > int64(limit) {
			j--
		}
		if j <= i {
			break
		}
		answer += int64(j - i)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
