func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	fmt.Fscan(in, &n)

	limit := int64(math.Sqrt(float64(n)))
	for (limit+1)*(limit+1) <= n {
		limit++
	}
	for limit*limit > n {
		limit--
	}

	composite := make([]bool, int(limit)+1)
	primes := make([]int64, 0)

	for i := 2; i <= int(limit); i++ {
		if !composite[i] {
			primes = append(primes, int64(i))
			if int64(i)*int64(i) <= limit {
				for j := i * i; j <= int(limit); j += i {
					composite[j] = true
				}
			}
		}
	}

	var answer int64

	// Numbers of the form p^2 * q^2, where p and q are distinct primes.
	right := len(primes) - 1
	for left := 0; left < len(primes); left++ {
		for right > left && primes[left]*primes[right] > limit {
			right--
		}
		if right <= left {
			break
		}
		answer += int64(right - left)
	}

	// Numbers of the form p^8.
	for _, p := range primes {
		value := int64(1)
		ok := true
		for i := 0; i < 8; i++ {
			if value > n/p {
				ok = false
				break
			}
			value *= p
		}
		if !ok {
			break
		}
		answer++
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
