package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Edge struct {
	u, v int
	w    int64
}

type DSU struct {
	parent  []int
	size    []int
	balance []int64
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{
		parent:  parent,
		size:    size,
		balance: make([]int64, n),
	}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	k := int(in.NextInt64())

	edges := make([]Edge, m)
	for i := 0; i < m; i++ {
		edges[i] = Edge{
			u: int(in.NextInt64()) - 1,
			v: int(in.NextInt64()) - 1,
			w: in.NextInt64(),
		}
	}

	dsu := NewDSU(n)

	for i := 0; i < k; i++ {
		a := int(in.NextInt64()) - 1
		dsu.balance[a]++
	}
	for i := 0; i < k; i++ {
		b := int(in.NextInt64()) - 1
		dsu.balance[b]--
	}

	sort.Slice(edges, func(i, j int) bool {
		return edges[i].w < edges[j].w
	})

	var answer int64

	for _, e := range edges {
		ru := dsu.Find(e.u)
		rv := dsu.Find(e.v)
		if ru == rv {
			continue
		}

		before := abs(dsu.balance[ru]) + abs(dsu.balance[rv])
		mergedBalance := dsu.balance[ru] + dsu.balance[rv]
		matched := (before - abs(mergedBalance)) / 2
		answer += matched * e.w

		if dsu.size[ru] < dsu.size[rv] {
			ru, rv = rv, ru
		}
		dsu.parent[rv] = ru
		dsu.size[ru] += dsu.size[rv]
		dsu.balance[ru] = mergedBalance
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
