type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1

	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Edge struct {
	u, v int
	w    int64
}

type DSU struct {
	parent []int
	size   []int
	a      []int64
	b      []int64
}

func NewDSU(n int) *DSU {
	d := &DSU{
		parent: make([]int, n),
		size:   make([]int, n),
		a:      make([]int64, n),
		b:      make([]int64, n),
	}
	for i := 0; i < n; i++ {
		d.parent[i] = i
		d.size[i] = 1
	}
	return d
}

func (d *DSU) Find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.Find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) Union(x, y int, weight int64) int64 {
	x = d.Find(x)
	y = d.Find(y)
	if x == y {
		return 0
	}
	if d.size[x] < d.size[y] {
		x, y = y, x
	}

	d.parent[y] = x
	d.size[x] += d.size[y]

	totalA := d.a[x] + d.a[y]
	totalB := d.b[x] + d.b[y]
	matched := totalA
	if totalB < matched {
		matched = totalB
	}

	d.a[x] = totalA - matched
	d.b[x] = totalB - matched

	return matched * weight
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	k := int(in.NextInt64())

	edges := make([]Edge, m)
	for i := 0; i < m; i++ {
		edges[i] = Edge{
			u: int(in.NextInt64()) - 1,
			v: int(in.NextInt64()) - 1,
			w: in.NextInt64(),
		}
	}

	dsu := NewDSU(n)

	for i := 0; i < k; i++ {
		v := int(in.NextInt64()) - 1
		dsu.a[v]++
	}
	for i := 0; i < k; i++ {
		v := int(in.NextInt64()) - 1
		dsu.b[v]++
	}

	sort.Slice(edges, func(i, j int) bool {
		return edges[i].w < edges[j].w
	})

	var answer int64
	for _, e := range edges {
		answer += dsu.Union(e.u, e.v, e.w)
	}

	fmt.Fprintln(out, answer)
}
