package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var A, B int
	var mod int64
	fmt.Fscan(in, &A, &B, &mod)

	lambda := make([]int, B)
	for i := 0; i < B-1; i++ {
		lambda[i] = A
	}
	lambda[B-1] = A - 1

	modPow := func(a, e int64) int64 {
		res := int64(1)
		for e > 0 {
			if e&1 == 1 {
				res = res * a % mod
			}
			a = a * a % mod
			e >>= 1
		}
		return res
	}

	tableauCount := func(shape []int) int64 {
		n := 0
		for _, x := range shape {
			n += x
		}

		res := int64(1)
		for i := 2; i <= n; i++ {
			res = res * int64(i) % mod
		}

		for r, width := range shape {
			for c := 0; c < width; c++ {
				below := 0
				for rr := r + 1; rr < len(shape); rr++ {
					if shape[rr] > c {
						below++
					}
				}
				hook := width - c + below
				res = res * modPow(int64(hook), mod-2) % mod
			}
		}
		return res
	}

	fLambda := tableauCount(lambda)

	// Binomial coefficients are used to encode a partition state uniquely
	// by its boundary path. A+B <= 62 under the constraints.
	maxN := A + B
	comb := make([][]uint64, maxN+1)
	for n := 0; n <= maxN; n++ {
		comb[n] = make([]uint64, n+1)
		comb[n][0] = 1
		comb[n][n] = 1
		for k := 1; k < n; k++ {
			comb[n][k] = comb[n-1][k-1] + comb[n-1][k]
		}
	}

	counts := make([]int, B)
	total := A*B - 1
	memo := make(map[uint64]int64)

	encode := func() uint64 {
		var rank uint64
		for j := 0; j < B; j++ {
			p := counts[B-1-j] + j
			rank += comb[p][j+1]
		}
		return rank
	}

	var dfs func(int) int64
	dfs = func(used int) int64 {
		if used == total {
			return 1
		}

		key := encode()
		if value, ok := memo[key]; ok {
			return value
		}

		var result int64
		for r := 0; r < B; r++ {
			capacity := A
			if r == B-1 {
				capacity = A - 1
			}
			if counts[r] >= capacity {
				continue
			}
			if r > 0 && counts[r] >= counts[r-1] {
				continue
			}

			newColumn := counts[r] + 1

			// To make row insertion finish at the missing southeast
			// corner, the last cell of row r must come after the
			// penultimate-column cell of row r+1.
			if newColumn == A && r+1 < B && counts[r+1] < A-1 {
				continue
			}

			counts[r]++
			result += dfs(used + 1)
			if result >= mod {
				result %= mod
			}
			counts[r]--
		}

		result %= mod
		memo[key] = result
		return result
	}

	goodInsertionTableaux := dfs(0)
	answer := fLambda * goodInsertionTableaux % mod

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
