func modPow(a, e, mod int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func countSYT(rows []int, mod int64) int64 {
	n := 0
	for _, x := range rows {
		n += x
	}

	res := int64(1)
	for i := 2; i <= n; i++ {
		res = res * int64(i) % mod
	}

	hooks := int64(1)
	for r, length := range rows {
		for c := 0; c < length; c++ {
			below := 0
			for rr := r + 1; rr < len(rows); rr++ {
				if rows[rr] > c {
					below++
				}
			}
			hook := length - c + below
			hooks = hooks * int64(hook) % mod
		}
	}

	return res * modPow(hooks, mod-2, mod) % mod
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var A, B int
	var M int64
	fmt.Fscan(in, &A, &B, &M)

	lambda := make([]int, B)
	for i := 0; i < B-1; i++ {
		lambda[i] = A
	}
	lambda[B-1] = A - 1
	f := countSYT(lambda, M)

	var reduced []int
	if A >= B {
		reduced = make([]int, B)
		for i := 0; i < B-2; i++ {
			reduced[i] = A
		}
		reduced[B-2] = A - 1
		reduced[B-1] = A - 1
	} else {
		reduced = make([]int, B)
		for i := 0; i < B-1; i++ {
			reduced[i] = A
		}
		reduced[B-1] = A - 2
	}

	g := countSYT(reduced, M)
	fmt.Fprintln(out, f*g%M)
}
