package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type HashTable struct {
	keys   []int
	counts []int64
	sums   []int64
	used   []int32
	stamp  int32
	mask   uint64
}

func NewHashTable(n int) *HashTable {
	size := 2
	for size < 2*n {
		size <<= 1
	}
	return &HashTable{
		keys:   make([]int, size),
		counts: make([]int64, size),
		sums:   make([]int64, size),
		used:   make([]int32, size),
		mask:   uint64(size - 1),
	}
}

func hashInt(x uint64) uint64 {
	x += 0x9e3779b97f4a7c15
	x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9
	x = (x ^ (x >> 27)) * 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func (h *HashTable) Reset() {
	h.stamp++
}

func (h *HashTable) Get(key int) (int64, int64) {
	pos := hashInt(uint64(key)) & h.mask
	for h.used[pos] == h.stamp {
		if h.keys[pos] == key {
			return h.counts[pos], h.sums[pos]
		}
		pos = (pos + 1) & h.mask
	}
	return 0, 0
}

func (h *HashTable) Add(key, value int) {
	pos := hashInt(uint64(key)) & h.mask
	for h.used[pos] == h.stamp {
		if h.keys[pos] == key {
			h.counts[pos]++
			h.sums[pos] += int64(value)
			return
		}
		pos = (pos + 1) & h.mask
	}
	h.used[pos] = h.stamp
	h.keys[pos] = key
	h.counts[pos] = 1
	h.sums[pos] = int64(value)
}

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt() int {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] < '0' || fs.data[fs.pos] > '9') {
		fs.pos++
	}
	n := 0
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		n = n*10 + int(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return n
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()

	a := make([]int, n)
	var sum int64
	maxA := 0
	for i := range a {
		a[i] = in.NextInt()
		sum += int64(a[i])
		if a[i] > maxA {
			maxA = a[i]
		}
	}

	answer := int64(n+1) * sum
	table := NewHashTable(n)

	for mod := 2; mod <= 2*maxA; mod <<= 1 {
		table.Reset()
		mask := mod - 1
		var deduction int64

		for _, x := range a {
			residue := x & mask
			complement := (-residue) & mask

			count, previousSum := table.Get(complement)
			deduction += (int64(x)*count + previousSum) / int64(mod)

			if (2*x)&mask == 0 {
				deduction += int64(2*x) / int64(mod)
			}

			table.Add(residue, x)
		}

		answer -= deduction
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
