		deg[v]++
	}

	maxKept := int64(0)

	for center := 0; center < n; center++ {
		middleDegrees := make([]int, 0, len(adj[center]))
		for _, v := range adj[center] {
			if deg[v] >= 2 {
				middleDegrees = append(middleDegrees, deg[v])
			}
