		sort.Sort(sort.Reverse(sort.IntSlice(middleDegrees)))

		for i, d := range middleDegrees {
			x := int64(i + 1)
			kept := int64(1) + x*int64(d)
			if kept > maxKept {
				maxKept = kept
			}
		}
	}

	answer := int64(n) - maxKept

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
