		v--
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u)
		degree[u]++
		degree[v]++
	}

	maxRemaining := 0

	for center := 0; center < n; center++ {
		middleDegrees := make([]int, 0, len(graph[center]))
		for _, neighbor := range graph[center] {
			if degree[neighbor] >= 2 {
				middleDegrees = append(middleDegrees, degree[neighbor])
			}
		}

		sort.Sort(sort.Reverse(sort.IntSlice(middleDegrees)))

		for i, d := range middleDegrees {
			x := i + 1
			remaining := 1 + x*d
			if remaining > maxRemaining {
				maxRemaining = remaining
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, n-maxRemaining)
}
