```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) Next() string {
	buf := make([]byte, 0, 16)
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return string(buf)
		}
		if b > ' ' {
			buf = append(buf, b)
			break
		}
	}
	for {
		b, err := fs.r.ReadByte()
		if err != nil || b <= ' ' {
			return string(buf)
		}
		buf = append(buf, b)
	}
}

func (fs *FastScanner) Int64() int64 {
	s := fs.Next()
	var value int64
	sign := int64(1)
	i := 0
	if len(s) > 0 && s[0] == '-' {
		sign = -1
		i = 1
	}
	for ; i < len(s); i++ {
		value = value*10 + int64(s[i]-'0')
	}
	return value * sign
}

type House struct {
	x, y int64
}

type Entry struct {
	fixed int64
	coord int64
	id    int
}

type Segment struct {
	left, right int
}

func find(parent []int, x int) int {
	root := x
	for parent[root] != root {
		root = parent[root]
	}
	for parent[x] != x {
		next := parent[x]
		parent[x] = root
		x = next
	}
	return root
}

func main() {
	in := NewFastScanner()

	n := int(in.Int64())
	m := int(in.Int64())
	x := in.Int64()
	y := in.Int64()

	houses := make([]House, n)
	horizontal := make([]Entry, n)
	vertical := make([]Entry, n)

	for i := 0; i < n; i++ {
		hx := in.Int64()
		hy := in.Int64()
		houses[i] = House{hx, hy}
		horizontal[i] = Entry{fixed: hy, coord: hx, id: i}
		vertical[i] = Entry{fixed: hx, coord: hy, id: i}
	}

	sort.Slice(horizontal, func(i, j int) bool {
		if horizontal[i].fixed != horizontal[j].fixed {
			return horizontal[i].fixed < horizontal[j].fixed
		}
		return horizontal[i].coord < horizontal[j].coord
	})

	sort.Slice(vertical, func(i, j int) bool {
		if vertical[i].fixed != vertical[j].fixed {
			return vertical[i].fixed < vertical[j].fixed
		}
		return vertical[i].coord < vertical[j].coord
	})

	horizontalPos := make([]int, n)
	verticalPos := make([]int, n)
	horizontalGroups := make(map[int64]Segment)
	verticalGroups := make(map[int64]Segment)

	for i, entry := range horizontal {
		horizontalPos[entry.id] = i
	}
	for i := 0; i < n; {
		j := i + 1
		for j < n && horizontal[j].fixed == horizontal[i].fixed {
			j++
		}
		horizontalGroups[horizontal[i].fixed] = Segment{i, j}
		i = j
	}

	for i, entry := range vertical {
		verticalPos[entry.id] = i
	}
	for i := 0; i < n; {
		j := i + 1
		for j < n && vertical[j].fixed == vertical[i].fixed {
			j++
		}
		verticalGroups[vertical[i].fixed] = Segment{i, j}
		i = j
	}

	parentHorizontal := make([]int, n+1)
	parentVertical := make([]int, n+1)
	for i := 0; i <= n; i++ {
		parentHorizontal[i] = i
		parentVertical[i] = i
	}

	visitedCount := 0

	visitHouse := func(id int) {
		hp := horizontalPos[id]
		vp := verticalPos[id]
		parentHorizontal[hp] = find(parentHorizontal, hp+1)
		parentVertical[vp] = find(parentVertical, vp+1)
		visitedCount++
	}

	visitHorizontal := func(row, from, to int64) {
		if from > to {
			from, to = to, from
		}
		group, ok := horizontalGroups[row]
		if !ok {
			return
		}

		left := group.left + sort.Search(group.right-group.left, func(i int) bool {
			return horizontal[group.left+i].coord >= from
		})
		right := group.left + sort.Search(group.right-group.left, func(i int) bool {
			return horizontal[group.left+i].coord > to
		})

		for pos := find(parentHorizontal, left); pos < right; pos = find(parentHorizontal, pos) {
			visitHouse(horizontal[pos].id)
		}
	}

	visitVertical := func(column, from, to int64) {
		if from > to {
			from, to = to, from
		}
		group, ok := verticalGroups[column]
		if !ok {
			return
		}

		left := group.left + sort.Search(group.right-group.left, func(i int) bool {
			return vertical[group.left+i].coord >= from
		})
		right := group.left + sort.Search(group.right-group.left, func(i int) bool {
			return vertical[group.left+i].coord > to
		})

		for pos := find(parentVertical, left); pos < right; pos = find(parentVertical, pos) {
			visitHouse(vertical[pos].id)
		}
	}

	for i := 0; i < m; i++ {
		direction := in.Next()[0]
		distance := in.Int64()

		switch direction {
		case 'U':
			nextY := y + distance
			visitVertical(x, y, nextY)
			y = nextY
		case 'D':
			nextY := y - distance
			visitVertical(x, nextY, y)
			y = nextY
		case 'L':
			nextX := x - distance
			visitHorizontal(y, nextX, x)
			x = nextX
		case 'R':
			nextX := x + distance
			visitHorizontal(y, x, nextX)
			x = nextX
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintf(out, "%d %d %d\n", x, y, visitedCount)
}
