package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) skipSpaces() {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
}

func (fs *FastScanner) NextInt64() int64 {
	fs.skipSpaces()

	var sign int64 = 1
	if fs.data[fs.pos] == '-' {
		sign = -1
		fs.pos++
	}

	var value int64
	for fs.pos < len(fs.data) {
		c := fs.data[fs.pos]
		if c < '0' || c > '9' {
			break
		}
		value = value*10 + int64(c-'0')
		fs.pos++
	}
	return value * sign
}

func (fs *FastScanner) NextByte() byte {
	fs.skipSpaces()
	c := fs.data[fs.pos]
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return c
}

type Node struct {
	key         int64
	priority    uint64
	left, right *Node
}

var randomState uint64 = 0x9e3779b97f4a7c15

func nextRandom() uint64 {
	randomState ^= randomState << 7
	randomState ^= randomState >> 9
	randomState ^= randomState << 8
	return randomState
}

func split(root *Node, key int64) (*Node, *Node) {
	if root == nil {
		return nil, nil
	}
	if root.key < key {
		leftOfRight, right := split(root.right, key)
		root.right = leftOfRight
		return root, right
	}
	left, rightOfLeft := split(root.left, key)
	root.left = rightOfLeft
	return left, root
}

func insert(root *Node, node *Node) *Node {
	if root == nil {
		return node
	}
	if node.priority > root.priority {
		node.left, node.right = split(root, node.key)
		return node
	}
	if node.key < root.key {
		root.left = insert(root.left, node)
	} else {
		root.right = insert(root.right, node)
	}
	return root
}

func merge(left, right *Node) *Node {
	if left == nil {
		return right
	}
	if right == nil {
		return left
	}
	if left.priority > right.priority {
		left.right = merge(left.right, right)
		return left
	}
	right.left = merge(left, right.left)
	return right
}

func erase(root *Node, key int64) *Node {
	if root == nil {
		return nil
	}
	if key < root.key {
		root.left = erase(root.left, key)
		return root
	}
	if key > root.key {
		root.right = erase(root.right, key)
		return root
	}
	return merge(root.left, root.right)
}

func lowerBound(root *Node, key int64) *Node {
	var result *Node
	for root != nil {
		if root.key >= key {
			result = root
			root = root.left
		} else {
			root = root.right
		}
	}
	return result
}

func minMax(a, b int64) (int64, int64) {
	if a < b {
		return a, b
	}
	return b, a
}

func main() {
	in := NewFastScanner()

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	x := in.NextInt64()
	y := in.NextInt64()

	// xRoots[x] contains all currently unvisited house y-coordinates at x.
	// yRoots[y] contains all currently unvisited house x-coordinates at y.
	xRoots := make(map[int64]*Node, n)
	yRoots := make(map[int64]*Node, n)

	for i := 0; i < n; i++ {
		hx := in.NextInt64()
		hy := in.NextInt64()

		xRoots[hx] = insert(xRoots[hx], &Node{
			key:      hy,
			priority: nextRandom(),
		})
		yRoots[hy] = insert(yRoots[hy], &Node{
			key:      hx,
			priority: nextRandom(),
		})
	}

	visited := 0

	for i := 0; i < m; i++ {
		direction := in.NextByte()
		distance := in.NextInt64()

		switch direction {
		case 'L', 'R':
			nextX := x
			if direction == 'L' {
				nextX -= distance
			} else {
				nextX += distance
			}

			low, high := minMax(x, nextX)
			for {
				node := lowerBound(yRoots[y], low)
				if node == nil || node.key > high {
					break
				}

				hx := node.key
				yRoots[y] = erase(yRoots[y], hx)
				xRoots[hx] = erase(xRoots[hx], y)
				visited++
			}
			x = nextX

		case 'U', 'D':
			nextY := y
			if direction == 'D' {
				nextY -= distance
			} else {
				nextY += distance
			}

			low, high := minMax(y, nextY)
			for {
				node := lowerBound(xRoots[x], low)
				if node == nil || node.key > high {
					break
				}

				hy := node.key
				xRoots[x] = erase(xRoots[x], hy)
				yRoots[hy] = erase(yRoots[hy], x)
				visited++
			}
			y = nextY
		}
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintf(out, "%d %d %d\n", x, y, visited)
	out.Flush()
}
