```go
package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt() int {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] < '0' || fs.data[fs.pos] > '9') {
		fs.pos++
	}
	n := 0
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		n = n*10 + int(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return n
}

type Fenwick struct {
	count []int64
	sum   []int64
	n     int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		count: make([]int64, n+1),
		sum:   make([]int64, n+1),
		n:     n,
	}
}

func (f *Fenwick) Add(index int, countDelta, sumDelta int64) {
	for index <= f.n {
		f.count[index] += countDelta
		f.sum[index] += sumDelta
		index += index & -index
	}
}

func (f *Fenwick) Prefix(index int) (int64, int64) {
	var count, sum int64
	for index > 0 {
		count += f.count[index]
		sum += f.sum[index]
		index -= index & -index
	}
	return count, sum
}

type Query struct {
	x, y  int
	index int
	block int
}

func distanceToSet(f *Fenwick, rank int, value, totalCount, totalSum int64) int64 {
	leftCount, leftSum := f.Prefix(rank)
	rightCount := totalCount - leftCount
	rightSum := totalSum - leftSum
	return value*leftCount - leftSum + rightSum - value*rightCount
}

func main() {
	in := NewFastScanner()

	n := in.NextInt()
	a := make([]int64, n)
	b := make([]int64, n)
	values := make([]int64, 0, 2*n)

	for i := 0; i < n; i++ {
		a[i] = int64(in.NextInt())
		values = append(values, a[i])
	}
	for i := 0; i < n; i++ {
		b[i] = int64(in.NextInt())
		values = append(values, b[i])
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})
	unique := values[:0]
	for _, v := range values {
		if len(unique) == 0 || unique[len(unique)-1] != v {
			unique = append(unique, v)
		}
	}

	rankA := make([]int, n)
	rankB := make([]int, n)
	for i := 0; i < n; i++ {
		rankA[i] = sort.Search(len(unique), func(j int) bool {
			return unique[j] >= a[i]
		}) + 1
		rankB[i] = sort.Search(len(unique), func(j int) bool {
			return unique[j] >= b[i]
		}) + 1
	}

	prefixA := make([]int64, n+1)
	prefixB := make([]int64, n+1)
	for i := 0; i < n; i++ {
		prefixA[i+1] = prefixA[i] + a[i]
		prefixB[i+1] = prefixB[i] + b[i]
	}

	k := in.NextInt()
	queries := make([]Query, k)

	sqrtK := 1
	for (sqrtK+1)*(sqrtK+1) <= k {
		sqrtK++
	}
	blockSize := n / sqrtK
	if blockSize < 1 {
		blockSize = 1
	}

	for i := 0; i < k; i++ {
		x := in.NextInt()
		y := in.NextInt()
		queries[i] = Query{
			x:     x,
			y:     y,
			index: i,
			block: (x - 1) / blockSize,
		}
	}

	sort.Slice(queries, func(i, j int) bool {
		if queries[i].block != queries[j].block {
			return queries[i].block < queries[j].block
		}
		if queries[i].block&1 == 0 {
			return queries[i].y < queries[j].y
		}
		return queries[i].y > queries[j].y
	})

	bitA := NewFenwick(len(unique))
	bitB := NewFenwick(len(unique))
	answers := make([]int64, k)

	currentX, currentY := 0, 0
	var currentAnswer int64

	for _, q := range queries {
		for currentX < q.x {
			value := a[currentX]
			currentAnswer += distanceToSet(
				bitB, rankA[currentX], value,
				int64(currentY), prefixB[currentY],
			)
			bitA.Add(rankA[currentX], 1, value)
			currentX++
		}
		for currentX > q.x {
			currentX--
			value := a[currentX]
			currentAnswer -= distanceToSet(
				bitB, rankA[currentX], value,
				int64(currentY), prefixB[currentY],
			)
			bitA.Add(rankA[currentX], -1, -value)
		}
		for currentY < q.y {
			value := b[currentY]
			currentAnswer += distanceToSet(
				bitA, rankB[currentY], value,
				int64(currentX), prefixA[currentX],
			)
			bitB.Add(rankB[currentY], 1, value)
			currentY++
		}
		for currentY > q.y {
			currentY--
			value := b[currentY]
			currentAnswer -= distanceToSet(
				bitA, rankB[currentY], value,
				int64(currentX), prefixA[currentX],
			)
			bitB.Add(rankB[currentY], -1, -value)
		}
		answers[q.index] = currentAnswer
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	buffer := make([]byte, 0, k*24)
	for _, answer := range answers {
		buffer = strconv.AppendInt(buffer, answer, 10)
		buffer = append(buffer, '\n')
	}
	_, _ = out.Write(buffer)
	_ = out.Flush()
}
