func main() {
	in := bufio.NewReader(os.Stdin)

	var k int
	var s, t string
	fmt.Fscan(in, &k, &s, &t)

	possible := false

	if len(s) == len(t) {
		mismatches := 0
		for i := 0; i < len(s); i++ {
			if s[i] != t[i] {
				mismatches++
			}
		}
		possible = mismatches <= k
	} else if k >= 1 && abs(len(s)-len(t)) == 1 {
		shorter, longer := s, t
		if len(shorter) > len(longer) {
			shorter, longer = longer, shorter
		}

		i, j := 0, 0
		skips := 0
		for i < len(shorter) && j < len(longer) {
			if shorter[i] == longer[j] {
				i++
				j++
			} else {
				skips++
				j++
			}
		}
		skips += len(longer) - j
		possible = skips <= k
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if possible {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
