		}
		possible = mismatches <= k
	} else if abs(len(s)-len(t)) <= k {
		shorter, longer := s, t
		if len(shorter) > len(longer) {
			shorter, longer = longer, shorter
		}

		i := 0
		for j := 0; j < len(longer) && i < len(shorter); j++ {
			if shorter[i] == longer[j] {
				i++
			}
		}
		possible = i == len(shorter)
	}

	if possible {
		fmt.Fprintln(out, "Yes")
	} else {
		fmt.Fprintln(out, "No")
	}
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
