package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

type FastScanner struct {
	r   *bufio.Reader
	buf []byte
}

func NewFastScanner() *FastScanner {
	return &FastScanner{
		r:   bufio.NewReaderSize(os.Stdin, 1<<20),
		buf: make([]byte, 0, 32),
	}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	sign := int64(1)
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func (fs *FastScanner) NextInt() int {
	return int(fs.NextInt64())
}

type WaveletMatrix struct {
	n         int
	bits      int
	zeroCount []int32
	zeroSum   []int64
	zeroTotal []int
	prefixSum []int64
}

func buildWavelet(values []int64, ranks []int, bitCount int) *WaveletMatrix {
	n := len(values)
	width := n + 1

	w := &WaveletMatrix{
		n:         n,
		bits:      bitCount,
		zeroCount: make([]int32, bitCount*width),
		zeroSum:   make([]int64, bitCount*width),
		zeroTotal: make([]int, bitCount),
		prefixSum: make([]int64, n+1),
	}

	for i, v := range values {
		w.prefixSum[i+1] = w.prefixSum[i] + v
	}

	curRanks := append([]int(nil), ranks...)
	curValues := append([]int64(nil), values...)
	nextRanks := make([]int, n)
	nextValues := make([]int64, n)

	for level := 0; level < bitCount; level++ {
		base := level * width
		shift := bitCount - 1 - level

		for i := 0; i < n; i++ {
			w.zeroCount[base+i+1] = w.zeroCount[base+i]
			w.zeroSum[base+i+1] = w.zeroSum[base+i]
			if ((curRanks[i] >> shift) & 1) == 0 {
				w.zeroCount[base+i+1]++
				w.zeroSum[base+i+1] += curValues[i]
			}
		}

		zeros := int(w.zeroCount[base+n])
		w.zeroTotal[level] = zeros
		zPos, oPos := 0, zeros

		for i := 0; i < n; i++ {
			if ((curRanks[i] >> shift) & 1) == 0 {
				nextRanks[zPos] = curRanks[i]
				nextValues[zPos] = curValues[i]
				zPos++
			} else {
				nextRanks[oPos] = curRanks[i]
				nextValues[oPos] = curValues[i]
				oPos++
			}
		}

		curRanks, nextRanks = nextRanks, curRanks
		curValues, nextValues = nextValues, curValues
	}

	return w
}

// absPrefix returns sum_{i=0}^{end-1} |values[i]-value|.
func (w *WaveletMatrix) absPrefix(end, rank int, value int64) int64 {
	l, r := 0, end
	lessCount := 0
	var lessSum int64
	width := w.n + 1

	for level := 0; level < w.bits; level++ {
		base := level * width
		zl := int(w.zeroCount[base+l])
		zr := int(w.zeroCount[base+r])

		shift := w.bits - 1 - level
		if ((rank >> shift) & 1) != 0 {
			lessCount += zr - zl
			lessSum += w.zeroSum[base+r] - w.zeroSum[base+l]

			zeros := w.zeroTotal[level]
			l = zeros + (l - zl)
			r = zeros + (r - zr)
		} else {
			l = zl
			r = zr
		}
	}

	c := int64(lessCount)
	totalCount := int64(end)
	totalSum := w.prefixSum[end]

	return value*c - lessSum +
		(totalSum-lessSum) - value*(totalCount-c)
}

type Query struct {
	x, y  int
	index int
	block int
}

func main() {
	in := NewFastScanner()

	n := in.NextInt()
	a := make([]int64, n)
	b := make([]int64, n)
	all := make([]int64, 0, 2*n)

	for i := 0; i < n; i++ {
		a[i] = in.NextInt64()
		all = append(all, a[i])
	}
	for i := 0; i < n; i++ {
		b[i] = in.NextInt64()
		all = append(all, b[i])
	}

	sort.Slice(all, func(i, j int) bool {
		return all[i] < all[j]
	})
	unique := all[:0]
	for _, v := range all {
		if len(unique) == 0 || unique[len(unique)-1] != v {
			unique = append(unique, v)
		}
	}

	rankOf := func(v int64) int {
		return sort.Search(len(unique), func(i int) bool {
			return unique[i] >= v
		})
	}

	aRanks := make([]int, n)
	bRanks := make([]int, n)
	for i := 0; i < n; i++ {
		aRanks[i] = rankOf(a[i])
		bRanks[i] = rankOf(b[i])
	}

	bitCount := 1
	for (1 << bitCount) < len(unique) {
		bitCount++
	}

	waveA := buildWavelet(a, aRanks, bitCount)
	waveB := buildWavelet(b, bRanks, bitCount)

	k := in.NextInt()
	queries := make([]Query, k)

	sqrtK := 1
	for (sqrtK+1)*(sqrtK+1) <= k {
		sqrtK++
	}
	blockSize := n / sqrtK
	if blockSize < 1 {
		blockSize = 1
	}

	for i := 0; i < k; i++ {
		x := in.NextInt()
		y := in.NextInt()
		queries[i] = Query{
			x:     x,
			y:     y,
			index: i,
			block: x / blockSize,
		}
	}

	sort.Slice(queries, func(i, j int) bool {
		if queries[i].block != queries[j].block {
			return queries[i].block < queries[j].block
		}
		if queries[i].block&1 == 0 {
			return queries[i].y < queries[j].y
		}
		return queries[i].y > queries[j].y
	})

	answers := make([]int64, k)
	curX, curY := 0, 0
	var current int64

	for _, q := range queries {
		for curX < q.x {
			current += waveB.absPrefix(curY, aRanks[curX], a[curX])
			curX++
		}
		for curX > q.x {
			curX--
			current -= waveB.absPrefix(curY, aRanks[curX], a[curX])
		}
		for curY < q.y {
			current += waveA.absPrefix(curX, bRanks[curY], b[curY])
			curY++
		}
		for curY > q.y {
			curY--
			current -= waveA.absPrefix(curX, bRanks[curY], b[curY])
		}
		answers[q.index] = current
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	buf := make([]byte, 0, 32)
	for _, answer := range answers {
		buf = strconv.AppendInt(buf[:0], answer, 10)
		buf = append(buf, '\n')
		out.Write(buf)
	}
	out.Flush()
}
