type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextUint64() uint64 {
	var n uint64
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b >= '0' && b <= '9' {
			n = uint64(b - '0')
			break
		}
	}
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return n
		}
		if b < '0' || b > '9' {
			return n
		}
		n = n*10 + uint64(b-'0')
	}
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextUint64())
	k := int(in.NextUint64())

	a := make([]uint64, n)
	var totalXOR uint64
	for i := range a {
		a[i] = in.NextUint64()
		totalXOR ^= a[i]
	}

	r := k
	useComplement := false
	if n-k < k {
		r = n - k
		useComplement = true
	}

	var answer uint64
	var dfs func(start, need int, x uint64)
	dfs = func(start, need int, x uint64) {
		if need == 0 {
			value := x
			if useComplement {
				value ^= totalXOR
			}
			if value > answer {
				answer = value
			}
			return
		}

		last := n - need
		for i := start; i <= last; i++ {
			dfs(i+1, need-1, x^a[i])
		}
	}

	dfs(0, r, 0)
	fmt.Fprintln(out, answer)
}
