	var n int
	fmt.Fscan(in, &n)

	var prevX, prevH int64
	fmt.Fscan(in, &prevX, &prevH)

	if n == 1 {
		fmt.Fprintln(out, "-1")
		return
	}

	var bestNum, bestDen int64
	var left, right, a, b big.Int

	for i := 1; i < n; i++ {
		var x, h int64
		fmt.Fscan(in, &x, &h)

		num := prevH*x - h*prevX
		den := x - prevX

		if i == 1 {
			bestNum, bestDen = num, den
		} else {
			a.SetInt64(num)
			b.SetInt64(bestDen)
			left.Mul(&a, &b)

			a.SetInt64(bestNum)
			b.SetInt64(den)
			right.Mul(&a, &b)

			if left.Cmp(&right) > 0 {
				bestNum, bestDen = num, den
			}
		}

		prevX, prevH = x, h
	}

	if bestNum < 0 {
		fmt.Fprintln(out, "-1")
		return
	}

	answer := float64(bestNum) / float64(bestDen)
	fmt.Fprintf(out, "%.18f\n", answer)
