func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var k int
	var s, t string
	fmt.Fscan(in, &k, &s, &t)

	n, m := len(s), len(t)
	diff := n - m
	if diff < 0 {
		diff = -diff
	}
	if diff > k {
		fmt.Println("No")
		return
	}

	constOffset := k + 1
	size := 2*k + 3
	inf := k + 1

	prev := make([]int, size)
	curr := make([]int, size)
	for i := range prev {
		prev[i] = inf
		curr[i] = inf
	}

	// Base cases: edit distance from empty S to prefixes of T.
	limit := m
	if limit > k {
		limit = k
	}
	for j := 0; j <= limit; j++ {
		prev[j+constOffset] = j
	}

	for i := 1; i <= n; i++ {
		for x := range curr {
			curr[x] = inf
		}

		low := i - k
		if low < 0 {
			low = 0
		}
		high := i + k
		if high > m {
			high = m
		}

		for j := low; j <= high; j++ {
			d := j - i
			idx := d + constOffset
			best := inf

			// Delete s[i-1].
			if v := prev[idx+1] + 1; v < best {
				best = v
			}

			// Insert t[j-1].
			if j > 0 {
				if v := curr[idx-1] + 1; v < best {
					best = v
				}
			}

			// Match or replace.
			if j > 0 {
				cost := 0
				if s[i-1] != t[j-1] {
					cost = 1
				}
				if v := prev[idx] + cost; v < best {
					best = v
				}
			}

			curr[idx] = best
		}

		prev, curr = curr, prev
	}

	result := prev[m-n+constOffset]
	if result <= k {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
