```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 62

type Matrix [2][2]int64

type Anchor struct {
	x, y int64
	cost [2]int64
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func addSafe(a, b int64) int64 {
	if a >= INF || b >= INF || a > INF-b {
		return INF
	}
	return a + b
}

func identity() Matrix {
	return Matrix{{0, INF}, {INF, 0}}
}

func multiply(a, b Matrix) Matrix {
	var c Matrix
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			c[i][j] = INF
			for k := 0; k < 2; k++ {
				v := addSafe(a[i][k], b[k][j])
				if v < c[i][j] {
					c[i][j] = v
				}
			}
		}
	}
	return c
}

func matrixMin(a, b Matrix) Matrix {
	var c Matrix
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			c[i][j] = min64(a[i][j], b[i][j])
		}
	}
	return c
}

func power(a Matrix, n int64) Matrix {
	res := identity()
	for n > 0 {
		if n&1 != 0 {
			res = multiply(res, a)
		}
		a = multiply(a, a)
		n >>= 1
	}
	return res
}

func floorDiv(a, b int64) int64 {
	q := a / b
	r := a % b
	if r < 0 {
		q--
	}
	return q
}

func mod(a, b int64) int64 {
	r := a % b
	if r < 0 {
		r += b
	}
	return r
}

func orientation(x, y int64) int {
	if mod(x+y, 2) == 0 {
		return 0 // horizontal
	}
	return 1 // vertical
}

func actionMatrix(orient, axis, sign int, switchCost int64) Matrix {
	var m Matrix
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			m[i][j] = INF
		}
	}

	aligned := (orient == 0 && axis == 0) || (orient == 1 && axis == 1)
	if aligned {
		dest := 0
		if sign < 0 {
			dest = 1
		}
		m[0][dest] = 1
		m[1][dest] = 1
	} else {
		required := 1
		if sign < 0 {
			required = 0
		}
		for src := 0; src < 2; src++ {
			cost := int64(1)
			if src != required {
				cost += switchCost
			}
			m[src][0] = cost
			m[src][1] = cost
		}
	}
	return m
}

type Move struct {
	axis int
	sign int
}

func sequenceMatrix(orient int, moves []Move, switchCost int64) Matrix {
	res := identity()
	o := orient
	for _, mv := range moves {
		res = multiply(res, actionMatrix(o, mv.axis, mv.sign, switchCost))
		o ^= 1
	}
	return res
}

func diagonalUnit(orient, sx, sy int, switchCost int64) Matrix {
	a := sequenceMatrix(orient, []Move{{0, sx}, {1, sy}}, switchCost)
	b := sequenceMatrix(orient, []Move{{1, sy}, {0, sx}}, switchCost)
	return matrixMin(a, b)
}

func excessUnit(orient, majorAxis, majorSign int, switchCost int64) Matrix {
	straight := sequenceMatrix(orient, []Move{
		{majorAxis, majorSign},
		{majorAxis, majorSign},
	}, switchCost)

	minorAxis := majorAxis ^ 1
	base := []Move{
		{majorAxis, majorSign},
		{majorAxis, majorSign},
		{minorAxis, 1},
		{minorAxis, -1},
	}

	best := straight
	var permute func(int)
	permute = func(pos int) {
		if pos == len(base) {
			m := sequenceMatrix(orient, base, switchCost)
			best = matrixMin(best, m)
			return
		}
		for i := pos; i < len(base); i++ {
			duplicate := false
			for j := pos; j < i; j++ {
				if base[j] == base[i] {
					duplicate = true
					break
				}
			}
			if duplicate {
				continue
			}
			base[pos], base[i] = base[i], base[pos]
			permute(pos + 1)
			base[pos], base[i] = base[i], base[pos]
		}
	}
	permute(0)
	return best
}

func endpointDistance(dx, dy int64, startOrient int, switchCost int64) Matrix {
	ax, ay := dx, dy
	sx, sy := 1, 1
	if ax < 0 {
		ax = -ax
		sx = -1
	}
	if ay < 0 {
		ay = -ay
		sy = -1
	}

	diagCount := min64(ax, ay)
	var majorAxis, majorSign int
	var excess int64
	if ax >= ay {
		majorAxis, majorSign = 0, sx
		excess = ax - ay
	} else {
		majorAxis, majorSign = 1, sy
		excess = ay - ax
	}
	excessPairs := excess / 2
	hasOdd := excess&1 != 0

	type Segment int
	const (
		segDiag Segment = iota
		segExcess
		segOdd
	)

	segments := make([]Segment, 0, 3)
	if diagCount > 0 {
		segments = append(segments, segDiag)
	}
	if excessPairs > 0 {
		segments = append(segments, segExcess)
	}
	if hasOdd {
		segments = append(segments, segOdd)
	}

	best := Matrix{{INF, INF}, {INF, INF}}
	used := make([]bool, len(segments))
	order := make([]Segment, 0, len(segments))

	var dfs func()
	dfs = func() {
		if len(order) == len(segments) {
			cur := identity()
			o := startOrient
			for _, s := range order {
				switch s {
				case segDiag:
					u := diagonalUnit(o, sx, sy, switchCost)
					cur = multiply(cur, power(u, diagCount))
				case segExcess:
					u := excessUnit(o, majorAxis, majorSign, switchCost)
					cur = multiply(cur, power(u, excessPairs))
				case segOdd:
					cur = multiply(cur, actionMatrix(o, majorAxis, majorSign, switchCost))
					o ^= 1
				}
			}
			best = matrixMin(best, cur)
			return
		}
		for i := range segments {
			if used[i] {
				continue
			}
			used[i] = true
			order = append(order, segments[i])
			dfs()
			order = order[:len(order)-1]
			used[i] = false
		}
	}

	if len(segments) == 0 {
		return identity()
	}
	dfs()
	return best
}

func makeAnchors(K, x, y int64) (int64, int64, int64, int, []Anchor) {
	bx := floorDiv(x, K)
	by := floorDiv(y, K)
	o := orientation(bx, by)

	var k int64
	if o == 0 {
		k = y - by*K
	} else {
		k = x - bx*K
	}

	switchCost := min64(K-1, 4)
	to0 := min64(k, (K-1-k)+switchCost)
	to1 := min64(K-1-k, k+switchCost)

	anchors := []Anchor{
		{bx, by, [2]int64{to0, to1}},
	}

	if o == 0 {
		anchors = append(anchors,
			Anchor{bx - 1, by, [2]int64{INF, 1}},
			Anchor{bx + 1, by, [2]int64{1, INF}},
		)
	} else {
		anchors = append(anchors,
			Anchor{bx, by - 1, [2]int64{INF, 1}},
			Anchor{bx, by + 1, [2]int64{1, INF}},
		)
	}

	return bx, by, k, o, anchors
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var T int
	fmt.Fscan(in, &T)

	for ; T > 0; T-- {
		var K, sx, sy, tx, ty int64
		fmt.Fscan(in, &K, &sx, &sy, &tx, &ty)

		sbx, sby, sk, so, sa := makeAnchors(K, sx, sy)
		tbx, tby, tk, to, ta := makeAnchors(K, tx, ty)

		if sbx == tbx && sby == tby && so == to && sk == tk {
			fmt.Fprintln(out, 0)
			continue
		}

		switchCost := min64(K-1, 4)
		answer := INF

		if sbx == tbx && sby == tby && so == to {
			answer = min64(answer, sk-tk)
			if answer < 0 {
				answer = -answer
			}
		}

		for _, a := range sa {
			for _, b := range ta {
				dx := b.x - a.x
				dy := b.y - a.y
				m := endpointDistance(dx, dy, orientation(a.x, a.y), switchCost)

				for i := 0; i < 2; i++ {
					for j := 0; j < 2; j++ {
						v := addSafe(a.cost[i], m[i][j])
						v = addSafe(v, b.cost[j])
						if v < answer {
							answer = v
						}
					}
				}
			}
		}

		fmt.Fprintln(out, answer)
	}
}
