package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

type Point struct {
	x, y int64
}

func cross(a, b, c Point) int64 {
	return (b.x-a.x)*(c.y-a.y) - (b.y-a.y)*(c.x-a.x)
}

// Returns whether slope(a, q) <= slope(b, q).
func slopeLE(a, b, q Point) bool {
	left := (q.y - a.y) * (q.x - b.x)
	right := (q.y - b.y) * (q.x - a.x)
	return left <= right
}

func compareProducts(a, b, c, d uint64) int {
	hi1, lo1 := bits.Mul64(a, b)
	hi2, lo2 := bits.Mul64(c, d)
	if hi1 < hi2 || (hi1 == hi2 && lo1 < lo2) {
		return -1
	}
	if hi1 > hi2 || (hi1 == hi2 && lo1 > lo2) {
		return 1
	}
	return 0
}

// Returns whether n1/d1 > n2/d2, where d1,d2 are positive.
func fractionGreater(n1, d1, n2, d2 int64) bool {
	if n1 >= 0 && n2 < 0 {
		return true
	}
	if n1 < 0 && n2 >= 0 {
		return false
	}

	if n1 >= 0 {
		return compareProducts(uint64(n1), uint64(d2), uint64(n2), uint64(d1)) > 0
	}

	// For negative values, -a/d1 > -b/d2 iff a*d2 < b*d1.
	a := uint64(-n1)
	b := uint64(-n2)
	return compareProducts(a, uint64(d2), b, uint64(d1)) < 0
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	points := make([]Point, n)
	for i := range points {
		fmt.Fscan(in, &points[i].x, &points[i].y)
	}

	if n <= 1 {
		fmt.Fprintln(out, "-1")
		return
	}

	hull := make([]Point, 0, n)
	hull = append(hull, points[0])

	var bestNum, bestDen int64
	hasBest := false

	for i := 1; i < n; i++ {
		q := points[i]

		// Find the hull point minimizing the slope to q.
		left, right := 0, len(hull)-1
		for left < right {
			mid := (left + right) / 2
			if slopeLE(hull[mid], hull[mid+1], q) {
				right = mid
			} else {
				left = mid + 1
			}
		}

		p := hull[left]
		num := q.x*p.y - p.x*q.y
		den := q.x - p.x

		if !hasBest || fractionGreater(num, den, bestNum, bestDen) {
			bestNum, bestDen = num, den
			hasBest = true
		}

		// Maintain the upper convex hull.
		for len(hull) >= 2 && cross(hull[len(hull)-2], hull[len(hull)-1], q) >= 0 {
			hull = hull[:len(hull)-1]
		}
		hull = append(hull, q)
	}

	if !hasBest || bestNum < 0 {
		fmt.Fprintln(out, "-1")
		return
	}

	answer := float64(bestNum) / float64(bestDen)
	fmt.Fprintf(out, "%.18f\n", answer)
}
