package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) Next() string {
	for {
		b, err := fs.r.ReadByte()
		if err != nil {
			return ""
		}
		if b > ' ' {
			buf := []byte{b}
			for {
				b, err = fs.r.ReadByte()
				if err != nil || b <= ' ' {
					return string(buf)
				}
				buf = append(buf, b)
			}
		}
	}
}

func primitiveExponent(s string) int64 {
	n := len(s)
	pi := make([]int, n)

	for i := 1; i < n; i++ {
		j := pi[i-1]
		for j > 0 && s[i] != s[j] {
			j = pi[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		pi[i] = j
	}

	period := n - pi[n-1]
	if n%period == 0 {
		return int64(n / period)
	}
	return 1
}

func counts(x string) (zeros, ones int64) {
	for i := 0; i < len(x); i++ {
		if x[i] == '0' {
			zeros++
		} else {
			ones++
		}
	}
	return
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var t int
	fmt.Sscanf(in.Next(), "%d", &t)

	for ; t > 0; t-- {
		s := in.Next()
		x := in.Next()
		y := in.Next()

		k := primitiveExponent(s)
		zx, ox := counts(x)
		zy, oy := counts(y)

		// We need a nonnegative integer q satisfying:
		// (ox - oy) * q = (zy - zx) * k.
		a := ox - oy
		numerator := (zy - zx) * k

		ok := false
		if a == 0 {
			ok = numerator == 0
		} else if numerator%a == 0 {
			q := numerator / a
			ok = q >= 0
		}

		if ok {
			fmt.Fprintln(out, "Yes")
		} else {
			fmt.Fprintln(out, "No")
		}
	}
}
