type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := in.NextInt()
	for ; t > 0; t-- {
		n := in.NextInt()
		p := make([]int, n)

		sorted := true
		oneOperation := false
		prefixMax := 0

		for i := 1; i <= n; i++ {
			p[i-1] = in.NextInt()

			if p[i-1] != i {
				sorted = false
			}
			if p[i-1] == i && prefixMax < i {
				oneOperation = true
			}
			if p[i-1] > prefixMax {
				prefixMax = p[i-1]
			}
		}

		answer := 2
		if sorted {
			answer = 0
		} else if oneOperation {
			answer = 1
		} else if p[0] == n && p[n-1] == 1 {
			answer = 3
		}

		fmt.Fprintln(out, answer)
	}
