			continue
		}

		oneOperation := false
		prefixMax := 0
		for i := 0; i < n; i++ {
			if p[i] > prefixMax {
				prefixMax = p[i]
			}
			if p[i] == i+1 && prefixMax == i+1 {
				oneOperation = true
				break
			}
		}

		if oneOperation {
			fmt.Fprintln(out, 1)
		} else if p[0] == n && p[n-1] == 1 {
			fmt.Fprintln(out, 3)
		} else {
			fmt.Fprintln(out, 2)
		}
	}
