package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type Matrix struct {
	n int
	a []int64
}

func newMatrix(n int) Matrix {
	return Matrix{n: n, a: make([]int64, n*n)}
}

func multiply(x, y Matrix) Matrix {
	n := x.n
	z := newMatrix(n)

	for i := 0; i < n; i++ {
		iBase := i * n
		for k := 0; k < n; k++ {
			xik := x.a[iBase+k]
			if xik == 0 {
				continue
			}
			kBase := k * n
			for j := 0; j < n; j++ {
				if y.a[kBase+j] == 0 {
					continue
				}
				idx := iBase + j
				z.a[idx] = (z.a[idx] + xik*y.a[kBase+j]) % mod
			}
		}
	}
	return z
}

func multiplyVector(a Matrix, v []int64) []int64 {
	n := a.n
	res := make([]int64, n)
	for i := 0; i < n; i++ {
		var sum int64
		base := i * n
		for j := 0; j < n; j++ {
			if a.a[base+j] != 0 && v[j] != 0 {
				sum = (sum + a.a[base+j]*v[j]) % mod
			}
		}
		res[i] = sum
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var N int64
	var M int
	fmt.Fscan(in, &N, &M)

	allPrimes := []int{2, 3, 5, 7, 11, 13}
	primes := make([]int, 0, len(allPrimes))
	for _, p := range allPrimes {
		if p <= M {
			primes = append(primes, p)
		}
	}

	r := len(primes)
	states := 1 << r

	// deriv[mask] is the mixed derivative, at all variables equal to 1,
	// of sum_{a=1}^M prod_p x_p^{v_p(a)}.
	deriv := make([]int64, states)
	for a := 1; a <= M; a++ {
		exponents := make([]int64, r)
		for i, p := range primes {
			x := a
			for x%p == 0 {
				exponents[i]++
				x /= p
			}
		}

		for mask := 0; mask < states; mask++ {
			value := int64(1)
			for i := 0; i < r; i++ {
				if mask&(1<<i) != 0 {
					value *= exponents[i]
				}
			}
			deriv[mask] = (deriv[mask] + value) % mod
		}
	}

	// The last state accumulates the scores for lengths 1 through k.
	dim := states + 1
	trans := newMatrix(dim)

	for row := 0; row < states; row++ {
		for col := row; ; col = (col - 1) & row {
			remaining := row ^ col
			trans.a[row*dim+col] = deriv[remaining]

			if col == 0 {
				break
			}
		}
	}

	// accumulator' = accumulator + sum of all derivative states after transition
	for col := 0; col < states; col++ {
		var value int64
		for row := 0; row < states; row++ {
			value += trans.a[row*dim+col]
			if value >= mod {
				value -= mod
			}
		}
		trans.a[states*dim+col] = value
	}
	trans.a[states*dim+states] = 1

	vector := make([]int64, dim)
	vector[0] = 1 // Empty product before choosing any elements.

	for N > 0 {
		if N&1 == 1 {
			vector = multiplyVector(trans, vector)
		}
		N >>= 1
		if N > 0 {
			trans = multiply(trans, trans)
		}
	}

	fmt.Fprintln(out, vector[states])
}
