package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func multiply(a, b []int64, n int) []int64 {
	c := make([]int64, n*n)
	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			aik := a[i*n+k]
			if aik == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				bkj := b[k*n+j]
				if bkj == 0 {
					continue
				}
				idx := i*n + j
				c[idx] = (c[idx] + aik*bkj) % mod
			}
		}
	}
	return c
}

func multiplyVector(a, v []int64, n int) []int64 {
	res := make([]int64, n)
	for i := 0; i < n; i++ {
		var sum int64
		for j := 0; j < n; j++ {
			if a[i*n+j] != 0 && v[j] != 0 {
				sum = (sum + a[i*n+j]*v[j]) % mod
			}
		}
		res[i] = sum
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var N uint64
	var M int
	fmt.Fscan(in, &N, &M)

	allPrimes := []int{2, 3, 5, 7, 11, 13}
	primes := make([]int, 0, len(allPrimes))
	for _, p := range allPrimes {
		if p <= M {
			primes = append(primes, p)
		}
	}

	pCount := len(primes)
	dim := 1 << pCount

	valuations := make([][]int64, M+1)
	for x := 1; x <= M; x++ {
		valuations[x] = make([]int64, pCount)
		y := x
		for i, p := range primes {
			for y%p == 0 {
				valuations[x][i]++
				y /= p
			}
		}
	}

	// B maps the coefficients of f(e) to those of
	// sum_{x=1}^M f(e + valuation(x)).
	B := make([]int64, dim*dim)
	for s := 0; s < dim; s++ {
		for r := s; ; r = (r - 1) & s {
			diff := s ^ r
			var coefficient int64

			for x := 1; x <= M; x++ {
				product := int64(1)
				for p := 0; p < pCount; p++ {
					if diff&(1<<p) != 0 {
						product *= valuations[x][p]
					}
				}
				coefficient += product
			}

			B[r*dim+s] = coefficient % mod
			if r == 0 {
				break
			}
		}
	}

	// Add one state that accumulates the constant coefficient after
	// each application of B.
	size := dim + 1
	matrix := make([]int64, size*size)
	for i := 0; i < dim; i++ {
		for j := 0; j < dim; j++ {
			matrix[i*size+j] = B[i*dim+j]
		}
	}
	for j := 0; j < dim; j++ {
		matrix[dim*size+j] = B[j] // Row 0 of B.
	}
	matrix[dim*size+dim] = 1

	// The divisor-count polynomial is product_p (e_p + 1),
	// whose multilinear coefficients are all 1.
	vector := make([]int64, size)
	for i := 0; i < dim; i++ {
		vector[i] = 1
	}

	for N > 0 {
		if N&1 != 0 {
			vector = multiplyVector(matrix, vector, size)
		}
		N >>= 1
		if N > 0 {
			matrix = multiply(matrix, matrix, size)
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, vector[dim])
}
