	if len(answer) < n*k {
		lowerMiddle := n / 2
		answer = append(answer, lowerMiddle)
		count[lowerMiddle]--
	}

	// The rest is the lexicographically greatest possible completion.
	for value := n; value >= 1; value-- {
		for count[value] > 0 {
			answer = append(answer, value)
			count[value]--
		}
	}

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
