package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Fenwick struct {
	n    int
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int, n+1),
	}
}

func (f *Fenwick) Add(i, delta int) {
	for i <= f.n {
		f.tree[i] += delta
		i += i & -i
	}
}

func (f *Fenwick) Sum(i int) int {
	res := 0
	for i > 0 {
		res += f.tree[i]
		i -= i & -i
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	p := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
	}

	var m int
	fmt.Fscan(in, &m)

	a := make([]int, m)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	// leftGreater[j] is the number of elements before position j
	// whose values are greater than P[j].
	leftGreater := make([]int, n)
	bit := NewFenwick(n)
	var inversions int64

	for j, value := range p {
		lessBefore := bit.Sum(value - 1)
		leftGreater[j] = j - lessBefore
		inversions += int64(leftGreater[j])
		bit.Add(value, 1)
	}

	// An element at original position j resolves one inversion in each
	// operation starting from the first operation whose prefix reaches j,
	// for leftGreater[j] operations.
	diff := make([]int64, m+1)

	for j := 1; j <= n; j++ {
		count := leftGreater[j-1]
		if count == 0 {
			continue
		}

		start := sort.SearchInts(a, j)
		if start == m {
			continue
		}

		end := start + count - 1
		if end >= m {
			end = m - 1
		}

		diff[start]++
		diff[end+1]--
	}

	var swapsThisOperation int64
	for i := 0; i < m; i++ {
		swapsThisOperation += diff[i]
		inversions -= swapsThisOperation
		fmt.Fprintln(out, inversions)
	}
}
