package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func floorDiv(a, b int64) int64 {
	if a >= 0 {
		return a / b
	}
	return -((-a + b - 1) / b)
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := in.NextInt64()

	a := make([]int64, n)
	b := make([]int64, n)

	for i := range a {
		a[i] = in.NextInt64()
	}
	for i := range b {
		b[i] = in.NextInt64()
	}

	if m == 2 {
		for i := 0; i < n; i++ {
			if a[i] != b[i] {
				fmt.Fprintln(out, -1)
				return
			}
		}
		fmt.Fprintln(out, 0)
		return
	}

	z := make([]int64, n)
	var offset int64

	z[0] = b[0] - a[0]
	for i := 1; i < n; i++ {
		initialIncreasing := a[i-1] < a[i]
		targetIncreasing := b[i-1] < b[i]

		if initialIncreasing && !targetIncreasing {
			offset++
		} else if !initialIncreasing && targetIncreasing {
			offset--
		}

		z[i] = b[i] + m*offset - a[i]
	}

	sortedZ := append([]int64(nil), z...)
	sort.Slice(sortedZ, func(i, j int) bool {
		return sortedZ[i] < sortedZ[j]
	})

	median := sortedZ[n/2]
	q0 := floorDiv(-median, m)

	cost := func(q int64) int64 {
		var result int64
		for _, v := range z {
			result += abs(v + m*q)
		}
		return result
	}

	answer := cost(q0)
	if other := cost(q0 + 1); other < answer {
		answer = other
	}

	fmt.Fprintln(out, answer)
}
