			prefix--
		}
		c[i] = b[i] - a[i] + m*prefix
	}

	sorted := append([]int64(nil), c...)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i] < sorted[j]
	})

	median := sorted[n/2]
	baseK := floorDiv(-median, m)

	const inf int64 = 1 << 62
	answer := inf

	for k := baseK - 2; k <= baseK+3; k++ {
		var cost int64
		for _, x := range c {
			cost += abs64(x + m*k)
		}
		if cost < answer {
			answer = cost
		}
	}

	fmt.Fprintln(out, answer)
}
