package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
)

type uint128 struct {
	hi, lo uint64
}

func u128(x uint64) uint128 {
	return uint128{lo: x}
}

func add128(a, b uint128) uint128 {
	lo, carry := bits.Add64(a.lo, b.lo, 0)
	hi, _ := bits.Add64(a.hi, b.hi, carry)
	return uint128{hi: hi, lo: lo}
}

func sub128(a, b uint128) uint128 {
	lo, borrow := bits.Sub64(a.lo, b.lo, 0)
	hi, _ := bits.Sub64(a.hi, b.hi, borrow)
	return uint128{hi: hi, lo: lo}
}

func mul64(a, b uint64) uint128 {
	hi, lo := bits.Mul64(a, b)
	return uint128{hi: hi, lo: lo}
}

func scale128(a uint128, b uint64) uint128 {
	carry, lo := bits.Mul64(a.lo, b)
	hi := a.hi*b + carry
	return uint128{hi: hi, lo: lo}
}

func shr1(a uint128) uint128 {
	return uint128{
		hi: a.hi >> 1,
		lo: (a.lo >> 1) | (a.hi << 63),
	}
}

func sumIndices(n uint64) uint64 {
	return n * (n - 1) / 2
}

func sumSquares(n uint64) uint128 {
	if n == 0 {
		return uint128{}
	}
	x, y, z := n, n-1, 2*n-1

	if x%2 == 0 {
		x /= 2
	} else {
		y /= 2
	}

	if x%3 == 0 {
		x /= 3
	} else if y%3 == 0 {
		y /= 3
	} else {
		z /= 3
	}

	return scale128(mul64(x, y), z)
}

type momentsResult struct {
	sum   uint128 // sum floor((a*i+b)/m)
	isum  uint128 // sum i*floor((a*i+b)/m)
	sqsum uint128 // sum floor((a*i+b)/m)^2
}

func floorMoments(n, m, a, b uint64) momentsResult {
	if n == 0 {
		return momentsResult{}
	}

	qa, ra := a/m, a%m
	qb, rb := b/m, b%m

	var core momentsResult

	if ra != 0 {
		y := (ra*(n-1) + rb) / m
		if y != 0 {
			offset := m + ra - 1 - rb
			rec := floorMoments(y, ra, m, offset)

			core.sum = sub128(mul64(n, y), rec.sum)

			ySquaredN := scale128(mul64(y, y), n)
			temp := add128(scale128(rec.isum, 2), rec.sum)
			core.sqsum = sub128(ySquaredN, temp)

			left := scale128(u128(sumIndices(n)), y)
			right := shr1(sub128(rec.sqsum, rec.sum))
			core.isum = sub128(left, right)
		}
	}

	s1 := sumIndices(n)
	s2 := sumSquares(n)

	result := core

	result.sum = add128(result.sum, scale128(u128(s1), qa))
	result.sum = add128(result.sum, mul64(qb, n))

	result.isum = add128(result.isum, scale128(s2, qa))
	result.isum = add128(result.isum, scale128(u128(s1), qb))

	result.sqsum = add128(result.sqsum, scale128(s2, qa*qa))
	result.sqsum = add128(result.sqsum, scale128(mul64(qb, qb), n))
	result.sqsum = add128(result.sqsum, scale128(u128(s1), 2*qa*qb))
	result.sqsum = add128(result.sqsum, scale128(core.isum, 2*qa))
	result.sqsum = add128(result.sqsum, scale128(core.sum, 2*qb))

	return result
}

type prefixCalculator struct {
	k, m, d uint64
	base    momentsResult
	total   uint128
}

func newPrefixCalculator(k, m, d uint64) prefixCalculator {
	base := floorMoments(k, m, d, 0)
	total := sub128(
		scale128(u128(sumIndices(k)), d),
		scale128(base.sum, m),
	)
	return prefixCalculator{
		k:     k,
		m:     m,
		d:     d,
		base:  base,
		total: total,
	}
}

// Returns the count and sum of residues d*i mod m that are less than limit.
func (p prefixCalculator) prefix(limit uint64) (uint64, uint64) {
	if limit == 0 {
		return 0, 0
	}
	if limit >= p.m {
		return p.k, p.total.lo
	}

	shifted := floorMoments(p.k, p.m, p.d, p.m-limit)

	countGE128 := sub128(shifted.sum, p.base.sum)
	countGE := countGE128.lo

	indexSumGE := sub128(shifted.isum, p.base.isum)

	qSquareDiff := sub128(shifted.sqsum, p.base.sqsum)
	qSumGE := shr1(sub128(qSquareDiff, u128(countGE)))

	residueSumGE := sub128(
		scale128(indexSumGE, p.d),
		scale128(qSumGE, p.m),
	)

	countLess := p.k - countGE
	sumLess := sub128(p.total, residueSumGE).lo
	return countLess, sumLess
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var m, c, k uint64
	fmt.Fscan(in, &n, &m, &c, &k)

	values := make([]uint64, n)
	for i := range values {
		fmt.Fscan(in, &values[i])
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	unique := values[:0]
	for _, x := range values {
		if len(unique) == 0 || unique[len(unique)-1] != x {
			unique = append(unique, x)
		}
	}

	d := (m - c) % m
	calc := newPrefixCalculator(k, m, d)

	u := len(unique)
	prefixCount := make([]uint64, u)
	prefixSum := make([]uint64, u)

	for i, x := range unique {
		prefixCount[i], prefixSum[i] = calc.prefix(x + 1)
	}

	var answer uint64

	for i := 1; i < u; i++ {
		count := prefixCount[i] - prefixCount[i-1]
		sum := prefixSum[i] - prefixSum[i-1]
		answer += unique[i]*count - sum
	}

	first := unique[0]
	last := unique[u-1]

	upperCount := k - prefixCount[u-1]
	upperSum := calc.total.lo - prefixSum[u-1]
	answer += (first+m)*upperCount - upperSum

	lowerCount := prefixCount[0]
	lowerSum := prefixSum[0]
	answer += first*lowerCount - lowerSum

	fmt.Fprintln(out, answer)
}
