package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353
const INF int = 1 << 30
const reduceThreshold int64 = 4_000_000_000_000_000_000

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	m := in.NextInt()

	minR := make([][]int, n+2)
	for x := 0; x < n+2; x++ {
		minR[x] = make([]int, n+2)
		for l := 0; l < n+2; l++ {
			minR[x][l] = INF
		}
	}

	for i := 0; i < m; i++ {
		l := in.NextInt()
		r := in.NextInt()
		x := in.NextInt()
		if r < minR[x][l] {
			minR[x][l] = r
		}
	}

	// minR[x][l] becomes the minimum R among conditions with X=x and L>=l.
	for x := 1; x <= n; x++ {
		cur := INF
		for l := n; l >= 1; l-- {
			if minR[x][l] < cur {
				cur = minR[x][l]
			}
			minR[x][l] = cur
		}
	}

	inv := make([]int64, n+1)
	if n >= 1 {
		inv[1] = 1
	}
	for i := 2; i <= n; i++ {
		ii := int64(i)
		inv[i] = MOD - (MOD/ii)*inv[int(MOD%ii)]%MOD
	}

	dp := make([][]int64, n+2)
	for i := range dp {
		dp[i] = make([]int64, n+2)
	}

	for length := 1; length <= n; length++ {
		for l := 1; l+length-1 <= n; l++ {
			r := l + length - 1
			var sum int64

			for root := l; root <= r; root++ {
				// Invalid if some condition [L,R,root] is contained in [l,r].
				if minR[root][l] <= r {
					continue
				}

				leftWays := int64(1)
				if root > l {
					leftWays = dp[l][root-1]
				}

				rightWays := int64(1)
				if root < r {
					rightWays = dp[root+1][r]
				}

				sum += leftWays * rightWays
				if sum >= reduceThreshold {
					sum %= MOD
				}
			}

			sum %= MOD
			dp[l][r] = sum * inv[length] % MOD
		}
	}

	factorial := int64(1)
	for i := 2; i <= n; i++ {
		factorial = factorial * int64(i) % MOD
	}

	answer := dp[1][n] * factorial % MOD
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
