type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func possibleK1(a, b []int) bool {
	compressedA := make([]int, 0, len(a))
	for _, v := range a {
		if len(compressedA) == 0 || compressedA[len(compressedA)-1] != v {
			compressedA = append(compressedA, v)
		}
	}

	pos := 0
	lastB := 0
	hasLastB := false

	for _, v := range b {
		if hasLastB && v == lastB {
			continue
		}
		hasLastB = true
		lastB = v

		for pos < len(compressedA) && compressedA[pos] != v {
			pos++
		}
		if pos == len(compressedA) {
			return false
		}
		pos++
	}
	return true
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := in.NextInt()
	for ; t > 0; t-- {
		n := in.NextInt()
		k := in.NextInt()

		a := make([]int, n)
		b := make([]int, n)

		for i := range a {
			a[i] = in.NextInt()
		}
		for i := range b {
			b[i] = in.NextInt()
		}

		ok := true

		if k == 1 {
			ok = possibleK1(a, b)
		} else {
			seenA := make([]bool, n+1)
			seenB := make([]bool, n+1)
			distinctA, distinctB := 0, 0

			for _, v := range a {
				if !seenA[v] {
					seenA[v] = true
					distinctA++
				}
			}
			for _, v := range b {
				if !seenB[v] {
					seenB[v] = true
					distinctB++
					if !seenA[v] {
						ok = false
					}
				}
			}

			if ok && distinctA == n && distinctB == n {
				for i := 0; i < n; i++ {
					if a[i] != b[i] {
						ok = false
						break
					}
				}
			}
		}

		if ok {
			fmt.Fprintln(out, "Yes")
		} else {
			fmt.Fprintln(out, "No")
		}
	}
}
