func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var T int
	fmt.Fscan(in, &T)

	for ; T > 0; T-- {
		var n, k int
		fmt.Fscan(in, &n, &k)

		a := make([]int, n)
		present := make([]bool, n+1)
		for i := range a {
			fmt.Fscan(in, &a[i])
			present[a[i]] = true
		}

		b := make([]int, n)
		for i := range b {
			fmt.Fscan(in, &b[i])
		}

		possible := true

		if k == 1 {
			compressedA := make([]int, 0, n)
			for _, x := range a {
				if len(compressedA) == 0 || compressedA[len(compressedA)-1] != x {
					compressedA = append(compressedA, x)
				}
			}

			pos := 0
			last := -1
			for _, x := range b {
				if x == last {
					continue
				}
				last = x

				for pos < len(compressedA) && compressedA[pos] != x {
					pos++
				}
				if pos == len(compressedA) {
					possible = false
					break
				}
				pos++
			}
		} else {
			same := true
			for i := 0; i < n; i++ {
				if a[i] != b[i] {
					same = false
				}
				if !present[b[i]] {
					possible = false
				}
			}

			if possible && !same {
				lastPosition := make([]int, n+1)
				for i := range lastPosition {
					lastPosition[i] = -1
				}

				hasNearbyDuplicate := false
				for i, x := range b {
					if lastPosition[x] >= 0 && i-lastPosition[x] <= k {
						hasNearbyDuplicate = true
						break
					}
					lastPosition[x] = i
				}

				if !hasNearbyDuplicate {
					possible = false
				}
			}
