		for y := 1; y <= n; y++ {
			prefix[x][y] = grid[x][y] +
				prefix[x-1][y] +
				prefix[x][y-1] -
				prefix[x-1][y-1]
		}
	}

	rectCount := func(x1, x2, y1, y2 int) int {
		if x1 > x2 || y1 > y2 {
			return 0
		}
		return prefix[x2][y2] -
			prefix[x1-1][y2] -
			prefix[x2][y1-1] +
			prefix[x1-1][y1-1]
	}

	isGood := func(left, right int) bool {
		top := yAt[left]
		bottom := yAt[right]

		for x := left + 1; x < right; x++ {
			y := yAt[x]
			if y <= bottom || y >= top {
				continue
			}

			southWest := rectCount(left+1, x-1, bottom+1, y-1)
			northEast := rectCount(x+1, right-1, y+1, top-1)
			if southWest == 0 && northEast == 0 {
				return false
			}
		}
		return true
	}

	dp := make([]int64, n+2)
	dp[0] = 1

	for right := 1; right <= n+1; right++ {
		for left := 0; left < right; left++ {
			if yAt[left] > yAt[right] && isGood(left, right) {
				dp[right] += dp[left]
				if dp[right] >= mod {
					dp[right] -= mod
				}
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, dp[n+1])
