package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const mod int64 = 998244353

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) NextInt() int {
	for fs.pos < len(fs.data) && (fs.data[fs.pos] < '0' || fs.data[fs.pos] > '9') {
		fs.pos++
	}
	v := 0
	for fs.pos < len(fs.data) && fs.data[fs.pos] >= '0' && fs.data[fs.pos] <= '9' {
		v = v*10 + int(fs.data[fs.pos]-'0')
		fs.pos++
	}
	return v
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	m := in.NextInt()

	groupID := make(map[string]int)
	groups := make([][]int, 0)
	periods := make([]int, 0)

	for i := 0; i < n; i++ {
		a := make([]byte, m)
		first := m
		for j := 0; j < m; j++ {
			a[j] = byte(in.NextInt())
			if a[j] == 1 && first == m {
				first = j
			}
		}

		phase := 0
		period := 1

		if first < m {
			length := m - first
			for period < length {
				period <<= 1
			}

			for p := 1; p < length; p <<= 1 {
				if a[first+p] == 1 {
					phase += p
					for k := length - 1; k >= p; k-- {
						a[first+k] ^= a[first+k-p]
					}
				}
			}
		}

		key := string(a)
		id, ok := groupID[key]
		if !ok {
			id = len(groups)
			groupID[key] = id
			groups = append(groups, nil)
			periods = append(periods, period)
		}
		groups[id] = append(groups[id], phase)
	}

	var answer int64

	for id, phases := range groups {
		q := periods[id]
		bit := make([]int, q+1)

		add := func(pos int) {
			for x := pos + 1; x <= q; x += x & -x {
				bit[x]++
			}
		}
		prefixCount := func(pos int) int64 {
			var result int64
			for x := pos + 1; x > 0; x -= x & -x {
				result += int64(bit[x])
			}
			return result
		}

		var count, sumPhases int64
		for _, phase := range phases {
			p := int64(phase)
			notGreater := prefixCount(phase)
			greater := count - notGreater

			contribution := count*p - sumPhases + int64(q)*greater
			answer += contribution

			add(phase)
			count++
			sumPhases += p
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	fmt.Fprintln(out, answer%mod)
	out.Flush()
}
