package main

import (
	"bufio"
	"fmt"
	"os"
)

type Branch struct {
	start int
	pos   int
	rem   int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	head := make([]int, n)
	for i := range head {
		head[i] = -1
	}
	to := make([]int, 2*(n-1))
	next := make([]int, 2*(n-1))
	edgeCount := 0

	addEdge := func(u, v int) {
		to[edgeCount] = v
		next[edgeCount] = head[u]
		head[u] = edgeCount
		edgeCount++
	}

	for i := 0; i < n-1; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		addEdge(a, b)
		addEdge(b, a)
	}

	// First rooting: compute subtree sizes and find a centroid.
	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := make([]int, 0, n)
	stack = append(stack, 0)

	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, u)

		for e := head[u]; e != -1; e = next[e] {
			v := to[e]
			if v == parent[u] {
				continue
			}
			parent[v] = u
			stack = append(stack, v)
		}
	}

	sub := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		u := order[i]
		sub[u]++
		if parent[u] >= 0 {
			sub[parent[u]] += sub[u]
		}
	}

	centroid := 0
	for u := 0; u < n; u++ {
		maxPart := n - sub[u]
		for e := head[u]; e != -1; e = next[e] {
			v := to[e]
			if parent[v] == u && sub[v] > maxPart {
				maxPart = sub[v]
			}
		}
		if maxPart <= n/2 {
			centroid = u
			break
		}
	}

	// Root the tree at the centroid.
	parent2 := make([]int, n)
	for i := range parent2 {
		parent2[i] = -2
	}
	parent2[centroid] = -1

	order2 := make([]int, 0, n)
	stack = stack[:0]
	stack = append(stack, centroid)

	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order2 = append(order2, u)

		for e := head[u]; e != -1; e = next[e] {
			v := to[e]
			if v == parent2[u] {
				continue
			}
			parent2[v] = u
			stack = append(stack, v)
		}
	}

	sub2 := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		u := order2[i]
		sub2[u]++
		if parent2[u] >= 0 {
			sub2[parent2[u]] += sub2[u]
		}
	}

	// For every component adjacent to the centroid, build its valid
	// leaf-removal order. At each vertex, the unique odd child, if any,
	// is processed before the even children.
	deletionOrder := make([]int, 0, n-1)
	branches := make([]Branch, 0)
	tmp := make([]int, 0)

	for e := head[centroid]; e != -1; e = next[e] {
		root := to[e]
		if parent2[root] != centroid {
			continue
		}

		tmp = tmp[:0]
		stack = stack[:0]
		stack = append(stack, root)

		for len(stack) > 0 {
			u := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			tmp = append(tmp, u)

			oddChild := -1
			for ee := head[u]; ee != -1; ee = next[ee] {
				v := to[ee]
				if parent2[v] == u && sub2[v]%2 == 1 {
					oddChild = v
					break
				}
			}

			if oddChild != -1 {
				stack = append(stack, oddChild)
			}
			for ee := head[u]; ee != -1; ee = next[ee] {
				v := to[ee]
				if parent2[v] == u && v != oddChild {
					stack = append(stack, v)
				}
			}
		}

		start := len(deletionOrder)
		for i := len(tmp) - 1; i >= 0; i-- {
			deletionOrder = append(deletionOrder, tmp[i])
		}
		branches = append(branches, Branch{
			start: start,
			pos:   0,
			rem:   sub2[root],
		})
	}

	oddBranch := -1
	evenStack := make([]int, 0, len(branches))

	for i := range branches {
		if branches[i].rem%2 == 1 {
			oddBranch = i
		} else {
			evenStack = append(evenStack, i)
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	remaining := n - 1

	popVertex := func(idx int) int {
		b := &branches[idx]
		v := deletionOrder[b.start+b.pos]
		b.pos++
		b.rem--
		return v
	}

	for remaining > 1 {
		evenIdx := evenStack[len(evenStack)-1]
		evenStack = evenStack[:len(evenStack)-1]

		x := popVertex(oddBranch)
		y := popVertex(evenIdx)
		fmt.Fprintf(out, "%d %d\n", x+1, y+1)
		remaining -= 2

		if branches[oddBranch].rem > 0 {
			evenStack = append(evenStack, oddBranch)
		}
		oddBranch = evenIdx
	}

	last := popVertex(oddBranch)
	fmt.Fprintf(out, "%d %d\n", last+1, centroid+1)
}
