package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

type node struct {
	child [2]int32
	add   uint16
}

type uint128 struct {
	lo uint64
	hi uint64
}

func lessEqual(a, b uint128) bool {
	if a.hi != b.hi {
		return a.hi < b.hi
	}
	return a.lo <= b.lo
}

func feasible(r uint128, depth int, upper uint128) bool {
	if r.lo != 0 || r.hi != 0 {
		return lessEqual(r, upper)
	}

	var smallest uint128
	if depth < 64 {
		smallest.lo = uint64(1) << depth
	} else {
		smallest.hi = uint64(1) << (depth - 64)
	}
	return lessEqual(smallest, upper)
}

func residue(a uint64, t int) uint128 {
	lo, borrow := bits.Sub64(0, a, 0)
	hi, _ := bits.Sub64(0, 0, borrow)

	if t < 64 {
		var carry uint64
		lo, carry = bits.Add64(lo, uint64(1)<<t, 0)
		hi, _ = bits.Add64(hi, 0, carry)
	} else {
		hi, _ = bits.Add64(hi, uint64(1)<<(t-64), 0)
	}

	return uint128{lo: lo, hi: hi}
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]uint64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	maxA := a[n-1]

	nodes := make([]node, 1, n*305+1)

	for _, x := range a {
		for t := 0; t < 100; t++ {
			r := residue(x, t)
			depth := t + 2
			cur := int32(0)

			for d := 0; d < depth; d++ {
				var bit int
				if d < 64 {
					bit = int((r.lo >> d) & 1)
				} else {
					bit = int((r.hi >> (d - 64)) & 1)
				}

				next := nodes[cur].child[bit]
				if next == 0 {
					next = int32(len(nodes))
					nodes = append(nodes, node{})
					nodes[cur].child[bit] = next
				}
				cur = next
			}
			nodes[cur].add++
		}
	}

	sub := maxA + 1
	upperLo, borrow := bits.Sub64(0, sub, 0)
	upperHi, _ := bits.Sub64(uint64(1)<<36, 0, borrow)
	upper := uint128{lo: upperLo, hi: upperHi}

	answer := 0

	var dfs func(idx int32, depth int, r uint128, score int)
	dfs = func(idx int32, depth int, r uint128, score int) {
		if !feasible(r, depth, upper) {
			return
		}

		score += int(nodes[idx].add)
		if score > answer {
			answer = score
		}

		for bit := 0; bit < 2; bit++ {
			next := nodes[idx].child[bit]
			if next == 0 {
				continue
			}

			nr := r
			if bit == 1 {
				if depth < 64 {
					nr.lo |= uint64(1) << depth
				} else {
					nr.hi |= uint64(1) << (depth - 64)
				}
			}
			dfs(next, depth+1, nr, score)
		}
	}

	dfs(0, 0, uint128{}, 0)

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
