			divisors[multiple] = append(divisors[multiple], d)
		}
	}

	weightedMultiples := make([]int64, maxA+1)
	var answer int64
	weight := int64(1)

	for _, x := range a {
		var added int64
		for _, d := range divisors[x] {
			added += int64(phi[d]) * weightedMultiples[d] % mod
			if added >= mod {
