const mod int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type Group struct {
	period int
	phases []int
}

func mergeCount(a, tmp []int, left, right int) int64 {
	if right-left <= 1 {
		return 0
	}
	mid := (left + right) / 2
	inv := mergeCount(a, tmp, left, mid) + mergeCount(a, tmp, mid, right)

	i, j, k := left, mid, left
	for i < mid && j < right {
		if a[i] <= a[j] {
			tmp[k] = a[i]
			i++
		} else {
			tmp[k] = a[j]
			j++
			inv += int64(mid - i)
		}
		k++
	}
	for i < mid {
		tmp[k] = a[i]
		i++
		k++
	}
	for j < right {
		tmp[k] = a[j]
		j++
		k++
	}
	copy(a[left:right], tmp[left:right])
	return inv
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	n := in.NextInt()
	m := in.NextInt()

	groups := make([]Group, 0)
	smallKeys := make(map[uint64]int)
	largeKeys := make(map[string]int)

	row := make([]byte, m)

	for i := 0; i < n; i++ {
		first := m
		for j := 0; j < m; j++ {
			row[j] = byte(in.NextInt())
			if row[j] == 1 && first == m {
				first = j
			}
		}

		phase := 0
		period := 1

		if first < m {
			length := m - first
			for d := 1; d < length; d <<= 1 {
				if row[first+d] == 1 {
					phase += d
					for k := length - 1; k >= d; k-- {
						row[first+k] ^= row[first+k-d]
					}
				}
				period = d << 1
			}
		}

		groupIndex := -1

		if m <= 64 {
			var key uint64
			for j := 0; j < m; j++ {
				if row[j] != 0 {
					key |= uint64(1) << uint(j)
				}
			}
			if idx, ok := smallKeys[key]; ok {
				groupIndex = idx
			} else {
				groupIndex = len(groups)
				smallKeys[key] = groupIndex
				groups = append(groups, Group{period: period})
			}
		} else {
			packed := make([]byte, (m+7)/8)
			for j := 0; j < m; j++ {
				if row[j] != 0 {
					packed[j>>3] |= 1 << uint(j&7)
				}
			}
			key := string(packed)
			if idx, ok := largeKeys[key]; ok {
				groupIndex = idx
			} else {
				groupIndex = len(groups)
				largeKeys[key] = groupIndex
				groups = append(groups, Group{period: period})
			}
		}

		groups[groupIndex].phases = append(groups[groupIndex].phases, phase)
	}

	var answer int64

	for _, group := range groups {
		k := len(group.phases)
		if k <= 1 {
			continue
		}

		var prefix int64
		var linear int64
		for j, phase := range group.phases {
			p := int64(phase)
			linear += int64(j)*p - prefix
			prefix += p
		}

		sorted := append([]int(nil), group.phases...)
		tmp := make([]int, k)
		inversions := mergeCount(sorted, tmp, 0, k)

		contribution := linear%mod +
			(int64(group.period)%mod)*(inversions%mod)%mod
		answer = (answer + contribution) % mod
	}

	if answer < 0 {
		answer += mod
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	fmt.Fprintln(out, answer)
	out.Flush()
}
