package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Item struct {
	id   int
	rem  int
}

type MaxHeap []Item

func (h MaxHeap) Len() int { return len(h) }
func (h MaxHeap) Less(i, j int) bool {
	if h[i].rem != h[j].rem {
		return h[i].rem > h[j].rem
	}
	return h[i].id < h[j].id
}
func (h MaxHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *MaxHeap) Push(x interface{}) {
	*h = append(*h, x.(Item))
}
func (h *MaxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

type Frame struct {
	v, p int
	exit bool
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n int
	fmt.Fscan(in, &n)

	adj := make([][]int, n)
	for i := 0; i < n-1; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
	}

	// Find a centroid.
	parent := make([]int, n)
	order := make([]int, 0, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1
	stack := []int{0}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)
		for _, to := range adj[v] {
			if to == parent[v] {
				continue
			}
			parent[to] = v
			stack = append(stack, to)
		}
	}

	size := make([]int, n)
	centroid := 0
	best := n + 1
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		size[v] = 1
		maxPart := 0
		for _, to := range adj[v] {
			if parent[to] == v {
				size[v] += size[to]
				if size[to] > maxPart {
					maxPart = size[to]
				}
			}
		}
		if n-size[v] > maxPart {
			maxPart = n - size[v]
		}
		if maxPart < best {
			best = maxPart
			centroid = v
		}
	}

	color := make([]int, n)
	for i := 0; i < n; i++ {
		color[i] = i & 1
	}

	// Build a postorder for a component rooted at root, excluding centroid.
	// The child joined by a prescribed matching edge is processed first.
	buildSequence := func(root int) []int {
		seq := make([]int, 0)
		st := []Frame{{v: root, p: centroid, exit: false}}
		for len(st) > 0 {
			f := st[len(st)-1]
			st = st[:len(st)-1]
			if f.exit {
				seq = append(seq, f.v)
				continue
			}

			st = append(st, Frame{v: f.v, p: f.p, exit: true})

			mate := f.v ^ 1
			children := make([]int, 0, len(adj[f.v]))
			matchChild := -1
			for _, to := range adj[f.v] {
				if to == f.p || to == centroid {
					continue
				}
				if to == mate {
					matchChild = to
				} else {
					children = append(children, to)
				}
			}

			// Stack is LIFO. Push ordinary children in reverse order,
			// then the matching child last so that it is processed first.
			for i := len(children) - 1; i >= 0; i-- {
				st = append(st, Frame{v: children[i], p: f.v})
			}
			if matchChild != -1 {
				st = append(st, Frame{v: matchChild, p: f.v})
			}
		}
		return seq
	}

	sequences := make([][]int, 0, len(adj[centroid])+1)
	for _, to := range adj[centroid] {
		sequences = append(sequences, buildSequence(to))
	}
	sequences = append(sequences, []int{centroid})

	pos := make([]int, len(sequences))
	heaps := [2]MaxHeap{}
	heap.Init(&heaps[0])
	heap.Init(&heaps[1])

	addComponent := func(id int) {
		if pos[id] >= len(sequences[id]) {
			return
		}
		v := sequences[id][pos[id]]
		heap.Push(&heaps[color[v]], Item{
			id:  id,
			rem: len(sequences[id]) - pos[id],
		})
	}

	for i := range sequences {
		addComponent(i)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for step := 0; step < n/2; step++ {
		a := heap.Pop(&heaps[0]).(Item)
		b := heap.Pop(&heaps[1]).(Item)

		if a.id == b.id {
			var a2, b2 Item
			hasA2 := heaps[0].Len() > 0
			hasB2 := heaps[1].Len() > 0
			if hasA2 {
				a2 = heap.Pop(&heaps[0]).(Item)
			}
			if hasB2 {
				b2 = heap.Pop(&heaps[1]).(Item)
			}

			if hasB2 && (!hasA2 || a.rem+b2.rem >= a2.rem+b.rem) {
				heap.Push(&heaps[1], b)
				b = b2
				if hasA2 {
					heap.Push(&heaps[0], a2)
				}
			} else {
				heap.Push(&heaps[0], a)
				a = a2
				if hasB2 {
					heap.Push(&heaps[1], b2)
				}
			}
		}

		x := sequences[a.id][pos[a.id]]
		y := sequences[b.id][pos[b.id]]
		fmt.Fprintf(out, "%d %d\n", x+1, y+1)

		pos[a.id]++
		pos[b.id]++
		addComponent(a.id)
		addComponent(b.id)
	}
}
