package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	mod1  int64 = 998244353
	mod2  int64 = 1004535809
	root  int64 = 3
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func modPow(a, e, mod int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func ntt(a []int64, invert bool, mod int64) {
	n := len(a)

	for i, j := 1, 0; i < n; i++ {
		bit := n >> 1
		for ; j&bit != 0; bit >>= 1 {
			j ^= bit
		}
		j ^= bit
		if i < j {
			a[i], a[j] = a[j], a[i]
		}
	}

	base := root
	if invert {
		base = modPow(base, mod-2, mod)
	}

	for length := 2; length <= n; length <<= 1 {
		wlen := modPow(base, (mod-1)/int64(length), mod)
		half := length >> 1

		for i := 0; i < n; i += length {
			w := int64(1)
			for j := 0; j < half; j++ {
				u := a[i+j]
				v := a[i+j+half] * w % mod

				x := u + v
				if x >= mod {
					x -= mod
				}
				y := u - v
				if y < 0 {
					y += mod
				}

				a[i+j] = x
				a[i+j+half] = y
				w = w * wlen % mod
			}
		}
	}

	if invert {
		invN := modPow(int64(n), mod-2, mod)
		for i := range a {
			a[i] = a[i] * invN % mod
		}
	}
}

func convolutionSquare(freq []int32, a []int64, mod int64) {
	for i := range a {
		a[i] = 0
	}
	for i, count := range freq {
		a[i] = int64(count) % mod
	}

	ntt(a, false, mod)
	for i := range a {
		a[i] = a[i] * a[i] % mod
	}
	ntt(a, true, mod)
}

func findCandidate(x int, freq []int32, conv []int64, mod int64) int {
	for c := 1; c <= x; c++ {
		if freq[c] == 0 {
			continue
		}

		sum := x - c
		if sum < 2 {
			continue
		}

		var correction int64

		// Remove pairs in which both positions are the same input index.
		if sum&1 == 0 {
			correction += int64(freq[sum/2])
		}

		// Remove ordered pairs containing the selected occurrence of c.
		d := sum - c
		if d >= 1 && d <= x {
			other := int64(freq[d])
			if d == c {
				other--
			}
			correction += 2 * other
		}

		residue := conv[sum] - correction%mod
		residue %= mod
		if residue < 0 {
			residue += mod
		}
		if residue != 0 {
			return c
		}
	}
	return -1
}

func validValues(a, b, c int, freq []int32) bool {
	if freq[a] == 0 || freq[b] == 0 || freq[c] == 0 {
		return false
	}

	if a == b && b == c {
		return freq[a] >= 3
	}
	if a == b {
		return freq[a] >= 2
	}
	if a == c {
		return freq[a] >= 2
	}
	if b == c {
		return freq[b] >= 2
	}
	return true
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	x := in.NextInt()

	values := make([]int32, n)
	freq := make([]int32, x+1)

	for i := 0; i < n; i++ {
		v := in.NextInt()
		values[i] = int32(v)
		freq[v]++
	}

	size := 1
	for size < 2*x+1 {
		size <<= 1
	}
	conv := make([]int64, size)

	convolutionSquare(freq, conv, mod1)
	c := findCandidate(x, freq, conv, mod1)

	if c == -1 {
		convolutionSquare(freq, conv, mod2)
		c = findCandidate(x, freq, conv, mod2)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()

	if c == -1 {
		fmt.Fprintln(out, -1)
		return
	}

	pairSum := x - c
	a, b := -1, -1
	for v := 1; v < pairSum; v++ {
		w := pairSum - v
		if w < 1 || w > x {
			continue
		}
		if validValues(v, w, c, freq) {
			a, b = v, w
			break
		}
	}

	if a == -1 {
		fmt.Fprintln(out, -1)
		return
	}

	targets := [3]int{a, b, c}
	indices := [3]int{}
	used := [3]bool{}
	found := 0

	for i, value := range values {
		for t := 0; t < 3; t++ {
			if !used[t] && int(value) == targets[t] {
				used[t] = true
				indices[t] = i + 1
				found++
				break
			}
		}
		if found == 3 {
			break
		}
	}

	if indices[0] > indices[1] {
		indices[0], indices[1] = indices[1], indices[0]
	}
	if indices[1] > indices[2] {
		indices[1], indices[2] = indices[2], indices[1]
	}
	if indices[0] > indices[1] {
		indices[0], indices[1] = indices[1], indices[0]
	}

	fmt.Fprintln(out, indices[0], indices[1], indices[2])
}
