			for rows := 2; usedRows+rows <= n; rows++ {
				for cols := 2; usedCols+cols <= n; cols++ {
					shift := rows * cols
					wordShift := shift / 64
					bitShift := uint(shift % 64)
					dst := dp[usedRows+rows][usedCols+cols]

