const (
	mod1 int64 = 998244353
	mod2 int64 = 1004535809
	root int64 = 3
)

type FastScanner struct {
	r   *os.File
	buf []byte
	pos int
	n   int
}

func NewFastScanner() *FastScanner {
	return &FastScanner{
		r:   os.Stdin,
		buf: make([]byte, 1<<20),
	}
}

func (fs *FastScanner) readByte() byte {
	if fs.pos >= fs.n {
		n, _ := fs.r.Read(fs.buf)
		fs.n = n
		fs.pos = 0
		if n == 0 {
			return 0
		}
	}
	b := fs.buf[fs.pos]
	fs.pos++
	return b
}

func (fs *FastScanner) NextInt() int {
	b := fs.readByte()
	for b < '0' || b > '9' {
		b = fs.readByte()
	}
	v := 0
	for b >= '0' && b <= '9' {
		v = v*10 + int(b-'0')
		b = fs.readByte()
	}
	return v
}

func modPow(a, e, mod int64) int64 {
	var result int64 = 1
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func ntt(a []int64, invert bool, mod int64) {
	n := len(a)

	for i, j := 1, 0; i < n; i++ {
		bit := n >> 1
		for j&bit != 0 {
			j ^= bit
			bit >>= 1
		}
		j ^= bit
		if i < j {
			a[i], a[j] = a[j], a[i]
		}
	}

	for length := 2; length <= n; length <<= 1 {
		wlen := modPow(root, (mod-1)/int64(length), mod)
		if invert {
			wlen = modPow(wlen, mod-2, mod)
		}
		half := length >> 1

		for i := 0; i < n; i += length {
			w := int64(1)
			for j := 0; j < half; j++ {
				u := a[i+j]
				v := a[i+j+half] * w % mod

				x := u + v
				if x >= mod {
					x -= mod
				}
				y := u - v
				if y < 0 {
					y += mod
				}

				a[i+j] = x
				a[i+j+half] = y
				w = w * wlen % mod
			}
		}
	}

	if invert {
		invN := modPow(int64(n), mod-2, mod)
		for i := range a {
			a[i] = a[i] * invN % mod
		}
	}
}

func squareConvolution(a []int64, mod int64) {
	ntt(a, false, mod)
	for i := range a {
		a[i] = a[i] * a[i] % mod
	}
	ntt(a, true, mod)
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()
	x := in.NextInt()

	values := make([]int32, n)
	freq := make([]int64, x+1)

	for i := 0; i < n; i++ {
		v := in.NextInt()
		values[i] = int32(v)
		freq[v]++
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()

	if x < 3 {
		fmt.Fprintln(out, -1)
		return
	}

	size := 1
	for size <= 2*x {
		size <<= 1
	}

	work := make([]int64, size)
	for i := 1; i <= x; i++ {
		work[i] = freq[i] % mod1
	}
	squareConvolution(work, mod1)

	firstResidue := make([]int32, x+1)
	for i := 0; i <= x; i++ {
		firstResidue[i] = int32(work[i])
	}

	for i := range work {
		work[i] = 0
	}
	for i := 1; i <= x; i++ {
		work[i] = freq[i] % mod2
	}
	squareConvolution(work, mod2)

	invMod1 := modPow(mod1%mod2, mod2-2, mod2)

	reconstruct := func(sum int) int64 {
		r1 := int64(firstResidue[sum])
		r2 := work[sum]
		delta := (r2 - r1) % mod2
		if delta < 0 {
			delta += mod2
		}
		t := delta * invMod1 % mod2
		return r1 + mod1*t
	}

	chosenA, chosenB, chosenC := -1, -1, -1

	for c := 1; c <= x; c++ {
		if freq[c] == 0 {
			continue
		}

		sum := x - c
		if sum < 2 {
			continue
		}

		pairCount := reconstruct(sum)

		if sum%2 == 0 {
			pairCount -= freq[sum/2]
		}

		d := x - 2*c
		if d >= 1 && d <= x {
			pairCount -= 2 * freq[d]
		}

		if 3*c == x {
			pairCount += 2
		}

		if pairCount <= 0 {
			continue
		}

		for a := 1; a <= sum/2; a++ {
			b := sum - a
			if b < 1 || b > x || freq[a] == 0 || freq[b] == 0 {
				continue
			}

			valid := false
			switch {
			case a == b && b == c:
				valid = freq[a] >= 3
			case a == b:
				valid = freq[a] >= 2 && freq[c] >= 1
			case a == c:
				valid = freq[a] >= 2 && freq[b] >= 1
			case b == c:
				valid = freq[b] >= 2 && freq[a] >= 1
			default:
				valid = true
			}

			if valid {
				chosenA, chosenB, chosenC = a, b, c
				break
			}
		}

		if chosenA != -1 {
			break
		}
	}

	if chosenA == -1 {
		fmt.Fprintln(out, -1)
		return
	}

	required := make(map[int]int, 3)
	required[chosenA]++
	required[chosenB]++
	required[chosenC]++

	indices := make([]int, 0, 3)
	for i, v32 := range values {
		v := int(v32)
		if required[v] > 0 {
			indices = append(indices, i+1)
			required[v]--
			if len(indices) == 3 {
				break
			}
		}
	}

	fmt.Fprintf(out, "%d %d %d\n", indices[0], indices[1], indices[2])
}
