}

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := NewFastScanner()
	n := in.NextInt()

	maxN := 2*n + 5
	fact := make([]int64, maxN)
	invFact := make([]int64, maxN)

	fact[0] = 1
	for i := 1; i < maxN; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxN-1] = modPow(fact[maxN-1], mod-2)
	for i := maxN - 1; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(n, k int) int64 {
		if n < 0 || k < 0 || k > n {
			return 0
		}
		return fact[n] * invFact[k] % mod * invFact[n-k] % mod
	}

	forestRangeSum := func(r, l, u int) int64 {
		if l > u {
			return 0
		}
		res := comb(2*r-l, r)
		res -= comb(2*r-u-1, r)
		res -= comb(2*r-l, r+1)
		res += comb(2*r-u-1, r+1)
		res %= mod
		if res < 0 {
			res += mod
		}
		return res
	}

	answer := int64(0)
	slots := 1
	active := true

	for i := 1; i <= n; i++ {
		a := in.NextInt()
		if !active {
			continue
		}

		remaining := n - i

		if remaining == 0 {
			// The only possible final value is 0, and slots must be 1.
			if slots == 1 && a > 0 {
				answer++
				if answer >= mod {
					answer -= mod
				}
			}

			slots = slots - 1 + a
			if slots == 0 {
				answer++
				if answer >= mod {
					answer -= mod
				}
			}
			active = false
			continue
		}

		// Choose a smaller value x in [0, a-1].
		// The number of slots afterward is slots-1+x.
		l := slots - 1
		if l < 1 {
			l = 1
		}
		u := slots + a - 2
		if u > remaining {
			u = remaining
		}

		if l <= u {
			answer += forestRangeSum(remaining, l, u)
			answer %= mod
		}

		// Continue along the prefix equal to A.
		slots = slots - 1 + a
		if slots < 1 || slots > remaining {
			active = false
		}
	}

	fmt.Fprintln(bufio.NewWriterSize(os.Stdout, 1<<20), answer)
