const mod int64 = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	maxFact := 2*n + 5
	fact := make([]int64, maxFact)
	invFact := make([]int64, maxFact)
	fact[0] = 1
	for i := 1; i < maxFact; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxFact-1] = modPow(fact[maxFact-1], mod-2)
	for i := maxFact - 1; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(x, y int) int64 {
		if x < 0 || y < 0 || y > x {
			return 0
		}
		return fact[x] * invFact[y] % mod * invFact[x-y] % mod
	}

	// Sum over t in [left, right] of the number of ordered forests
	// with t roots and m total vertices.
	forestRange := func(m int, left, right int64) int64 {
		if m <= 0 {
			return 0
		}
		if left < 1 {
			left = 1
		}
		if right > int64(m) {
			right = int64(m)
		}
		if left > right {
			return 0
		}

		l := int(left)
		r := int(right)
		lowK := 2*m - r - 1
		highK := 2*m - l - 1

		res := comb(highK+1, m) - comb(lowK, m)
		res -= comb(highK+1, m+1) - comb(lowK, m+1)
		res %= mod
		if res < 0 {
			res += mod
		}
		return res
	}

	var ans int64
	slots := int64(1)

	for i := 0; i < n; i++ {
		remaining := n - i - 1

		// Choose the current value strictly smaller than A[i].
		// The resulting number of pending roots ranges over:
		// slots-1, ..., slots+A[i]-2.
		left := slots - 1
		right := slots + a[i] - 2

		if remaining == 0 {
			if left <= 0 && 0 <= right {
				ans++
				if ans == mod {
					ans = 0
				}
			}
		} else {
			ans += forestRange(remaining, left, right)
			ans %= mod
		}

		// Continue with the prefix equal to A.
		slots = slots - 1 + a[i]

		if i == n-1 {
			if slots == 0 {
				ans++
				ans %= mod
			}
			break
		}
		if slots == 0 {
			break
		}
	}

	fmt.Fprintln(out, ans)
}
