		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	b := make([]int, n)
	totalUnknown := 0
	for i := 0; i < n; i++ {
		b[i] = in.NextInt()
		if b[i] == -1 {
			totalUnknown++
		}
	}

	// suffixMax[i] is the maximum fixed value in B[i:].
	suffixMax := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixMax[i] = suffixMax[i+1]
		if b[i] != -1 && b[i] > suffixMax[i] {
			suffixMax[i] = b[i]
		}
	}

	// powers[x][e] = x^e modulo mod.
	stride := n + 1
	powers := make([]int64, (m+1)*stride)
	for base := 0; base <= m; base++ {
		offset := base * stride
		powers[offset] = 1
		for e := 1; e <= n; e++ {
			powers[offset+e] = powers[offset+e-1] * int64(base) % mod
		}
	}

	// Every completed sequence contributes at least one component.
	answer := powers[m*stride+totalUnknown]

	leftUnknown := 0
	leftFixedMin := m + 1

	for cut := 1; cut < n; cut++ {
		x := b[cut-1]
		if x == -1 {
			leftUnknown++
		} else if x < leftFixedMin {
			leftFixedMin = x
		}

		rightUnknown := totalUnknown - leftUnknown
		rightFixedMax := suffixMax[cut]

		low := rightFixedMax + 1
		high := leftFixedMin
		if high > m {
			high = m
		}

		for minimumLeft := low; minimumLeft <= high; minimumLeft++ {
			// Number of left-side assignments whose overall minimum is
			// exactly minimumLeft.
			leftWays := powers[(m-minimumLeft+1)*stride+leftUnknown]
			if leftFixedMin >= minimumLeft+1 {
				leftWays -= powers[(m-minimumLeft)*stride+leftUnknown]
				if leftWays < 0 {
					leftWays += mod
				}
			}

			// Every right-side unknown must be smaller than minimumLeft.
			rightWays := powers[(minimumLeft-1)*stride+rightUnknown]

			answer += leftWays * rightWays % mod
			if answer >= mod {
				answer -= mod
			}
		}
	}

	fmt.Fprintln(out, answer)
}
