const mod = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var N, K int
	var S string
	fmt.Fscan(in, &N, &K)
	fmt.Fscan(in, &S)

	m := N + 2
	size := m * m * m * 4
	dp := make([]int, size)
	next := make([]int, size)

	index := func(c0, c1, c2, state int) int {
		return (((c0*m)+c1)*m+c2)*4 + state
	}

	// Before reading any character, prefix state 0 has occurred once.
	dp[index(1, 0, 0, 0)] = 1

	for pos := 0; pos < N; pos++ {
		clear(next)
		total := pos + 1

		var masks [3]int
		maskCount := 1
		switch S[pos] {
		case 'A':
			masks[0] = 1
		case 'B':
			masks[0] = 2
		case 'C':
			masks[0] = 3
		default:
			masks = [3]int{1, 2, 3}
			maskCount = 3
		}

		for c0 := 0; c0 <= total; c0++ {
			for c1 := 0; c1 <= total-c0; c1++ {
				for c2 := 0; c2 <= total-c0-c1; c2++ {
					for state := 0; state < 4; state++ {
						value := dp[index(c0, c1, c2, state)]
						if value == 0 {
							continue
						}

						for i := 0; i < maskCount; i++ {
							ns := state ^ masks[i]
							nc0, nc1, nc2 := c0, c1, c2
							switch ns {
							case 0:
								nc0++
							case 1:
								nc1++
							case 2:
								nc2++
							}

							idx := index(nc0, nc1, nc2, ns)
							next[idx] += value
							if next[idx] >= mod {
								next[idx] -= mod
							}
						}
					}
				}
			}
		}

		dp, next = next, dp
	}

	total := N + 1
	answer := 0

	for c0 := 0; c0 <= total; c0++ {
		for c1 := 0; c1 <= total-c0; c1++ {
			for c2 := 0; c2 <= total-c0-c1; c2++ {
				c3 := total - c0 - c1 - c2
				good := c0*(c0-1)/2 +
					c1*(c1-1)/2 +
					c2*(c2-1)/2 +
					c3*(c3-1)/2

				if good < K {
					continue
				}

				for state := 0; state < 4; state++ {
					answer += dp[index(c0, c1, c2, state)]
					if answer >= mod {
						answer -= mod
					}
				}
			}
		}
	}

	fmt.Fprintln(out, answer)
}
