package main

import (
	"bufio"
	"fmt"
	"os"
)

type DSU struct {
	parent []int
	size   []int
	xor    []int // parity between node and parent
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{
		parent: parent,
		size:   size,
		xor:    make([]int, n),
	}
}

func (d *DSU) Find(x int) (int, int) {
	if d.parent[x] == x {
		return x, 0
	}
	root, parity := d.Find(d.parent[x])
	d.xor[x] ^= parity
	d.parent[x] = root
	return d.parent[x], d.xor[x]
}

// Unite imposes value[a] XOR value[b] = w.
func (d *DSU) Unite(a, b, w int) bool {
	ra, xa := d.Find(a)
	rb, xb := d.Find(b)

	if ra == rb {
		return xa^xb == w
	}

	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
		xa, xb = xb, xa
	}

	d.parent[rb] = ra
	d.xor[rb] = xa ^ xb ^ w
	d.size[ra] += d.size[rb]
	return true
}

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	firstB := make([]int, n)
	firstC := make([]int, n)
	hasTestimony := make([]bool, n)

	dsu := NewDSU(n)
	possible := true

	for i := 0; i < m; i++ {
		a := in.NextInt() - 1
		b := in.NextInt() - 1
		c := in.NextInt()

		if !hasTestimony[a] {
			hasTestimony[a] = true
			firstB[a] = b
			firstC[a] = c
		} else if possible {
			// For testimonies (a, firstB) and (a, b):
			// liar[b] XOR liar[firstB] = c XOR firstC.
			if !dsu.Unite(b, firstB[a], c^firstC[a]) {
				possible = false
			}
		}
	}

	if !possible {
		fmt.Fprintln(out, -1)
		return
	}

	liar := make([]int, n)
	for i := 0; i < n; i++ {
		_, parity := dsu.Find(i)
		liar[i] = parity
	}

	answer := make([]byte, n)
	for i := 0; i < n; i++ {
		confused := 0
		if hasTestimony[i] {
			confused = liar[i] ^ liar[firstB[i]] ^ firstC[i]
		}
		answer[i] = byte('0' + confused)
	}

	fmt.Fprintln(out, string(answer))
}
