package main

import (
	"bufio"
	"fmt"
	"os"
)

type DSU struct {
	parent []int
	size   []int
	parity []int // value[x] XOR value[parent[x]]
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	parity := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size, parity: parity}
}

func (d *DSU) find(x int) (int, int) {
	if d.parent[x] == x {
		return x, 0
	}
	p := d.parent[x]
	root, v := d.find(p)
	d.parity[x] ^= v
	d.parent[x] = root
	return root, d.parity[x]
}

// unite imposes value[a] XOR value[b] = w.
func (d *DSU) unite(a, b, w int) bool {
	ra, pa := d.find(a)
	rb, pb := d.find(b)

	if ra == rb {
		return pa^pb == w
	}

	rootParity := pa ^ pb ^ w
	if d.size[ra] < d.size[rb] {
		d.parent[ra] = rb
		d.parity[ra] = rootParity
		d.size[rb] += d.size[ra]
	} else {
		d.parent[rb] = ra
		d.parity[rb] = rootParity
		d.size[ra] += d.size[rb]
	}
	return true
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	dsu := NewDSU(n)
	firstB := make([]int, n)
	firstC := make([]int, n)
	hasTestimony := make([]bool, n)
	possible := true

	for i := 0; i < m; i++ {
		var a, b, c int
		fmt.Fscan(in, &a, &b, &c)
		a--
		b--

		if !hasTestimony[a] {
			hasTestimony[a] = true
			firstB[a] = b
			firstC[a] = c
		} else if possible {
			requiredParity := firstC[a] ^ c
			if !dsu.unite(firstB[a], b, requiredParity) {
				possible = false
			}
		}
	}

	if !possible {
		fmt.Fprintln(out, -1)
		return
	}

	honesty := make([]int, n)
	for i := 0; i < n; i++ {
		_, honesty[i] = dsu.find(i)
	}

	answer := make([]byte, n)
	for i := 0; i < n; i++ {
		confused := 0
		if hasTestimony[i] {
			confused = firstC[i] ^ honesty[i] ^ honesty[firstB[i]]
		}
		answer[i] = byte('0' + confused)
	}

	fmt.Fprintln(out, string(answer))
}
