package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Box struct {
	b int64 // V - 1
	p int64
	q int64 // V - P
}

type Fenwick struct {
	n     int
	count []int64
	sum   []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:     n,
		count: make([]int64, n+1),
		sum:   make([]int64, n+1),
	}
}

func (f *Fenwick) Add(pos int, dc, ds int64) {
	for i := pos + 1; i <= f.n; i += i & -i {
		f.count[i] += dc
		f.sum[i] += ds
	}
}

func (f *Fenwick) SumKSmallest(k int64, values []int64) int64 {
	if k == 0 {
		return 0
	}

	idx := 0
	var cnt, sum int64

	step := 1
	for step<<1 <= f.n {
		step <<= 1
	}

	for step > 0 {
		next := idx + step
		if next <= f.n && cnt+f.count[next] < k {
			idx = next
			cnt += f.count[next]
			sum += f.sum[next]
		}
		step >>= 1
	}

	return sum + (k-cnt)*values[idx]
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var T int
	fmt.Fscan(in, &T)

	for ; T > 0; T-- {
		var n, m int
		fmt.Fscan(in, &n, &m)

		boxes := make([]Box, n)
		values := make([]int64, 0, 2*n)
		var positiveSum int64

		for i := 0; i < n; i++ {
			var v, p int64
			fmt.Fscan(in, &v, &p)
			b := v - 1
			q := v - p
			boxes[i] = Box{b: b, p: p, q: q}
			values = append(values, b, p-1)
			if q > 0 {
				positiveSum += q
			}
		}

		if m == 1 {
			fmt.Fprintln(out, positiveSum)
			continue
		}
		if m > n {
			fmt.Fprintln(out, 0)
			continue
		}

		sort.Slice(boxes, func(i, j int) bool {
			return boxes[i].b > boxes[j].b
		})

		sort.Slice(values, func(i, j int) bool {
			return values[i] < values[j]
		})
		unique := values[:0]
		for _, x := range values {
			if len(unique) == 0 || unique[len(unique)-1] != x {
				unique = append(unique, x)
			}
		}
		values = unique

		indexOf := func(x int64) int {
			return sort.Search(len(values), func(i int) bool {
				return values[i] >= x
			})
		}

		suffixPositive := make([]int64, n+1)
		for i := n - 1; i >= 0; i-- {
			suffixPositive[i] = suffixPositive[i+1]
			if boxes[i].q > 0 {
				suffixPositive[i] += boxes[i].q
			}
		}

		k := int64(m - 1)
		fw := NewFenwick(len(values))
		var inserted int64
		var answer int64

		for i := 0; i < n; {
			j := i
			for j < n && boxes[j].b == boxes[i].b {
				j++
			}

			for x := i; x < j; x++ {
				loss := boxes[x].p - 1
				if boxes[x].q > 0 {
					loss = boxes[x].b
				}
				fw.Add(indexOf(loss), 1, loss)
				inserted++
			}

			if inserted >= k {
				loss := fw.SumKSmallest(k, values)
				candidate := suffixPositive[i] - loss
				if candidate > answer {
					answer = candidate
				}
			}

			for x := i; x < j; x++ {
				if boxes[x].q > 0 {
					oldLoss := boxes[x].b
					newLoss := boxes[x].p - 1
					fw.Add(indexOf(oldLoss), -1, -oldLoss)
					fw.Add(indexOf(newLoss), 1, newLoss)
				}
			}

			i = j
		}

		fmt.Fprintln(out, answer)
	}
}
