package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func addMod(a, b int64) int64 {
	return (a + b) % mod
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var N, M, K int
	fmt.Fscan(in, &N, &M, &K)

	X := make([]int, M)
	for i := range X {
		fmt.Fscan(in, &X[i])
	}

	changes := 0
	for i := 0; i+1 < M; i++ {
		if X[i] != X[i+1] {
			changes++
		}
	}

	q := K - 1
	minimumLength := M*q + changes + (M - 1)
	if minimumLength > N {
		fmt.Fprintln(out, 0)
		return
	}

	excess := N - minimumLength
	maxBlockLength := N - (M - 1)

	// C[l]: number of length-l words over q symbols containing every symbol.
	C := make([]int64, maxBlockLength+1)
	seenDP := make([]int64, q+1)
	seenDP[0] = 1

	for length := 1; length <= maxBlockLength; length++ {
		next := make([]int64, q+1)
		for seen := 0; seen <= q; seen++ {
			v := seenDP[seen]
			if v == 0 {
				continue
			}
			if seen > 0 {
				next[seen] = addMod(next[seen], v*int64(seen)%mod)
			}
			if seen < q {
				next[seen+1] = addMod(next[seen+1], v*int64(q-seen)%mod)
			}
		}
		seenDP = next
		C[length] = seenDP[q]
	}

	// D[l]: number of length-l words over q symbols which contain all symbols,
	// and in which a distinguished symbol occurs after every symbol has already
	// occurred at least once.
	D := make([]int64, maxBlockLength+1)
	unseenT := make([]int64, q)
	seenT := make([]int64, q)
	unseenT[0] = 1

	var complete, good int64

	for length := 1; length <= maxBlockLength; length++ {
		nextUnseenT := make([]int64, q)
		nextSeenT := make([]int64, q)
		var nextComplete, nextGood int64

		for seenOther := 0; seenOther < q; seenOther++ {
			if v := unseenT[seenOther]; v != 0 {
				// Append an already seen non-distinguished symbol.
				if seenOther > 0 {
					nextUnseenT[seenOther] = addMod(
						nextUnseenT[seenOther],
						v*int64(seenOther)%mod,
					)
				}

				// Append a new non-distinguished symbol.
				newChoices := q - 1 - seenOther
				if newChoices > 0 {
					nextUnseenT[seenOther+1] = addMod(
						nextUnseenT[seenOther+1],
						v*int64(newChoices)%mod,
					)
				}

				// Append the distinguished symbol.
				if seenOther == q-1 {
					nextComplete = addMod(nextComplete, v)
				} else {
					nextSeenT[seenOther] = addMod(nextSeenT[seenOther], v)
				}
			}

			if v := seenT[seenOther]; v != 0 {
				// Append the distinguished symbol or an already seen other symbol.
				nextSeenT[seenOther] = addMod(
					nextSeenT[seenOther],
					v*int64(seenOther+1)%mod,
				)

				// Append a new non-distinguished symbol.
				newChoices := q - 1 - seenOther
				if newChoices > 0 {
					add := v * int64(newChoices) % mod
					if seenOther+1 == q-1 {
						nextComplete = addMod(nextComplete, add)
					} else {
						nextSeenT[seenOther+1] = addMod(nextSeenT[seenOther+1], add)
					}
				}
			}
		}

		// Once complete, another distinguished symbol makes the word good.
		nextComplete = addMod(nextComplete, complete*int64(q-1)%mod)
		nextGood = addMod(nextGood, complete)
		nextGood = addMod(nextGood, good*int64(q)%mod)

		unseenT = nextUnseenT
		seenT = nextSeenT
		complete = nextComplete
		good = nextGood
		D[length] = good
	}

	dp := make([]int64, excess+1)
	dp[0] = 1
	currentMax := 0

	equalBlocks := M - changes
	for block := 0; block < M; block++ {
		isDifferent := block >= equalBlocks
		minBlock := q
		factor := C
		if isDifferent {
			minBlock = q + 1
			factor = D
		}

		next := make([]int64, excess+1)
		nextMax := currentMax + excess
		if nextMax > excess {
			nextMax = excess
		}

		for used := 0; used <= currentMax; used++ {
			if dp[used] == 0 {
				continue
			}
			for extra := 0; used+extra <= excess; extra++ {
				length := minBlock + extra
				if length > maxBlockLength {
					break
				}
				ways := factor[length]
				if ways == 0 {
					continue
				}
				next[used+extra] = (next[used+extra] + dp[used]*ways) % mod
			}
		}

		dp = next
		currentMax = nextMax
	}

	fmt.Fprintln(out, dp[excess])
}
