		fmt.Fscan(in, &a[i])
	}

	ks := make([]int, 0)
	totalOperations := 0
	valid := true

	for left := 1; left <= n; {
		right := left
		for right+1 <= n && a[right+1] == a[left] {
			right++
		}

		if a[left] != left%2 || a[right] != right%2 {
			valid = false
			break
		}

		k := (right - left) / 2
		ks = append(ks, k)
		totalOperations += k
		left = right + 1
	}

	if !valid {
		fmt.Fprintln(out, 0)
		return
