	for i := totalOperations; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	answer := fact[totalOperations]
	for _, k := range ks {
		answer = answer * doubleFact[k] % mod
		answer = answer * invFact[k] % mod
	}

