const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	outWriter := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer outWriter.Flush()

	var n int
	fmt.Fscan(in, &n)

	A := make([]int, n)
	B := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &A[i])
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &B[i])
	}

	owner := make([]int, n)
	for i := range owner {
		owner[i] = -1
	}
	plus := make([]bool, n)

	valid := true
	for i, rank := range A {
		block := (rank - 1) / 2
		if owner[block] != -1 {
			valid = false
		} else {
			owner[block] = i
		}
		plus[i] = rank%2 == 1
	}
	for _, x := range owner {
		if x == -1 {
			valid = false
		}
	}

	if !valid {
		fmt.Fprintln(outWriter, 0)
		return
	}

	next := make([]int, n)
	prev := make([]int, n)
	for i := 0; i < n; i++ {
		next[i] = -1
		prev[i] = -1
	}

	for i, rank := range B {
		if rank == -1 {
			continue
		}
		block := (rank - 1) / 2
		p := owner[block]

		if p == -1 || next[p] != -1 || prev[i] != -1 {
			valid = false
			break
		}
		next[p] = i
		prev[i] = p
	}

	if !valid {
		fmt.Fprintln(outWriter, 0)
		return
	}

	visited := make([]bool, n)
	positivePaths, negativePaths, mixedPaths := 0, 0, 0

	// Components with a vertex of indegree zero are directed paths.
	for start := 0; start < n; start++ {
		if prev[start] != -1 || visited[start] {
			continue
		}

		hasPlus, hasMinus := false, false
		for v := start; v != -1; v = next[v] {
			visited[v] = true
			if plus[v] {
				hasPlus = true
			} else {
				hasMinus = true
			}
		}

		if hasPlus && hasMinus {
			mixedPaths++
		} else if hasPlus {
			positivePaths++
		} else {
			negativePaths++
		}
	}

	// Unvisited components are already closed cycles.
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		hasPlus, hasMinus := false, false
		v := start
		for {
			visited[v] = true
			if plus[v] {
				hasPlus = true
			} else {
				hasMinus = true
			}
			v = next[v]
			if v == start {
				break
			}
		}

		if !hasPlus || !hasMinus {
			fmt.Fprintln(outWriter, 0)
			return
		}
	}

	m := positivePaths + negativePaths + mixedPaths

	fact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	if m == 0 {
		fmt.Fprintln(outWriter, 1)
		return
	}

	answer := fact[m]
	answer -= int64(positivePaths+negativePaths) * fact[m-1] % mod

	if m >= 2 {
		add := int64(positivePaths) * int64(negativePaths) % mod
		add = add * fact[m-2] % mod
		answer += add
	}

	answer %= mod
	if answer < 0 {
		answer += mod
	}
	fmt.Fprintln(outWriter, answer)
}
