		if b[j] != expected || next[p] != -1 {
			valid = false
			break
		}

		next[p] = j
		indegree[j]++
		if indegree[j] > 1 {
			valid = false
			break
		}
	}

	if !valid {
		fmt.Fprintln(out, 0)
		return
	}

	visited := make([]bool, n)
	pureOdd, pureEven, mixed := 0, 0, 0

	// Components beginning at indegree-zero vertices are directed paths.
	for start := 0; start < n; start++ {
		if indegree[start] != 0 {
			continue
		}

		hasOdd, hasEven := false, false
		cur := start
		for cur != -1 {
			visited[cur] = true
			if a[cur]%2 == 1 {
				hasOdd = true
			} else {
				hasEven = true
			}
			cur = next[cur]
		}

		if hasOdd && hasEven {
			mixed++
		} else if hasOdd {
			pureOdd++
		} else {
			pureEven++
		}
	}

	// Remaining components are already closed cycles.
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		hasOdd, hasEven := false, false
		cur := start
		for !visited[cur] {
			visited[cur] = true
			if a[cur]%2 == 1 {
				hasOdd = true
			} else {
				hasEven = true
			}
			cur = next[cur]
		}

		if !(hasOdd && hasEven) {
			fmt.Fprintln(out, 0)
			return
		}
	}

	k := pureOdd + pureEven + mixed
	if k == 0 {
		fmt.Fprintln(out, 1)
		return
	}

	fact := make([]int64, k+1)
	fact[0] = 1
	for i := 1; i <= k; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	ans := fact[k]
	ans = (ans - int64(pureOdd+pureEven)*fact[k-1]) % mod
	if k >= 2 {
		ans = (ans + int64(pureOdd)*int64(pureEven)%mod*fact[k-2]) % mod
	}
	if ans < 0 {
		ans += mod
	}

	fmt.Fprintln(out, ans)
}
