package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func requiredChain(perm, balls []int, x int) ([]int, bool) {
	n := len(perm)
	inv := make([]int, n)
	for i, to := range perm {
		inv[to] = i
	}

	inCycle := make([]bool, n)
	dist := make([]int, n)
	inCycle[x] = true

	// nodesByDistance[d-1] is the vertex whose distance to x is d.
	nodesByDistance := make([]int, 0)
	cur := inv[x]
	d := 1
	for cur != x {
		inCycle[cur] = true
		dist[cur] = d
		nodesByDistance = append(nodesByDistance, cur)
		cur = inv[cur]
		d++
	}

	maxDist := 0
	for i, count := range balls {
		if count == 0 {
			continue
		}
		if !inCycle[i] {
			return nil, false
		}
		if dist[i] > maxDist {
			maxDist = dist[i]
		}
	}

	chain := make([]int, 0, maxDist)
	for d := maxDist; d >= 1; d-- {
		chain = append(chain, nodesByDistance[d-1])
	}
	return chain, true
}

func lcsLengthUnique(a, b []int, n int) int {
	pos := make([]int, n)
	for i := range pos {
		pos[i] = -1
	}
	for i, v := range b {
		pos[v] = i
	}

	tails := make([]int, 0)
	for _, v := range a {
		if pos[v] == -1 {
			continue
		}
		p := pos[v]
		i := sort.SearchInts(tails, p)
		if i == len(tails) {
			tails = append(tails, p)
		} else {
			tails[i] = p
		}
	}
	return len(tails)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, x int
	fmt.Fscan(in, &n, &x)
	x--

	a := make([]int, n)
	b := make([]int, n)
	p := make([]int, n)
	q := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	for i := range b {
		fmt.Fscan(in, &b[i])
	}
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}
	for i := range q {
		fmt.Fscan(in, &q[i])
		q[i]--
	}

	redChain, ok := requiredChain(p, a, x)
	if !ok {
		fmt.Fprintln(out, -1)
		return
	}

	blueChain, ok := requiredChain(q, b, x)
	if !ok {
		fmt.Fprintln(out, -1)
		return
	}

	lcs := lcsLengthUnique(redChain, blueChain, n)
	answer := len(redChain) + len(blueChain) - lcs
	fmt.Fprintln(out, answer)
}
