package main

import (
	"bufio"
	"fmt"
	"os"
)

type MaxSegmentTree struct {
	n    int
	tree []int64
}

func NewMaxSegmentTree(values []int64) *MaxSegmentTree {
	n := 1
	for n < len(values) {
		n <<= 1
	}

	const negInf int64 = -1 << 62
	tree := make([]int64, 2*n)
	for i := range tree {
		tree[i] = negInf
	}
	for i, v := range values {
		tree[n+i] = v
	}
	for i := n - 1; i > 0; i-- {
		if tree[i<<1] > tree[i<<1|1] {
			tree[i] = tree[i<<1]
		} else {
			tree[i] = tree[i<<1|1]
		}
	}
	return &MaxSegmentTree{n: n, tree: tree}
}

func (st *MaxSegmentTree) firstGE(node, left, right, queryLeft int, threshold int64) int {
	if right <= queryLeft || st.tree[node] < threshold {
		return -1
	}
	if right-left == 1 {
		return left
	}

	mid := (left + right) >> 1
	result := st.firstGE(node<<1, left, mid, queryLeft, threshold)
	if result != -1 {
		return result
	}
	return st.firstGE(node<<1|1, mid, right, queryLeft, threshold)
}

func (st *MaxSegmentTree) FirstGE(queryLeft int, threshold int64) int {
	return st.firstGE(1, 0, st.n, queryLeft, threshold)
}

func (st *MaxSegmentTree) lastGE(node, left, right, queryRight int, threshold int64) int {
	if queryRight < left || st.tree[node] < threshold {
		return -1
	}
	if right-left == 1 {
		return left
	}

	mid := (left + right) >> 1
	result := st.lastGE(node<<1|1, mid, right, queryRight, threshold)
	if result != -1 {
		return result
	}
	return st.lastGE(node<<1, left, mid, queryRight, threshold)
}

func (st *MaxSegmentTree) LastGE(queryRight int, threshold int64) int {
	return st.lastGE(1, 0, st.n, queryRight, threshold)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		prefix[i+1] = prefix[i] + a[i]
	}

	// To absorb i while moving right from an interval whose left end is l:
	// A[i] < prefix[i] - prefix[l]
	// A[i] - prefix[i] < -prefix[l].
	rightKey := make([]int64, n)

	// To absorb i while moving left from an interval whose right end is r:
	// A[i] < prefix[r+1] - prefix[i+1]
	// A[i] + prefix[i+1] < prefix[r+1].
	leftKey := make([]int64, n)

	for i := 0; i < n; i++ {
		rightKey[i] = a[i] - prefix[i]
		leftKey[i] = a[i] + prefix[i+1]
	}

	rightTree := NewMaxSegmentTree(rightKey)
	leftTree := NewMaxSegmentTree(leftKey)

	const negInf int64 = -1 << 62

	suffixMaxRight := make([]int64, n+1)
	suffixMaxRight[n] = negInf
	for i := n - 1; i >= 0; i-- {
		suffixMaxRight[i] = suffixMaxRight[i+1]
		if rightKey[i] > suffixMaxRight[i] {
			suffixMaxRight[i] = rightKey[i]
		}
	}

	prefixMaxLeft := make([]int64, n)
	for i := 0; i < n; i++ {
		if i == 0 || leftKey[i] > prefixMaxLeft[i-1] {
			prefixMaxLeft[i] = leftKey[i]
		} else {
			prefixMaxLeft[i] = prefixMaxLeft[i-1]
		}
	}

	answer := make([]int64, n)

	for start := 0; start < n; start++ {
		l, r := start, start

		for {
			oldL, oldR := l, r

			if r+1 < n {
				threshold := -prefix[l]
				if suffixMaxRight[r+1] >= threshold {
					blocker := rightTree.FirstGE(r+1, threshold)
					if blocker >= 0 && blocker < n {
						r = blocker - 1
					} else {
						r = n - 1
					}
				} else {
					r = n - 1
				}
			}

			if l > 0 {
				threshold := prefix[r+1]
				if prefixMaxLeft[l-1] >= threshold {
					blocker := leftTree.LastGE(l-1, threshold)
					l = blocker + 1
				} else {
					l = 0
				}
			}

			if l == oldL && r == oldR {
				break
			}
		}

		answer[start] = prefix[r+1] - prefix[l]
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
	out.Flush()
}
